insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ac',16,10,'crampon1923','Après cette vision de Paul, nous cherchâmes aussitôt à nous rendre en Macédoine, certains que Dieu nous appelait à y annoncer la bonne nouvelle.'),
('ac',16,11,'crampon1923','Ayant donc pris la mer à Troas, nous fîmes voile droit vers Samothrace, et le lendemain nous débarquâmes à Néapolis.'),
('ac',16,12,'crampon1923','De là nous allâmes à Philippes, qui est la première ville de cette partie de la Macédoine et une colonie. Nous demeurâmes quelques jours dans cette ville.'),
('ac',16,13,'crampon1923','Le jour du sabbat, nous nous rendîmes hors de la porte, sur le bord d''une rivière, où nous pensions qu''était le lieu de la prière. Nous étant assis, nous parlâmes aux femmes qui s''y étaient assemblées.'),
('ac',16,14,'crampon1923','Or dans l''auditoire était une femme nommée Lydie: c''était une marchande de pourpre, de la ville de Thyatire, craignant Dieu, et le Seigneur lui ouvrit le cœur pour qu''elle fût attentive à ce que disait Paul.'),
('ac',16,15,'crampon1923','Quand elle eut reçu le baptême, elle et sa famille, elle nous adressa cette prière: " Si vous avez jugé que j''ai foi au Seigneur, entrez dans ma maison et demeurez-y. " Et elle nous contraignit par ses instances.'),
('ac',16,16,'crampon1923','Un jour que nous allions à la prière, nous rencontrâmes une jeune esclave qui avait un esprit Python et procurait un grand profit à ses maîtres par ses divinations.'),
('ac',16,17,'crampon1923','Elle se mit à nous suivre, Paul et nous, en criant: " Ces hommes sont les serviteurs du Dieu très haut; ils vous annoncent la voie du salut. "'),
('ac',16,18,'crampon1923','Elle fit ainsi pendant plusieurs jours. Comme Paul en éprouvait de la peine, il se retourna et dit à l''esprit: " Je te commande, au nom de Jésus-Christ, de sortir de cette fille. " Et il sortit à l''heure même.'),
('ac',16,19,'crampon1923','Les maîtres de la jeune fille, voyant s''évanouir l''espoir de leur gain, se saisirent de Paul et de Silas et les traînèrent à l''agora devant les magistrats.'),
('ac',16,20,'crampon1923','Et les ayant amenés aux stratèges, ils dirent: " Ces hommes troublent notre ville. Ce sont des Juifs;'),
('ac',16,21,'crampon1923','ils prêchent des usages qu''il ne nous est pas permis, à nous, Romains, de recevoir ni de suivre. "'),
('ac',16,22,'crampon1923','En même temps la foule se souleva contre eux, et les stratèges ayant fait arracher leurs vêtements, ordonnèrent qu''on les battît de verges.'),
('ac',16,23,'crampon1923','Après qu''on les eut chargés de coups, ils les firent mettre en prison, en recommandant au geôlier de les garder sûrement.'),
('ac',16,24,'crampon1923','Le geôlier ayant reçu cet ordre, les mit dans un des cachots intérieurs, et engagea leurs pieds dans des ceps.'),
('ac',16,25,'crampon1923','Vers le milieu de la nuit, Paul et Silas chantaient les louanges de Dieu, et les prisonniers les entendaient.'),
('ac',16,26,'crampon1923','Tout à coup il se fit un tremblement de terre si violent que les fondements de la prison en furent ébranlés; au même instant, toutes les portes s''ouvrirent et les liens de tous les prisonniers tombèrent.'),
('ac',16,27,'crampon1923','Le geôlier s''étant éveillé et voyant les portes de la prison ouvertes, tira son épée, et il allait se tuer, pensant que les prisonniers avaient pris la fuite.'),
('ac',16,28,'crampon1923','Mais Paul cria d''une voix forte: " Ne te fais point de mal, nous sommes tous ici. "'),
('ac',16,29,'crampon1923','Alors Le geôlier, ayant demandé de la lumière, entra précipitamment et se jeta tout tremblant aux pieds de Paul et de Silas; puis'),
('ac',16,30,'crampon1923','il les fit sortir et dit: " Seigneurs, que faut-il que je fasse pour être sauvé? "'),
('ac',16,31,'crampon1923','Ils répondirent: " Crois au Seigneur Jésus et tu seras sauvé, toi et ta famille. "'),
('ac',16,32,'crampon1923','Et ils lui annoncèrent la parole de Dieu, ainsi qu''à tous ceux qui étaient dans la maison.'),
('ac',16,33,'crampon1923','Les prenant avec lui à cette heure de la nuit, il lava leurs plaies, et aussitôt après il fut baptisé, lui et tous les siens.'),
('ac',16,34,'crampon1923','Ensuite il les fit monter dans sa maison et leur servit à manger, se réjouissant avec toute sa famille d''avoir cru en Dieu.'),
('ac',16,35,'crampon1923','Quand il fit jour, les stratèges envoyèrent les licteurs qui dirent: " Mets ces hommes en liberté. "'),
('ac',16,36,'crampon1923','Le geôlier annonça la chose à Paul: " Les stratèges ont envoyé l''ordre de vous relâcher; sortez donc maintenant et allez en paix. "'),
('ac',16,37,'crampon1923','Mais Paul dit aux licteurs: " Après nous avoir publiquement battus de verges, sans jugement, nous qui sommes Romains, on nous a jetés en prison, et maintenant on nous fait sortir en secret! Il n''en sera pas ainsi. Qu''ils viennent eux-mêmes'),
('ac',16,38,'crampon1923','nous mettre en liberté. " Les licteurs rapportèrent ces paroles aux stratèges, qui furent effrayés en apprenant que ces hommes étaient Romains.'),
('ac',16,39,'crampon1923','Ils vinrent donc les exhorter, et ils les mirent en liberté, en les priant de quitter la ville.'),
('ac',16,40,'crampon1923','Au sortir de la prison, Paul et Silas entrèrent chez Lydie, et après avoir vu et exhorté les frères, ils partirent.'),
('ac',17,1,'crampon1923','Ayant ensuite traversé Amphipolis et Apollonie, Paul et Silas arrivèrent à Thessalonique, où était la synagogue des Juifs.'),
('ac',17,2,'crampon1923','Selon sa coutume, Paul y entra, et pendant trois sabbats, il discuta avec eux. Partant des Ecritures,'),
('ac',17,3,'crampon1923','il expliquait et établissait que le Messie avait dû souffrir et ressusciter des morts; et " ce Messie, disait-il, c''est le Christ Jésus que je vous annonce. "'),
('ac',17,4,'crampon1923','Quelques Juifs furent persuadés, et ils se joignirent à Paul et à Silas, ainsi qu''une grande multitude de gentils craignant Dieu, et un assez grand nombre de femmes du premier rang.'),
('ac',17,5,'crampon1923','Mais les Juifs, piqués de jalousie, enrôlèrent quelques mauvais sujets de la lie du peuple, provoquèrent des attroupements, et répandirent l''agitation dans la ville. Puis, s''étant précipités vers la maison de Jason, ils cherchèrent Paul et Silas pour les amener devant le peuple.'),
('ac',17,6,'crampon1923','Ne les ayant pas trouvés, ils traînèrent Jason et quelques frères devant les politarques, en criant: " Ces hommes qui ont bouleversé le monde sont aussi venus ici,'),
('ac',17,7,'crampon1923','et Jason les a reçus. Ils sont tous en contravention avec les édits de César, disant qu''il y a un autre roi, Jésus. "'),
('ac',17,8,'crampon1923','Ils mirent ainsi en émoi le peuple et les politarques qui les écoutaient.'),
('ac',17,9,'crampon1923','Et ce ne fut qu''après avoir reçu une caution de Jason et des autres qu''ils les laissèrent aller.'),
('ac',17,10,'crampon1923','Les frères, sans perdre de temps, firent partir de nuit Paul et Silas pour Bérée. Quand ils furent arrivés dans cette ville, ils se rendirent à la synagogue des Juifs.'),
('ac',17,11,'crampon1923','Ces derniers avaient des sentiments plus nobles que ceux de Thessalonique; ils reçurent la parole avec beaucoup d''empressement, examinant chaque jour les Ecritures, pour voir si ce qu''on leur enseignait était exact.'),
('ac',17,12,'crampon1923','Beaucoup d''entre eux, et, parmi les Grecs, des femmes de qualité et des hommes en grand nombre, embrassèrent la foi.'),
('ac',17,13,'crampon1923','Mais quand les Juifs de Thessalonique surent que Paul annonçait aussi à Bérée la parole de Dieu, ils vinrent encore y agiter la population.'),
('ac',17,14,'crampon1923','Alors les frères firent sur-le-champ partir Paul jusqu''à la mer; mais Silas et Timothée restèrent à Bérée.'),
('ac',17,15,'crampon1923','Ceux qui conduisaient Paul l''accompagnèrent jusqu''à Athènes; puis, chargés de mander à Silas et à Timothée de venir le rejoindre au plus tôt, ils s''en retournèrent.'),
('ac',17,16,'crampon1923','Pendant que Paul les attendait à Athènes, il sentait en son âme une vive indignation au spectacle de cette ville pleine d''idoles.'),
('ac',17,17,'crampon1923','Il discutait donc dans la synagogue avec les Juifs et les hommes craignant Dieu, et tous les jours dans l''Agora avec ceux qu''il rencontrait.'),
('ac',17,18,'crampon1923','Or quelques philosophes épicuriens et stoïciens ayant conféré avec lui, les uns disaient: " Que nous veut ce semeur de paroles? " D''autres, l''entendant prêcher Jésus et la résurrection, disaient: " Il paraît qu''il vient nous annoncer des divinités étrangères. "'),
('ac',17,19,'crampon1923','Et l''ayant pris avec eux, ils le menèrent sur l''Aréopage, disant: " Pourrions-nous savoir quelle est cette nouvelle doctrine que tu enseignes?'),
('ac',17,20,'crampon1923','Car tu nous fais entendre des choses étranges; nous voudrions donc savoir ce qu''il en est. "'),
('ac',17,21,'crampon1923','Or tous les Athéniens et les étrangers établis dans la ville ne passaient leur temps qu''à dire ou à écouter des nouvelles.'),
('ac',17,22,'crampon1923','Paul, debout au milieu de l''Aréopage, parla ainsi: " Athéniens, je constate qu''à tous égards vous êtes éminemment religieux.'),
('ac',17,23,'crampon1923','Car lorsqu''en passant je regardais les objets de votre culte, j''ai trouvé même un autel avec cette inscription: AU DIEU INCONNU. Celui que vous adorez sans le connaître, je viens vous l''annoncer.'),
('ac',17,24,'crampon1923','Le Dieu qui a fait le monde et tout ce qu''il renferme, étant le Seigneur du ciel et de la terre, n''habite point dans des temples faits de main d''homme;'),
('ac',17,25,'crampon1923','il n''est point servi par des mains humaines, comme s''il avait besoin de quelque chose, lui qui donne à tous la vie, le souffle et toutes choses.'),
('ac',17,26,'crampon1923','D''un seul homme il a fait sortir tout le genre humain, pour peupler la surface de toute la terre, ayant déterminé pour chaque nation la durée de son existence et les bornes de son domaine,'),
('ac',17,27,'crampon1923','afin que les hommes le cherchent et le trouvent comme à tâtons: quoiqu''il ne soit pas loin de chacun de nous,'),
('ac',17,28,'crampon1923','car c''est en lui que nous avons la vie, le mouvement et l''être; et, comme l''ont dit aussi quelques-uns de vos poètes... de sa race nous sommes.'),
('ac',17,29,'crampon1923','Etant donc de la race de Dieu, nous ne devons pas croire que la divinité soit semblable à de l''or, à de l''argent, ou à de la pierre, sculptés par l''art et le génie de l''homme.'),
('ac',17,30,'crampon1923','Dieu ne tenant pas compte de ces temps d''ignorance, annonce maintenant aux hommes qu''ils aient tous, en tous lieux, à se repentir;'),
('ac',17,31,'crampon1923','car il a fixé un jour où il jugera le monde selon la justice, par l''homme qu''il a désigné, et qu''il a accrédité auprès de tous, en le ressuscitant des morts. "'),
('ac',17,32,'crampon1923','Lorsqu''ils entendirent parler de résurrection des morts, les uns se moquèrent, les autres dirent: " Nous t''entendrons là-dessus une autre fois. "'),
('ac',17,33,'crampon1923','C''est ainsi que Paul se retira du milieu d''eux.'),
('ac',17,34,'crampon1923','Quelques personnes néanmoins s''attachèrent à lui et crurent; de ce nombre furent Denys l''Aréopagite, une femme nommée Damaris, et d''autres avec eux.'),
('ac',18,1,'crampon1923','Après cela, Paul partit d''Athènes et se rendit à Corinthe.'),
('ac',18,2,'crampon1923','Il y trouva un Juif nommé Aquila, originaire du Pont, et récemment arrivé d''Italie avec sa femme Priscille, parce que Claude avait enjoint à tous les Juifs de sortir de Rome. Paul alla les voir;'),
('ac',18,3,'crampon1923','et comme il exerçait le même métier, il demeura chez eux et y travailla: ils étaient faiseurs de tentes.'),
('ac',18,4,'crampon1923','Chaque sabbat, il discourait dans la synagogue, et il persuadait des Juifs et des Grecs.'),
('ac',18,5,'crampon1923','Lorsque Silas et Timothée furent arrivés de Macédoine, il se donna tout entier à la parole, attestant aux Juifs que Jésus était le Christ.'),
('ac',18,6,'crampon1923','Mais comme ceux-ci s''opposaient à lui et l''injuriaient, Paul secoua ses vêtements et leur dit: " Que votre sang soit sur votre tête! J''en suis pur; dès ce moment j''irai chez les Gentils. "'),
('ac',18,7,'crampon1923','Et sortant de là, il entra chez un nommé Justus, homme craignant Dieu, et dont la maison était contiguë à la synagogue.'),
('ac',18,8,'crampon1923','Or Crispus, le chef de la synagogue, crut au Seigneur avec toute sa maison; un grand nombre de Corinthiens, en entendant Paul, crurent aussi et furent baptisés.'),
('ac',18,9,'crampon1923','Pendant la nuit, le Seigneur dit à Paul dans une vision: " Sois sans crainte, mais parle et ne te tais point.'),
('ac',18,10,'crampon1923','Car je suis avec toi, et personne ne mettra la main sur toi pour te faire du mal; car j''ai un peuple nombreux dans cette ville. "'),
('ac',18,11,'crampon1923','Paul demeura un an et six mois à Corinthe, y enseignant la parole de Dieu.'),
('ac',18,12,'crampon1923','Or, Gallion étant proconsul d''Achaïe, les Juifs se soulevèrent unanimement contre Paul, et le menèrent devant le tribunal,'),
('ac',18,13,'crampon1923','en disant: " Celui-ci persuade aux hommes un culte contraire à la Loi. "'),
('ac',18,14,'crampon1923','Comme Paul ouvrait la bouche pour répondre, Gallion dit aux Juifs: " S''il s''agissait de quelque délit ou de quelque grave méfait, je vous écouterais comme de raison, ô Juifs.'),
('ac',18,15,'crampon1923','Mais puisqu''il s''agit de discussions sur une doctrine, sur des noms et sur votre loi, cela vous regarde; je ne veux pas être juge de ces choses. "'),
('ac',18,16,'crampon1923','Et il les renvoya du tribunal.'),
('ac',18,17,'crampon1923','Alors tous, se saisissant de Sosthènes, le chef de la synagogue, le battirent devant le tribunal, sans que Gallion s''en mît en peine.'),
('ac',18,18,'crampon1923','Paul resta encore assez longtemps à Corinthe; puis, ayant dit adieu aux frères, il s''embarqua pour la Syrie, avec Priscille et Aquila, après s''être fait raser la tête à Cenchrées, en vertu d''un vœu.'),
('ac',18,19,'crampon1923','Il arriva à Ephèse, et y laissa ses compagnons. Pour lui, étant entré dans la synagogue, il s''entretint avec les Juifs,'),
('ac',18,20,'crampon1923','qui le prièrent de prolonger son séjour. Mais il n''y consentit point,'),
('ac',18,21,'crampon1923','et il prit congé d''eux, en disant: " [Il faut absolument que je célèbre la fête prochaine à Jérusalem.] Je reviendrai vers vous, si Dieu le veut. " Et il partit d''Ephèse.'),
('ac',18,22,'crampon1923','Ayant débarqué à Césarée, il monta à Jérusalem, salua l''Eglise et descendit à Antioche.'),
('ac',18,23,'crampon1923','Après y avoir passé quelque temps, Paul se mit en route, et parcourut successivement le pays des Galates et la Phrygie, affermissant tous les disciples.'),
('ac',18,24,'crampon1923','Or, un Juif nommé Apollos, originaire d''Alexandrie, homme éloquent et versé dans les Ecritures, vint à Ephèse.'),
('ac',18,25,'crampon1923','Il avait été instruit dans la voie du Seigneur, et, d''un cœur ardent, il enseignait avec exactitude ce qui concerne Jésus, bien qu''il ne connût que le baptême de Jean.'),
('ac',18,26,'crampon1923','Il se mit à parler avec assurance dans la synagogue. Priscille et Aquila, l''ayant entendu, le prirent avec eux et lui exposèrent plus à fond la voie du Seigneur.'),
('ac',18,27,'crampon1923','Et comme il voulait passer en Achaïe, les frères l''approuvèrent et écrivirent aux disciples de le bien recevoir. Quand il fut arrivé, il fut d''un grand secours à ceux qui avaient cru par la grâce,'),
('ac',18,28,'crampon1923','car il réfutait vigoureusement les Juifs en public, démontrant par les Ecritures que Jésus est le Christ.'),
('ac',19,1,'crampon1923','Or, pendant qu''Apollos était à Corinthe, Paul, après avoir parcouru les hautes régions, arriva à Ephèse. Ayant rencontré quelques disciples,'),
('ac',19,2,'crampon1923','il leur dit: " Avez-vous reçu le Saint-Esprit quand vous avez cru? " Ils lui répondirent: " Nous n''avons pas même entendu dire qu''il y ait un Saint-Esprit. " —'),
('ac',19,3,'crampon1923','" Quel baptême avez-vous donc reçu? " demanda Paul. Ils dirent: " Le baptême de Jean. "'),
('ac',19,4,'crampon1923','Paul dit alors: " Jean a baptisé du baptême de pénitence, en disant au peuple de croire en celui qui venait après lui, c''est-à-dire en Jésus. "'),
('ac',19,5,'crampon1923','Ayant entendu ces paroles, ils se firent baptiser au nom du Seigneur Jésus.'),
('ac',19,6,'crampon1923','Lorsque Paul leur eut imposé les mains, le Saint-Esprit vint sur eux, et ils se mirent à parler des langues et à prophétiser.'),
('ac',19,7,'crampon1923','Ils étaient environ douze en tout.'),
('ac',19,8,'crampon1923','Ensuite Paul entra dans la synagogue, et pendant trois mois, il y parla avec beaucoup d''assurance, discourant d''une manière persuasive sur les choses qui concernent le royaume de Dieu.'),
('ac',19,9,'crampon1923','Mais, comme quelques-uns restaient endurcis et incrédules, décriant devant le peuple la voie du Seigneur, il se sépara d''eux, prit à part les disciples et discourut chaque jour dans l''école d''un nommé Tyrannus.'),
('ac',19,10,'crampon1923','Ce qu''il fit durant deux ans, de sorte que tous ceux qui habitaient l''Asie, Juifs et Grecs, entendirent la parole du Seigneur.'),
('ac',19,11,'crampon1923','Et Dieu faisait des miracles extraordinaires par les mains de Paul,'),
('ac',19,12,'crampon1923','au point qu''on appliquait sur les malades des mouchoirs et des ceintures qui avaient touché son corps, et les maladies les quittaient, et les esprits mauvais étaient chassés.'),
('ac',19,13,'crampon1923','Quelques-uns des exorcistes Juifs qui couraient le pays essayèrent aussi d''invoquer le nom du Seigneur Jésus sur ceux qui avaient des esprits malins, en disant: " Je vous adjure par Jésus que Paul prêche. "'),
('ac',19,14,'crampon1923','Or ils étaient sept fils de Scéva, grand prêtre juif, qui se livraient à cette pratique.'),
('ac',19,15,'crampon1923','L''esprit malin leur répondit: " Je connais Jésus et je sais qui est Paul; mais vous, qui êtes-vous? "'),
('ac',19,16,'crampon1923','Et l''homme qui était possédé de l''esprit malin se jeta sur eux, s''en rendit maître et les maltraita si fort, qu''ils s''enfuirent de cette maison nus et blessés.'),
('ac',19,17,'crampon1923','Ce fait étant venu à la connaissance de tous les Juifs et de tous les Grecs qui demeuraient à Ephèse, la crainte tomba sur eux tous, et le nom du Seigneur Jésus fut glorifié.'),
('ac',19,18,'crampon1923','Un grand nombre de ceux qui avaient cru venaient confesser et déclarer leurs actions.'),
('ac',19,19,'crampon1923','Et parmi ceux qui s''étaient adonnés aux pratiques superstitieuses, beaucoup apportèrent leurs livres et les brûlèrent devant tout le peuple: en estimant la valeur de ces livres on trouva cinquante mille pièces d''argent:'),
('ac',19,20,'crampon1923','tant la parole du Seigneur s''étendait avec force et se montrait puissante!'),
('ac',19,21,'crampon1923','Après cela, Paul résolut d''aller à Jérusalem, en traversant la Macédoine et l''Achaïe. " Après que j''aurai été là, se disait-il, il faut aussi que je voie Rome. "'),
('ac',19,22,'crampon1923','Il envoya en Macédoine deux de ses auxiliaires, Timothée et Eraste, et lui-même resta encore quelque temps en Asie.'),
('ac',19,23,'crampon1923','Il survint en ce temps-là un grand tumulte au sujet de la voie du Seigneur.'),
('ac',19,24,'crampon1923','Un orfèvre, nommé Démétrius, fabriquait en argent de petits temples de Diane, et procurait à ses ouvriers un gain considérable.'),
('ac',19,25,'crampon1923','Les ayant rassemblés, avec ceux du même métier, il leur dit: " Mes amis, vous savez que notre bien-être dépend de cette industrie;'),
('ac',19,26,'crampon1923','et vous voyez et entendez dire que, non seulement à Ephèse, mais encore dans presque toute l''Asie, ce Paul a persuadé et détourné une foule de gens, en disant que les dieux faits de main d''homme ne sont pas des dieux.'),
('ac',19,27,'crampon1923','Il est donc à craindre, non seulement que notre industrie ne tombe dans le discrédit, mais encore que le temple de la grande déesse Diane ne soit tenu pour rien, et même que la majesté de celle que révèrent l''Asie et le monde entier ne soit réduite à néant. "'),
('ac',19,28,'crampon1923','A ces mots, transportés de colère, ils se mirent à crier: " Grande est la Diane des Ephésiens! "'),
('ac',19,29,'crampon1923','Bientôt la ville fut remplie de confusion. Ils se portèrent tous ensemble au théâtre, entraînant Gaïus et Aristarque, Macédoniens qui avaient accompagné Paul dans son voyage.'),
('ac',19,30,'crampon1923','Paul voulait pénétrer au milieu de la foule, mais les disciples l''en empêchèrent.'),
('ac',19,31,'crampon1923','Quelques-uns même des Asiarques, qui étaient de ses amis, envoyèrent vers lui, pour l''engager à ne pas se présenter au théâtre.'),
('ac',19,32,'crampon1923','Mille cris divers s''y faisaient entendre; car le désordre régnait dans l''assemblée, et la plupart ne savaient pourquoi ils s''étaient réunis.'),
('ac',19,33,'crampon1923','Alors on dégagea de la foule Alexandre que les Juifs poussaient en avant. Il fit signe de la main qu''il voulait parler au peuple.'),
('ac',19,34,'crampon1923','Mais, lorsqu''ils eurent reconnu qu''il était juif, ils crièrent tous d''une seule voix durant près de deux heures: " Grande est la Diane des Ephésiens! "'),
('ac',19,35,'crampon1923','Le grammate ayant enfin apaisé la foule, dit: " Ephésiens, quel est l''homme qui ne sache que la ville d''Ephèse est vouée au culte de la grande Diane et de sa statue tombée du ciel?'),
('ac',19,36,'crampon1923','Cela étant incontestable, vous devez être calme et ne rien faire inconsidérément;'),
('ac',19,37,'crampon1923','car ces hommes que vous avez amenés ici ne sont ni des sacrilèges, ni des blasphémateurs de votre déesse.'),
('ac',19,38,'crampon1923','Que si Démétrius et ceux de son industrie ont à se plaindre de quelqu''un, il y a des jours d''audience et des proconsuls: que chacun fasse valoir ses griefs.'),
('ac',19,39,'crampon1923','Si vous avez quelque autre affaire à régler, on en décidera dans l''assemblée légale.'),
('ac',19,40,'crampon1923','Nous risquons, en effet, d''être accusés de sédition pour ce qui s''est passé aujourd''hui, car il n''existe aucun motif qui nous permette de justifier cet attroupement. " Ayant parlé ainsi, il congédia l''assemblée.'),
('ac',19,41,'crampon1923',''),
('ac',20,1,'crampon1923','Lorsque le tumulte eut cessé, Paul réunit les disciples, prit congé d''eux et partit pour la Macédoine.'),
('ac',20,2,'crampon1923','Il parcourut cette contrée, en adressant aux disciples de nombreux exhortations, et se rendit en Grèce,'),
('ac',20,3,'crampon1923','où il passa trois mois. Il se disposait à faire voile pour la Syrie, quand les Juifs lui dressèrent des embûches. Alors il se décida à reprendre la route de Macédoine.'),
('ac',20,4,'crampon1923','Il avait pour l''accompagner jusqu''en Asie, Sopater de Bérée, fils de Pyrrhus, Aristarque et Secundus de Thessalonique; Gaius de Derbé, Timothée, Tychique et Trophime d''Asie.'),
('ac',20,5,'crampon1923','Ceux-ci prirent les devants et nous attendirent à Troas.'),
('ac',20,6,'crampon1923','Pour nous, après les jours des Azymes, nous nous embarquâmes à Philippes, et au bout de cinq jours nous les rejoignîmes à Troas, où nous passâmes sept jours.'),
('ac',20,7,'crampon1923','Le premier jour de la semaine, comme nous étions assemblés pour la fraction du pain, Paul, qui devait partir le lendemain, s''entretint avec les disciples, et prolongea son discours jusqu''à minuit.'),
('ac',20,8,'crampon1923','Il y avait beaucoup de lampes dans la salle haute où nous étions assemblés.'),
('ac',20,9,'crampon1923','Or un jeune homme, nommé Eutyque, était assis sur le bord de la fenêtre. Pendant le long discours de Paul, il s''endormit profondément, et, sous le poids du sommeil, il tomba du troisième en bas; on le releva mort.'),
('ac',20,10,'crampon1923','Mais Paul, étant descendu, se pencha sur lui et le prit dans ses bras, en disant: " Ne vous troublez pas, car son âme est en lui. "'),
('ac',20,11,'crampon1923','Puis étant remonté, il rompit le pain et mangea, et il parla longtemps encore, jusqu''au jour; après quoi, il partit.'),
('ac',20,12,'crampon1923','Quant au jeune homme, on le ramena vivant, ce qui fut le sujet d''une grande consolation.'),
('ac',20,13,'crampon1923','Pour nous, prenant les devants par mer, nous fîmes voile pour Assos, où nous devions reprendre Paul; c''est ainsi qu''il l''avait ordonné; car il devait faire le voyage à pied.'),
('ac',20,14,'crampon1923','Quand il nous eut rejoints à Assos, nous le prîmes à bord, et nous gagnâmes Mytilène.'),
('ac',20,15,'crampon1923','De là, continuant par la mer, nous arrivâmes le lendemain à la hauteur de Chio. Le jour suivant, nous cinglâmes vers Samos, et, [après avoir passé la nuit à Trogylle], nous arrivâmes le lendemain à Milet.'),
('ac',20,16,'crampon1923','Paul avait résolu de passer devant Ephèse sans s''y arrêter, afin de ne pas perdre de temps en Asie. Car il se hâtait pour se trouver, s''il était possible, à Jérusalem, le jour de la Pentecôte.'),
('ac',20,17,'crampon1923','Or, de Milet, Paul envoya à Ephèse pour faire venir les Anciens de cette Eglise.'),
('ac',20,18,'crampon1923','Lorsqu''ils furent réunis autour de lui, il leur dit: " Vous savez comment, depuis le premier jour que j''ai mis le pied en Asie, je me suis toujours comporté avec vous,'),
('ac',20,19,'crampon1923','servant le Seigneur en toute humilité, au milieu des larmes et des épreuves que me suscitaient les embûches des Juifs;'),
('ac',20,20,'crampon1923','comment je ne vous ai rien caché de ce qui vous était avantageux, ne manquant pas de prêcher et de vous instruire en public et dans les maisons particulières;'),
('ac',20,21,'crampon1923','annonçant aux Juifs et aux Gentils le retour à Dieu par la pénitence et la foi en Notre-Seigneur Jésus-Christ.'),
('ac',20,22,'crampon1923','Et maintenant voici que, lié par l''Esprit, je vais à Jérusalem, sans savoir ce qui doit m''arriver;'),
('ac',20,23,'crampon1923','si ce n''est que de ville en ville l''Esprit-Saint m''assure que des chaînes et des persécutions m''attendent.'),
('ac',20,24,'crampon1923','Mais je n''en tiens aucun compte, et je n''attache pour moi-même aucun prix à la vie, pourvu que je consomme ma course et que j''accomplisse le ministère que j''ai reçu du Seigneur Jésus, d''annoncer la bonne nouvelle de la grâce de Dieu.'),
('ac',20,25,'crampon1923','Oui, je sais que vous ne verrez plus mon visage, ô vous tous parmi lesquels j''ai passé en prêchant le royaume de Dieu.'),
('ac',20,26,'crampon1923','C''est pourquoi je vous atteste aujourd''hui que je suis pur du sang de tous;'),
('ac',20,27,'crampon1923','car je vous ai annoncé tout le dessein de Dieu, sans vous en rien cacher.'),
('ac',20,28,'crampon1923','Prenez donc garde à vous-mêmes et à tout le troupeau sur lequel le Saint-Esprit vous a établis évêques, pour paître l''Eglise du Seigneur, qu''il s''est acquise par son propre sang.'),
('ac',20,29,'crampon1923','Moi, je sais en effet qu''après mon départ, il s''introduira parmi vous des loups cruels qui n''épargneront pas le troupeau.'),
('ac',20,30,'crampon1923','Et même il s''élèvera du milieu de vous des hommes qui enseigneront des doctrines perverses pour entraîner les disciples après eux.'),
('ac',20,31,'crampon1923','Veillez donc, vous souvenant que, durant trois années, je n''ai cessé nuit et jour d''exhorter avec larmes chacun de vous.'),
('ac',20,32,'crampon1923','Et maintenant je vous recommande à Dieu, et à la parole de sa grâce, à celui qui peut achever l''édifice et vous donner l''héritage avec tous les sanctifiés.'),
('ac',20,33,'crampon1923','Je n''ai désiré ni l''argent, ni l''or, ni le vêtement de personne.'),
('ac',20,34,'crampon1923','Vous savez vous-mêmes que ces mains ont pourvu à mes besoins et à ceux des personnes qui étaient avec moi.'),
('ac',20,35,'crampon1923','Je vous ai montré de toutes manières que c''est en travaillant ainsi qu''il faut soutenir les faibles, et se rappeler la parole du Seigneur Jésus, qui a dit lui-même: Il y a plus de bonheur à donner qu''à recevoir. "'),
('ac',20,36,'crampon1923','Après avoir ainsi parlé, il se mit à genoux et pria avec eux tous.'),
('ac',20,37,'crampon1923','Ils fondaient tous en larmes, en se jetant au cou de Paul, ils le baisaient,'),
('ac',20,38,'crampon1923','affligés surtout de ce qu''il avait dit: " Vous ne verrez plus mon visage. " Et ils l''accompagnèrent jusqu''au navire.'),
('ac',21,1,'crampon1923','Après nous être arrachés à leurs embrassements, nous mîmes à la voile et nous allâmes droit à Cos; le lendemain nous atteignîmes Rhodes, puis Patare.'),
('ac',21,2,'crampon1923','Là, ayant trouvé un vaisseau qui faisait la traversée vers la Phénicie, nous y montâmes et partîmes.'),
('ac',21,3,'crampon1923','Arrivés en vue de Chypre, nous laissâmes l''île à gauche, nous dirigeant vers la Syrie, et nous abordâmes à Tyr, où le navire devait déposer sa cargaison.'),
('ac',21,4,'crampon1923','Nous trouvâmes les disciples, et nous restâmes là sept jours; et ils disaient à Paul, par l''Esprit de Dieu, de ne point monter à Jérusalem.'),
('ac',21,5,'crampon1923','Mais au bout de sept jours, nous nous acheminâmes pour partir, et tous, avec leurs femmes et leurs enfants, nous accompagnèrent jusqu''en dehors de la ville. Nous nous mîmes à genoux sur le rivage pour prier;'),
('ac',21,6,'crampon1923','puis, après nous être dit adieu, nous montâmes sur le vaisseau, tandis qu''ils retournèrent chez eux.'),
('ac',21,7,'crampon1923','Pour nous, achevant notre navigation, nous allâmes de Tyr à Ptolémaïs, et ayant salué les frères, nous passâmes un jour avec eux.'),
('ac',21,8,'crampon1923','Nous partîmes le lendemain et nous arrivâmes à Césarée. Etant entrés dans la maison de Philippe l''évangéliste, l''un des sept, nous logeâmes chez lui.'),
('ac',21,9,'crampon1923','Il avait quatre filles vierges, qui prophétisaient.'),
('ac',21,10,'crampon1923','Comme nous étions dans cette ville depuis quelques jours, il arriva de Judée un prophète nommé Agabus.'),
('ac',21,11,'crampon1923','Etant venu vers nous, il prit la ceinture de Paul, se lia les pieds et les mains et dit: " Voici ce que déclare l''Esprit-Saint: L''homme à qui appartient cette ceinture sera ainsi lié à Jérusalem par les Juifs et livré aux mains des Gentils. "'),
('ac',21,12,'crampon1923','Ayant entendu ces paroles, nous et les fidèles de Césarée, nous conjurâmes Paul de ne point monter à Jérusalem.'),
('ac',21,13,'crampon1923','Alors il répondit: " Que faites-vous de pleurer ainsi et de me briser le cœur? Pour moi, je suis prêt, non seulement à porter les chaînes, mais encore à mourir à Jérusalem pour le nom du Seigneur Jésus. "'),
('ac',21,14,'crampon1923','Comme il restait inflexible, nous cessâmes nos instances, en disant: " Que la volonté du Seigneur se fasse! "'),
('ac',21,15,'crampon1923','Après ces jours-là, ayant achevé nos préparatifs, nous montâmes à Jérusalem.'),
('ac',21,16,'crampon1923','Des disciples de Césarée vinrent aussi avec nous, emmenant un nommé Mnason, de l''île de Chypre, depuis longtemps disciple, chez qui nous devions loger.'),
('ac',21,17,'crampon1923','A notre arrivée à Jérusalem, les frères nous reçurent avec joie.'),
('ac',21,18,'crampon1923','Le lendemain, Paul se rendit avec nous chez Jacques, et tous les Anciens s''y réunirent.'),
('ac',21,19,'crampon1923','Après les avoir embrassés, il raconta en détail tout ce que Dieu avait fait parmi les Gentils par son ministère.'),
('ac',21,20,'crampon1923','Ce qu''ayant entendu, ils glorifièrent Dieu, et dirent à Paul: " Tu vois, frère, combien de milliers de Juifs ont cru, et tous sont zélés pour la Loi.'),
('ac',21,21,'crampon1923','Or ils ont entendu dire de toi que tu enseignes aux Juifs dispersés parmi les Gentils de se séparer de Moïse, leur disant de ne pas circoncire leurs enfants et de ne pas se conformer aux coutumes.'),
('ac',21,22,'crampon1923','Que faire donc? Sans aucun doute, on se rassemblera en foule, car on va savoir ton arrivée.'),
('ac',21,23,'crampon1923','Fais donc ce que nous allons te dire. Nous avons ici quatre hommes qui ont fait un vœu;'),
('ac',21,24,'crampon1923','prends-les, purifie-toi avec eux, et fais pour eux les frais des sacrifices, afin qu''ils se rasent la tête. Ainsi tous sauront que les rapports faits sur ton compte sont sans valeur, et que toi aussi tu observes la Loi.'),
('ac',21,25,'crampon1923','Quant aux Gentils qui ont cru, nous leur avons écrit après avoir décidé [qu''ils n''ont rien de pareil à observer, sauf] qu''ils doivent s''abstenir des viandes offertes aux idoles, du sang, des animaux étouffés et de la fornication. "'),
('ac',21,26,'crampon1923','Alors Paul prit avec lui ces hommes, et après s''être purifié, il entra le lendemain avec eux dans le temple, pour annoncer que les jours du naziréat étaient expirés, et il y vint jusqu''à ce que le sacrifice eût été offert pour chacun d''eux.'),
('ac',21,27,'crampon1923','Comme les sept jours touchaient à leur fin, les Juifs d''Asie, ayant vu Paul dans le temple, soulevèrent toute la foule et mirent la main sur lui, en criant:'),
('ac',21,28,'crampon1923','" Enfants d''Israël, au secours! Voici l''homme qui prêche partout et à tout le monde contre le peuple, contre la Loi et contre ce lieu; il a même introduit des païens dans le temple et a profané ce saint lieu. "'),
('ac',21,29,'crampon1923','Car ils avaient vu auparavant Trophime d''Ephèse avec lui dans la ville, et ils croyaient que Paul l''avait fait entrer dans le temple.'),
('ac',21,30,'crampon1923','Aussitôt toute la ville fut en émoi, et le peuple accourut de toute part; on se saisit de Paul et on l''entraîna hors du temple, dont les portes furent immédiatement fermées.'),
('ac',21,31,'crampon1923','Pendant qu''ils cherchaient à le tuer, la nouvelle arriva au tribun de la cohorte que tout Jérusalem était en confusion.'),
('ac',21,32,'crampon1923','Il prit à l''instant des soldats et des centurions, et accourut à eux. A la vue du tribun et des soldats, ils cessèrent de frapper Paul.'),
('ac',21,33,'crampon1923','Alors le tribun s''approchant, se saisit de lui et le fit lier de deux chaînes; puis il demanda qui il était et ce qu''il avait fait.'),
('ac',21,34,'crampon1923','Mais, dans cette foule, les uns criaient une chose, les autres une autre. Ne pouvant donc rien apprendre de certain, à cause du tumulte, il ordonna de l''emmener dans la forteresse.'),
('ac',21,35,'crampon1923','Lorsque Paul fut sur les degrés, il dut être porté par les soldats, à cause de la violence de la multitude.'),
('ac',21,36,'crampon1923','Car le peuple suivait en foule en criant: " Fais-le mourir. "'),
('ac',21,37,'crampon1923','Au moment d''être introduit dans la forteresse, Paul dit au tribun: " M''est-il permis de te dire quelque chose? — " Tu sais le grec? répondit le tribun.'),
('ac',21,38,'crampon1923','Tu n''es donc pas l''Egyptien qui s''est révolté dernièrement et qui a emmené au désert quatre mille sicaires? "'),
('ac',21,39,'crampon1923','Paul lui dit: " Je suis Juif, de Tarse en Cilicie, citoyen d''une ville qui n''est pas sans renom. Je t''en prie, permets-moi de parler au peuple. "'),
('ac',21,40,'crampon1923','Le tribun le lui ayant permis, Paul debout sur les degrés, fit signe de la main au peuple. Un profond silence s''établit, et Paul, s''exprimant en langue hébraïque, leur parla ainsi:'),
('ac',22,1,'crampon1923','" Mes frères et mes pères, écoutez ce que j''ai maintenant à vous dire pour ma défense. " —'),
('ac',22,2,'crampon1923','Dès qu''ils entendirent qu''il leur parlait en langue hébraïque, ils firent encore plus de silence.'),
('ac',22,3,'crampon1923','Et Paul dit: " Je suis Juif, né à Tarse en Cilicie; mais j''ai été élevé dans cette ville et instruit aux pieds de Gamaliel dans la connaissance exacte de la Loi de nos pères, étant plein de zèle pour Dieu, comme vous l''êtes tous aujourd''hui.'),
('ac',22,4,'crampon1923','C''est moi qui ai persécuté cette secte jusqu''à la mort, chargeant de chaînes et jetant en prison hommes et femmes:'),
('ac',22,5,'crampon1923','le grand-prêtre et tous les Anciens m''en sont témoins. Ayant même reçu d''eux des lettres pour les frères, je partis pour Damas afin d''amener enchaînés à Jérusalem ceux qui se trouvaient là, et de les faire punir.'),
('ac',22,6,'crampon1923','Mais comme j''étais en chemin, et déjà près de Damas, tout à coup, vers midi, une vive lumière venant du ciel resplendit autour de moi.'),
('ac',22,7,'crampon1923','Je tombai par terre, et j''entendis une voix qui me disait: Saul, Saul, pourquoi me persécutes-tu?'),
('ac',22,8,'crampon1923','Je répondis: Qui êtes-vous, Seigneur? Et il me dit: Je suis Jésus de Nazareth, que tu persécutes.'),
('ac',22,9,'crampon1923','Ceux qui étaient avec moi virent bien la lumière, mais ils n''entendirent pas la voix de celui qui me parlait.'),
('ac',22,10,'crampon1923','Alors je dis: Que dois-je faire, Seigneur? Et le Seigneur me répondit: Lève-toi, va à Damas, et là on te dira tout ce que tu dois faire.'),
('ac',22,11,'crampon1923','Et comme par suite de l''éclat de cette lumière je ne voyais plus, ceux qui étaient avec moi me prirent par la main, et j''arrivai à Damas.'),
('ac',22,12,'crampon1923','Or un homme pieux selon la Loi, nommé Ananie, et de qui tous les Juifs de la ville rendaient un bon témoignage,'),
('ac',22,13,'crampon1923','vint me voir, et s''étant approché de moi, me dit: Saul, mon frère, recouvre la vue. Et au même instant je le vis.'),
('ac',22,14,'crampon1923','Il dit alors: Le Dieu de nos pères t''a prédestiné à connaître sa volonté, à voir le Juste et entendre les paroles de sa bouche.'),
('ac',22,15,'crampon1923','Car tu lui serviras de témoin, devant tous les hommes, des choses que tu as vues et entendues.'),
('ac',22,16,'crampon1923','Et maintenant que tardes-tu? Lève-toi, reçois le baptême et purifie-toi de tes péchés, en invoquant son nom. —'),
('ac',22,17,'crampon1923','De retour à Jérusalem, comme je priais dans le temple, il m''arriva d''être ravi en esprit,'),
('ac',22,18,'crampon1923','et je vis le Seigneur qui me disait: Hâte-toi et sors au plus tôt de Jérusalem, parce qu''on n''y recevra pas le témoignage que tu rendras de moi. —'),
('ac',22,19,'crampon1923','Seigneur, répondis-je, ils savent eux-mêmes que je faisais mettre en prison et battre de verges dans les synagogues ceux qui croyaient en vous,'),
('ac',22,20,'crampon1923','et lorsqu''on répandit le sang d''Etienne, votre témoin, j''étais moi-même présent, joignant mon approbation à celle des autres et gardant les vêtements de ceux qui le lapidaient.'),
('ac',22,21,'crampon1923','Alors il me dit: Va, c''est aux nations lointaines que je veux t''envoyer. "'),
('ac',22,22,'crampon1923','Les Juifs l''avaient écouté jusqu''à ces mots; ils élevèrent alors la voix, en disant: " Ote de la terre un pareil homme; il n''est pas digne de vivre. "'),
('ac',22,23,'crampon1923','Et comme ils poussaient de grands cris, jetant leurs manteaux et lançant de la poussière en l''air,'),
('ac',22,24,'crampon1923','le tribun ordonna de faire entrer Paul dans la forteresse et de lui donner la question par le fouet, afin de savoir pour quel motif ils criaient ainsi contre lui.'),
('ac',22,25,'crampon1923','Déjà les soldats l''avaient lié avec les courroies, lorsque Paul dit au centurion qui était là: " Vous est-il permis de flageller un citoyen romain, qui n''est pas même condamné? "'),
('ac',22,26,'crampon1923','A ces mots, le centurion alla trouver le tribun pour l''avertir, et lui dit: " Que vas-tu faire? Cet homme est citoyen romain. "'),
('ac',22,27,'crampon1923','Le tribun vint et dit à Paul: " Dis-moi, es-tu citoyen romain? " " Oui, " répondit-il;'),
('ac',22,28,'crampon1923','et le tribun repris: " Moi, j''ai acheté bien cher ce droit de cité. " — " Et moi, dit Paul, je l''ai par ma naissance. "'),
('ac',22,29,'crampon1923','Aussitôt ceux qui se disposaient à lui donner la question se retirèrent; et le tribun aussi eut peur, quand il sut que Paul était citoyen romain et qu''il l''avait fait lier.'),
('ac',22,30,'crampon1923','Le lendemain, voulant savoir exactement de quoi les Juifs l''accusaient, il lui fit ôter ses liens, et donna l''ordre aux princes des prêtres et à tout le Sanhédrin de se réunir; puis, ayant fait descendre Paul, il le plaça au milieu d''eux.'),
('ac',23,1,'crampon1923','Paul, les regards fixés sur le Sanhédrin, dit: " Mes frères, je me suis conduit devant Dieu jusqu''à ce jour dans toute la droiture d''une bonne conscience... "'),
('ac',23,2,'crampon1923','Le grand prêtre Ananie ordonna à ses satellites de le frapper sur la bouche.'),
('ac',23,3,'crampon1923','Alors Paul lui dit: " Certainement, Dieu te frappera, muraille blanchie! Tu sièges ici pour me juger selon la Loi, et, au mépris de la Loi, tu ordonnes qu''on me frappe! "'),
('ac',23,4,'crampon1923','Les assistants dirent: " Tu outrages le grand-prêtre de Dieu! "'),
('ac',23,5,'crampon1923','Paul répondit: " Je ne savais pas, mes frères, qu''il fût grand-prêtre; car il est écrit: Tu ne proféreras pas d''injure contre un chef de ton peuple. "'),
('ac',23,6,'crampon1923','Paul, sachant qu''une partie de l''assemblée était composée de Sadducéens et l''autre de Pharisiens, s''écria dans le Sanhédrin: " Mes frères, je suis Pharisien, fils de Pharisiens; c''est à cause de l''espérance en la résurrection des morts que je suis mis en jugement. "'),
('ac',23,7,'crampon1923','Dès qu''il eut prononcé ces paroles, il s''éleva une discussion entre les Pharisiens et les Sadducéens, et l''assemblée se divisa.'),
('ac',23,8,'crampon1923','Car les Sadducéens disent qu''il n''y a point de résurrection, ni d''ange et d''esprit, tandis que les Pharisiens affirment l''un et l''autre.'),
('ac',23,9,'crampon1923','Il y eut donc une bruyante agitation, et quelques Scribes du parti des Pharisiens, s''étant levés, engagèrent un vif débat, et dirent: " Nous ne trouvons rien à reprendre en cet homme; si un esprit ou un ange lui avait parlé?... "'),
('ac',23,10,'crampon1923','Comme la discorde allait croissant, le tribun, craignant que Paul ne fût mis en pièces par eux, ordonna à des soldats de descendre pour l''enlever du milieu d''eux et de le ramener dans la forteresse.'),
('ac',23,11,'crampon1923','La nuit suivante, le Seigneur apparut à Paul et lui dit: " Courage! De même que tu as rendu témoignage de moi dans Jérusalem, il faut aussi que tu me rendes témoignage dans Rome. "'),
('ac',23,12,'crampon1923','Dès que le jour parut, les Juifs ourdirent un complot et jurèrent avec des imprécations contre eux-mêmes, de ne manger ni boire jusqu''à ce qu''ils eussent tué Paul.'),
('ac',23,13,'crampon1923','Il y en avait plus de quarante qui s''étaient engagés dans cette conjuration.'),
('ac',23,14,'crampon1923','Ils allèrent trouver le prince des prêtres et les Anciens et dirent: " Nous avons solennellement juré de ne prendre aucune nourriture que nous n''ayons tué Paul.'),
('ac',23,15,'crampon1923','Vous donc, maintenant, adressez-vous avec le Sanhédrin au tribun, pour qu''il l''amène devant vous, comme si vous vouliez examiner plus à fond sa cause; et nous, nous sommes prêts à le tuer pendant le trajet. "'),
('ac',23,16,'crampon1923','Le fils de la sœur de Paul ayant eu connaissance du complot, accourut à la forteresse et en donna avis à Paul.'),
('ac',23,17,'crampon1923','Celui-ci appela un des centurions et lui dit: " Mène ce jeune homme vers le tribun, car il a quelque chose à lui révéler. "'),
('ac',23,18,'crampon1923','Le centurion, prenant le jeune homme avec lui, le mena au tribun et dit: " Le prisonnier Paul m''a prié de t''amener ce jeune homme qui a quelque chose à te dire. "'),
('ac',23,19,'crampon1923','Le tribun le prit par la main, et l''ayant tiré à part, il lui demanda: " Qu''as-tu à me communiquer? "'),
('ac',23,20,'crampon1923','Il répondit: " Les Juifs sont convenus de te prier de faire demain comparaître Paul devant le Sanhédrin, sous le prétexte d''examiner plus à fond sa cause.'),
('ac',23,21,'crampon1923','Ne les écoute pas, car plus de quarante d''entre eux lui dressent des embûches, et se sont engagés, avec des imprécations contre eux-mêmes, à ne manger ni boire avant qu''ils ne l''aient tué. Ils sont tout prêts et n''attendent que ton ordre. "'),
('ac',23,22,'crampon1923','Le tribun renvoya ce jeune homme, après lui avoir recommandé de ne dire à personne qu''il lui avait fait ce rapport.'),
('ac',23,23,'crampon1923','Et ayant appelé deux centurions, il leur dit: " Tenez prêts, dès la troisième heure de la nuit, deux cents soldats avec soixante-dix cavaliers et deux cents lanciers, pour aller jusqu''à Césarée.'),
('ac',23,24,'crampon1923','Préparez aussi des chevaux pour y faire monter Paul, afin de le conduire sain et sauf au gouverneur Félix. "'),
('ac',23,25,'crampon1923','Il avait écrit une lettre ainsi conçue:'),
('ac',23,26,'crampon1923','" Claude Lysias, au très excellent gouverneur Félix, salut.'),
('ac',23,27,'crampon1923','Les Juifs s''étaient saisis de cet homme et allaient le tuer, lorsque je survins avec des soldats et l''arrachai de leurs mains, ayant appris qu''il était Romain.'),
('ac',23,28,'crampon1923','Voulant savoir de quel crime ils l''accusaient, je le menai devant leur assemblée,'),
('ac',23,29,'crampon1923','et je trouvai qu''il était accusé au sujet de questions relatives à leur loi, mais n''avait commis aucun crime qui méritât la mort ou la prison.'),
('ac',23,30,'crampon1923','Informé que les Juifs lui dressaient des embûches, je te l''ai immédiatement envoyé, en faisant savoir à ses accusateurs qu''ils eussent à s''expliquer devant toi à son sujet. [Adieu.] "'),
('ac',23,31,'crampon1923','Les soldats ayant donc pris Paul, selon l''ordre qu''ils avaient reçu, le conduisirent pendant la nuit à Antipatris.'),
('ac',23,32,'crampon1923','Le lendemain, laissant les cavaliers poursuivre la route avec le prisonnier, ils retournèrent à la forteresse.'),
('ac',23,33,'crampon1923','Arrivés à Césarée, les cavaliers remirent la lettre au gouverneur et lui présentèrent Paul.'),
('ac',23,34,'crampon1923','Le gouverneur, après avoir lu la lettre, demanda de quelle province était Paul, et apprenant qu''il était de Cilicie:'),
('ac',23,35,'crampon1923','" Je t''entendrai, dit-il, quand tes accusateurs seront venus. " Et il ordonna de le garder dans le prétoire d''Hérode.'),
('ac',24,1,'crampon1923','Cinq jours après, arriva le grand prêtre Ananie, avec quelques Anciens et un certain rhéteur nommé Tertullus; ils portèrent plainte au gouverneur contre Paul.'),
('ac',24,2,'crampon1923','Celui-ci ayant été appelé, Tertullus se mit à l''accuser en ces termes: " Jouissant d''une paix profonde, grâce à toi, excellent Félix, et aux réformes que ta prévoyance a opérées en faveur de cette nation,'),
('ac',24,3,'crampon1923','nous les accueillons toujours et partout avec une entière reconnaissance.'),
('ac',24,4,'crampon1923','Mais, pour ne pas t''arrêter davantage, je te prie de nous écouter un moment avec ta bonté ordinaire.'),
('ac',24,5,'crampon1923','Nous avons trouvé cet homme: c''est une peste, un homme qui excite des troubles parmi les Juifs dans le monde entier, un chef de la secte des Nazaréens,'),
('ac',24,6,'crampon1923','et qui même a tenté de profaner le temple; aussi nous l''avons arrêté. [et nous voulions le juger selon notre loi.'),
('ac',24,7,'crampon1923','Mais le tribun Lysias étant survenu, l''a arraché violemment de nos mains,'),
('ac',24,8,'crampon1923','et il a ordonné que ses accusateurs vinssent devant toi]. Tu pourras toi-même, en l''interrogeant, apprendre de sa bouche tout ce dont nous l''accusons. "'),
('ac',24,9,'crampon1923','Les Juifs se joignirent à cette accusation, soutenant que les choses étaient ainsi.'),
('ac',24,10,'crampon1923','Après que le gouverneur lui eut fait signe de parler, Paul répondit: " C''est avec confiance que je prends la parole pour me justifier, car je sais que tu gouvernes cette nation depuis plusieurs années.'),
('ac',24,11,'crampon1923','Il n''y a pas plus de douze jours, tu peux t''en assurer, que je suis monté à Jérusalem pour adorer.'),
('ac',24,12,'crampon1923','Et l''on ne m''a pas vu dans le temple parler à quelqu''un, ni ameuter la foule, soit dans les synagogues,'),
('ac',24,13,'crampon1923','soit dans la ville; et ils ne sauraient prouver ce dont ils m''accusent maintenant.'),
('ac',24,14,'crampon1923','Je te confesse que je sers le Dieu de nos pères selon la religion qu''ils appellent une secte, croyant tout ce qui est écrit dans la Loi et les Prophètes,'),
('ac',24,15,'crampon1923','et ayant en Dieu cette espérance, comme ils l''ont eux-mêmes, qu''il y aura une résurrection des justes et des pécheurs.'),
('ac',24,16,'crampon1923','C''est pourquoi moi aussi je m''efforce d''avoir constamment une conscience sans reproche devant Dieu et devant les hommes.'),
('ac',24,17,'crampon1923','Je suis donc venu, après plusieurs années, pour faire des aumônes à mes compatriotes et pour présenter des oblations.'),
('ac',24,18,'crampon1923','C''est alors que j''ai été trouvé dans le temple, après ma consécration, sans attroupement ni tumulte,'),
('ac',24,19,'crampon1923','par certains Juifs d''Asie; c''était à eux de paraître devant toi comme accusateurs, s''ils avaient quelque chose à me reprocher.'),
('ac',24,20,'crampon1923','Ou bien que ceux-ci disent de quel crime ils m''ont trouvé coupable, lorsque j''ai comparu devant le Sanhédrin,'),
('ac',24,21,'crampon1923','à moins qu''on me fasse un crime de cette seule parole que j''ai dite à haute voix devant eux: C''est à cause de la résurrection des morts que je suis aujourd''hui mis en jugement devant vous. "'),
('ac',24,22,'crampon1923','Félix, qui connaissait bien cette religion les ajourna, en disant: " Quand le tribun Lysias sera venu je connaîtrai à fond votre affaire. "'),
('ac',24,23,'crampon1923','Et il donna l''ordre au centurion de garder Paul, mais en lui laissant quelque liberté, et sans empêcher aucun des siens de lui rendre des services.'),
('ac',24,24,'crampon1923','Quelques jours après, Félix vint avec Drusille, sa femme, qui était juive. Ayant fait appeler Paul, il l''entendit sur la foi en Jésus-Christ.'),
('ac',24,25,'crampon1923','Mais Paul en étant venu à parler de justice, de tempérance et de jugement à venir, Félix effrayé dit: " Pour le moment, retire-toi; je te rappellerai à la première occasion. "'),
('ac',24,26,'crampon1923','Il espérait en même temps que Paul lui donnerait de l''argent; aussi le faisait-il venir assez fréquemment pour s''entretenir avec lui.'),
('ac',24,27,'crampon1923','Deux ans s''écoulèrent ainsi, et Félix eut pour successeur Porcius Festus; et, dans le désir d''être agréable aux Juifs, il laissa Paul en prison.'),
('ac',25,1,'crampon1923','Festus, étant donc arrivé dans sa province, monta trois jours après de Césarée à Jérusalem.'),
('ac',25,2,'crampon1923','Les chefs des prêtres et les principaux d''entre les Juifs vinrent lui porter plainte contre Paul. Avec beaucoup d''instances'),
('ac',25,3,'crampon1923','ils lui demandèrent comme une faveur, dans un but hostile à l''Apôtre, qu''il le fît transférer à Jérusalem; ils préparaient un guet-apens pour le faire périr en route.'),
('ac',25,4,'crampon1923','Festus répondit que Paul était gardé à Césarée et que lui-même y retournerait sous peu.'),
('ac',25,5,'crampon1923','" Que ceux d''entre vous, ajouta-t-il, qui ont qualité pour cela, descendent avec moi, et s''il y a des charges contre cet homme, qu''ils l''accusent. "'),
('ac',25,6,'crampon1923','Après avoir seulement passé huit ou dix jours à Jérusalem, Festus descendit à Césarée. Le lendemain, ayant pris place sur son tribunal, il fit amener Paul.'),
('ac',25,7,'crampon1923','Quand on l''eut amené, les Juifs venus de Jérusalem l''entourèrent, en portant contre lui de nombreuses et graves accusations, qu''ils ne pouvaient prouver.'),
('ac',25,8,'crampon1923','Paul dit pour sa défense: " Je n''ai rien fait de répréhensible, ni contre la loi des Juifs, ni contre le temple, ni contre César. "'),
('ac',25,9,'crampon1923','Festus, qui voulait faire plaisir aux Juifs, dit à Paul: " Veux-tu monter à Jérusalem et y être jugé sur ces griefs en ma présence? "'),
('ac',25,10,'crampon1923','Paul répondit: " Je suis devant le tribunal de César; c''est là que je dois être jugé. Je n''ai fait aucun tort aux Juifs, comme tu le sais bien toi-même.'),
('ac',25,11,'crampon1923','Si j''ai commis quelque injustice ou quelque attentat qui mérite la mort, je ne refuse pas de mourir; mais s''il n''y a rien de fondé dans leurs accusations, personne n''a le droit de me livrer à eux. J''en appelle à César. "'),
('ac',25,12,'crampon1923','Alors Festus, après en avoir conféré avec son conseil, répondit: " Tu en as appelé à César, tu iras à César. "'),
('ac',25,13,'crampon1923','Quelques jours après le roi Agrippa et Bérénice arrivèrent à Césarée pour saluer Festus.'),
('ac',25,14,'crampon1923','Comme ils y passèrent plusieurs jours, Festus exposa au roi l''affaire de Paul, en disant: " Il y a ici un homme que Félix a laissé prisonnier.'),
('ac',25,15,'crampon1923','Lorsque j''étais à Jérusalem, les princes des prêtres et les Anciens des Juifs ont porté plainte contre lui, demandant sa condamnation.'),
('ac',25,16,'crampon1923','Je leur ai répondu que ce n''est pas la coutume des Romains de livrer un homme avant d''avoir confronté l''accusé avec ses accusateurs et de lui avoir donné les moyens de se justifier de ce dont on l''accuse.'),
('ac',25,17,'crampon1923','Ils sont donc venus ici, et, sans différer, j''ai pris place le lendemain sur mon tribunal, et j''ai ordonné de m''amener cet homme.'),
('ac',25,18,'crampon1923','Les accusateurs, s''étant présentés, ne lui imputèrent aucun des crimes que je supposais;'),
('ac',25,19,'crampon1923','mais ils eurent avec lui des controverses ayant trait à leur religion particulière et à un certain Jésus, qui est mort et que Paul affirmait être vivant.'),
('ac',25,20,'crampon1923','Comme j''étais embarrassé pour faire une enquête sur ces matières, je lui demandai s''il voulait aller à Jérusalem et y être jugé sur ces accusations.'),
('ac',25,21,'crampon1923','Mais Paul en ayant appelé, pour que sa cause fût réservée à la connaissance de l''empereur, j''ai ordonné de le garder jusqu''à ce que je l''envoie à César. "'),
('ac',25,22,'crampon1923','Agrippa dit à Festus: " J''aurais voulu, moi aussi, entendre cet homme. " — " Demain, répondit Festus, tu l''entendras. "'),
('ac',25,23,'crampon1923','Le lendemain, Agrippa et Bérénice vinrent en grand faste. Quand ils furent dans la salle d''audience avec les tribuns et les principaux personnages de la ville, Paul fut amené par l''ordre de Festus.'),
('ac',25,24,'crampon1923','Et Festus dit: " Roi Agrippa, et vous tous qui êtes présents avec nous, vous avez devant vous l''homme au sujet duquel les Juifs sont venus en foule me parler soit à Jérusalem, soit ici, en criant qu''il ne fallait plus le laisser vivre.'),
('ac',25,25,'crampon1923','Pour moi, ayant reconnu qu''il n''a rien fait qui mérite la mort, et lui-même en ayant appelé à l''empereur, j''ai résolu de le lui envoyer.'),
('ac',25,26,'crampon1923','Comme je n''ai rien de précis à écrire à l''empereur sur son compte, je l''ai fait comparaître devant vous, et surtout devant toi, roi Agrippa, afin qu''après cette audience je puisse rédiger mon rapport.'),
('ac',25,27,'crampon1923','Car il me paraît déraisonnable d''envoyer un prisonnier, sans indiquer en même temps de quoi on l''accuse. "'),
('ac',26,1,'crampon1923','Agrippa dit à Paul: " Tu as la parole pour ta défense. " Alors Paul, étendant la main, se justifia en ces termes:'),
('ac',26,2,'crampon1923','" Je m''estime heureux, roi Agrippa, d''avoir aujourd''hui à me justifier devant toi de toutes les accusations portées contre moi par les Juifs;'),
('ac',26,3,'crampon1923','car tu connais mieux que personne leurs coutumes et leurs controverses. Je te prie donc de m''écouter avec patience.'),
('ac',26,4,'crampon1923','Ma vie, dès les premiers temps de ma jeunesse, est connue de tous les Juifs, puisqu''elle s''est passée à Jérusalem, au milieu de ma nation.'),
('ac',26,5,'crampon1923','Me connaissant ainsi depuis longtemps, ils savent, s''ils veulent en rendre témoignage, que j''ai vécu en pharisien selon la secte la plus austère de notre religion.'),
('ac',26,6,'crampon1923','Et maintenant je suis mis en jugement parce que j''espère en la promesse que Dieu a faite à nos pères,'),
('ac',26,7,'crampon1923','promesse dont nos douze tribus, en servant Dieu sans relâche, nuit et jour, attendent la réalisation. C''est pour cette espérance, ô roi, que les Juifs m''accusent!'),
('ac',26,8,'crampon1923','Vous semble-t-il donc incroyable que Dieu ressuscite les morts?'),
('ac',26,9,'crampon1923','Moi aussi j''avais cru que je devais m''opposer de toutes mes forces au nom de Jésus de Nazareth.'),
('ac',26,10,'crampon1923','C''est ce que j''ai fait à Jérusalem; j''ai fait enfermer dans les prisons un grand nombre de saints, en ayant reçu le pouvoir des princes des prêtres; et quand on les mettait à mort, j''y donnais mon suffrage.'),
('ac',26,11,'crampon1923','Souvent, parcourant toutes les synagogues et sévissant contre eux, je les ai forcés de blasphémer; et ma fureur allant toujours croissant, je les poursuivais jusque dans les villes étrangères.'),
('ac',26,12,'crampon1923','Comme j''allais ainsi à Damas, avec de pleins pouvoirs et un mandat des chefs des prêtres,'),
('ac',26,13,'crampon1923','vers le milieu du jour, je vis sur le chemin, ô roi, une lumière venant du ciel, plus éclatante que celle du soleil, resplendir autour de moi et de mes compagnons.'),
('ac',26,14,'crampon1923','Nous tombâmes tous par terre, et j''entendis une voix qui me disait en langue hébraïque: Saul, Saul, pourquoi me persécutes-tu? Il te serait dur de regimber contre l''aiguillon. —'),
('ac',26,15,'crampon1923','Qui êtes-vous, Seigneur? m''écriai-je. Et le Seigneur dit: Je suis Jésus, que tu persécutes.'),
('ac',26,16,'crampon1923','Mais relève-toi, et tiens-toi ferme sur tes pieds, car je t''ai apparu, afin de te constituer ministre et témoin des choses que tu as vues et de celles pour lesquelles je t''apparaîtrai encore.'),
('ac',26,17,'crampon1923','Je t''ai tiré du milieu de ce peuple et des Gentils auxquels maintenant je t''envoie,'),
('ac',26,18,'crampon1923','pour leur ouvrir les yeux, afin qu''ils passent des ténèbres à la lumière, et de la puissance de Satan à Dieu, et qu''ainsi, par la foi en moi, ils reçoivent la rémission des péchés et l''héritage avec les sanctifiés.'),
('ac',26,19,'crampon1923','Je n''ai donc pas résisté, roi Agrippa, à la vision céleste;'),
('ac',26,20,'crampon1923','mais d''abord j''ai prêché, à ceux de Damas, puis à Jérusalem, et dans toute la Judée, et parmi les Gentils, le repentir et la conversion à Dieu, par la pratique d''œuvres dignes de la pénitence.'),
('ac',26,21,'crampon1923','Voilà pourquoi les Juifs se sont saisis de moi dans le temple et ont essayé de me faire périr.'),
('ac',26,22,'crampon1923','C''est donc grâce au secours de Dieu que je suis resté debout jusqu''à ce jour, rendant témoignage devant les petits et les grands, sans dire autre chose que ce que Moïse et les prophètes ont prédit,'),
('ac',26,23,'crampon1923','savoir, que le Christ devait souffrir, et que, ressuscité le premier d''entre les morts, il annoncerait la lumière au peuple et aux Gentils... "'),
('ac',26,24,'crampon1923','Comme il parlait ainsi pour sa défense, Festus dit à haute voix: " Tu déraisonnes, Paul; ton grand savoir égare ton esprit. "'),
('ac',26,25,'crampon1923','" Je ne déraisonne pas, très excellent Festus, répondit Paul; je parle le langage de la vérité et de la sagesse.'),
('ac',26,26,'crampon1923','Le roi est instruit de ces choses, et je lui en parle librement, persuadé qu''il n''en ignore aucune; car rien de tout cela ne s''est passé dans un coin.'),
('ac',26,27,'crampon1923','Crois-tu aux prophètes, roi Agrippa? Je sais que tu y crois. "'),
('ac',26,28,'crampon1923','Agrippa dit à Paul: " Peu s''en faut que tu ne me persuades de devenir chrétien. " —'),
('ac',26,29,'crampon1923','" Qu''il s''en faille de peu ou de beaucoup, repartit Paul, plût à Dieu que non seulement toi, mais encore tous ceux qui m''écoutent en ce moment, vous fussiez tels que je suis, à l''exception de ces chaînes! "'),
('ac',26,30,'crampon1923','Alors le roi se leva, et avec lui le gouverneur, Bérénice et toute leur suite.'),
('ac',26,31,'crampon1923','S''étant retirés, ils se disaient les uns aux autres: " Cet homme n''a rien fait qui mérite la mort ou la prison. "'),
('ac',26,32,'crampon1923','Et Agrippa dit à Festus: " On pourrait le relâcher, s''il n''en avait pas appelé à César. "'),
('ac',27,1,'crampon1923','Lorsqu''il eut été décidé que nous irions par mer en Italie, on remit Paul et quelques autres prisonniers à un centurion nommé Julius, de la cohorte Augusta.'),
('ac',27,2,'crampon1923','Nous montâmes sur un vaisseau d''Adramytte qui devait longer les côtes de l''Asie, et nous levâmes l''ancre, ayant avec nous Aristarque, Macédonien de Thessalonique.'),
('ac',27,3,'crampon1923','Le jour suivant, nous abordâmes à Sidon; et Julius, qui traitait Paul avec bienveillance, lui permit d''aller chez ses amis et de recevoir leurs soins.'),
('ac',27,4,'crampon1923','Etant partis de là, nous côtoyâmes l''île de Chypre, parce que les vents étaient contraires.'),
('ac',27,5,'crampon1923','Après avoir traversé la mer qui baigne la Cilicie et la Pamphylie, nous arrivâmes à Myre, en Lycie.'),
('ac',27,6,'crampon1923','Le centurion y ayant trouvé un navire d''Alexandrie qui faisait voile pour l''Italie, il nous y fit monter.'),
('ac',27,7,'crampon1923','Pendant plusieurs jours nous navigâmes lentement, et ce ne fut pas sans difficulté que nous arrivâmes à la hauteur de Cnide, où le vent ne nous permit pas d''aborder. Nous passâmes au-dessous de l''île de Crète, du côté de Salmoné,'),
('ac',27,8,'crampon1923','et longeant la côte avec peine, nous arrivâmes à un lieu nommé Bons-Ports, près duquel était la ville de Laséa.'),
('ac',27,9,'crampon1923','Un temps assez long s''était écoulé et la navigation devenait dangereuse, car l''époque du jeûne était déjà passée. Paul fit des représentations à l''équipage:'),
('ac',27,10,'crampon1923','" Mes amis, leur dit-il, je vois que la navigation ne pourra se faire sans danger et sans de graves dommages, non seulement pour la cargaison et le navire, mais encore pour nos personnes. "'),
('ac',27,11,'crampon1923','Mais le centurion avait plus de confiance en ce que disait le pilote et le patron du navire, que dans les paroles de Paul.'),
('ac',27,12,'crampon1923','Et comme le port n''était pas bon pour hiverner, la plupart furent d''avis de reprendre la mer et de tâcher d''atteindre, pour y passer l''hiver, Phénice, port de Crète qui regarde l''Africus et le Corus.'),
('ac',27,13,'crampon1923','Un léger vent du sud vint à souffler; se croyant maîtres d''exécuter leur dessin, ils levèrent l''ancre et rasèrent plus près les côtes de Crète.'),
('ac',27,14,'crampon1923','Mais bientôt un vent impétueux, nommé Euraquilon, se déchaîna sur l''île.'),
('ac',27,15,'crampon1923','Le navire fut entraîné, sans pouvoir lutter contre l''ouragan, et nous nous laissâmes aller à la dérive.'),
('ac',27,16,'crampon1923','Nous passâmes rapidement au-dessous d''une petite île, nommée Cauda, et nous eûmes beaucoup de peine à remonter la chaloupe.'),
('ac',27,17,'crampon1923','Quand on l''eut hissée, les matelots, ayant recours à tous les moyens de salut, ceintrèrent le navire, et dans la crainte d''échouer sur la Syrte, ils abattirent la voilure et se laissèrent aller.'),
('ac',27,18,'crampon1923','Comme nous étions violemment battus par la tempête, on jeta le lendemain la cargaison à la mer,'),
('ac',27,19,'crampon1923','et le jour suivant nous y lançâmes de nos propres mains les agrès du navire.'),
('ac',27,20,'crampon1923','Pendant plusieurs jours, ni le soleil ni les étoiles ne se montrèrent, et la tempête continuait de sévir avec violence: tout espoir de salut s''était évanoui.'),
('ac',27,21,'crampon1923','Depuis longtemps personne n''avait mangé. Paul, se levant alors au milieu d''eux, leur dit: " Vous auriez dû m''écouter, mes amis, ne point partir de Crète, et vous épargner ce péril et ce dommage.'),
('ac',27,22,'crampon1923','Cependant je vous exhorte à prendre courage, car aucun de vous ne perdra la vie; le vaisseau seul sera perdu.'),
('ac',27,23,'crampon1923','Cette nuit même un ange de Dieu à qui j''appartiens et que je sers, m''est apparu,'),
('ac',27,24,'crampon1923','et m''a dit: Paul, ne crains point; il faut que tu comparaisses devant César, et voici que Dieu t''a donné tous ceux qui naviguent avec toi.'),
('ac',27,25,'crampon1923','Courage donc, mes amis; car j''ai confiance en Dieu qu''il en sera comme il m''a été dit.'),
('ac',27,26,'crampon1923','Nous devons échouer sur une île. "'),
('ac',27,27,'crampon1923','La quatorzième nuit, comme nous étions ballottés dans l''Adriatique, les matelots soupçonnèrent, vers le milieu de la nuit, qu''on approchait de quelque terre.'),
('ac',27,28,'crampon1923','Jetant aussitôt la sonde, ils trouvèrent vingt brasses; un peu plus loin, il la jetèrent de nouveau, et en trouvèrent quinze.'),
('ac',27,29,'crampon1923','Dans la crainte de heurter contre des récifs, ils jetèrent quatre ancres de la poupe, et attendirent le jour avec impatience.'),
('ac',27,30,'crampon1923','Mais comme les matelots cherchaient à s''échapper du navire, et que déjà, sous prétexte d''aller jeter des ancres du côté de la proue, ils avaient mis la chaloupe à flot,'),
('ac',27,31,'crampon1923','Paul dit au centurion et aux soldats: " Si ces hommes ne restent pas dans le navire, vous êtes tous perdus. "'),
('ac',27,32,'crampon1923','Alors les soldats coupèrent les amarres de la chaloupe, et la laissèrent tomber.'),
('ac',27,33,'crampon1923','En attendant le jour, Paul exhorta tout le monde à prendre de la nourriture: " Voici, leur dit-il, le quatorzième jour que, remplis d''anxiété, vous restez à jeun sans rien prendre.'),
('ac',27,34,'crampon1923','Je vous engage donc à manger, car cela importe à votre salut; aucun de vous ne perdra un cheveu de sa tête. "'),
('ac',27,35,'crampon1923','Ayant ainsi parlé, il prit du pain, et après avoir rendu grâces à Dieu devant tous, il le rompit et se mit à manger.'),
('ac',27,36,'crampon1923','Et tous, reprenant courage, mangèrent aussi.'),
('ac',27,37,'crampon1923','Nous étions en tout, sur le bâtiment, deux cent soixante-seize personnes.'),
('ac',27,38,'crampon1923','Quand ils eurent mangés suffisamment, ils allégèrent le navire en jetant les provisions à la mer.'),
('ac',27,39,'crampon1923','Le jour étant venu, ils ne reconnurent pas la côte; mais ayant aperçu une baie qui avait une plage de sable, ils résolurent de faire échouer le navire, s''ils le pouvaient.'),
('ac',27,40,'crampon1923','On coupa donc les amarres des ancres, qu''on abandonna à la mer; on lâcha en même temps les attaches des gouvernails, on mit au vent la voile d''artimon et on se dirigea vers la plage.'),
('ac',27,41,'crampon1923','Mais ayant touché sur une langue de terre, ils y échouèrent; la proue s''enfonça et resta immobile, tandis que la poupe se disloquait sous la violence des vagues.'),
('ac',27,42,'crampon1923','Les soldats furent d''avis de tuer les prisonniers, de peur que quelqu''un d''entre eux ne s''échappât à la nage.'),
('ac',27,43,'crampon1923','Mais le centurion, qui voulait sauver Paul, les empêcha d''exécuter leur dessein. Il ordonna à ceux qui savaient nager de se jeter à l''eau les premiers et de gagner la terre,'),
('ac',27,44,'crampon1923','et aux autres de se mettre sur des planches ou sur des débris du vaisseau. Et ainsi tous atteignirent le rivage sains et saufs.'),
('ac',28,1,'crampon1923','Une fois sauvés, nous reconnûmes que l''île s''appelait Malte. Les barbares nous traitèrent avec une bienveillance peu commune;'),
('ac',28,2,'crampon1923','ils nous recueillirent tous autour d''un grand feu qu''ils avaient allumé, à cause de la pluie qui était survenue, et du froid.'),
('ac',28,3,'crampon1923','Paul ayant ramassé quelques broussailles et les ayant jetées dans le brasier, une vipère, que la chaleur en fit sortir, s''attacha à sa main.'),
('ac',28,4,'crampon1923','En voyant ce reptile qui pendait à sa main, les barbares se dirent les uns aux autres: " Sans aucun doute, cet homme est un meurtrier; car, après qu''il a été sauvé de la mer, la Justice divine n''a pas voulu le laisser vivre. "'),
('ac',28,5,'crampon1923','Lui, cependant, secoua la vipère dans le feu et n''en ressentit aucun mal.'),
('ac',28,6,'crampon1923','Les barbares s''attendaient à le voir enfler ou tomber mort subitement. Mais après avoir longtemps attendu, voyant qu''il ne lui arrivait aucun mal, ils changèrent de sentiment, et dirent: C''est un dieu.'),
('ac',28,7,'crampon1923','Il y avait, dans le voisinage, des terres appartenant au premier personnage de l''île, nommé Publius; qui nous reçut et nous donna pendant trois jours l''hospitalité la plus amicale.'),
('ac',28,8,'crampon1923','Le père de Publius était alors au lit, malade de la fièvre et de la dysenterie. Paul alla le visiter, et après avoir prié, il lui imposa les mains et le guérit.'),
('ac',28,9,'crampon1923','Sur quoi tous les autres malades de l''île vinrent le trouver, et ils furent guéris.'),
('ac',28,10,'crampon1923','On nous rendit de grands honneurs à notre départ, et on nous pourvut de ce dont nous avions besoin.'),
('ac',28,11,'crampon1923','Après un séjour de trois mois, nous nous embarquâmes sur un vaisseau d''Alexandrie qui avait passé l''hiver dans l''île; il portait pour enseigne les Dioscures.'),
('ac',28,12,'crampon1923','Ayant abordé à Syracuse, nous y restâmes trois jours.'),
('ac',28,13,'crampon1923','De là, en suivant la côte, nous atteignîmes Reggio, et le lendemain, le vent soufflant du sud, nous arrivâmes en deux jours à Pouzzoles;'),
('ac',28,14,'crampon1923','nous y trouvâmes des frères qui nous prièrent de passer sept jours avec eux; ensuite nous partîmes pour Rome.'),
('ac',28,15,'crampon1923','Ayant entendu parler de notre arrivée, les frères de cette ville vinrent au-devant de nous jusqu''au Forum d''Appius et aux Trois-Tavernes. Paul, en les voyant, rendit grâces à Dieu et fut rempli de confiance.'),
('ac',28,16,'crampon1923','Quand nous fûmes arrivés à Rome, on permit à Paul de demeurer en son particulier avec un soldat qui le gardait.'),
('ac',28,17,'crampon1923','Trois jours après, Paul fit appeler les principaux d''entre les Juifs, et quand ils furent venus, il leur dit: " Mes frères, sans avoir rien fait ni contre le peuple, ni contre les coutumes de nos pères, je suis prisonnier, et, depuis Jérusalem, livré au pouvoir des Romains.'),
('ac',28,18,'crampon1923','Après m''avoir interrogé, ils voulaient me relâcher, parce qu''il n''y avait rien en moi qui méritât la mort.'),
('ac',28,19,'crampon1923','Mais les Juifs s''y opposèrent, et je me suis vu forcé d''en appeler à César, non certes que j''aie aucun dessein d''accuser ma nation.'),
('ac',28,20,'crampon1923','Voilà pourquoi j''ai demandé à vous voir et à vous parler; car c''est à cause de l''espérance d''Israël que je porte cette chaîne. "'),
('ac',28,21,'crampon1923','Ils lui répondirent: " Nous n''avons reçu de Judée aucune lettre à ton sujet, et aucun des frères qui en sont revenus n''a rien rapporté ou dit de défavorable à ton égard.'),
('ac',28,22,'crampon1923','Mais nous voudrions entendre de ta bouche ce que tu penses; car, pour ce qui est de cette secte, nous savons qu''elle rencontre partout de l''opposition. "'),
('ac',28,23,'crampon1923','Ayant pris jour avec lui, ils vinrent en plus grand nombre le trouver où il logeait. Paul leur exposa, dans un langage pressant, le royaume de Dieu, cherchant à les persuader, par la loi de Moïse et les Prophètes, de ce qui concerne Jésus. L''entretien dura depuis le matin jusqu''au soir.'),
('ac',28,24,'crampon1923','Les uns furent convaincus par ce qu''il disait, mais les autres ne crurent point.'),
('ac',28,25,'crampon1923','Comme ils se retiraient en désaccord, Paul n''ajouta que ces mots: " Elle est bien vraie cette parole que le Saint-Esprit a dite à vos pères par le prophète Isaïe:'),
('ac',28,26,'crampon1923','Va vers ce peuple, et dis-leur: Vous entendrez de vos oreilles, et vous ne comprendrez point; vous regarderez de vos yeux, et vous ne verrez point.'),
('ac',28,27,'crampon1923','Car le cœur de ce peuple est devenu insensible; ils ont endurci leurs oreilles et ils ont fermé leurs yeux, de peur de voir de leurs yeux, d''entendre de leurs oreilles, de comprendre avec leur cœur, de se convertir et de recevoir de moi le salut. —'),
('ac',28,28,'crampon1923','Sachez donc que ce salut de Dieu a été envoyé aux Gentils; pour eux, ils le recevront avec docilité. "'),
('ac',28,29,'crampon1923','[Lorsqu''il eut ainsi parlé, les Juifs s''en allèrent, en discutant vivement entre eux.]'),
('ac',28,30,'crampon1923','Paul demeura deux ans entiers dans une maison qu''il avait louée. Il recevait tous ceux qui venaient le visiter,'),
('ac',28,31,'crampon1923','prêchant le royaume de Dieu et enseignant ce qui regarde le Seigneur Jésus-Christ, en toute liberté et sans empêchement.'),
('rm',1,1,'crampon1923','Paul, serviteur du Christ-Jésus, apôtre par son appel, mis à part pour annoncer l''Evangile de Dieu,'),
('rm',1,2,'crampon1923','Evangile que Dieu avait promis auparavant par ses prophètes dans les saintes Ecritures,'),
('rm',1,3,'crampon1923','touchant son Fils (né de la postérité de David selon la chair,'),
('rm',1,4,'crampon1923','et déclaré Fils de Dieu miraculeusement, selon l''Esprit de sainteté, par une résurrection d''entre les morts), Jésus-Christ Notre-Seigneur,'),
('rm',1,5,'crampon1923','par qui nous avons reçu la grâce et l''apostolat, pour amener en son nom à l''obéissance de la foi tous les Gentils,'),
('rm',1,6,'crampon1923','du nombre desquels vous êtes, vous aussi, par appel de Jésus-Christ, —'),
('rm',1,7,'crampon1923','à tous les bien-aimés de Dieu, les saints appelés par lui, qui sont à Rome: grâce et paix à vous de la part de Dieu notre Père et du Seigneur Jésus-Christ!'),
('rm',1,8,'crampon1923','Et d''abord je rends grâce à mon Dieu, par Jésus-Christ, au sujet de vous tous, de ce que votre foi est renommée dans le monde entier.'),
('rm',1,9,'crampon1923','Dieu m''en est témoin, ce Dieu que je sers en mon esprit par la prédication de l''Evangile de son Fils, sans cesse je fais mémoire de vous,'),
('rm',1,10,'crampon1923','demandant continuellement dans mes prières d''avoir enfin, par sa volonté, quelque heureuse occasion de me rendre auprès de vous.'),
('rm',1,11,'crampon1923','Car j''ai un grand désir de vous voir, pour vous communiquer quelque don spirituel, capable de vous affermir,'),
('rm',1,12,'crampon1923','je veux dire, de nous encourager ensemble au milieu de vous par la foi qui nous est commune, à vous et à moi.'),
('rm',1,13,'crampon1923','Je ne veux pas vous laisser ignorer, frères, que je me suis souvent proposé d''aller vous voir, — mais j''en ai été empêché jusqu''ici, — afin de recueillir aussi quelques fruits parmi vous, comme parmi les autres nations.'),
('rm',1,14,'crampon1923','Je me dois aux Grecs et aux Barbares, aux savants et aux ignorants.'),
('rm',1,15,'crampon1923','Ainsi, autant qu''il est en moi, je suis prêt à vous annoncer aussi l''Evangile, à vous qui êtes à Rome.'),
('rm',1,16,'crampon1923','Car je n''ai point honte de l''Evangile; c''est une force divine pour le salut de tout homme qui croit, premièrement du Juif, puis du Grec.'),
('rm',1,17,'crampon1923','En effet, en lui est révélée une justice de Dieu qui vient de la foi et est destinée à la foi, selon qu''il est écrit: " Le juste vivra par la foi. "'),
('rm',1,18,'crampon1923','En effet, la colère de Dieu éclate du haut du ciel contre toute impiété et toute injustice des hommes, qui, par leur injustice, retiennent la vérité captive;'),
('rm',1,19,'crampon1923','car ce qui se peut connaître de Dieu, est manifeste parmi eux: Dieu le leur a manifesté.'),
('rm',1,20,'crampon1923','En effet ses perfections invisibles, son éternelle puissance et sa divinité sont, depuis la création du monde, rendues visibles à l''intelligence par le moyen de ses œuvres. Ils sont donc inexcusables,'),
('rm',1,21,'crampon1923','puisque, ayant connu Dieu, ils ne l''ont pas glorifié comme Dieu et ne lui ont pas rendu grâces; mais ils sont devenus vains dans leurs pensées, et leur cœur sans intelligence s''est enveloppé de ténèbres.'),
('rm',1,22,'crampon1923','Se vantant d''être sages, ils sont devenus fous;'),
('rm',1,23,'crampon1923','et ils ont échangé la majesté du Dieu incorruptible pour des images représentant l''homme corruptible, des oiseaux, des quadrupèdes et des reptiles.'),
('rm',1,24,'crampon1923','Aussi Dieu les a-t-il livrés, au milieu des convoitises de leurs cœurs, à l''impureté, en sorte qu''ils déshonorent entre eux leurs propres corps,'),
('rm',1,25,'crampon1923','eux qui ont échangé le Dieu véritable pour le mensonge, et qui ont adoré et servi la créature de préférence au Créateur, (lequel est béni éternellement. Amen!)'),
('rm',1,26,'crampon1923','C''est pourquoi Dieu les a livrés à des passions d''ignominie: leurs femmes ont changé l''usage naturel en celui qui est contre nature;'),
('rm',1,27,'crampon1923','de même aussi les hommes, au lieu d''user de la femme selon l''ordre de la nature, ont, dans leurs désirs, brûlé les uns pour les autres, ayant hommes avec hommes un commerce infâme, et recevant, dans une mutuelle dégradation, le juste salaire de leur égarement.'),
('rm',1,28,'crampon1923','Et comme ils ne se sont pas souciés de bien connaître Dieu, Dieu les a livrés à leur sens pervers pour faire ce qui ne convient pas,'),
('rm',1,29,'crampon1923','étant remplis de toute espèce d''iniquité, de malice, [de fornication], de cupidité, de méchanceté, pleins d''envie, de pensées homicides, de querelle, de fraude, de malignité,'),
('rm',1,30,'crampon1923','semeurs de faux bruits, calomniateurs, haïs de Dieu, arrogants, hautains, fanfarons, ingénieux au mal, rebelles à leurs parents,'),
('rm',1,31,'crampon1923','sans intelligence, sans loyauté, [implacables], sans affection, sans pitié.'),
('rm',1,32,'crampon1923','Et bien qu''ils connaissent le jugement de Dieu déclarant dignes de mort ceux qui commettent de telles choses, non seulement ils les font, mais encore ils approuvent ceux qui les font.'),
('rm',2,1,'crampon1923','Ainsi, qui que tu sois, ô homme, toi qui juges, tu es inexcusable; car, en jugeant les autres, tu te condamnes toi-même, puisque tu fais les mêmes choses, toi qui juges.'),
('rm',2,2,'crampon1923','Car nous savons que le jugement de Dieu est selon la vérité contre ceux qui commettent de telles choses.'),
('rm',2,3,'crampon1923','Et tu penses, ô homme, toi qui juges ceux qui les commettent, et qui les fais toi-même, que tu échapperas au jugement de Dieu?'),
('rm',2,4,'crampon1923','Ou méprises-tu les richesses de sa bonté, de sa patience et de sa longanimité? et ne sais-tu pas que la bonté de Dieu t''invite à la pénitence?'),
('rm',2,5,'crampon1923','Par ton endurcissement et ton cœur impénitent, tu t''amasses un trésor de colère pour le jour de la colère et de la manifestation du juste jugement de Dieu,'),
('rm',2,6,'crampon1923','qui rendra à chacun selon ses œuvres:'),
('rm',2,7,'crampon1923','la vie éternelle à ceux qui, par la persévérance dans le bien, cherchent la gloire, l''honneur et l''immortalité;'),
('rm',2,8,'crampon1923','mais la colère et l''indignation aux enfants de contention, indociles à la vérité, dociles à l''iniquité.'),
('rm',2,9,'crampon1923','Oui, tribulation et angoisse sur tout homme qui fait le mal, sur le Juif premièrement, puis sur le Grec;'),
('rm',2,10,'crampon1923','gloire, honneur et paix pour quiconque fait le bien, pour le Juif premièrement, puis pour le Grec.'),
('rm',2,11,'crampon1923','Car Dieu ne fait pas acception des personnes.'),
('rm',2,12,'crampon1923','Tous ceux qui ont péché sans loi périront aussi sans loi, et tous ceux qui ont péché avec une loi seront jugés par cette loi.'),
('rm',2,13,'crampon1923','Ce ne sont pas, en effet, ceux qui écoutent une loi qui sont justes devant Dieu; mais ce sont ceux qui la mettent en pratique qui seront justifiés.'),
('rm',2,14,'crampon1923','Quand des païens, qui n''ont pas la loi, accomplissent naturellement ce que la Loi commande, n''ayant pas la loi, ils se tiennent lieu de loi à eux-mêmes;'),
('rm',2,15,'crampon1923','ils montrent que ce que la Loi ordonne est écrit dans leurs cœurs, leur conscience rendant en même temps témoignage par des pensées qui, de part et d''autre, les accusent ou les défendent.'),
('rm',2,16,'crampon1923','C''est ce qui paraîtra au jour où, selon mon Evangile, Dieu jugera par Jésus-Christ les actions secrètes des hommes.'),
('rm',2,17,'crampon1923','Toi qui portes le nom de Juif, qui te reposes sur la Loi, qui te glorifies en Dieu,'),
('rm',2,18,'crampon1923','qui connais sa volonté, qui sais discerner ce qu''il y a de meilleur, instruit que tu es par la Loi;'),
('rm',2,19,'crampon1923','toi qui te flattes d''être le guide des aveugles, la lumière de ceux qui sont dans les ténèbres,'),
('rm',2,20,'crampon1923','le docteur des ignorants, le maître des enfants, ayant dans la Loi la règle de la science et de la vérité: —'),
('rm',2,21,'crampon1923','toi donc qui enseignes les autres, tu ne t''enseignes pas toi-même! Toi qui prêches de ne pas dérober, tu dérobes!'),
('rm',2,22,'crampon1923','Toi qui défends de commettre l''adultère, tu commets l''adultère! Toi qui as les idoles en abomination, tu profanes le temple!'),
('rm',2,23,'crampon1923','Toi qui te fais une gloire d''avoir une loi, tu déshonores Dieu en la transgressant!'),
('rm',2,24,'crampon1923','Car " le nom de Dieu est blasphémé à cause de vous parmi les nations ", comme dit l''Ecriture.'),
('rm',2,25,'crampon1923','La circoncision est utile, il est vrai, si tu observes la Loi; mais si tu transgresses la Loi, tu n''es plus, avec ta circoncision, qu''un incirconcis.'),
('rm',2,26,'crampon1923','Si donc l''incirconcis observe les préceptes de la Loi, son incirconcision ne sera-t-elle pas réputée circoncision?'),
('rm',2,27,'crampon1923','Bien plus, l''homme incirconcis de naissance, s''il observe la Loi, te jugera, toi qui, avec la lettre de la Loi et la circoncision, transgresses la Loi.'),
('rm',2,28,'crampon1923','Le vrai Juif, ce n''est pas celui qui l''est au dehors, et la vraie circoncision, ce n''est pas celle qui paraît dans la chair.'),
('rm',2,29,'crampon1923','Mais le Juif, c''est celui qui l''est intérieurement, et la circoncision, c''est celle du cœur, dans l''esprit, et non dans la lettre: ce Juif aura sa louange, non des hommes, mais de Dieu.'),
('rm',3,1,'crampon1923','Quel est donc l''avantage du Juif? ou quelle est l''utilité de la circoncision?')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('rm',3,2,'crampon1923','Cet avantage est grand de toute manière. Et d''abord c''est qu''à eux ont été confiés les oracles de Dieu.'),
('rm',3,3,'crampon1923','Mais quoi? Si quelques-uns n''ont pas cru, leur incrédulité anéantira-t-elle la fidélité de Dieu? Loin de là!'),
('rm',3,4,'crampon1923','Mais plutôt que Dieu soit reconnu pour vrai, et tout homme pour menteur, selon qu''il est écrit: " Afin, ô Dieu, que tu sois trouvé juste dans tes paroles et que tu triomphes lorsqu''on te juge. "'),
('rm',3,5,'crampon1923','Mais si notre injustice démontre la justice de Dieu, que dirons-nous? Dieu n''est-il pas injuste en donnant cours à sa colère?'),
('rm',3,6,'crampon1923','(je parle à la manière des hommes) Loin de là! Autrement, comment Dieu jugera-t-il le monde?'),
('rm',3,7,'crampon1923','Car si, par mon mensonge, la vérité de Dieu éclate davantage pour sa gloire, pourquoi, après cela, suis-je moi-même condamné comme pécheur?'),
('rm',3,8,'crampon1923','Et pourquoi ne ferions-nous pas le mal afin qu''il en arrive du bien, comme la calomnie nous en accuse, et comme quelques-uns prétendent, que nous l''enseignons? ceux-là, leur condamnation est juste!'),
('rm',3,9,'crampon1923','Et bien donc? Avons-nous quelque supériorité? Non, aucune; car nous venons de prouver que tous, Juifs et Grecs, sont sous le péché,'),
('rm',3,10,'crampon1923','selon qu''il est écrit: " Il n''y a point de juste, pas même un seul;'),
('rm',3,11,'crampon1923','il n''y en a point qui ait de l''intelligence, il n''y en a point qui cherche Dieu.'),
('rm',3,12,'crampon1923','Tous sont sortis de la voie, tous sont pervertis; il n''y a personne qui fasse le bien, pas même un seul. "'),
('rm',3,13,'crampon1923','" Sépulcre ouvert est leur gosier; ils se servent de leurs langues pour tromper. " " Un venin d''aspic est sous leurs lèvres. "'),
('rm',3,14,'crampon1923','" Leur bouche est pleine de malédiction et d''amertume. "'),
('rm',3,15,'crampon1923','" Ils ont les pieds agiles pour répandre le sang.'),
('rm',3,16,'crampon1923','La désolation et le malheur sont dans leurs voies.'),
('rm',3,17,'crampon1923','Ils ne connaissent pas le chemin de la paix. "'),
('rm',3,18,'crampon1923','" La crainte de Dieu n''est pas devant leurs yeux. "'),
('rm',3,19,'crampon1923','Or nous savons que tout ce que dit la Loi, elle le dit à ceux qui sont sous la Loi, afin que toute bouche soit fermée, et que le monde entier soit sous le coup de la justice de Dieu.'),
('rm',3,20,'crampon1923','En effet, nul homme ne sera justifié devant lui par les œuvres de la Loi, car la loi ne fait que donner la connaissance du péché.'),
('rm',3,21,'crampon1923','Mais maintenant, sans la Loi, a été manifestée une justice de Dieu à la quelle rendent témoignage la Loi et les Prophètes,'),
('rm',3,22,'crampon1923','justice de Dieu par la foi en Jésus-Christ pour tous ceux et à tous ceux qui croient; il n''y a point de distinction,'),
('rm',3,23,'crampon1923','car tous ont péché et sont privés de la gloire de Dieu;'),
('rm',3,24,'crampon1923','et ils sont justifiés gratuitement par sa grâce, par le moyen de la rédemption qui est en Jésus-Christ.'),
('rm',3,25,'crampon1923','C''est lui que Dieu a donné comme victime propitiatoire par son sang moyennant la foi, afin de manifester sa justice, ayant, au temps de sa patience, laissé impunis les péchés précédents,'),
('rm',3,26,'crampon1923','afin, dis-je, de manifester sa justice dans le temps présent, de manière à être reconnu juste et justifiant celui qui croit [en Jésus-Christ].'),
('rm',3,27,'crampon1923','Où est donc la jactance? Elle est exclue. Par quelle loi? Par la loi des œuvres? Non, mais par la loi de la foi.'),
('rm',3,28,'crampon1923','Car nous tenons pour certain que l''homme est justifié par la foi, à l''exclusion des œuvres de la Loi.'),
('rm',3,29,'crampon1923','Ou bien Dieu n''est-il que le Dieu des Juifs? et n''est-il pas aussi le Dieu des Gentils? Oui, il est aussi le Dieu des Gentils,'),
('rm',3,30,'crampon1923','puisqu''il y a un seul Dieu qui justifiera les circoncis par principe de foi et les incirconcis par la foi.'),
('rm',3,31,'crampon1923','Détruisons-nous donc la Loi par la foi? Loin de là! Nous la confirmons au contraire.'),
('rm',4,1,'crampon1923','Quel avantage dirons-nous donc qu''Abraham, notre père, ait obtenu selon la chair?'),
('rm',4,2,'crampon1923','Si Abraham a été justifié par les œuvres, il a sujet de se glorifier. Mais il n''en a pas sujet devant Dieu.'),
('rm',4,3,'crampon1923','En effet, que dit l''Ecriture? " Abraham crut à Dieu, et cela lui fut imputé à justice. "'),
('rm',4,4,'crampon1923','Or, à celui qui fait une œuvre, le salaire est imputé, non comme une grâce, mais comme une chose due;'),
('rm',4,5,'crampon1923','et à celui qui ne fait aucune œuvre, mais qui croit en celui qui justifie l''impie, sa foi lui est imputée à justice.'),
('rm',4,6,'crampon1923','C''est ainsi que David proclame la béatitude de l''homme à qui Dieu impute la justice indépendamment des œuvres:'),
('rm',4,7,'crampon1923','Heureux ceux dont les iniquités sont pardonnées, et dont les péchés ont été couverts!'),
('rm',4,8,'crampon1923','Heureux l''homme à qui le Seigneur n''impute pas son péché! "'),
('rm',4,9,'crampon1923','Ce bonheur n''est-il que pour les circoncis, ou est-il également pour les incirconcis? Car nous disons que la foi fut imputée à justice à Abraham.'),
('rm',4,10,'crampon1923','Comment donc lui fut-elle imputée? Etait-ce en l''état de circoncision, ou en l''état d''incirconcision? Ce ne fut pas dans l''état de circoncision, il était encore incirconcis.'),
('rm',4,11,'crampon1923','Il reçut ensuite le signe de la circoncision comme sceau de la justice qu''il avait obtenue par la foi quand il était incirconcis, afin d''être le père de tous ceux qui ont la foi bien qu''incirconcis, pour que la justice leur soit aussi imputée,'),
('rm',4,12,'crampon1923','et le père des circoncis, de ceux qui ne sont pas seulement circoncis, mais qui marchent en même temps sur les traces de la foi qu''avait notre père Abraham lorsqu''il était incirconcis.'),
('rm',4,13,'crampon1923','En effet, ce n''est point par la Loi que l''héritage du monde a été promis à Abraham et à sa postérité; c''est par la justice de la foi.'),
('rm',4,14,'crampon1923','Car si ceux qui ont la Loi sont héritiers, la foi est vaine et la promesse est sans effet,'),
('rm',4,15,'crampon1923','parce que la loi produit la colère, et que là où il n''y a pas de loi, il n''y a pas non plus de transgression.'),
('rm',4,16,'crampon1923','Donc c''est bien par la foi, afin que ce soit par grâce, pour que la promesse soit assurée à toute la postérité, non seulement à ceux qui relèvent de la Loi, mais encore à ceux qui relèvent de la foi d''Abraham, notre père à tous,'),
('rm',4,17,'crampon1923','selon qu''il est écrit: " Je t''ai fait père d''un grand nombre de nations. " Il l''est devant celui auquel il a cru, devant Dieu, qui donne la vie aux morts et qui appelle les choses qui ne sont point comme si elles étaient.'),
('rm',4,18,'crampon1923','Espérant contre toute espérance, il crut, en sorte qu''il devint le père d''un grand nombre de nations, selon ce qui lui avait été dit: " Telle sera ta postérité. "'),
('rm',4,19,'crampon1923','Et, inébranlable dans sa foi, il ne considéra pas que son corps était déjà éteint, puisqu''il avait près de cent ans, ni que le sein de Sara était épuisé.'),
('rm',4,20,'crampon1923','Devant la promesse de Dieu, il n''eut ni hésitation ni défiance; mais puisant sa force dans la foi, il rendit gloire à Dieu,'),
('rm',4,21,'crampon1923','pleinement convaincu qu''il saura accomplir la promesse qu''il a faite.'),
('rm',4,22,'crampon1923','Et voilà pourquoi sa foi lui fut imputée à justice.'),
('rm',4,23,'crampon1923','Or ce n''est pas pour lui seul qu''il est écrit qu''elle lui fut imputée à justice,'),
('rm',4,24,'crampon1923','mais c''est aussi pour nous, à qui elle doit être imputée, pour nous qui croyons en celui qui a ressuscité d''entre les morts Jésus-Christ, Notre-Seigneur,'),
('rm',4,25,'crampon1923','lequel a été livré pour nos offenses, et est ressuscité pour notre justification.'),
('rm',5,1,'crampon1923','Etant donc justifiés par la foi, nous avons la paix avec Dieu par Notre-Seigneur Jésus-Christ,'),
('rm',5,2,'crampon1923','à qui nous devons d''avoir eu accès par la foi à cette grâce dans laquelle nous demeurons fermes, et de nous glorifier dans l''espérance de la gloire de Dieu.'),
('rm',5,3,'crampon1923','Bien plus, nous nous glorifions même dans les tribulations, sachant que la tribulation produit la constance,'),
('rm',5,4,'crampon1923','la constance une vertu éprouvée, et la vertu éprouvée l''espérance.'),
('rm',5,5,'crampon1923','Or, l''espérance ne trompe point, parce que l''amour de Dieu est répandu dans nos cœurs par l''Esprit-Saint qui nous a été donné.'),
('rm',5,6,'crampon1923','Car, lorsque nous étions encore impuissants, le Christ, au temps marqué, est mort pour des impies.'),
('rm',5,7,'crampon1923','C''est à peine si l''on meurt pour un juste, et peut-être quelqu''un saurait-il mourir pour un homme de bien.'),
('rm',5,8,'crampon1923','Mais Dieu montre son amour envers nous en ce que, lorsque nous étions encore des pécheurs, [au temps marqué],'),
('rm',5,9,'crampon1923','Jésus-Christ est mort pour nous. A plus forte raison donc, maintenant que nous sommes justifiés dans son sang, serons-nous sauvés par lui de la colère.'),
('rm',5,10,'crampon1923','Car si, lorsque nous étions ennemis, nous avons été réconciliés avec Dieu par la mort de son Fils, à plus forte raison, étant réconciliés, serons-nous sauvés par sa vie.'),
('rm',5,11,'crampon1923','Bien plus, nous nous glorifions même en Dieu par Notre-Seigneur Jésus-Christ, par qui maintenant nous avons obtenu la réconciliation.'),
('rm',5,12,'crampon1923','Ainsi donc, comme par un seul homme le péché est entré dans le monde, et par le péché la mort... Et ainsi la mort a passé dans tous les hommes parce que tous ont péché.'),
('rm',5,13,'crampon1923','Car jusqu''à la Loi le péché était dans le monde; or le péché n''est pas imputé lorsqu''il n''y a point de loi.'),
('rm',5,14,'crampon1923','Cependant la mort a régné depuis Adam jusqu''à Moïse, même sur ceux qui n''avaient pas péché, par une transgression semblable à celle d''Adam, lequel est la figure de celui qui devait venir.'),
('rm',5,15,'crampon1923','Mais il n''en est pas du don gratuit comme de la faute; car si, par la faute d''un seul, tous les hommes sont morts, à plus forte raison la grâce de Dieu et le don se sont, par la grâce d''un seul homme, Jésus-Christ, abondamment répandus sur tous les hommes.'),
('rm',5,16,'crampon1923','Et il n''en est pas du don comme des suites du péché d''un seul; car le jugement a été porté à cause d''une seule faute pour la condamnation, tandis que le don amène la justification de beaucoup de fautes.'),
('rm',5,17,'crampon1923','En effet, si, par la faute d''un seul, la mort a régné par ce seul homme, à plus forte raison ceux qui reçoivent l''abondance de la grâce et du don de la justice règneront-ils dans la vie par le seul Jésus-Christ.'),
('rm',5,18,'crampon1923','Ainsi donc, comme par la faute d''un seul la condamnation est venue sur tous les hommes, ainsi par la justice d''un seul vient à tous les hommes la justification qui donne la vie.'),
('rm',5,19,'crampon1923','De même en effet, que par la désobéissance d''un seul homme, tous ont été constitués pécheurs, de même par l''obéissance d''un seul tous seront constitués justes.'),
('rm',5,20,'crampon1923','La loi est intervenue pour faire abonder la faute; mais là où le péché a abondé, la grâce a surabondé,'),
('rm',5,21,'crampon1923','afin que, comme le péché a régné par la mort, ainsi la grâce régnât par la justice pour la vie éternelle, par Jésus-Christ Notre-Seigneur.'),
('rm',6,1,'crampon1923','Que dirons-nous donc? Demeurerons-nous dans le péché, afin que la grâce abonde?'),
('rm',6,2,'crampon1923','Loin de là! Nous qui sommes morts au péché, comment vivrons-nous encore dans le péché?'),
('rm',6,3,'crampon1923','Ne savez-vous pas que nous tous qui avons été baptisés en Jésus-Christ, c''est en sa mort que nous avons été baptisés?'),
('rm',6,4,'crampon1923','Nous avons donc été ensevelis avec lui par le baptême en sa mort, afin que, comme le Christ est ressuscité des morts par la gloire du Père, nous aussi nous marchions dans une vie nouvelle.'),
('rm',6,5,'crampon1923','Si, en effet, nous avons été greffés sur lui, par la ressemblance de sa mort, nous le serons aussi par celle de sa résurrection:'),
('rm',6,6,'crampon1923','sachant que notre vieil homme a été crucifié avec lui, afin que le corps du péché fût détruit, pour que nous ne soyons plus les esclaves du péché;'),
('rm',6,7,'crampon1923','car celui qui est mort est affranchi du péché.'),
('rm',6,8,'crampon1923','Mais si nous sommes morts avec le Christ, nous croyons que nous vivrons avec lui,'),
('rm',6,9,'crampon1923','sachant que le Christ ressuscité des morts ne meurt plus; la mort n''a plus sur lui d''empire.'),
('rm',6,10,'crampon1923','Car sa mort fut une mort au péché une fois pour toutes, et sa vie est une vie pour Dieu.'),
('rm',6,11,'crampon1923','Ainsi vous-mêmes regardez-vous comme morts au péché, et comme vivants pour Dieu en Jésus-Christ [Notre-Seigneur].'),
('rm',6,12,'crampon1923','Que le péché ne règne donc point dans votre corps mortel, de sorte que vous obéissiez à ses convoitises.'),
('rm',6,13,'crampon1923','Ne livrez pas vos membres au péché pour être des instruments d''iniquité, mais offrez-vous vous-mêmes à Dieu comme étant vivants, de morts que vous étiez, et offrez-lui vos membres pour être des instruments de justice.'),
('rm',6,14,'crampon1923','Car le péché n''aura pas d''empire sur vous, parce que vous n''êtes pas sous la Loi, mais sous la grâce.'),
('rm',6,15,'crampon1923','Quoi donc! Pécherons-nous, parce que nous ne sommes pas sous la Loi mais sous la grâce? Loin de là!'),
('rm',6,16,'crampon1923','Ne savez-vous pas que, si vous vous livrez à quelqu''un comme esclaves pour lui obéir, vous êtes esclaves de celui à qui vous obéissez, soit du péché pour la mort, soit de l''obéissance à Dieu pour la justice?'),
('rm',6,17,'crampon1923','Mais grâces soient rendues à Dieu de ce que, après avoir été les esclaves du péché, vous avez obéi de cœur à la règle de doctrine qui vous a été enseignée.'),
('rm',6,18,'crampon1923','Ainsi, ayant été affranchis du péché, vous êtes devenus les esclaves de la justice. —'),
('rm',6,19,'crampon1923','Je parle à la manière des hommes, à cause de la faiblesse de votre chair. — De même que vous avez livré vos membres comme esclaves à l''impureté et à l''injustice, pour arriver à l''injustice, de même livrez maintenant vos membres comme esclaves à la justice, pour arriver à la sainteté.'),
('rm',6,20,'crampon1923','Car, lorsque vous étiez les esclaves du péché, vous étiez libres à l''égard de la justice.'),
('rm',6,21,'crampon1923','Quel fruit aviez-vous alors des choses dont vous rougissez aujourd''hui? Car la fin de ces choses, c''est la mort.'),
('rm',6,22,'crampon1923','Mais maintenant, affranchis du péché et devenus les esclaves de Dieu, vous avez pour fruit la sainteté, et pour fin la vie éternelle.'),
('rm',6,23,'crampon1923','Car le salaire du péché, c''est la mort; mais le don de Dieu c''est la vie éternelle en Jésus-Christ Notre-Seigneur.'),
('rm',7,1,'crampon1923','Ignorez-vous, mes frères — car je parle à des hommes qui connaissent la Loi, — que l''homme est sous l''empire de la loi aussi longtemps qu''il vit?'),
('rm',7,2,'crampon1923','Ainsi une femme mariée est liée par la loi à son mari tant qu''il est vivant; mais si le mari meurt, elle est dégagée de la loi qui la liait à son mari.'),
('rm',7,3,'crampon1923','Si donc, du vivant de son mari, elle épouse un autre homme, elle sera appelée adultère; mais si son mari meurt, elle est affranchie de la loi, en sorte qu''elle n''est plus adultère en devenant la femme d''un autre mari.'),
('rm',7,4,'crampon1923','Ainsi, mes frères, vous aussi vous êtes morts à la Loi, par le corps de Jésus-Christ, pour que vous soyez à un autre, à celui qui est ressuscité des morts, afin que nous portions des fruits pour Dieu.'),
('rm',7,5,'crampon1923','Car, lorsque nous étions dans la chair, les passions qui engendrent les péchés, excitées par la Loi, agissaient dans nos membres, de manière à produire des fruits pour la mort.'),
('rm',7,6,'crampon1923','Mais maintenant nous avons été dégagés de la Loi, étant morts à la Loi, sous l''autorité de laquelle nous étions tenus, de sorte que nous servons Dieu dans un esprit nouveau, et non selon une lettre surannée.'),
('rm',7,7,'crampon1923','Que dirons-nous donc? La loi est-elle péché? Loin de là! Mais je n''ai connu le péché que par la Loi; par exemple, je n''aurais pas connu la convoitise, si la Loi ne disait: " Tu ne convoiteras point. "'),
('rm',7,8,'crampon1923','Puis le péché, saisissant l''occasion, a fait naître en moi, par le commandement, toutes sortes de convoitises; car, sans la Loi, le péché est mort.'),
('rm',7,9,'crampon1923','Pour moi, je vivais autrefois sans la Loi; mais le commandement étant venu, le péché a pris vie,'),
('rm',7,10,'crampon1923','et moi, je suis mort. Ainsi le commandement qui devait conduire à la vie, s''est trouvé pour moi conduire à la mort.'),
('rm',7,11,'crampon1923','Car le péché, saisissant l''occasion qu''offrait le commandement, m''a séduit et par lui m''a donné la mort.'),
('rm',7,12,'crampon1923','Ainsi donc la Loi est sainte, et le commandement est saint, juste et bon.'),
('rm',7,13,'crampon1923','Une chose bonne a donc été pour moi une cause de mort? Loin de là! Mais c''est le péché qui m''a donné la mort, afin de se montrer péché en me donnant la mort par le moyen d''une chose bonne, et de se développer à l''excès comme péché par le moyen du commandement.'),
('rm',7,14,'crampon1923','Nous savons, en effet, que la Loi est spirituelle; mais moi, je suis charnel, vendu au péché.'),
('rm',7,15,'crampon1923','Car je ne sais pas ce que je fais: je ne fais pas ce que je veux, et je fais ce que je hais.'),
('rm',7,16,'crampon1923','Or, si je fais ce que je ne voudrais pas, je reconnais par là que la Loi est bonne.'),
('rm',7,17,'crampon1923','Mais alors ce n''est plus moi qui le fais, c''est le péché qui habite en moi.'),
('rm',7,18,'crampon1923','Car je sais que le bien n''habite pas en moi, c''est-à-dire dans ma chair; le vouloir est à ma portée, mais non le pouvoir de l''accomplir.'),
('rm',7,19,'crampon1923','Car je ne fais pas le bien que je veux, et je fais le mal que je ne veux pas.'),
('rm',7,20,'crampon1923','Or, si je fais ce que je ne veux pas, ce n''est plus moi qui le fais, c''est le péché qui habite en moi.'),
('rm',7,21,'crampon1923','Je trouve donc cette loi en moi: quand je veux faire le bien, le mal est près de moi.'),
('rm',7,22,'crampon1923','Car je prends plaisir à la loi de Dieu, selon l''homme intérieur;'),
('rm',7,23,'crampon1923','mais je vois dans mes membres une autre loi qui lutte contre la loi de ma raison, et qui me rend captif de la loi du péché qui est dans mes membres.'),
('rm',7,24,'crampon1923','Malheureux que je suis! Qui me délivrera de ce corps de mort?'),
('rm',7,25,'crampon1923','Grâces soient rendues à Dieu par Jésus-Christ Notre-Seigneur! Ainsi donc moi-même, par l''esprit, je suis l''esclave de la loi de Dieu, et par la chair l''esclave de la loi du péché.'),
('rm',8,1,'crampon1923','Il n''y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ, [qui ne marchent pas selon la chair].'),
('rm',8,2,'crampon1923','En effet, la loi de l''Esprit de la vie m''a affranchi en Jésus-Christ de la loi du péché et de la mort.'),
('rm',8,3,'crampon1923','Car, ce qui était impossible à la Loi parce qu''elle était sans force à cause de la chair, Dieu l''a fait: en envoyant, pour le péché, son propre Fils dans une chair semblable à celle du péché, et il a condamné le péché dans la chair,'),
('rm',8,4,'crampon1923','afin que la justice de la loi fût accomplie en nous, qui marchons, non selon la chair, mais selon l''Esprit.'),
('rm',8,5,'crampon1923','Ceux, en effet, qui vivent selon la chair, s''affectionnent aux choses de la chair; mais ceux qui vivent selon l''Esprit s''affectionnent aux choses de l''Esprit.'),
('rm',8,6,'crampon1923','Et les affections de la chair, c''est la mort, tandis que les affections de l''Esprit, c''est la vie et la paix:'),
('rm',8,7,'crampon1923','parce que les affections de la chair sont inimitié contre Dieu, car elles ne se soumettent pas à la loi divine, et elles ne le peuvent même pas.'),
('rm',8,8,'crampon1923','Or ceux qui vivent dans la chair ne sauraient plaire à Dieu.'),
('rm',8,9,'crampon1923','Pour vous, vous ne vivez point dans la chair, mais dans l''Esprit, si du moins l''Esprit de Dieu habite en vous. Si quelqu''un n''a pas l''Esprit du Christ, il ne lui appartient pas.'),
('rm',8,10,'crampon1923','Mais si le Christ est en vous, le corps, il est vrai, est mort à cause du péché, mais l''esprit est vie à cause de la justice.'),
('rm',8,11,'crampon1923','Et si l''Esprit de celui qui a ressuscité Jésus d''entre les morts habite en vous, celui qui a ressuscité le Christ d''entre les morts rendra aussi la vie à vos corps mortels, à cause de son Esprit qui habite en vous.'),
('rm',8,12,'crampon1923','Ainsi donc, mes frères, nous ne sommes point redevables à la chair pour vivre selon la chair.'),
('rm',8,13,'crampon1923','Car si vous vivez, selon la chair, vous mourrez; mais si, par l''Esprit, vous faites mourir les œuvres du corps, vous vivrez;'),
('rm',8,14,'crampon1923','car tous ceux qui sont conduits par l''Esprit de Dieu sont fils de Dieu.'),
('rm',8,15,'crampon1923','En effet, vous n''avez point reçu un Esprit de servitude, pour être encore dans la crainte; mais vous avez reçu un Esprit d''adoption, en qui nous crions: Abba! Père!'),
('rm',8,16,'crampon1923','Cet Esprit lui-même rend témoignage à notre esprit que nous sommes enfants de Dieu.'),
('rm',8,17,'crampon1923','Or, si nous sommes enfants, nous sommes aussi héritiers, héritiers de Dieu et cohéritiers du Christ, si toutefois nous souffrons avec lui, pour être glorifiés avec lui.'),
('rm',8,18,'crampon1923','Car j''estime que les souffrances du temps présent sont sans proportion avec la gloire à venir qui sera manifestée en nous.'),
('rm',8,19,'crampon1923','Aussi la création attend-elle avec un ardent désir la manifestation des enfants de Dieu.'),
('rm',8,20,'crampon1923','La création, en effet, a été assujettie à la vanité, — non de son gré, mais par la volonté de celui qui l''y a soumise, — avec l''espérance'),
('rm',8,21,'crampon1923','qu''elle aussi sera affranchie de la servitude de la corruption, pour avoir part à la liberté glorieuse des enfants de Dieu.'),
('rm',8,22,'crampon1923','Car nous savons que, jusqu''à ce jour, la création tout entière gémit et souffre les douleurs de l''enfantement.'),
('rm',8,23,'crampon1923','Et ce n''est pas elle seulement; nous aussi, qui avons les prémices de l''Esprit, nous gémissons en nous-mêmes, attendant l''adoption [des enfants de Dieu], la rédemption de notre corps.'),
('rm',8,24,'crampon1923','Car c''est en espérance que nous sommes sauvés. Or, voir ce qu''on espère, ce n''est plus espérer: car ce qu''on voit pourquoi l''espérer encore?'),
('rm',8,25,'crampon1923','Mais si nous espérons ce que nous ne voyons pas, nous l''attendons avec patience.'),
('rm',8,26,'crampon1923','De même aussi l''Esprit vient en aide à notre faiblesse, car nous ne savons pas ce que nous devons, selon nos besoins, demander dans nos prières. Mais l''Esprit lui-même prie pour nous par des gémissements ineffables;'),
('rm',8,27,'crampon1923','et celui qui sonde les cœurs connaît quels sont les désirs de l''Esprit; il sait qu''il prie selon Dieu pour des saints.'),
('rm',8,28,'crampon1923','Nous savons d''ailleurs que toutes choses concourent au bien de ceux qui aiment Dieu, de ceux qui sont appelés selon son éternel dessein.'),
('rm',8,29,'crampon1923','Car ceux qu''il a connus d''avance, il les a aussi prédestinés à être conformes à l''image de son Fils, afin que son Fils soit le premier-né d''un grand nombre de frères.'),
('rm',8,30,'crampon1923','Et ceux qu''il a prédestinés, il les a aussi appelés; et ceux qu''il a appelés, il les a aussi justifiés; et ceux qu''il a justifiés il les a glorifiés.'),
('rm',8,31,'crampon1923','Que dirons-nous donc après cela? Si Dieu est pour nous, qui sera contre nous?'),
('rm',8,32,'crampon1923','Lui qui n''a pas épargné son propre Fils, mais qui l''a livré à la mort pour nous tous, comment avec lui ne nous donnera-t-il pas toutes choses?'),
('rm',8,33,'crampon1923','Qui accusera des élus de Dieu? C''est Dieu qui les justifie!'),
('rm',8,34,'crampon1923','Qui les condamnera? Le Christ est mort, bien plus il est ressuscité, il est à la droite de Dieu, il intercède pour nous!'),
('rm',8,35,'crampon1923','Qui nous séparera de l''amour du Christ? Sera-ce la tribulation, ou l''angoisse, ou la persécution, ou la faim, ou la nudité, ou le péril, ou l''épée?'),
('rm',8,36,'crampon1923','Selon qu''il est écrit: " A cause de toi, tout le jour nous sommes livrés à la mort, et on nous regarde comme des brebis destinées à la boucherie. "'),
('rm',8,37,'crampon1923','Mais dans toutes ces épreuves nous sommes plus que vainqueurs, par celui qui nous a aimés.'),
('rm',8,38,'crampon1923','Car j''ai l''assurance que ni la mort, ni la vie, ni les anges, ni les principautés, ni les choses présentes, ni les choses à venir, ni les puissances,'),
('rm',8,39,'crampon1923','ni la hauteur, ni la profondeur, ni aucune autre créature ne pourra nous séparer de l''amour de Dieu dans le Christ Jésus Notre-Seigneur.'),
('rm',9,1,'crampon1923','Je dis la vérité dans le Christ, je ne mens point, ma conscience m''en rend témoignage par l''Esprit-Saint:'),
('rm',9,2,'crampon1923','j''éprouve une grande tristesse et j''ai au cœur une douleur incessante.'),
('rm',9,3,'crampon1923','Car je souhaiterais d''être moi-même anathème, loin du Christ, pour mes frères, mes parents selon la chair,'),
('rm',9,4,'crampon1923','qui sont Israélites, à qui appartiennent l''adoption, et la gloire, et les alliances, et la Loi, et le culte, et les promesses,'),
('rm',9,5,'crampon1923','et les patriarches, et de qui est issu le Christ selon la chair, lequel est au-dessus de toutes choses, Dieu, béni éternellement. Amen!'),
('rm',9,6,'crampon1923','Ce n''est pas que la parole de Dieu ait failli. Car tous ceux qui descendent d''Israël ne sont pas le véritable Israël,'),
('rm',9,7,'crampon1923','et pour être la postérité d''Abraham, tous ne sont pas ses enfants; mais " C''est la postérité d''Isaac qui sera dite ta postérité ",'),
('rm',9,8,'crampon1923','c''est-à-dire que ce sont pas les enfants de la chair qui sont enfants de Dieu, mais ce sont les enfants de la promesse qui sont regardés comme la postérité d''Abraham.'),
('rm',9,9,'crampon1923','Voici en effet les termes d''une promesse: " Je reviendrai à cette même époque, et Sara aura un fils. "'),
('rm',9,10,'crampon1923','Et non seulement Sara; mais il en fut encore ainsi de Rebecca qui conçut deux enfants d''un seul homme, d''Isaac notre père;'),
('rm',9,11,'crampon1923','car, avant même que les enfants fussent nés, et qu''ils eussent rien fait, ni bien ni mal, — afin que le dessein électif de Dieu fût reconnu ferme, non en vertu des œuvres, mais par le choix de celui qui appelle, —'),
('rm',9,12,'crampon1923','il fut dit à Rebecca: " L''aîné sera assujetti au plus jeune, "'),
('rm',9,13,'crampon1923','selon qu''il est écrit: " J''ai aimé Jacob, et j''ai haï Esaü. "'),
('rm',9,14,'crampon1923','Que dirons-nous donc? Y a-t-il de l''injustice en Dieu? Loin de là!'),
('rm',9,15,'crampon1923','Car il dit à Moïse: " Je ferai miséricorde à qui je veux faire miséricorde, et j''aurai compassion de qui je veux avoir compassion. "'),
('rm',9,16,'crampon1923','Ainsi donc l''élection ne dépend ni de la volonté, ni des efforts, mais de Dieu qui fait miséricorde.'),
('rm',9,17,'crampon1923','Car l''Ecriture dit à Pharaon: " Je t''ai suscité, pour montrer en toi ma puissance, et pour que mon nom soit célébré sur toute la terre. "'),
('rm',9,18,'crampon1923','Ainsi il fait miséricorde à qui il veut, et il endurcit qui il veut.'),
('rm',9,19,'crampon1923','Tu me diras: De quoi donc Dieu se plaint-il encore? Car qui peut s''opposer à sa volonté?'),
('rm',9,20,'crampon1923','Mais plutôt, ô homme, qui es-tu pour contester avec Dieu? Est-ce que le vase d''argile dit à celui qui l''a façonné: Pourquoi m''as-tu fait ainsi?'),
('rm',9,21,'crampon1923','Le potier n''est-il pas maître de son argile, pour faire de la même masse un vase d''honneur et un vase d''ignominie?'),
('rm',9,22,'crampon1923','Et si Dieu, voulant montrer sa colère et faire connaître sa puissance, a supporté avec une grande patience des vases de colère, formés pour la perdition,'),
('rm',9,23,'crampon1923','et s''il a voulu faire connaître aussi les richesses de sa gloire à l''égard des vases de miséricorde qu''il a d''avance préparés pour la gloire,'),
('rm',9,24,'crampon1923','envers nous, qu''il a appelés, non seulement d''entre les Juifs, mais encore d''entre les Gentils, où est l''injustice?'),
('rm',9,25,'crampon1923','C''est ainsi qu''il dit dans Osée: " Celui qui n''était pas mon peuple, je l''appellerai mon peuple et celle qui n''était pas la bien-aimée, je l''appellerai bien-aimée. "'),
('rm',9,26,'crampon1923','" Et dans le lieu où il leur fut dit: Vous n''êtes pas mon peuple, là même on les appellera fils du Dieu vivant. "'),
('rm',9,27,'crampon1923','D''autre part, Isaïe s''écrie au sujet d''Israël: " Quand le nombre des fils d''Israël serait comme le sable de la mer, un faible reste seulement sera sauvé. "'),
('rm',9,28,'crampon1923','Car accomplissant sa parole pleinement et promptement, il l''exécutera sur la terre [en toute justice].'),
('rm',9,29,'crampon1923','Et comme Isaïe l''avait prédit: " Si le Seigneur des armées ne nous avait laissé un rejeton, nous serions devenus comme Sodome, et nous aurions été semblables à Gomorrhe. "'),
('rm',9,30,'crampon1923','Que dirons-nous donc? Que les Gentils, qui ne cherchaient pas la justice, on atteint la justice, mais la justice qui vient de la foi,'),
('rm',9,31,'crampon1923','tandis qu''Israël, qui cherchait une loi de justice, n''est point parvenu à une loi de justice.'),
('rm',9,32,'crampon1923','Pourquoi? parce qu''il a cherché à l''atteindre, non par la foi, mais comme s''il avait pu arriver par les œuvres. Il s''est heurté contre la pierre d''achoppement,'),
('rm',9,33,'crampon1923','selon qu''il est écrit: " Voici que je mets en Sion une pierre d''achoppement et un rocher de scandale, mais quiconque croit en lui ne sera pas confondu. "'),
('rm',10,1,'crampon1923','Frères, le vœu de mon cœur et ma prière à Dieu pour eux, c''est qu''ils soient sauvés.'),
('rm',10,2,'crampon1923','Car je leur rends le témoignage qu''ils ont du zèle pour Dieu, mais c''est un zèle mal éclairé.'),
('rm',10,3,'crampon1923','Ne connaissant pas la justice de Dieu, et cherchant à établir leur propre justice, ils ne se sont pas soumis à la justice de Dieu.'),
('rm',10,4,'crampon1923','C''est qu''en effet le fin de la Loi c''est le Christ, pour la justification de tout homme qui croit.'),
('rm',10,5,'crampon1923','En effet, Moïse dit de la justice qui vient de la Loi: " L''homme qui mettra ces choses en pratique vivra par elles. "'),
('rm',10,6,'crampon1923','Mais voici comment parle la justice qui vient de la foi: " Ne dis pas dans ton cœur: Qui montera au Ciel " Ce qui signifie en faire descendre le Christ;'),
('rm',10,7,'crampon1923','ou: " Qui descendra dans l''abîme? " Ce qui signifie faire remonter le Christ d''entre les morts.'),
('rm',10,8,'crampon1923','Que dit-elle donc? " Près de toi est la parole, dans ta bouche et dans ton cœur. " C''est la parole de la foi que nous prêchons.'),
('rm',10,9,'crampon1923','Si tu confesses de ta bouche Jésus comme Seigneur, et si tu crois dans ton cœur que Dieu l''a ressuscité des morts tu seras sauvé.'),
('rm',10,10,'crampon1923','Car c''est en croyant de cœur qu''on parvient à la justice, et c''est en confessant de bouche qu''on parvient au salut,'),
('rm',10,11,'crampon1923','selon ce que dit l''Ecriture: " Quiconque croit en lui ne sera pas confondu. "'),
('rm',10,12,'crampon1923','Il n''y a pas de différence entre le Juif et le Gentil, parce que le même Christ est le Seigneur de tous, étant riche envers tous ceux qui l''invoquent.'),
('rm',10,13,'crampon1923','Car " quiconque invoquera le nom du Seigneur sera sauvé. "'),
('rm',10,14,'crampon1923','Comment donc invoquera-t-on celui en qui on n''a pas encore cru? Et comment croira-t-on en celui dont on n''a pas entendu parler? Et comment en entendra-t-on parler s''il n''y a pas de prédicateur?'),
('rm',10,15,'crampon1923','Et comment seront-ils prédicateurs, s''ils ne sont pas envoyés? selon qu''il est écrit: " Qu''ils sont beaux les pieds de ceux qui annoncent le bonheur! "'),
('rm',10,16,'crampon1923','Mais tous n''ont pas obéi à l''Evangile; car Isaïe dit: " Seigneur, qui a cru à notre prédication? "'),
('rm',10,17,'crampon1923','Ainsi la foi vient de la prédication entendue, et la prédication se fait par la parole de Dieu.'),
('rm',10,18,'crampon1923','Mais je demande: n''ont-ils pas entendu? Au contraire: " Leur voix est allée par toute la terre, et leurs paroles jusqu''aux extrémités du monde. "'),
('rm',10,19,'crampon1923','Je demande encore: Israël n''en a-t-il pas eu connaissance? Moïse le premier a dit: " J''exciterai votre jalousie contre une nation qui n''en est pas une; j''exciterai votre colère contre une nation sans intelligence. "'),
('rm',10,20,'crampon1923','Et Isaïe pousse la hardiesse jusqu''à dire: " J''ai été trouvé par ceux qui ne me cherchaient pas, je me suis manifesté à ceux qui ne me demandaient pas. "'),
('rm',10,21,'crampon1923','Mais au sujet d''Israël il dit: " J''ai tendu mes mains tout le jour vers un peuple incroyant et rebelle. "'),
('rm',11,1,'crampon1923','Je dis donc: Est-ce que Dieu a rejeté son peuple? Loin de là! Car moi aussi, je suis Israélite, de la postérité d''Abraham, de la race de Benjamin.'),
('rm',11,2,'crampon1923','Non, Dieu n''a pas rejeté son peuple, qu''il a connu d''avance. Ne savez-vous pas ce que l''Ecriture rapporte dans le chapitre d''Elie, comment il adresse à Dieu cette plainte contre Israël:'),
('rm',11,3,'crampon1923','" Seigneur, ils ont tué vos prophètes, ils ont renversé vos autels, je suis resté moi seul, et ils en veulent à ma vie. "'),
('rm',11,4,'crampon1923','Mais que lui répond la voix divine? " Je me suis réservé sept mille hommes qui n''ont pas fléchi le genou devant Baal. "'),
('rm',11,5,'crampon1923','De même aussi, dans le temps présent, il y a une réserve selon un choix de grâce.'),
('rm',11,6,'crampon1923','Or, si c''est par grâce, ce n''est plus par les œuvres; autrement la grâce cesse d''être une grâce. [Et si c''est par les œuvres, ce n''est plus une grâce; autrement l''œuvre cesse d''être une œuvre.]'),
('rm',11,7,'crampon1923','Que dirons-nous donc? Ce qu''Israël cherche, il ne l''a pas obtenu; mais ceux que Dieu a choisis l''ont obtenu, tandis que les autres ont été aveuglés,'),
('rm',11,8,'crampon1923','selon qu''il est écrit: " Dieu leur a donné un esprit d''étourdissement, des yeux pour ne point voir, et des oreilles pour ne point entendre, jusqu''à ce jour. "'),
('rm',11,9,'crampon1923','Et David dit: " Que leur table leur devienne un piège, un lacet, un trébuchet et un juste châtiment!'),
('rm',11,10,'crampon1923','Que leurs yeux soient obscurcis pour ne point voir; tiens leur dos continuellement courbé! "'),
('rm',11,11,'crampon1923','Je demande donc, Ont-ils bronché, afin de tomber pour toujours? Loin de là! mais par leur chute, le salut est arrivé aux Gentils, de manière à exciter la jalousie d''Israël.'),
('rm',11,12,'crampon1923','Or, si leur chute a été la richesse du monde, et leur amoindrissement la richesse des Gentils, que ne sera pas leur plénitude!'),
('rm',11,13,'crampon1923','En effet, je vous le dis, à vous, chrétiens nés dans la gentilité: moi-même, en tant qu''apôtre des Gentils, je m''efforce de rendre mon ministère glorieux,'),
('rm',11,14,'crampon1923','afin, s''il est possible, d''exciter la jalousie de ceux de mon sang, et d''en sauver quelques-uns.'),
('rm',11,15,'crampon1923','Car si leur rejet a été la réconciliation du monde, que sera leur réintégration, sinon une résurrection d''entre les morts?'),
('rm',11,16,'crampon1923','Si les prémices sont saintes, la masse l''est aussi; et si la racine est sainte, les branches le sont aussi.'),
('rm',11,17,'crampon1923','Mais si quelques-unes des branches ont été retranchées, et si toi, qui n''étais qu''un olivier sauvage, tu as été enté à leur place et rendu participant de la racine et de la sève de l''olivier,'),
('rm',11,18,'crampon1923','ne te glorifie pas à l''encontre des branches. Si tu te glorifies, sache que ce n''est pas toi qui portes la racine, mais que c''est la racine qui te porte.'),
('rm',11,19,'crampon1923','Tu diras donc: Ces branches ont été retranchées, afin que moi je fusse enté.'),
('rm',11,20,'crampon1923','Cela est vrai; ils ont été retranchés à cause de leur incrédulité, et toi, tu subsistes par la foi; garde-toi de pensées orgueilleuses, mais crains.'),
('rm',11,21,'crampon1923','Car si Dieu n''a pas épargné les branches naturelles, crains qu''il ne t''épargne pas non plus.'),
('rm',11,22,'crampon1923','Considère donc la bonté et la sévérité de Dieu: sa sévérité envers ceux qui sont tombés, et sa bonté envers toi, si tu te maintiens dans cette bonté; autrement toi aussi tu seras retranché.'),
('rm',11,23,'crampon1923','Eux aussi, s''ils ne persévèrent pas dans leur incrédulité, ils seront entés; car Dieu est puissant pour les enter de nouveau.'),
('rm',11,24,'crampon1923','Si toi, tu as été coupé sur un olivier de nature sauvage, et enté, contrairement à ta nature, sur l''olivier franc, à plus forte raison les branches naturelles seront-elles entées sur leur propre olivier.'),
('rm',11,25,'crampon1923','Car je ne veux pas, frères, que vous ignoriez ce mystère, afin que vous ne soyez pas sages à vos propres yeux: c''est qu''une partie d''Israël est tombée dans l''aveuglement jusqu''à ce que la masse des Gentils soit entrée.'),
('rm',11,26,'crampon1923','Et ainsi tout Israël sera sauvé, selon qu''il est écrit: " Le libérateur viendra de Sion, et il éloignera de Jacob toute impiété;'),
('rm',11,27,'crampon1923','et ce sera mon alliance avec eux, lorsque j''aurai ôté leurs péchés. "'),
('rm',11,28,'crampon1923','Il est vrai, en ce qui concerne l''Evangile, ils sont encore ennemis à cause de vous; mais eu égard au choix divin, ils sont aimés à cause de leurs pères.'),
('rm',11,29,'crampon1923','Car les dons et la vocation de Dieu sont sans repentance.'),
('rm',11,30,'crampon1923','Et comme vous-mêmes autrefois vous avez désobéi à Dieu, et que, par le fait de leur désobéissance, vous avez maintenant obtenu miséricorde,'),
('rm',11,31,'crampon1923','de même, eux aussi, ils ont maintenant désobéi, à cause de la miséricorde qui vous a été faite, afin qu''ils obtiennent également miséricorde.'),
('rm',11,32,'crampon1923','Car Dieu a enfermé tous les hommes dans la désobéissance, pour faire miséricorde à tous.'),
('rm',11,33,'crampon1923','O profondeur inépuisable et de la sagesse et de la science de Dieu! Que ses jugements sont insondables et ses voies incompréhensibles!'),
('rm',11,34,'crampon1923','Car " qui a connu la pensée du Seigneur ou qui a été son conseiller? "'),
('rm',11,35,'crampon1923','Ou bien " qui lui a donné le premier, pour qu''il ait à recevoir en retour?'),
('rm',11,36,'crampon1923','De lui, par lui et pour lui sont toutes choses. A lui la gloire dans tous les siècles! Amen!'),
('rm',12,1,'crampon1923','Je vous exhorte donc, mes frères, par la miséricorde de Dieu, à offrir vos corps comme une hostie vivante, sainte, agréable à Dieu: c''est là le culte spirituel que vous lui devez.'),
('rm',12,2,'crampon1923','Et ne vous conformez pas au siècle présent, mais transformez-vous par le renouvellement de l''esprit, afin que vous éprouviez quelle est la volonté de Dieu, ce qui est bon, ce qui lui est agréable, ce qui est parfait.'),
('rm',12,3,'crampon1923','En vertu de la grâce qui m''a été donnée, je dis à chacun de vous de ne pas s''estimer plus qu''il ne faut; mais d''avoir des sentiments modestes, chacun selon la mesure de la foi que Dieu lui a départie.'),
('rm',12,4,'crampon1923','Car, de même que nous avons plusieurs membres dans un seul corps, et que tous les membres n''ont pas la même fonction,'),
('rm',12,5,'crampon1923','ainsi, nous qui sommes plusieurs, nous ne faisons qu''un seul corps dans le Christ, et chacun en particulier nous sommes membres les uns des autres;'),
('rm',12,6,'crampon1923','et nous avons des dons différents selon la grâce qui nous a été donnée: soit de prophétie, selon la mesure de notre foi,'),
('rm',12,7,'crampon1923','soit de ministère, pour nous contenir dans le ministère; celui-ci a reçu le don d''enseigner: qu''il enseigne;'),
('rm',12,8,'crampon1923','celui-là, le don d''exhorter: qu''il exhorte; un autre distribue: qu''il s''en acquitte avec simplicité; un autre préside: qu''il le fasse avec zèle; un autre exerce les œuvres de miséricorde: qu''il s''y livre avec joie.'),
('rm',12,9,'crampon1923','Que votre charité soit sans hypocrisie. Ayez le mal en horreur; attachez-vous fortement au bien.'),
('rm',12,10,'crampon1923','Quant à l''amour fraternel, soyez pleins d''affection les uns pour les autres, vous prévenant d''honneur les uns les autres;'),
('rm',12,11,'crampon1923','pour ce qui est du zèle, ne soyez pas nonchalants. Soyez fervents d''esprit; c''est le Seigneur que vous servez.'),
('rm',12,12,'crampon1923','Soyez pleins de la joie que donne l''espérance, patients dans l''affliction, assidus à la prière,'),
('rm',12,13,'crampon1923','prêts à subvenir aux nécessités des saints, empressés à donner l''hospitalité.'),
('rm',12,14,'crampon1923','Bénissez ceux qui vous persécutent: bénissez et ne maudissez pas.'),
('rm',12,15,'crampon1923','Réjouissez-vous avec ceux qui sont dans la joie; pleurez avec ceux qui pleurent.'),
('rm',12,16,'crampon1923','Ayez les mêmes sentiments entre vous; n''aspirez pas à ce qui est élevé, mais laissez-vous attirer par ce qui est humble. Ne soyez point sages à vos propres yeux;'),
('rm',12,17,'crampon1923','ne rendez à personne le mal pour le mal; veillez à faire ce qui est bien devant tous les hommes.'),
('rm',12,18,'crampon1923','S''il est possible, autant qu''il dépend de vous, soyez en paix avec tous.'),
('rm',12,19,'crampon1923','Ne vous vengez point vous-mêmes, bien-aimés; mais laissez agir la colère de Dieu; car il est écrit: " A moi la vengeance; c''est moi qui rétribuerai, dit le Seigneur. "'),
('rm',12,20,'crampon1923','Si ton ennemi a faim, donne-lui à manger; s''il a soif, donne-lui à boire; car en agissant ainsi, tu amasseras des charbons de feu sur sa tête.'),
('rm',12,21,'crampon1923','Ne te laisse pas vaincre par le mal, mais triomphe du mal par le bien.'),
('rm',13,1,'crampon1923','Que toute âme soit soumise aux autorités supérieures; car il n''y a point d''autorité qui ne vienne de Dieu, et celles qui existent ont été instituées par lui.'),
('rm',13,2,'crampon1923','C''est pourquoi celui qui résiste à l''autorité, résiste à l''ordre que Dieu a établi et ceux qui résistent, attireront sur eux-mêmes une condamnation.'),
('rm',13,3,'crampon1923','Car les magistrats ne sont point à redouter pour les bonnes actions, mais pour les mauvaises. Veux-tu ne pas craindre l''autorité? Fais le bien, et tu auras son approbation;'),
('rm',13,4,'crampon1923','car le prince est pour toi ministre de Dieu pour le bien. Mais si tu fais le mal, crains; car ce n''est pas en vain qu''il porte l''épée, étant ministre de Dieu pour tirer vengeance de celui qui fait le mal, et le punir.'),
('rm',13,5,'crampon1923','Il est nécessaire d''être soumis, non seulement par crainte du châtiment, mais aussi par motif de conscience.'),
('rm',13,6,'crampon1923','C''est aussi pour cette raison que vous payez les impôts; car les magistrats sont des ministres de Dieu, entièrement appliqués à cette fonction.'),
('rm',13,7,'crampon1923','Rendez [donc] à tous ce qui leur est dû: à qui l''impôt, l''impôt; à qui le tribut, le tribut; à qui la crainte, la crainte; à qui l''honneur, l''honneur.'),
('rm',13,8,'crampon1923','Ne soyez en dette avec personne, si ce n''est de l''amour mutuel; car celui qui aime son prochain a accompli la loi.'),
('rm',13,9,'crampon1923','En effet, ces commandements: " Tu ne commettras point d''adultère; tu ne tueras point; tu ne déroberas point; [tu ne diras point de faux témoignage]; tu ne convoiteras point, " et ceux qu''on pourrait citer encore, se résument dans cette parole: " Tu aimeras ton prochain comme toi-même. "'),
('rm',13,10,'crampon1923','L''amour ne fait point de mal au prochain; l''amour est donc la plénitude de la loi.'),
('rm',13,11,'crampon1923','Cela importe d''autant plus, que vous savez en quel temps nous sommes: c''est l''heure de nous réveiller enfin du sommeil; car maintenant le salut est plus près de nous que lorsque nous avons embrassé la foi.'),
('rm',13,12,'crampon1923','La nuit est avancée, et le jour approche. Dépouillons-nous donc des œuvres des ténèbres et revêtons les armes de la lumière.'),
('rm',13,13,'crampon1923','Marchons honnêtement, comme en plein jour, ne nous laissant point aller aux excès de la table et du vin, à la luxure et à l''impudicité, aux querelles et aux jalousies.'),
('rm',13,14,'crampon1923','Mais revêtez-vous du Seigneur Jésus-Christ, et ne prenez pas soin de la chair, de manière à en exciter les convoitises.'),
('rm',14,1,'crampon1923','Quant à celui qui est faible dans la foi, accueillez-le sans discuter ses opinions.'),
('rm',14,2,'crampon1923','Tel croit pouvoir manger de tout; tel autre, qui est faible, se nourrit de légumes.'),
('rm',14,3,'crampon1923','Que celui qui mange ne méprise point celui qui ne mange pas, et que celui qui ne mange pas ne juge point celui qui mange, car Dieu l''a accueilli parmi les siens.'),
('rm',14,4,'crampon1923','Qui es-tu, toi qui juges le serviteur d''autrui? S''il se tient debout, ou s''il tombe, cela regarde son maître. Mais il se tiendra debout, car Dieu a le pouvoir de le soutenir.'),
('rm',14,5,'crampon1923','Tel met de la différence entre les jours; tel autre les estime tous pareils: que chacun ait dans son esprit une pleine conviction.'),
('rm',14,6,'crampon1923','Celui qui observe tel ou tel jour, l''observe en vue du Seigneur; et celui qui mange, mange en vue du Seigneur, car il rend grâces à Dieu; et celui qui ne mange pas, c''est en vue du Seigneur qu''il ne mange pas, et il rend aussi grâces à Dieu.'),
('rm',14,7,'crampon1923','En effet, nul de nous ne vit pour soi-même, et nul ne meurt pour soi-même.'),
('rm',14,8,'crampon1923','Car, soit que nous vivions, nous vivons pour le Seigneur; soit que nous mourrions, nous mourons pour le Seigneur. Soit donc que nous vivions, soit que nous mourions, nous appartenons au Seigneur.'),
('rm',14,9,'crampon1923','Car le Christ est mort et a vécu afin d''être le Seigneur et des morts et des vivants.'),
('rm',14,10,'crampon1923','Mais toi, pourquoi juges-tu ton frère? Toi, aussi, pourquoi méprises-tu ton frère? puisque nous paraîtrons tous devant le tribunal du Christ;'),
('rm',14,11,'crampon1923','car il est écrit: " Je suis vivant, dit le Seigneur; tout genou fléchira devant moi, et toute langue donnera gloire à Dieu. "'),
('rm',14,12,'crampon1923','Ainsi chacun de nous rendra compte à Dieu pour soi-même.'),
('rm',14,13,'crampon1923','Ne nous jugeons donc plus les uns les autres; mais jugez plutôt qu''il ne faut rien faire qui soit pour votre frère une pierre d''achoppement ou une occasion de chute.'),
('rm',14,14,'crampon1923','Je sais et je suis persuadé dans le Seigneur Jésus que rien n''est impur en soi; néanmoins, si quelqu''un estime qu''une chose est impure, elle est impure pour lui.'),
('rm',14,15,'crampon1923','Or, si pour un aliment, tu contristes ton frère, tu ne marches plus selon la charité; n''entraîne pas à la perdition, par ton aliment, un homme pour lequel le Christ est mort.'),
('rm',14,16,'crampon1923','Que votre bien ne soit pas un sujet de blasphème!'),
('rm',14,17,'crampon1923','Car le royaume de Dieu ce n''est pas le manger et le boire; mais la justice et la paix et la joie dans l''Esprit-Saint.'),
('rm',14,18,'crampon1923','Celui qui sert le Christ de cette manière est agréable à Dieu et approuvé des hommes.'),
('rm',14,19,'crampon1923','Recherchons donc ce qui contribue à la paix et à l''édification mutuelle.'),
('rm',14,20,'crampon1923','Garde-toi, pour un aliment, de détruire l''œuvre de Dieu. Il est vrai que toutes choses sont pures, mais il est mal à un homme de devenir en mangeant une pierre d''achoppement.'),
('rm',14,21,'crampon1923','Ce qui est bien, c''est de ne pas manger de viande, de ne pas boire de vin, de ne rien faire qui soit pour ton frère une occasion de chute, [de scandale ou de faiblesse].'),
('rm',14,22,'crampon1923','As-tu une conviction? Garde-la pour toi-même devant Dieu. Heureux celui qui ne se condamne pas dans l''acte qu''il approuve.'),
('rm',14,23,'crampon1923','Mais celui qui a des doutes, s''il mange, il est condamné, parce qu''il n''agit pas par conviction; tout ce qui ne procède pas d''une conviction est péché.'),
('rm',15,1,'crampon1923','Nous devons, nous qui sommes forts, supporter les faiblesses de ceux qui ne le sont pas, et ne pas nous plaire à nous-mêmes.'),
('rm',15,2,'crampon1923','Que chacun de nous cherche à complaire au prochain pour le bien, afin de l''édifier.'),
('rm',15,3,'crampon1923','Car le Christ n''a pas eu de complaisance pour lui-même; mais, selon qu''il est écrit: " Les outrages de ceux qui t''outragent sont tombés sur moi. "'),
('rm',15,4,'crampon1923','Car tout ce qui a été écrit avant nous l''a été pour notre instruction, afin que, par la patience et la consolation que donnent les Ecritures, nous possédions l''espérance.'),
('rm',15,5,'crampon1923','Que le Dieu de la patience et de la consolation vous donne d''avoir les uns envers les autres les mêmes sentiments selon Jésus-Christ,'),
('rm',15,6,'crampon1923','afin que, d''un même cœur et d''une même bouche, vous glorifiez Dieu, le Père de Notre-Seigneur Jésus-Christ.'),
('rm',15,7,'crampon1923','Accueillez-vous donc les uns les autres, comme le Christ vous a accueillis, pour la gloire de Dieu.'),
('rm',15,8,'crampon1923','J''affirme, en effet, que le Christ a été ministre des circoncis, pour montrer la véracité de Dieu, en accomplissant les promesses faites à leurs pères,'),
('rm',15,9,'crampon1923','tandis que les Gentils glorifient Dieu à cause de sa miséricorde, selon qu''il est écrit: " C''est pourquoi je te louerai parmi les nations, et je chanterai à la gloire de ton nom. "'),
('rm',15,10,'crampon1923','L''Ecriture dit encore: " Nations, réjouissez-vous avec son peuple. "'),
('rm',15,11,'crampon1923','Et ailleurs: " Nations, louez toutes le Seigneur; peuples, célébrez-le tous. "'),
('rm',15,12,'crampon1923','Isaïe dit aussi: " Il paraîtra, le rejeton de Jessé, celui qui se lève pour régner sur les nations; en lui les nations mettront leur espérance. "'),
('rm',15,13,'crampon1923','Que le Dieu de l''espérance vous remplisse de toute joie et de toute paix dans la foi, afin que, par la vertu de l''Esprit-Saint, vous abondiez en espérance!'),
('rm',15,14,'crampon1923','Moi aussi, mes frères, j''ai de vous cette persuasion que vous êtes de vous-mêmes pleins de bons sentiments, remplis de toute connaissance, et capables de vous avertir les uns les autres.'),
('rm',15,15,'crampon1923','Cependant je vous ai écrit plus librement, comme pour raviver en partie vos souvenirs, — à cause de la grâce que Dieu m''a faite'),
('rm',15,16,'crampon1923','d''être ministre de Jésus-Christ, pour les Gentils, — en m''acquittant du divin service de l''Evangile de Dieu, afin que l''offrande des Gentils soit agréée, étant sanctifiée par le Saint-Esprit.'),
('rm',15,17,'crampon1923','J''ai donc sujet de me glorifier en Jésus-Christ pour ce qui regarde le service de Dieu.'),
('rm',15,18,'crampon1923','Car je n''oserais point parler de choses que le Christ n''aurait pas faites par mon ministère pour amener les païens à obéir à l''Evangile, par la parole et par l''action,'),
('rm',15,19,'crampon1923','par la vertu des miracles et des prodiges, par la puissance de l''Esprit-Saint: si bien que, depuis Jérusalem et les pays voisins jusqu''à l''Illyrie, j''ai porté partout l''Evangile du Christ,'),
('rm',15,20,'crampon1923','mettant toutefois mon honneur à prêcher l''Evangile là où le Christ n''avait pas encore été nommé, afin de ne pas bâtir sur le fondement qu''un autre aurait posé,'),
('rm',15,21,'crampon1923','mais selon qu''il est écrit: " Ceux à qui il n''avait pas été annoncé le verront, et ceux qui n''en avaient pas entendu parler le connaîtront. "'),
('rm',15,22,'crampon1923','C''est ce qui m''a souvent empêché d''aller chez vous.'),
('rm',15,23,'crampon1923','Mais maintenant n''ayant plus rien qui me retienne dans ces contrées, et ayant depuis plusieurs années le désir d''aller vers vous,'),
('rm',15,24,'crampon1923','j''espère vous voir en passant, quand je me rendrai en Espagne, et y être accompagné par vous, après que j''aurai satisfait, en partie du moins, mon désir de me trouver parmi vous.'),
('rm',15,25,'crampon1923','Présentement je vais à Jérusalem, pour venir en aide aux saints.'),
('rm',15,26,'crampon1923','Car la Macédoine et l''Achaïe ont bien voulu faire une collecte en faveur des saints de Jérusalem qui sont dans la pauvreté.'),
('rm',15,27,'crampon1923','Elles l''ont bien voulu; aussi bien elles le leur devaient; car si les Gentils ont eu part à leurs biens spirituels, ils doivent à leur tour les assister de leurs biens temporels.'),
('rm',15,28,'crampon1923','Dès que j''aurai terminé cette affaire et que j''aurai consigné ce don entre leurs mains, je partirai pour l''Espagne et passerai chez vous.'),
('rm',15,29,'crampon1923','Or je sais qu''en allant chez vous, j''y viendrai avec une abondante bénédiction du Christ.'),
('rm',15,30,'crampon1923','Je vous exhorte, mes frères, par Notre-Seigneur Jésus-Christ et par la charité du Saint-Esprit, à combattre avec moi, en adressant pour moi des prières à Dieu,'),
('rm',15,31,'crampon1923','afin que j''échappe aux incrédules qui sont en Judée, et que l''offrande que je porte à Jérusalem soit agréable aux saints,'),
('rm',15,32,'crampon1923','en sorte que j''arrive chez vous dans la joie, si c''est la volonté de Dieu, et que je goûte quelque repos au milieu de vous.'),
('rm',15,33,'crampon1923','Que le Dieu de paix soit avec vous tous! Amen!'),
('rm',16,1,'crampon1923','Je vous recommande Phœbé, notre sœur, qui est diaconesse de l''Eglise de Cenchrées,'),
('rm',16,2,'crampon1923','afin que vous la receviez en Notre-Seigneur d''une manière digne des saints, et que vous l''assistiez dans toutes les choses où elle pourrait avoir besoin de vous, car elle aussi a donné aide à plusieurs et à moi-même.'),
('rm',16,3,'crampon1923','Saluez Prisca et Aquila, mes coopérateurs en Jésus-Christ,'),
('rm',16,4,'crampon1923','eux qui, pour sauver ma vie, ont exposé leur tête; ce n''est pas moi seul qui leur rend grâces, ce sont encore toutes les Eglises des Gentils.'),
('rm',16,5,'crampon1923','Saluez aussi l''Eglise qui est dans leur maison. — Saluez Epénète, mon bien-aimé, qui a été pour le Christ les prémices de l''Asie. —'),
('rm',16,6,'crampon1923','Saluez Marie, qui a pris beaucoup de peine pour vous. —'),
('rm',16,7,'crampon1923','Saluez Andronique et Junias, mes parents et mes compagnons de captivité, qui jouissent d''une grande considération parmi les apôtres et qui même ont été dans le Christ avant moi. —'),
('rm',16,8,'crampon1923','Saluez Amplias, mon bien-aimé dans le Seigneur. —'),
('rm',16,9,'crampon1923','Saluez Urbain, notre coopérateur dans le Christ, et Stachys, mon bien-aimé. —'),
('rm',16,10,'crampon1923','Saluez Apelle, qui a fait ses preuves dans le Christ. Saluez ceux de la maison d''Aristobule. —'),
('rm',16,11,'crampon1923','Saluez Hérodion, mon parent. Saluez ceux de la maison de Narcisse qui sont dans le Seigneur. —'),
('rm',16,12,'crampon1923','Saluez Tryphène et Tryphose, qui travaillent dans le Seigneur. Saluez Perside, la bien-aimée qui a beaucoup travaillé dans le Seigneur. —'),
('rm',16,13,'crampon1923','Saluez Rufus, distingué dans le Seigneur, et sa mère, qui est aussi la mienne. —'),
('rm',16,14,'crampon1923','Saluez Asyncrite, Phlégon, Hermés, Patrobas, Hermas, et les frères qui sont avec eux. —'),
('rm',16,15,'crampon1923','Saluez Philologue et Julie, Nérée et sa sœur, ainsi qu''Olympias, et tous les saints qui sont avec eux. —'),
('rm',16,16,'crampon1923','Saluez-vous les uns les autres par un saint baiser. Toutes les Eglises du Christ vous saluent.'),
('rm',16,17,'crampon1923','Je vous exhorte, mes frères, à prendre garde à ceux qui causent les divisions et les scandales, en s''écartant de l''enseignement que vous avez reçu; éloignez-vous d''eux.'),
('rm',16,18,'crampon1923','Car de tels hommes ne servent point le Christ Notre-Seigneur, mais leur propre ventre, et avec leurs paroles douces et leur langage flatteur, ils séduisent les cœurs des simples.'),
('rm',16,19,'crampon1923','Car votre obéissance est arrivée aux oreilles de tous; je me réjouis donc à votre sujet; mais je désire que vous soyez prudents pour le bien et simple pour le mal.'),
('rm',16,20,'crampon1923','Le Dieu de paix écrasera bientôt Satan sous vos pieds. Que la grâce de Notre-Seigneur Jésus-Christ soit avec vous!'),
('rm',16,21,'crampon1923','Timothée, le compagnon de mes travaux, vous salue, ainsi que Lucius, Jason et Sosipater, mes parents. —'),
('rm',16,22,'crampon1923','Je vous salue dans le Seigneur, moi Tertius, qui ai écrit cette lettre. —'),
('rm',16,23,'crampon1923','Caïus, mon hôte et celui de l''Eglise, vous salue. Eraste, le trésorier de la ville, vous salue, ainsi que Quartus, notre frère.'),
('rm',16,24,'crampon1923','[Que la grâce de Notre-Seigneur Jésus-Christ soit avec vous tous! Amen!]'),
('rm',16,25,'crampon1923','A celui qui peut vous affermir selon mon Evangile et la prédication de Jésus-Christ, — conformément à la révélation du mystère resté caché durant de longs siècles,'),
('rm',16,26,'crampon1923','mais manifesté maintenant, et, selon l''ordre du Dieu éternel, porté par les écrits des prophètes, à la connaissance de toutes les nations pour qu''elles obéissent à la foi, —'),
('rm',16,27,'crampon1923','à Dieu, seul sage, soit la gloire par Jésus-Christ aux siècles des siècles! Amen!'),
('1co',1,1,'crampon1923','Paul, apôtre de Jésus-Christ appelé par la volonté de Dieu, et Sosthène, son frère,'),
('1co',1,2,'crampon1923','à l''Eglise de Dieu qui est à Corinthe, aux fidèles sanctifiés en Jésus-Christ, saints par vocation, et à tous ceux qui invoquent, en quelque lieu que ce soit, le nom de Notre-Seigneur Jésus-Christ, leur Seigneur et le nôtre:'),
('1co',1,3,'crampon1923','grâce et paix vous soient données de la part de Dieu notre Père et du Seigneur Jésus-Christ!'),
('1co',1,4,'crampon1923','Je rends à mon Dieu de continuelles actions de grâces à votre sujet, pour la grâce de Dieu qui vous a été faite en Jésus-Christ.'),
('1co',1,5,'crampon1923','Car par votre union avec lui, vous avez été comblés de toute sorte de richesses, en toute parole et en toute connaissance,'),
('1co',1,6,'crampon1923','le témoignage du Christ ayant été solidement établi parmi vous,'),
('1co',1,7,'crampon1923','de sorte que vous ne le cédez à personne en aucun don de grâce, attendant avec confiance la révélation de Notre-Seigneur Jésus-Christ.'),
('1co',1,8,'crampon1923','Il vous affermira aussi jusqu''à la fin, pour que vous soyez irréprochables, au jour de Notre-Seigneur Jésus-Christ.'),
('1co',1,9,'crampon1923','Il est fidèle, le Dieu, qui vous a appelés à la communion de son Fils Jésus-Christ, Notre-Seigneur.'),
('1co',1,10,'crampon1923','Je vous exhorte, frères, au nom de Notre-Seigneur Jésus-Christ, à avoir tous un même langage; qu''il n''y ait point de scission parmi vous, mais soyez parfaitement unis dans un même esprit, et un même sentiment.'),
('1co',1,11,'crampon1923','Car il m''a été rapporté à votre sujet, mes frères, par les gens de Chloé, qu''il y a des disputes parmi vous.'),
('1co',1,12,'crampon1923','Je veux dire que tel d''entre vous dit: " Moi, je suis à Paul! — tel autre: et moi, à Apollos! — et moi à Céphas! — et moi, au Christ! "'),
('1co',1,13,'crampon1923','Le Christ est-il divisé? Est-ce Paul qui a été crucifié pour vous? Est-ce au nom de Paul que vous avez été baptisés?'),
('1co',1,14,'crampon1923','Je rends grâces à Dieu de ce que je n''ai baptisé aucun de vous, si ce n''est Crispus et Gaïus,'),
('1co',1,15,'crampon1923','afin que personne ne puisse dire qu''il a été baptisé en mon nom.'),
('1co',1,16,'crampon1923','J''ai encore baptisé la famille de Stéphanas; du reste, je ne sache pas que j''ai baptisé personne d''autre.'),
('1co',1,17,'crampon1923','Ce n''est pas pour baptiser que le Christ m''a envoyé, c''est pour prêcher l''Evangile, non point par la sagesse du discours, afin que la croix du Christ ne soit pas rendue vaine.'),
('1co',1,18,'crampon1923','En effet, la doctrine de la croix est une folie pour ceux qui périssent; mais pour nous qui sommes sauvés, elle est une force divine.'),
('1co',1,19,'crampon1923','Car il est écrit: " Je détruirai la sagesse des sages, et j''anéantirai la science des savants. "'),
('1co',1,20,'crampon1923','Où est le sage? où est le docteur? où est le disputeur de ce siècle? Dieu n''a-t-il pas convaincu de folie la sagesse du monde?'),
('1co',1,21,'crampon1923','Car le monde, avec sa sagesse, n''ayant pas connu Dieu dans la sagesse de Dieu, il a plu à Dieu de sauver les croyants par la folie de la prédication.'),
('1co',1,22,'crampon1923','Les Juifs exigent des miracles, et les Grecs cherchent la sagesse;'),
('1co',1,23,'crampon1923','nous, nous prêchons un Christ crucifié, scandale pour les Juifs et folie pour les Gentils,'),
('1co',1,24,'crampon1923','mais pour ceux qui sont appelés, soit Juifs, soit Grecs, puissance de Dieu et sagesse de Dieu.'),
('1co',1,25,'crampon1923','Car ce qui serait folie de Dieu est plus sage que la sagesse des hommes, et ce qui serait faiblesse de Dieu est plus fort que la force des hommes.'),
('1co',1,26,'crampon1923','Considérez en effet votre vocation, mes frères; il n''y a parmi vous ni beaucoup de sages selon la chair, ni beaucoup de puissants, ni beaucoup de nobles.'),
('1co',1,27,'crampon1923','Mais ce que le monde tient pour insensé, c''est ce que Dieu a choisi pour confondre les sages; et ce que le monde tient pour rien, c''est ce que Dieu a choisi pour confondre les forts;'),
('1co',1,28,'crampon1923','et Dieu a choisi ce qui dans le monde est sans considération et sans puissance, ce qui n''est rien, pour réduire au néant ce qui est,'),
('1co',1,29,'crampon1923','afin que nulle chair ne se glorifie devant Dieu.'),
('1co',1,30,'crampon1923','Or c''est par lui que vous êtes dans le Christ-Jésus, lequel, de par Dieu, a été fait pour nous sagesse, et justice, et sanctification, et rédemption,'),
('1co',1,31,'crampon1923','afin que, selon le mot de l''Ecriture, " celui qui se glorifie, se glorifie dans le Seigneur. "'),
('1co',2,1,'crampon1923','Moi aussi, mes frères, lorsque je suis venu chez vous, ce n''est pas avec une supériorité de langage ou de sagesse que je suis venu vous annoncer le témoignage de Dieu.'),
('1co',2,2,'crampon1923','Car je n''ai pas jugé que je dusse savoir parmi vous autre chose que Jésus-Christ, et Jésus-Christ crucifié.'),
('1co',2,3,'crampon1923','Mais c''est dans la faiblesse, dans la crainte, et dans un grand tremblement que je me suis présenté chez vous;'),
('1co',2,4,'crampon1923','et ma parole et ma prédication n''avaient rien du langage persuasif de la sagesse, mais l''Esprit-Saint et la force de Dieu en démontraient la vérité:'),
('1co',2,5,'crampon1923','afin que votre foi repose, non sur la sagesse des hommes, mais sur la puissance de Dieu.'),
('1co',2,6,'crampon1923','Pourtant il est une sagesse que nous prêchons parmi les parfaits, sagesse qui n''est pas celle de ce siècle, ni des princes de ce siècle, dont le règne va finir.'),
('1co',2,7,'crampon1923','Nous prêchons une sagesse de Dieu mystérieuse et cachée, que Dieu, avant les siècles, avait destinée pour notre glorification.'),
('1co',2,8,'crampon1923','Cette sagesse, nul des princes de ce siècle ne l''a connue; — car, s''ils l''avaient connue, ils n''auraient pas crucifié le Seigneur de la gloire.'),
('1co',2,9,'crampon1923','Mais ce sont, comme il est écrit, " des choses que l''œil n''a point vues, que l''oreille n''a point entendues, et qui ne sont pas montées au cœur de l''homme, — des choses que Dieu a préparées pour ceux qui l''aiment. "'),
('1co',2,10,'crampon1923','C''est à nous que Dieu les a révélées par son Esprit; car l''Esprit pénètre tout, même les profondeurs de Dieu.'),
('1co',2,11,'crampon1923','Car qui d''entre les hommes connaît ce qui se passe dans l''homme, si ce n''est l''esprit de l''homme qui est en lui? De même personne ne connaît ce qui est en Dieu, si ce n''est l''Esprit de Dieu.'),
('1co',2,12,'crampon1923','Pour nous, nous avons reçu non l''esprit du monde, mais l''Esprit qui vient de Dieu, afin que nous connaissions les choses que Dieu nous a données par sa grâce.'),
('1co',2,13,'crampon1923','Et nous en parlons, non avec des paroles qu''enseigne la sagesse humaine, mais avec celles qu''enseigne l''Esprit, en exprimant les choses spirituelles par un langage spirituel.'),
('1co',2,14,'crampon1923','Mais l''homme naturel ne reçoit pas les choses de l''Esprit de Dieu, car elles sont une folie pour lui, et il ne peut les connaître, parce que c''est par l''Esprit qu''on en juge.'),
('1co',2,15,'crampon1923','L''homme spirituel, au contraire, juge de tout, et il n''est lui-même jugé par personne.'),
('1co',2,16,'crampon1923','Car " qui a connu la pensée du Seigneur, pour pouvoir l''instruire? " Mais nous, nous avons la pensée du Christ.'),
('1co',3,1,'crampon1923','Moi-même, mes frères, ce n''est pas comme à des hommes spirituels que j''ai pu vous parler, mais comme à des hommes charnels, comme à de petits enfants dans le Christ.'),
('1co',3,2,'crampon1923','Je vous ai donné du lait à boire, non de la nourriture solide, car vous n''en étiez pas capables, et vous ne l''êtes pas même à présent, parce que vous êtes encore charnels.'),
('1co',3,3,'crampon1923','En effet, puisqu''il y a parmi vous de la jalousie et des disputes, n''êtes-vous pas charnels, et ne marchez-vous pas selon l''homme?'),
('1co',3,4,'crampon1923','Quand l''un dit: Moi je suis à Paul! et un autre: Moi, je suis à Apollos! n''êtes-vous pas des hommes? Qu''est-ce donc qu''Apollos? et qu''est-ce que Paul?'),
('1co',3,5,'crampon1923','Des ministres par le moyen desquels vous avez cru, selon ce que le Seigneur a donné à chacun.'),
('1co',3,6,'crampon1923','Moi, j''ai planté, Apollos a arrosé; mais Dieu a fait croître.'),
('1co',3,7,'crampon1923','Ainsi ni celui qui plante n''est quelque chose, ni celui qui arrose; mais Dieu, qui fait croître.'),
('1co',3,8,'crampon1923','Celui qui plante et celui qui arrose sont égaux; et chacun recevra sa propre récompense selon son propre travail.'),
('1co',3,9,'crampon1923','Car nous sommes ouvriers avec Dieu. Vous êtes le champ de Dieu, l''édifice de Dieu.'),
('1co',3,10,'crampon1923','Selon la grâce de Dieu qui m''a été donnée, j''ai, comme un sage architecte, posé le fondement, et un autre bâtit dessus. Seulement que chacun prenne garde comment il bâtit dessus.'),
('1co',3,11,'crampon1923','Car personne ne peut poser un autre fondement que celui qui est déjà posé, savoir Jésus-Christ.'),
('1co',3,12,'crampon1923','Si l''on bâtit sur ce fondement avec de l''or, de l''argent, des pierres précieuses, du bois, du foin, du chaume,'),
('1co',3,13,'crampon1923','l''ouvrage de chacun sera manifesté; car le jour du Seigneur le fera connaître, parce qu''il va se révéler dans le feu, et le feu même éprouvera ce qu''est l''ouvrage de chacun.'),
('1co',3,14,'crampon1923','Si l''ouvrage que l''on aura bâti dessus subsiste, on recevra une récompense;'),
('1co',3,15,'crampon1923','si l''ouvrage de quelqu''un est consumé, il perdra sa récompense; lui pourtant sera sauvé, mais comme au travers du feu.'),
('1co',3,16,'crampon1923','Ne savez-vous pas que vous êtes un temple de Dieu, et que l''Esprit de Dieu habite en vous?'),
('1co',3,17,'crampon1923','Si quelqu''un détruit le temple de Dieu, Dieu le détruira; car le temple de Dieu est saint, et c''est ce que vous êtes vous-mêmes.'),
('1co',3,18,'crampon1923','Que nul ne s''abuse soi-même. Si quelqu''un parmi vous pense être sage dans ce siècle, qu''il devienne fou, afin de devenir sage.'),
('1co',3,19,'crampon1923','En effet, la sagesse de ce monde est folie devant Dieu; car il est écrit: " Je prendrai les sages dans leurs ruses. "'),
('1co',3,20,'crampon1923','Et encore: " Le Seigneur connaît les pensées des sages, il sait qu''elles sont vaines. "'),
('1co',3,21,'crampon1923','Que personne donc ne mette sa gloire dans des hommes;'),
('1co',3,22,'crampon1923','car tout est à vous, et Paul, et Apollos, et Céphas, et le monde, et la vie, et la mort, et les choses présentes, et les choses à venir. Tout est à vous,'),
('1co',3,23,'crampon1923','mais vous vous êtes au Christ, et le Christ est à Dieu.'),
('1co',4,1,'crampon1923','Ainsi, qu''on nous regarde comme des serviteurs du Christ et des dispensateurs des mystères de Dieu.'),
('1co',4,2,'crampon1923','Eh bien! ce que l''on cherche dans les dispensateurs, c''est que chacun soit trouvé fidèle.'),
('1co',4,3,'crampon1923','Pour moi, il m''importe fort peu d''être jugé par vous ou par un tribunal humain; je ne me juge pas moi-même;'),
('1co',4,4,'crampon1923','car, quoique je ne me sente coupable de rien, je ne suis pas pour cela justifié: mon juge, c''est le Seigneur.'),
('1co',4,5,'crampon1923','C''est pourquoi ne jugez de rien avant le temps jusqu''à ce que vienne le Seigneur: il mettra en lumière ce qui est caché dans les ténèbres et manifestera les desseins des cœurs, et alors chacun recevra de Dieu la louange qui lui est due.'),
('1co',4,6,'crampon1923','Ce que je viens de dire d''Apollos et de moi, n''est qu''une forme que j''ai prise à cause de vous, frères, afin que vous appreniez en nos personnes à ne pas aller au delà de ce qui est écrit, ne vous enflant pas d''orgueil en faveur de l''un contre l''autre.'),
('1co',4,7,'crampon1923','Car qui est-ce qui te distingue? Qu''as-tu que tu ne l''aies reçu? Et si tu l''as reçu, pourquoi te glorifies-tu comme si tu ne l''avais pas reçu?'),
('1co',4,8,'crampon1923','Déjà vous êtes rassasiés! Déjà vous êtes riches! Sans nous, vous êtes rois! Dieu veuille que vous le soyez en effet, afin que nous aussi nous régnions avec vous!'),
('1co',4,9,'crampon1923','Car il semble que Dieu nous ait fait paraître, nous les Apôtres, comme les derniers des hommes, comme des condamnés à mort, puisque nous avons été en spectacle au monde, aux anges et aux hommes.'),
('1co',4,10,'crampon1923','Nous, nous sommes insensés à cause du Christ, et vous, vous êtes sages en Jésus-Christ; nous, nous sommes faibles, et vous, vous êtes forts; vous, vous êtes en honneur, et nous dans le mépris!'),
('1co',4,11,'crampon1923','A cette heure encore, nous souffrons la faim, la soif, la nudité; nous sommes meurtris de coups, nous n''avons ni feu ni lieu,'),
('1co',4,12,'crampon1923','et nous nous fatiguons à travailler de nos propres mains; maudits, nous bénissons; persécutés, nous le supportons;'),
('1co',4,13,'crampon1923','calomniés, nous supplions; nous sommes jusqu''à présent comme les balayures du monde, le rebut des hommes.'),
('1co',4,14,'crampon1923','Ce n''est pas pour vous faire honte que j''écris ces choses; mais je vous avertis comme mes enfants bien-aimés.'),
('1co',4,15,'crampon1923','Car, eussiez-vous dix mille maîtres dans le Christ, vous n''avez pas cependant plusieurs pères, puisque c''est moi qui vous ai engendrés en Jésus-Christ par l''Evangile.'),
('1co',4,16,'crampon1923','Je vous en conjure donc, soyez mes imitateurs, (comme je le suis du Christ).'),
('1co',4,17,'crampon1923','C''est pour cela que je vous ai envoyé Timothée, qui est mon enfant bien-aimé et fidèle dans le Seigneur; il vous rappellera quelles sont mes voies en Jésus-Christ, de quelle manière j''enseigne partout, dans toutes les Eglises.'),
('1co',4,18,'crampon1923','Quelques-uns, présumant que je n''irais plus chez vous, se sont enflés d''orgueil.'),
('1co',4,19,'crampon1923','Mais j''irai bientôt chez vous, s''il plaît au Seigneur, et je prendrai connaissance non des paroles de ceux qui se sont enflés, mais de ce qu''ils peuvent faire.'),
('1co',4,20,'crampon1923','Car le royaume de Dieu consiste, non en paroles, mais en œuvres.'),
('1co',4,21,'crampon1923','Que voulez-vous? Que j''aille chez vous avec la verge, ou avec amour et dans un esprit de douceur?'),
('1co',5,1,'crampon1923','On n''entend parler que d''une impudicité commise parmi vous, et d''une impudicité telle qu''il ne s''en rencontre pas de semblable même chez les païens; c''est au point que quelqu''un a la femme de son père.'),
('1co',5,2,'crampon1923','Et vous êtes enflés d''orgueil! Et vous n''avez pas été plutôt dans le deuil, afin que celui qui a commis un tel acte fût retranché du milieu de vous!'),
('1co',5,3,'crampon1923','Pour moi, absent de corps, mais présent d''esprit, j''ai déjà jugé, comme si j''étais présent, celui qui a commis un tel attentat:'),
('1co',5,4,'crampon1923','Au nom de Notre-Seigneur Jésus-Christ, vous tous réunis et moi en esprit au milieu de vous, avec la puissance de Notre-Seigneur Jésus,'),
('1co',5,5,'crampon1923','qu''un tel homme soit livré à Satan pour la mort de la chair, afin que l''esprit soit sauvé au jour du Seigneur Jésus. —'),
('1co',5,6,'crampon1923','Vous avez tort de vous tant glorifier! Ne savez-vous pas qu''un peu de levain fait lever toute la pâte?'),
('1co',5,7,'crampon1923','Purifiez-vous du vieux levain, afin que vous soyez une pâte nouvelle, comme aussi vous êtes des azymes; car notre Pâque, le Christ, a été immolé.'),
('1co',5,8,'crampon1923','Célébrons donc la fête, non avec du vieux levain ni avec un levain de malice et de perversité, mais avec les azymes de la pureté et de la vérité.'),
('1co',5,9,'crampon1923','Je vous ai écrit dans ma lettre de ne pas avoir de relations avec les impudiques:'),
('1co',5,10,'crampon1923','non pas absolument avec les impudiques de ce monde, ou avec les hommes cupides et rapaces, ou avec les idolâtres; autrement il vous faudrait sortir du monde.'),
('1co',5,11,'crampon1923','J''ai simplement voulu vous dire de n''avoir point de relations avec un homme qui, portant le nom de frère, est impudique ou cupide, ou idolâtre, ou médisant, ou ivrogne, ou rapace, de ne pas même manger avec un tel homme.'),
('1co',5,12,'crampon1923','Car est-ce à moi de juger ceux du dehors? N''est-ce pas ceux du dedans qu''il vous appartient de juger?'),
('1co',5,13,'crampon1923','Ceux du dehors, c''est Dieu qui les juge. Retranchez le méchant du milieu de vous.'),
('1co',6,1,'crampon1923','Quoi! il y en a parmi vous qui, ayant un différend avec un autre, osent aller en jugement devant les injustes, et non devant les saints!'),
('1co',6,2,'crampon1923','Ne savez-vous pas que les saints jugeront le monde? Et si c''est par vous que le monde doit être jugé, êtes-vous indignes de rendre des jugements de moindre importance?'),
('1co',6,3,'crampon1923','Ne savez-vous pas que nous jugerons les anges? Pourquoi pas, à plus forte raison, les affaires de cette vie?'),
('1co',6,4,'crampon1923','Quand donc vous avez des jugements à faire rendre sur les affaires de cette vie, établissez pour les juger ceux qui sont les moins considérés dans l''Eglise!'),
('1co',6,5,'crampon1923','Je le dis à votre honte: ainsi il n''y a pas un homme sage parmi vous, pas un seul qui puisse se prononcer entre ses frères!'),
('1co',6,6,'crampon1923','Mais un frère est en procès avec un frère, et cela devant des infidèles!'),
('1co',6,7,'crampon1923','C''est déjà certes un défaut pour vous que d''avoir des procès les uns avec les autres. Pourquoi ne souffrez-vous pas plutôt quelque injustice? Pourquoi ne vous laissez-vous pas plutôt dépouiller?'),
('1co',6,8,'crampon1923','Mais c''est vous-mêmes qui commettez l''injustice et qui dépouillez les autres et ce sont vos frères!'),
('1co',6,9,'crampon1923','Ne savez-vous pas que les injustes ne posséderont point le royaume de Dieu? Ne vous y trompez point: ni les impudiques, ni les idolâtres, ni les adultères,'),
('1co',6,10,'crampon1923','ni les efféminés, ni les infâmes, ni les voleurs, ni les avares, ni les ivrognes, ni les calomniateurs, ni les rapaces ne posséderont le royaume de Dieu.'),
('1co',6,11,'crampon1923','Voilà pourtant ce que vous étiez, du moins quelques-uns d''entre vous; mais vous avez été lavés, mais vous avez été sanctifiés, mais vous avez été justifiés au nom du Seigneur Jésus-Christ et par l''Esprit de notre Dieu.'),
('1co',6,12,'crampon1923','Tout m''est permis, mais tout n''est pas utile; tout m''est permis, mais moi, je ne me laisserai dominer par quoi que ce soit.'),
('1co',6,13,'crampon1923','Les aliments sont pour le ventre, et le ventre pour les aliments, et Dieu détruira l''un comme les autres. Mais le corps n''est pas pour l''impudicité; il est pour le Seigneur, et le Seigneur pour le corps.'),
('1co',6,14,'crampon1923','Et Dieu qui a ressuscité le Seigneur, nous ressuscitera aussi par sa puissance.'),
('1co',6,15,'crampon1923','Ne savez-vous pas que vos corps sont des membres du Christ? Prendrai-je donc les membres du Christ pour en faire les membres d''une prostituée? Loin de là!'),
('1co',6,16,'crampon1923','Ne savez-vous pas que celui qui s''unit à la prostituée est un seul corps avec elle? Car, dit l''Ecriture, " Ils seront les deux en une seule chair. "'),
('1co',6,17,'crampon1923','Au contraire celui qui s''unit au Seigneur est un seul esprit avec lui.'),
('1co',6,18,'crampon1923','Fuyez l''impudicité. Quelque autre péché qu''un homme commette, ce péché est hors du corps; mais celui qui se livre à l''impudicité pèche contre son propre corps.'),
('1co',6,19,'crampon1923','Ne savez-vous pas que votre corps est le temple du Saint-Esprit qui est en vous, que vous avez reçu de Dieu, et que vous n''êtes plus à vous-mêmes?'),
('1co',6,20,'crampon1923','Car vous avez été rachetés à prix. Glorifiez donc Dieu dans votre corps.'),
('1co',7,1,'crampon1923','Quant aux points sur lesquels vous m''avez écrit, je vous dirai qu''il est bon pour l''homme de ne pas toucher de femme.'),
('1co',7,2,'crampon1923','Toutefois, pour éviter toute impudicité, que chacun ait sa femme, et que chaque femme ait son mari.'),
('1co',7,3,'crampon1923','Que le mari rende à sa femme ce qu''il lui doit, et que la femme agisse de même envers son mari.'),
('1co',7,4,'crampon1923','La femme n''a pas puissance sur son propre corps, mais le mari; pareillement le mari n''a pas puissance sur son propre corps, mais la femme.'),
('1co',7,5,'crampon1923','Ne vous soustrayez pas l''un à l''autre, si ce n''est d''un commun accord, pour un temps, afin de vaquer à la prière; puis remettez-vous ensemble, de peur que Satan ne vous tente par suite de votre incontinence.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1co',7,6,'crampon1923','Je dis cela par condescendance, je n''en fais pas un ordre.'),
('1co',7,7,'crampon1923','Je voudrais, au contraire, que tous les hommes fussent comme moi; mais chacun reçoit de Dieu son don particulier, l''un d''une manière, l''autre d''une autre.'),
('1co',7,8,'crampon1923','A ceux qui ne sont pas mariés et aux veuves, je dis qu''il leur est bon de rester comme moi-même.'),
('1co',7,9,'crampon1923','Mais s''ils ne peuvent se contenir, qu''ils se marient; car il vaut mieux se marier que de brûler.'),
('1co',7,10,'crampon1923','Quant aux personnes mariées, j''ordonne, non pas moi, mais le Seigneur, que la femme ne se sépare point de son mari; —'),
('1co',7,11,'crampon1923','si elle en est séparée, qu''elle reste sans se remarier ou qu''elle se réconcilie avec son mari; pareillement, que le mari ne répudie point sa femme.'),
('1co',7,12,'crampon1923','Aux autres, je dis, moi, non le Seigneur: Si quelque frère a une femme qui n''a pas la foi, et qu''elle consente à habiter avec lui, qu''il ne la renvoie point;'),
('1co',7,13,'crampon1923','et si une femme a un mari qui n''a pas la foi, et qu''il consente à habiter avec elle, qu''elle ne renvoie point son mari.'),
('1co',7,14,'crampon1923','Car le mari infidèle est sanctifié par la femme, et la femme infidèle est sanctifiée par le mari; autrement vos enfants seraient impurs, tandis que maintenant ils sont saints.'),
('1co',7,15,'crampon1923','Si l''incrédule se sépare, qu''il se sépare; le frère ou la sœur ne sont pas asservis dans ces conditions. Dieu nous a appelés dans la paix.'),
('1co',7,16,'crampon1923','Car que sais-tu, femme, si tu sauveras ton mari? Ou que sais-tu, mari, si tu sauveras ta femme?'),
('1co',7,17,'crampon1923','Seulement, que chacun se conduise selon la position que le Seigneur lui a assignée, et selon que Dieu l''a appelé; c''est la règle que j''établis dans toutes les Eglises.'),
('1co',7,18,'crampon1923','Quelqu''un a-t-il été appelé étant circoncis, qu''il ne dissimule pas sa circoncision; quelqu''un a-t-il été appelé étant incirconcis, qu''il ne se fasse pas circoncire.'),
('1co',7,19,'crampon1923','La circoncision n''est rien, l''incirconcision n''est rien; ce qui est tout, c''est l''observation des commandements de Dieu.'),
('1co',7,20,'crampon1923','Que chacun demeure dans l''état où il était lorsqu''il a été appelé.'),
('1co',7,21,'crampon1923','As-tu été appelé étant esclave, ne t''en mets point en peine; mais alors même que tu pourrais devenir libre, mets plutôt ton appel à profit.'),
('1co',7,22,'crampon1923','Car l''esclave qui a été appelé dans le Seigneur est un affranchi du Seigneur; de même, l''homme libre qui a été appelé est un esclave du Christ.'),
('1co',7,23,'crampon1923','Vous avez été achetés un grand prix; ne vous rendez pas esclaves des hommes.'),
('1co',7,24,'crampon1923','Que chacun, frères, demeure devant Dieu dans l''état où il était lorsqu''il a été appelé.'),
('1co',7,25,'crampon1923','Pour ce qui est des vierges, je n''ai pas de commandement du Seigneur; mais je donne un conseil, comme ayant reçu du Seigneur la grâce d''être fidèle.'),
('1co',7,26,'crampon1923','Je pense donc à cause des difficultés présentes, qu''il est bon à un homme d''être ainsi. —'),
('1co',7,27,'crampon1923','Es-tu lié à une femme, ne cherche pas à rompre ce lien; n''es-tu pas lié à une femme, ne cherche pas de femme.'),
('1co',7,28,'crampon1923','Si pourtant tu t''es marié, tu n''as pas péché; et si la vierge s''est mariée, elle n''a pas péché; mais ces personnes auront des afflictions dans la chair, et moi je voudrais vous les épargner.'),
('1co',7,29,'crampon1923','Mais voici ce que je dis, frères: le temps s''est fait court; il faut donc que ceux qui ont des femmes soient comme n''en ayant pas,'),
('1co',7,30,'crampon1923','ceux qui pleurent comme ne pleurant pas, ceux qui se réjouissent comme ne se réjouissant pas, ceux qui achètent comme ne possédant pas,'),
('1co',7,31,'crampon1923','et ceux qui usent du monde comme n''en usant pas; car elle passe, la figure de ce monde.'),
('1co',7,32,'crampon1923','Or je voudrais que vous fussiez sans préoccupation. Celui qui n''est pas marié a souci des choses du Seigneur, il cherche à plaire au Seigneur;'),
('1co',7,33,'crampon1923','celui qui est marié a souci des choses du monde, il cherche à plaire à sa femme, et il est partagé.'),
('1co',7,34,'crampon1923','De même la femme, celle qui n''a pas de mari, et la vierge, ont souci des choses du Seigneur, afin d''être saintes de corps et d''esprit; mais celle qui est mariée a souci des choses du monde, elle cherche à plaire à son mari.'),
('1co',7,35,'crampon1923','Je dis cela dans votre intérêt, non pour jeter sur vous le filet, mais en vue de ce qui est bienséant et propre à vous attacher au Seigneur sans tiraillements.'),
('1co',7,36,'crampon1923','Si quelqu''un juge qu''il exposerait sa fille au déshonneur, si elle passait la fleur de l''âge, et qu''il est de son devoir de la marier, qu''il fasse comme il veut, il ne pèche point; qu''elle se marie.'),
('1co',7,37,'crampon1923','Mais celui qui, sans y être forcé, étant maître de faire ce qu''il veut, a mis dans son cœur une ferme résolution, et a décidé de garder sa fille vierge, celui-là fait bien.'),
('1co',7,38,'crampon1923','Ainsi celui qui marie sa fille fait bien, et celui qui ne la marie pas fait mieux.'),
('1co',7,39,'crampon1923','La femme est liée aussi longtemps que vit son mari; si le mari vient à mourir, elle est libre de se remarier à qui elle voudra; seulement que ce soit dans le Seigneur.'),
('1co',7,40,'crampon1923','Elle est plus heureuse, néanmoins, si elle demeure comme elle est: c''est mon avis; et je crois avoir, moi aussi, l''Esprit de Dieu.'),
('1co',8,1,'crampon1923','Pour ce qui est des viandes sacrifiées aux idoles, nous savons, car nous sommes tous éclairés... — La science enfle, tandis que la charité édifie.'),
('1co',8,2,'crampon1923','Si quelqu''un présume de sa science, il n''a encore rien connu comme on doit le connaître.'),
('1co',8,3,'crampon1923','Mais si quelqu''un aime Dieu, celui-là est connu de lui. —'),
('1co',8,4,'crampon1923','Pour ce qui est donc de manger des viandes immolées aux idoles, nous savons qu''une idole n''est rien dans le monde et qu''il n''y a de Dieu, qu''un seul.'),
('1co',8,5,'crampon1923','Car s''il est des êtres qui sont appelés dieux, soit dans le ciel, soit sur la terre, — il y a de la sorte beaucoup de dieux et beaucoup de seigneurs, —'),
('1co',8,6,'crampon1923','pour nous néanmoins, il n''y a qu''un seul Dieu, le Père, de qui viennent toutes choses et pour qui nous sommes, et un seul Seigneur, Jésus-Christ, par qui sont toutes choses et par qui nous sommes.'),
('1co',8,7,'crampon1923','Mais tous n''ont pas cette connaissance. Quelques-uns, conservant encore leur ancienne manière d''envisager l''idole, mangent de ces viandes comme ayant été immolées à une idole, et leur conscience, qui est faible, se trouve souillée.'),
('1co',8,8,'crampon1923','Un aliment n''est pas chose qui nous recommande à Dieu; si nous en mangeons, nous n''avons rien de plus; si nous n''en mangeons pas, nous n''avons rien de moins.'),
('1co',8,9,'crampon1923','Toutefois prenez garde que cette liberté dont vous jouissez ne devienne une occasion de chute pour les faibles.'),
('1co',8,10,'crampon1923','Car si quelqu''un te voit, toi qui es un homme éclairé, assis à table dans un temple d''idoles, sa conscience, à lui qui est faible, ne le portera-t-elle pas à manger des viandes immolées aux idoles?'),
('1co',8,11,'crampon1923','Et ainsi se perd le faible par ta science, ce frère pour lequel le Christ est mort!'),
('1co',8,12,'crampon1923','En péchant de la sorte contre vos frères, et en violentant leur conscience encore faible, vous péchez contre le Christ.'),
('1co',8,13,'crampon1923','C''est pourquoi, si un aliment est une occasion de chute pour mon frère, je me passerai éternellement de viande, afin de ne pas être pour lui une occasion de chute.'),
('1co',9,1,'crampon1923','Ne suis-je pas libre? Ne suis-je pas apôtre? N''ai-je pas vu Jésus notre Seigneur? N''êtes-vous pas mon ouvrage dans le Seigneur?'),
('1co',9,2,'crampon1923','Si pour d''autres je ne suis pas apôtre, je le suis au moins pour vous, car vous êtes le sceau de mon apostolat dans le Seigneur.'),
('1co',9,3,'crampon1923','Voilà ma réponse à mes détracteurs.'),
('1co',9,4,'crampon1923','N''avons-nous pas le droit de manger et de boire?'),
('1co',9,5,'crampon1923','N''avons-nous pas le droit de mener avec nous une sœur, comme font les autres Apôtres, et les frères du Seigneur, et Céphas?'),
('1co',9,6,'crampon1923','Ou bien sommes-nous les seuls, Barnabé et moi, qui n''ayons pas le droit de ne point travailler?'),
('1co',9,7,'crampon1923','Qui jamais a porté les armes à ses propres frais? Qui est-ce qui plante une vigne pour n''en pas manger le fruit? Qui est-ce qui fait paître un troupeau, sans se nourrir de son lait?'),
('1co',9,8,'crampon1923','Est-ce selon l''homme que je dis ces choses, et la Loi ne les dit-elle pas aussi?'),
('1co',9,9,'crampon1923','Car il est écrit dans la loi de Moïse: " Tu ne muselleras pas la bouche du bœuf qui foule le grain. " Dieu se met-il en peine des bœufs?'),
('1co',9,10,'crampon1923','N''est-ce pas absolument à cause de nous qu''il parle ainsi? Oui, c''est à cause de nous que cela a été écrit; celui qui laboure doit labourer avec espérance, et celui qui foule le grain doit le fouler dans l''espérance d''y avoir part.'),
('1co',9,11,'crampon1923','Si nous avons semé parmi vous les biens spirituels, est-ce une si grosse affaire que nous moissonnions de vos biens matériels?'),
('1co',9,12,'crampon1923','Si d''autres usent de ce droit sur vous, pourquoi pas plutôt nous-mêmes! Cependant nous n''avons pas usé de ce droit; mais nous supportons tout, afin de ne pas créer d''obstacle à l''Evangile du Christ.'),
('1co',9,13,'crampon1923','Ne savez-vous pas que ceux qui remplissent les fonctions sacrées vivent du temple, et que ceux qui servent à l''autel ont part à l''autel?'),
('1co',9,14,'crampon1923','De même aussi le Seigneur a ordonné à ceux qui annoncent l''Evangile de vivre de l''Evangile.'),
('1co',9,15,'crampon1923','Pour moi, je n''ai fait valoir aucun de ces droits, et ce n''est pas afin de les réclamer en ma faveur que j''écris ceci: il me vaudrait mieux mourir que de me laisser enlever ce titre de gloire.'),
('1co',9,16,'crampon1923','Si j''annonce l''Evangile, ce n''est pas pour moi une gloire, c''est une obligation qui m''incombe, et malheur à moi si je n''annonce pas l''Evangile!'),
('1co',9,17,'crampon1923','Si je le faisais de mon propre gré, je mériterais une récompense; mais je le fais par ordre, alors c''est une charge qui m''est confiée.'),
('1co',9,18,'crampon1923','Quelle est donc ma récompense? C''est que prêchant l''Evangile je l''offre gratuitement, sans user de mon droit de prédicateur de l''Evangile.'),
('1co',9,19,'crampon1923','Car, quoique libre à l''égard de tous, je me suis fait le serviteur de tous, afin d''en gagner un plus grand nombre.'),
('1co',9,20,'crampon1923','Avec les Juifs, j''ai été comme Juif, afin de gagner les Juifs;'),
('1co',9,21,'crampon1923','avec ceux qui sont sous la Loi, comme si j''étais sous la Loi (quoique je ne sois pas assujetti à la Loi), afin de gagner ceux qui sont sous la Loi; avec ceux qui sont sans la loi, comme si j''étais sans la loi, (quoique je ne sois pas sans la loi de Dieu, étant sous la loi du Christ), afin de gagner ceux qui sont sans loi.'),
('1co',9,22,'crampon1923','Je me suis fait faible avec les faibles, afin de gagner les faibles. Je me suis fait tout à tous, afin de les sauver tous.'),
('1co',9,23,'crampon1923','Je fais tout à cause de l''Evangile, afin d''y avoir part.'),
('1co',9,24,'crampon1923','Ne le savez-vous pas? Dans les courses du stade, tous courent, mais un seul emporte le prix. Courez de même, afin de le remporter.'),
('1co',9,25,'crampon1923','Quiconque veut lutter, s''abstient de tout: eux pour une couronne périssable; nous, pour une impérissable.'),
('1co',9,26,'crampon1923','Pour moi, je cours de même, non comme à l''aventure; je frappe, non pas comme battant l''air.'),
('1co',9,27,'crampon1923','Mais je traite durement mon corps et je le tiens en servitude, de peur qu''après avoir prêché aux autres, je ne sois moi-même réprouvé.'),
('1co',10,1,'crampon1923','Car je ne veux pas vous laisser ignorer, frères, que nos pères ont tous été sous la nuée, qu''ils ont tous traversé la mer,'),
('1co',10,2,'crampon1923','et qu''ils ont tous été baptisés en Moïse dans la nuée et dans la mer;'),
('1co',10,3,'crampon1923','qu''ils ont tous mangé le même aliment spirituel,'),
('1co',10,4,'crampon1923','et qu''ils ont tous bu le même breuvage spirituel, car ils buvaient à un rocher spirituel qui les accompagnait, et ce rocher était le Christ.'),
('1co',10,5,'crampon1923','Cependant ce n''est pas dans la plupart d''entre eux que Dieu trouva son plaisir, puisque leurs corps jonchèrent le désert.'),
('1co',10,6,'crampon1923','Or ces choses ont été des figures de ce qui nous concerne, afin que nous n''ayons pas de désirs coupables, comme ils en ont eu,'),
('1co',10,7,'crampon1923','et que vous ne deveniez pas idolâtres, comme quelques-uns d''entre eux, selon qu''il est écrit: " Le peuple s''assit pour manger et pour boire; puis il se leva pour se divertir. "'),
('1co',10,8,'crampon1923','Ne nous livrons point à l''impudicité, comme quelques-uns d''entre eux s''y livrèrent; et il en tomba vingt-trois mille en un seul jour.'),
('1co',10,9,'crampon1923','Ne tentons point le Christ, comme le tentèrent quelques-uns d''entre eux, qui périrent par les serpents.'),
('1co',10,10,'crampon1923','Ne murmurez point comme murmurèrent quelques-uns d''entre eux, qui périrent sous les coups de l''Exterminateur.'),
('1co',10,11,'crampon1923','Toutes ces choses leur sont arrivées en figure, et elles ont été écrites pour notre instruction, à nous qui sommes arrivés à la fin des temps.'),
('1co',10,12,'crampon1923','Ainsi donc que celui qui croit être debout prenne garde de tomber.'),
('1co',10,13,'crampon1923','Aucune tentation ne vous est survenue, qui n''ait été humaine; et Dieu, qui est fidèle, ne permettra pas que vous soyez tentés au delà de vos forces; mais, avec la tentation, il ménagera aussi une heureuse issue en vous donnant le pouvoir de la supporter.'),
('1co',10,14,'crampon1923','C''est pourquoi, mes bien-aimés, fuyez l''idolâtrie.'),
('1co',10,15,'crampon1923','Je vous parle comme à des hommes intelligents; jugez vous-mêmes de ce que je dis.'),
('1co',10,16,'crampon1923','Le calice de bénédiction, que nous bénissons, n''est-il pas une communion au sang du Christ? Et le pain, que nous rompons, n''est-il pas une communion au corps du Christ?'),
('1co',10,17,'crampon1923','Puisqu''il y a un seul pain, nous formons un seul corps, tout en étant plusieurs; car nous participons tous à un même pain.'),
('1co',10,18,'crampon1923','Voyez Israël selon la chair: ceux qui mangent les victimes ne participent-ils pas à l''autel?'),
('1co',10,19,'crampon1923','Qu''est-ce à dire? Que la viande sacrifiée aux idoles soit quelque chose, ou qu''une idole soit quelque chose?'),
('1co',10,20,'crampon1923','Nullement; je dis que ce que les païens offrent en sacrifice, ils l''immolent à des démons, et non à Dieu; or je ne veux pas que vous soyez en communion avec les démons.'),
('1co',10,21,'crampon1923','Vous ne pouvez boire à la fois au calice du Seigneur et au calice des démons; vous ne pouvez prendre part à la table du Seigneur et à la table des démons.'),
('1co',10,22,'crampon1923','Voulons-nous provoquer la jalousie du Seigneur? Sommes-nous plus forts que lui?'),
('1co',10,23,'crampon1923','Tout est permis, mais tout n''est pas expédient; tout est permis, mais tout n''édifie pas.'),
('1co',10,24,'crampon1923','Que personne ne cherche son propre avantage, mais celui d''autrui.'),
('1co',10,25,'crampon1923','Mangez de tout ce qui se vend au marché, sans faire aucune question par motif de conscience;'),
('1co',10,26,'crampon1923','car " la terre est au Seigneur, et tout ce qu''elle renferme. "'),
('1co',10,27,'crampon1923','Si un infidèle vous invite et que vous vouliez y aller, mangez de tout ce qu''on vous présentera, sans faire aucune question par motif de conscience.'),
('1co',10,28,'crampon1923','Mais si quelqu''un vous dit: Ceci a été offert en sacrifice [aux idoles], n''en mangez pas, à cause de celui qui vous a donné ce renseignement et à cause de la conscience.'),
('1co',10,29,'crampon1923','Je dis la conscience, non pas la vôtre, mais celle d''autrui. Pourquoi en effet ma liberté serait-elle jugée par une conscience étrangère?'),
('1co',10,30,'crampon1923','Si je mange avec action de grâces, pourquoi serais-je blâmé pour une chose dont je rends grâces?'),
('1co',10,31,'crampon1923','Soit donc que vous mangiez, soit que vous buviez, ou quelque autre chose que vous fassiez, faites tout pour la gloire de Dieu.'),
('1co',10,32,'crampon1923','Ne soyez en scandale ni aux Juifs, ni aux Grecs, ni à l''Eglise de Dieu.'),
('1co',10,33,'crampon1923','C''est ainsi que moi-même je m''efforce en toutes choses de complaire à tous, ne cherchant pas mon propre avantage, mais celui du plus grand nombre, afin qu''ils soient sauvés.'),
('1co',11,1,'crampon1923','Soyez mes imitateurs, comme je le suis moi-même du Christ.'),
('1co',11,2,'crampon1923','Je vous loue, [mes frères], de ce que vous vous souvenez de moi à tous égards, et de ce que vous retenez mes instructions telles que je vous les ai données.'),
('1co',11,3,'crampon1923','Je veux cependant que vous sachiez que le chef de tout homme c''est le Christ, que le chef de la femme, c''est l''homme, et que le chef du Christ, c''est Dieu.'),
('1co',11,4,'crampon1923','Tout homme qui prie ou qui prophétise la tête couverte, déshonore sa tête.'),
('1co',11,5,'crampon1923','Toute femme qui prie ou qui prophétise la tête non voilée, déshonore sa tête: elle est comme celle qui est rasée.'),
('1co',11,6,'crampon1923','Si une femme ne se voile pas la tête, qu''elle se coupe aussi les cheveux. Or, s''il est honteux à une femme d''avoir les cheveux coupés ou la tête rasée, qu''elle se voile.'),
('1co',11,7,'crampon1923','L''homme ne doit pas se couvrir la tête, parce qu''il est l''image de la gloire de Dieu, tandis que la femme est la gloire de l''homme.'),
('1co',11,8,'crampon1923','En effet, l''homme n''a pas été tiré de la femme, mais la femme de l''homme;'),
('1co',11,9,'crampon1923','et l''homme n''a pas été créé pour la femme, mais la femme pour l''homme.'),
('1co',11,10,'crampon1923','C''est pourquoi la femme doit, à cause des anges, avoir sur la tête un signe de sujétion.'),
('1co',11,11,'crampon1923','Toutefois, ni la femme n''est sans l''homme, ni l''homme sans la femme, dans le Seigneur.'),
('1co',11,12,'crampon1923','Car, si la femme a été tirée de l''homme, l''homme aussi naît de la femme, et tout vient de Dieu.'),
('1co',11,13,'crampon1923','Jugez-en vous-mêmes: est-il bienséant qu''une femme prie Dieu sans être voilée?'),
('1co',11,14,'crampon1923','La nature elle-même ne nous enseigne-t-elle pas que c''est une honte à un homme de porter de longs cheveux,'),
('1co',11,15,'crampon1923','tandis que c''est une gloire pour la femme qu''une longue chevelure, parce que la chevelure lui a été donnée en guise de voile?'),
('1co',11,16,'crampon1923','Si quelqu''un se plaît à contester, nous n''avons pas cette habitude, non plus que les Eglises de Dieu.'),
('1co',11,17,'crampon1923','Mais en vous recommandant ce point, je n''ai garde de vous louer de ce que vous vous assemblez, non pour votre avantage, mais pour votre préjudice.'),
('1co',11,18,'crampon1923','Et d''abord j''apprends que, lorsque vous vous réunissez en assemblée, il y a des scissions parmi vous, — et je le crois en partie;'),
('1co',11,19,'crampon1923','car il faut qu''il y ait parmi vous même des sectes, afin que les frères d''une vertu éprouvée soient manifestés parmi vous, —'),
('1co',11,20,'crampon1923','lors donc que vous vous réunissez ce n''est plus le repas du Seigneur que vous célébrez;'),
('1co',11,21,'crampon1923','car, à table, chacun commence par prendre son propre repas, en sorte que tels ont faim, tandis que d''autres se gorgent.'),
('1co',11,22,'crampon1923','N''avez-vous pas des maisons pour y manger et boire? ou méprisez-vous l''Eglise de Dieu, et voulez-vous faire un affront à ceux qui n''ont rien? Que vous dirai-je? Que je vous loue? Non, je ne vous loue point en cela.'),
('1co',11,23,'crampon1923','Car, pour moi, j''ai reçu du Seigneur, ce que je vous ai aussi transmis, savoir, que le Seigneur Jésus, dans la nuit où il fut livré, prit du pain,'),
('1co',11,24,'crampon1923','et après avoir rendu grâces, le rompit et dit: " [Prenez et mangez]; ceci est mon corps, [qui sera livré] pour vous; faites ceci en mémoire de moi. "'),
('1co',11,25,'crampon1923','De même, après avoir soupé, il prit le calice et dit: " Ce calice est la nouvelle alliance en mon sang; faites ceci, toutes les fois que vous en boirez, en mémoire de moi. "'),
('1co',11,26,'crampon1923','Car toutes les fois que vous mangez ce pain et que vous buvez ce calice, vous annoncez la mort du Seigneur, jusqu''à ce qu''il vienne.'),
('1co',11,27,'crampon1923','C''est pourquoi celui qui mangera le pain ou boira le calice du Seigneur indignement, sera coupable envers le corps et le sang du Seigneur.'),
('1co',11,28,'crampon1923','Que chacun donc s''éprouve soi-même, et qu''ainsi il mange de ce pain et boive de ce calice;'),
('1co',11,29,'crampon1923','car celui qui mange et boit [indignement], sans discerner le corps du Seigneur, mange et boit son propre jugement.'),
('1co',11,30,'crampon1923','C''est pour cela qu''il y a parmi vous beaucoup de gens débiles et de malades, et qu''un grand nombre sont morts.'),
('1co',11,31,'crampon1923','Si nous nous examinions nous-mêmes nous ne serions pas jugés.'),
('1co',11,32,'crampon1923','Mais le Seigneur nous juge et nous châtie, afin que nous ne soyons pas condamnés avec ce monde.'),
('1co',11,33,'crampon1923','Ainsi, mes frères, lorsque vous vous réunissez pour le repas, attendez-vous les uns les autres.'),
('1co',11,34,'crampon1923','Si quelqu''un a faim qu''il mange chez lui, afin que vous ne vous réunissiez pas pour votre condamnation. Je réglerai les autres choses quand je serai arrivé chez vous.'),
('1co',12,1,'crampon1923','Pour ce qui concerne les dons spirituels, je ne veux pas, mes frères, que vous soyez dans l''ignorance.'),
('1co',12,2,'crampon1923','Vous savez que, lorsque vous étiez païens, vous vous laissiez entraîner vers les idoles muettes, selon que vous y étiez conduits.'),
('1co',12,3,'crampon1923','Je vous déclare donc que personne, s''il parle par l''Esprit de Dieu, ne dit: Jésus est anathème; et personne ne peut dire: " Jésus est le Seigneur, " si ce n''est par l''Esprit-Saint.'),
('1co',12,4,'crampon1923','Il y a pourtant diversité de dons, mais c''est le même Esprit;'),
('1co',12,5,'crampon1923','diversité de ministères, mais c''est le même Seigneur;'),
('1co',12,6,'crampon1923','diversité d''opérations, mais c''est le même Dieu qui opère tout en tous.'),
('1co',12,7,'crampon1923','A chacun la manifestation de l''Esprit est donnée pour l''utilité commune.'),
('1co',12,8,'crampon1923','En effet, à l''un est donnée par l''Esprit une parole de sagesse, à l''autre une parole de connaissance, selon le même Esprit;'),
('1co',12,9,'crampon1923','à un autre, la foi, par le même Esprit; à un autre, le don des guérisons, par ce seul et même Esprit;'),
('1co',12,10,'crampon1923','à un autre, la puissance d''opérer des miracles; à un autre la prophétie; à un autre, le discernement des esprits; à un autre la diversité des langues; à un autre le don de les interpréter.'),
('1co',12,11,'crampon1923','Mais c''est le seul et même Esprit qui produit tous ces dons, les distribuant à chacun en particulier, comme il lui plaît.'),
('1co',12,12,'crampon1923','Car, comme le corps est un et a plusieurs membres, et comme tous les membres du corps, malgré leur nombre, ne forment qu''un seul corps, ainsi en est-il du Christ.'),
('1co',12,13,'crampon1923','Tous, en effet, nous avons été baptisés dans un seul esprit pour former un seul corps, soit Juifs, soit Grecs, soit esclaves, soit libres, et nous avons tous été abreuvés d''un seul Esprit.'),
('1co',12,14,'crampon1923','Ainsi le corps n''est pas un seul membre, mais il est formé de plusieurs.'),
('1co',12,15,'crampon1923','Si le pied disait: " Puisque je ne suis pas main, je ne suis pas du corps ", en serait-il moins du corps pour cela?'),
('1co',12,16,'crampon1923','Et si l''oreille disait: " Puisque je ne suis pas œil, je ne suis pas du corps ", en serait-elle moins du corps pour cela?'),
('1co',12,17,'crampon1923','Si tout le corps était œil, où serait l''ouïe? S''il était tout entier ouïe, où serait l''odorat?'),
('1co',12,18,'crampon1923','Mais Dieu a placé chacun des membres dans le corps, comme il l''a voulu.'),
('1co',12,19,'crampon1923','Si tous étaient un seul et même membre, où serait le corps?'),
('1co',12,20,'crampon1923','Il y a donc plusieurs membres et un seul corps.'),
('1co',12,21,'crampon1923','L''œil ne peut pas dire à la main: " Je n''ai pas besoin de toi "; ni la tête dire aux pieds: " Je n''ai pas besoin de vous. "'),
('1co',12,22,'crampon1923','Au contraire, les membres du corps qui paraissent les plus faibles sont plus nécessaires;'),
('1co',12,23,'crampon1923','et ceux que nous tenons pour les moins honorables du corps, sont ceux que nous entourons de plus d''honneur. Ainsi nos membres les moins honnêtes, nous les traitons avec plus de décence,'),
('1co',12,24,'crampon1923','tandis que nos parties honnêtes n''en ont pas besoin. Dieu a disposé le corps de manière à donner plus de respect à ce qui est moins digne,'),
('1co',12,25,'crampon1923','afin qu''il n''y ait pas de division dans le corps, mais que les membres aient également soin les uns des autres.'),
('1co',12,26,'crampon1923','Et si un membre souffre, tous les membres souffrent avec lui; si un membre est honoré, tous les membres s''en réjouissent avec lui.'),
('1co',12,27,'crampon1923','Vous êtes le corps du Christ, et vous êtes ses membres, chacun pour sa part.'),
('1co',12,28,'crampon1923','Dieu a établi dans l''Eglise premièrement des apôtres, secondement des prophètes, troisièmement des docteurs, ensuite ceux qui ont les dons {de faire des miracles,} de guérir, d''assister, de gouverner, de parler diverses langues.'),
('1co',12,29,'crampon1923','Tous sont-ils apôtres? Tous prophètes? Tous docteurs?'),
('1co',12,30,'crampon1923','Tous thaumaturges? Tous ont-ils les grâces de guérison? Tous parlent-ils des langues? Tous interprètent-ils?'),
('1co',12,31,'crampon1923','Aspirez aux dons supérieurs. Aussi bien je vais vous montrer une voie excellente entre toutes.'),
('1co',13,1,'crampon1923','Quand je parlerais les langues des hommes et des anges, si je n''ai pas la charité, je suis un airain qui résonne ou une cymbale qui retentit.'),
('1co',13,2,'crampon1923','Quand j''aurais le don de prophétie, que je connaîtrais tous les mystères, et que je posséderais toute science; quand j''aurais même toute la foi, jusqu''à transporter des montagnes, si je n''ai pas la charité, je ne suis rien.'),
('1co',13,3,'crampon1923','Quand je distribuerais tous mes biens pour la nourriture des pauvres, quand je livrerais mon corps aux flammes, si je n''ai pas la charité, tout cela ne me sert de rien.'),
('1co',13,4,'crampon1923','La charité est patiente, elle est bonne; la charité n''est pas envieuse, la charité n''est point inconsidérée, elle ne s''enfle point d''orgueil;'),
('1co',13,5,'crampon1923','elle ne fait rien d''inconvenant, elle ne cherche point son intérêt, elle ne s''irrite point, elle ne tient pas compte du mal;'),
('1co',13,6,'crampon1923','elle ne prend pas plaisir à l''injustice, mais elle se réjouit de la vérité;'),
('1co',13,7,'crampon1923','elle excuse tout, elle croit tout, elle espère tout, elle supporte tout.'),
('1co',13,8,'crampon1923','La charité ne passera jamais. S''agit-il des prophéties, elles prendront fin; des langues, elles cesseront; de la science, elle aura son terme.'),
('1co',13,9,'crampon1923','Car nous ne connaissons qu''en partie, et nous ne prophétisons qu''en partie;'),
('1co',13,10,'crampon1923','or, quand sera venu ce qui est parfait, ce qui est partiel prendra fin.'),
('1co',13,11,'crampon1923','Lorsque j''étais enfant, je parlais comme un enfant, je pensais comme un enfant, je raisonnais comme un enfant; lorsque je suis devenu homme, j''ai laissé là ce qui était de l''enfant.'),
('1co',13,12,'crampon1923','Maintenant nous voyons dans un miroir, d''une manière obscure, mais alors nous verrons face à face; aujourd''hui je connais en partie, mais alors je connaîtrai comme je suis connu.'),
('1co',13,13,'crampon1923','Maintenant ces trois choses demeurent: la foi, l''espérance, la charité; mais la plus grande des trois c''est la charité.'),
('1co',14,1,'crampon1923','Recherchez la charité. Aspirez néanmoins aux dons spirituels, mais surtout à celui de prophétie.'),
('1co',14,2,'crampon1923','En effet, celui qui parle en langue ne parle pas aux hommes, mais à Dieu, car personne ne le comprend, et c''est en esprit qu''il dit des mystères.'),
('1co',14,3,'crampon1923','Celui qui prophétise au contraire, parle aux hommes, les édifie, les exhorte, les console.'),
('1co',14,4,'crampon1923','Celui qui parle en langue s''édifie lui-même; celui qui prophétise édifie l''Eglise [de Dieu].'),
('1co',14,5,'crampon1923','Je désire que vous parliez tous en langues, mais encore plus que vous prophétisiez; car celui qui prophétise est plus grand que celui qui parle en langues, à moins que ce dernier n''interprète ce qu''il dit, pour que l''Eglise en reçoive de l''édification.'),
('1co',14,6,'crampon1923','Voyons, frères, de quelle utilité vous serais-je, si je venais à vous parlant en langues, et si je ne vous parle pas par révélation, ou par science, ou par prophétie, ou par doctrine?'),
('1co',14,7,'crampon1923','Si les objets inanimés qui rendent un son, comme une flûte ou une harpe, ne rendent pas des sons distincts, comment connaîtra-t-on ce qui est joué sur la flûte ou sur la harpe?'),
('1co',14,8,'crampon1923','Et si la trompette rend un son confus, qui se préparera au combat?'),
('1co',14,9,'crampon1923','De même vous, si vous ne faites pas entendre avec la langue une parole distincte, comment saura-t-on ce que vous dites? Vous parlerez en l''air.'),
('1co',14,10,'crampon1923','Quelque nombreuses que puissent être dans le monde les diverses langues, il n''en est aucune qui consiste en sons inintelligibles.'),
('1co',14,11,'crampon1923','Si donc j''ignore la valeur du son, je serai un barbare pour celui qui parle, et celui qui parle sera un barbare pour moi.'),
('1co',14,12,'crampon1923','De même vous aussi, puisque vous aspirez aux dons spirituels, que ce soit pour l''édification de l''Eglise que vous cherchiez à en avoir abondamment.'),
('1co',14,13,'crampon1923','C''est pourquoi, que celui qui parle en langue prie pour obtenir le don d''interpréter.'),
('1co',14,14,'crampon1923','Car si je prie en langue, mon esprit est en prière, mais mon intelligence demeure sans fruit.'),
('1co',14,15,'crampon1923','Que faire donc? Je prierai avec l''esprit, mais je prierai aussi avec l''intelligence; je chanterai avec l''esprit, mais je chanterai aussi avec l''intelligence.'),
('1co',14,16,'crampon1923','Autrement, si tu rends grâces avec l''esprit, comment celui qui est dans les rangs de l''homme du peuple répondra-t-il " Amen! " à ton action de grâces, puisqu''il ne sait pas ce que tu dis?'),
('1co',14,17,'crampon1923','Ton hymne d''action de grâces est sans doute fort beau; mais lui n''en est pas édifié.'),
('1co',14,18,'crampon1923','Je rends grâces à [mon] Dieu de ce que je parle en langues plus que vous tous;'),
('1co',14,19,'crampon1923','mais, dans l''Eglise, j''aime mieux dire cinq paroles avec mon intelligence, afin d''instruire aussi les autres, que dix mille paroles en langue.'),
('1co',14,20,'crampon1923','Frères, ne soyez pas des enfants sous le rapport du jugement; mais faites-vous enfants sous le rapport de la malice, et, pour le jugement, soyez des hommes faits.'),
('1co',14,21,'crampon1923','Il est écrit dans la Loi: " C''est par des hommes d''une autre langue et par des lèvres étrangères que je parlerai à ce peuple, et même ainsi ils ne m''écouteront pas, dit le Seigneur. "'),
('1co',14,22,'crampon1923','C''est donc que les langues sont un signe, non pour les croyants, mais pour les infidèles; la prophétie, au contraire, est un signe, non pour les infidèles, mais pour les croyants.'),
('1co',14,23,'crampon1923','Si donc, l''Eglise entière se trouvant réunie en assemblée, tous parlent en langues, et qu''il survienne des hommes non initiés ou des infidèles, ne diront-ils pas que vous êtes des fous?'),
('1co',14,24,'crampon1923','Mais si tous prophétisent, et qu''il survienne un infidèle ou un homme non initié, il est convaincu par tous, il est jugé par tous,'),
('1co',14,25,'crampon1923','les secrets de son cœur sont dévoilés, de telle sorte que, tombant sur sa face, il adorera Dieu, et publiera que Dieu est vraiment au milieu de vous.'),
('1co',14,26,'crampon1923','Que faire donc, mes frères? Lorsque vous vous assemblez, tel d''entre vous a un cantique, tel une instruction, tel une révélation, tel un discours en langue, tel une interprétation, que tout se passe de manière à édifier.'),
('1co',14,27,'crampon1923','Si l''on parle en langue, que ce soient chaque fois deux ou trois au plus, chacun à son tour, et qu''il y ait un interprète;'),
('1co',14,28,'crampon1923','s''il n''y a point d''interprète, qu''on se taise dans l''assemblée et qu''on se parle à soi-même et à Dieu.'),
('1co',14,29,'crampon1923','Pour les prophètes, qu''il y en ait deux ou trois à parler, et que les autres jugent;'),
('1co',14,30,'crampon1923','et si un autre, qui est assis, a une révélation, que le premier se taise.'),
('1co',14,31,'crampon1923','Car vous pouvez tous prophétiser l''un après l''autre, afin que tous soient instruits et que tous soient exhortés.'),
('1co',14,32,'crampon1923','Or les esprits des prophètes sont soumis aux prophètes,'),
('1co',14,33,'crampon1923','car Dieu n''est pas un Dieu de désordre, mais de paix. Comme cela a eu lieu dans toutes les Eglises des saints,'),
('1co',14,34,'crampon1923','que vos femmes se taisent dans les assemblées, car elles n''ont pas mission de parler; mais qu''elles soient soumises, comme le dit aussi la Loi.'),
('1co',14,35,'crampon1923','Si elles veulent s''instruire sur quelque point, qu''elles interrogent leurs maris à la maison; car il est malséant à une femme de parler dans une assemblée.'),
('1co',14,36,'crampon1923','Est-ce de chez vous que la parole de Dieu est sortie? ou est-ce à vous seuls qu''elle est parvenue?'),
('1co',14,37,'crampon1923','Si quelqu''un croit être prophète ou riche en dons spirituels, qu''il reconnaisse que ces choses que je vous ai écrites sont des commandements du Seigneur.'),
('1co',14,38,'crampon1923','Et s''il veut l''ignorer, qu''il l''ignore.'),
('1co',14,39,'crampon1923','Ainsi donc, mes frères, aspirez au don de prophétie, et n''empêchez pas de parler en langue.'),
('1co',14,40,'crampon1923','Mais que tout se fasse avec bienséance et avec ordre.'),
('1co',15,1,'crampon1923','Je vous rappelle, frères, l''Evangile que je vous ai annoncé, que vous avez reçu, dans lequel vous avez persévéré,'),
('1co',15,2,'crampon1923','et par lequel aussi vous êtes sauvés, si vous le retenez tel que je vous l''ai annoncé; à moins que vous n''ayez cru en vain.'),
('1co',15,3,'crampon1923','Je vous ai enseigné avant tout, comme je l''ai appris moi-même, que le Christ est mort pour nos péchés, conformément aux Ecritures;'),
('1co',15,4,'crampon1923','qu''il a été enseveli et qu''il est ressuscité le troisième jour, conformément aux Ecritures;'),
('1co',15,5,'crampon1923','et qu''il est apparu à Céphas, puis aux Douze.'),
('1co',15,6,'crampon1923','Après cela, il est apparu en une seule fois à plus de cinq cents frères, dont la plupart sont encore vivants, et quelques-uns se sont endormis.'),
('1co',15,7,'crampon1923','Ensuite il est apparu à Jacques, puis à tous les apôtres.'),
('1co',15,8,'crampon1923','Après eux tous, il m''est aussi apparu à moi, comme à l''avorton.'),
('1co',15,9,'crampon1923','Car je suis le moindre des Apôtres, moi qui ne suis pas digne d''être appelé apôtre, parce que j''ai persécuté l''Eglise de Dieu.'),
('1co',15,10,'crampon1923','C''est par la grâce de Dieu que je suis ce que je suis, et sa grâce envers moi n''a pas été vaine; loin de là, j''ai travaillé plus qu''eux tous, non pas moi pourtant, mais la grâce de Dieu qui est avec moi.'),
('1co',15,11,'crampon1923','Ainsi donc, soit moi, soit eux, voilà ce que nous prêchons, et voilà ce que vous avez cru.'),
('1co',15,12,'crampon1923','Or, si l''on prêche que le Christ est ressuscité des morts, comment quelques-uns parmi vous disent-ils qu''il n''y a point de résurrection des morts?'),
('1co',15,13,'crampon1923','S''il n''y a point de résurrection des morts, le Christ non plus n''est pas ressuscité.'),
('1co',15,14,'crampon1923','Et si le Christ n''est pas ressuscité, notre prédication est donc vaine, vaine aussi est votre foi.'),
('1co',15,15,'crampon1923','Il se trouve même que nous sommes de faux témoins à l''égard de Dieu, puisque nous avons témoigné contre lui qu''il a ressuscité le Christ, tandis qu''il ne l''aurait pas ressuscité, s''il est vrai que les morts ne ressuscitent pas.'),
('1co',15,16,'crampon1923','Car si les morts ne ressuscitent pas, le Christ non plus n''est pas ressuscité.'),
('1co',15,17,'crampon1923','Et si le Christ n''est pas ressuscité, votre foi est vaine, vous êtes encore dans vos péchés,'),
('1co',15,18,'crampon1923','et par conséquent aussi, ceux qui se sont endormis dans le Christ sont perdus.'),
('1co',15,19,'crampon1923','Si nous n''avons d''espérance dans le Christ que pour cette vie seulement, nous sommes les plus malheureux de tous les hommes.'),
('1co',15,20,'crampon1923','Mais maintenant le Christ est ressuscité des morts, il est les prémices de ceux qui se sont endormis.'),
('1co',15,21,'crampon1923','Car, puisque par un homme est venue la mort, c''est par un homme aussi que vient la résurrection des morts.'),
('1co',15,22,'crampon1923','Et comme tous meurent en Adam, de même aussi tous seront vivifiés dans le Christ,'),
('1co',15,23,'crampon1923','mais chacun en son rang: comme prémices le Christ, ensuite ceux qui appartiennent au Christ, lors de son avènement.'),
('1co',15,24,'crampon1923','Puis ce sera la fin, quand il remettra le royaume à Dieu et au Père, après avoir anéanti toute principauté, toute puissance et toute force.'),
('1co',15,25,'crampon1923','Car il faut qu''il règne: " jusqu''à ce qu''il ait mis tous ses ennemis sous ses pieds. "'),
('1co',15,26,'crampon1923','Le dernier ennemi qui sera détruit, c''est la mort,'),
('1co',15,27,'crampon1923','car Dieu " a tout mis sous ses pieds. " Mais lorsque l''Ecriture dit que tout lui a été soumis, il est évident que celui-là est excepté, qui lui a soumis toutes choses.'),
('1co',15,28,'crampon1923','Et lorsque tout lui aura été soumis, alors le Fils lui-même fera hommage à celui qui lui aura soumis toutes choses, afin que Dieu soit tout en tous.'),
('1co',15,29,'crampon1923','Autrement, que feraient ceux qui se font baptiser pour les morts? Si les morts ne ressuscitent en aucune manière, pourquoi se font-ils baptiser pour eux?'),
('1co',15,30,'crampon1923','Et nous-mêmes, pourquoi sommes-nous à toute heure en péril?'),
('1co',15,31,'crampon1923','Chaque jour je suis exposé à la mort, aussi vrai, mes frères, que vous êtes ma gloire en Jésus-Christ notre Seigneur.'),
('1co',15,32,'crampon1923','Si c''est avec des vues humaines que j''ai combattu contre les bêtes à Ephèse, quel avantage m''en revient-il? Si les morts ne ressuscitent pas, " mangeons et buvons, car demain nous mourrons. "'),
('1co',15,33,'crampon1923','Ne vous laissez pas séduire: " les mauvaises compagnies corrompent les bonnes mœurs. "'),
('1co',15,34,'crampon1923','Revenez à vous-mêmes, sérieusement, et ne péchez point; car il y en a qui sont dans l''ignorance de Dieu, je le dis à votre honte.'),
('1co',15,35,'crampon1923','Mais, dira quelqu''un: Comment les morts ressuscitent-ils? avec quel corps reviennent-ils?'),
('1co',15,36,'crampon1923','Insensé! ce que tu sèmes ne reprend pas vie, s''il ne meurt auparavant.'),
('1co',15,37,'crampon1923','Et ce que tu sèmes, ce n''est pas le corps qui sera un jour; c''est un simple grain, soit de blé, soit de quelque autre semence:'),
('1co',15,38,'crampon1923','mais Dieu lui donne un corps comme il l''a voulu, et à chaque semence il donne le corps qui lui est propre.'),
('1co',15,39,'crampon1923','Toute chair n''est pas la même chair; autre est la chair des hommes, autre celle des quadrupèdes, autre celle des oiseaux, autre celle des poissons.'),
('1co',15,40,'crampon1923','Il y a aussi des corps célestes et des corps terrestres; mais l''éclat des corps célestes est d''une autre nature que celui des corps terrestres:'),
('1co',15,41,'crampon1923','autre est l''éclat du soleil, autre l''éclat de la lune, et autre l''éclat des étoiles; même une étoile diffère en éclat d''une autre étoile.'),
('1co',15,42,'crampon1923','Ainsi en est-il pour la résurrection des morts. Semé dans la corruption, le corps ressuscite, incorruptible;'),
('1co',15,43,'crampon1923','semé dans l''ignominie, il ressuscite glorieux; semé dans la faiblesse, il ressuscite plein de force;'),
('1co',15,44,'crampon1923','semé corps animal, il ressuscite corps spirituel. S''il y a un corps animal, il y aussi un corps spirituel.'),
('1co',15,45,'crampon1923','C''est en ce sens qu''il est écrit: " Le premier homme, Adam, a été fait âme vivante "; le dernier Adam a été fait esprit vivifiant.'),
('1co',15,46,'crampon1923','Mais ce n''est pas ce qui est spirituel qui a été fait d''abord, c''est ce qui est animal; ce qui est spirituel vient ensuite.'),
('1co',15,47,'crampon1923','Le premier homme, tiré de la terre, est terrestre; le second vient du ciel.'),
('1co',15,48,'crampon1923','Tel est le terrestre, tels sont aussi les terrestres; et tel est le céleste, tels sont aussi les célestes.'),
('1co',15,49,'crampon1923','Et de même que nous avons porté l''image du terrestre, nous porterons aussi l''image du céleste.'),
('1co',15,50,'crampon1923','Ce que j''affirme, frères, c''est que ni la chair ni le sang ne peuvent hériter le royaume de Dieu, et que la corruption n''héritera pas l''incorruptibilité.'),
('1co',15,51,'crampon1923','Voici un mystère que je vous révèle: Nous ne nous endormirons pas tous, mais tous nous serons changés,'),
('1co',15,52,'crampon1923','en un instant, en un clin d''œil, au son de la dernière trompette, car la trompette retentira et les morts ressusciteront incorruptibles, et nous, nous serons changés.'),
('1co',15,53,'crampon1923','Car il faut que ce corps corruptible revête l''incorruptibilité, et que ce corps mortel revête l''immortalité.'),
('1co',15,54,'crampon1923','Lorsque ce corps corruptible aura revêtu l''incorruptibilité, et que ce corps mortel aura revêtu l''immortalité, alors s''accomplira la parole qui est écrite: " La mort a été engloutie pour la victoire. "'),
('1co',15,55,'crampon1923','" O mort, où est ta victoire? O mort, où est ton aiguillon? "'),
('1co',15,56,'crampon1923','Or l''aiguillon de la mort, c''est le péché et la puissance du péché, c''est la loi.'),
('1co',15,57,'crampon1923','Mais grâces soient rendues à Dieu, qui nous a donné la victoire par Notre-Seigneur Jésus-Christ!'),
('1co',15,58,'crampon1923','Ainsi, mes frères bien-aimés, soyez fermes, inébranlables, travaillant de plus en plus à l''œuvre du Seigneur, sachant que votre travail n''est pas vain dans le Seigneur.'),
('1co',16,1,'crampon1923','Quant à la collecte en faveur des saints, suivez, vous aussi, les prescriptions que j''ai données aux Eglises de la Galatie.'),
('1co',16,2,'crampon1923','Le premier jour de la semaine, que chacun de vous mette à part chez lui, et amasse ce qu''il peut épargner, afin qu''on n''attende pas mon arrivée pour faire les collectes.'),
('1co',16,3,'crampon1923','Et quand je serai arrivé, j''enverrai avec des lettres ceux que vous aurez désignés, porter vos libéralités à Jérusalem.'),
('1co',16,4,'crampon1923','S''il convient que j''y aille aussi moi-même, ils feront le voyage avec moi.'),
('1co',16,5,'crampon1923','J''irai chez vous quand j''aurai passé par la Macédoine; car je la traverserai seulement;'),
('1co',16,6,'crampon1923','mais peut-être séjournerai-je auprès de vous, ou même y passerai-je l''hiver, afin que ce soit vous qui m''accompagniez là où je dois aller.'),
('1co',16,7,'crampon1923','Je ne veux pas cette fois vous voir seulement en passant, mais j''espère demeurer quelque temps auprès de vous, si le Seigneur le permet.'),
('1co',16,8,'crampon1923','Je resterai cependant à Ephèse jusqu''à la Pentecôte;'),
('1co',16,9,'crampon1923','car une porte m''est ouverte, grande et efficace, et les adversaires sont nombreux.'),
('1co',16,10,'crampon1923','Si Timothée vient chez vous, faites en sorte qu''il soit sans crainte parmi vous, car il travaille comme moi à l''œuvre du Seigneur.'),
('1co',16,11,'crampon1923','Que personne donc ne le méprise. Reconduisez-le en paix, afin qu''il vienne me trouver, car je l''attends avec les frères.'),
('1co',16,12,'crampon1923','Pour ce qui est de notre frère Apollos, je l''ai fortement engagé à se rendre chez vous avec les frères, mais il n''a absolument pas voulu le faire maintenant; il ira quand il en trouvera l''occasion.'),
('1co',16,13,'crampon1923','Veillez, demeurez fermes dans la foi, soyez des hommes, fortifiez-vous.'),
('1co',16,14,'crampon1923','Que tout se fasse chez vous dans la charité.'),
('1co',16,15,'crampon1923','Je vous adresse encore cette recommandation, frères. Vous savez que la famille de Stéphanas est les prémices de l''Achaïe, et qu''elle s''est dévouée aux services des saints:'),
('1co',16,16,'crampon1923','ayez à votre tour de la déférence pour des hommes de ce mérite, et pour quiconque coopère et travaille à la même œuvre.'),
('1co',16,17,'crampon1923','Je suis heureux de la présence de Stéphanas, de Fortunat et d''Achaïque; ils ont suppléé à votre absence,'),
('1co',16,18,'crampon1923','car ils ont tranquillisé mon esprit et le vôtre. Sachez donc apprécier de tels hommes.'),
('1co',16,19,'crampon1923','Les Eglises d''Asie vous saluent. Aquilas et Priscille, avec l''Eglise qui est dans leur maison, vous saluent beaucoup dans le Seigneur.'),
('1co',16,20,'crampon1923','Tous les frères vous saluent. Saluez-vous les uns les autres par un saint baiser.'),
('1co',16,21,'crampon1923','La salutation est de ma propre main, à moi Paul.'),
('1co',16,22,'crampon1923','SI QUELQU''UN N''AIME PAS LE SEIGNEUR, QU''IL SOIT ANATHÈME! MARAN ATHA.'),
('1co',16,23,'crampon1923','QUE LA GRÂCE DU SEIGNEUR JÉSUS SOIT AVEC VOUS! MON AMOUR EST AVEC VOUS TOUS EN JÉSUS-CHRIST [AMEN!].'),
('1co',16,24,'crampon1923',''),
('2co',1,1,'crampon1923','Paul, apôtre de Jésus-Christ par la volonté de Dieu, et Timothée son frère, à l''Eglise de Dieu qui est à Corinthe, et à tous les saints qui sont dans toute l''Achaïe:'),
('2co',1,2,'crampon1923','grâce et paix vous soient données de la part de Dieu notre Père et du Seigneur Jésus-Christ!'),
('2co',1,3,'crampon1923','Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, le Père des miséricordes et le Dieu de toute consolation,'),
('2co',1,4,'crampon1923','qui nous console dans toutes nos tribulations, afin que, par la consolation que nous recevons nous-mêmes de lui, nous puissions consoler les autres dans toutes leurs afflictions!'),
('2co',1,5,'crampon1923','Car de même que les souffrances du Christ abondent en nous, de même aussi par le Christ abonde notre consolation.'),
('2co',1,6,'crampon1923','Si nous sommes affligés, c''est pour votre consolation et pour votre salut; si nous sommes consolés, c''est pour votre consolation, qui vous fait supporter avec patience les mêmes souffrances que nous endurons aussi.'),
('2co',1,7,'crampon1923','Et notre espérance à votre égard est ferme, parce que nous savons que, comme vous avez part aux souffrances, vous avez part aussi à la consolation.'),
('2co',1,8,'crampon1923','Nous ne voulons pas, en effet, vous laisser ignorer, frères, au sujet de la tribulation qui nous est survenue en Asie, que nous avons été accablés au delà de toute mesure, au delà de nos forces, à tel point que nous désespérions même de la vie;'),
('2co',1,9,'crampon1923','mais nous avions en nous-mêmes l''arrêt de notre mort, afin de ne pas mettre notre confiance en nous-mêmes, mais de la mettre en Dieu, qui ressuscite les morts.'),
('2co',1,10,'crampon1923','C''est lui qui nous a délivrés de cette mort si imminente, qui nous en délivre, et qui, nous l''espérons, nous délivrera dans la suite,'),
('2co',1,11,'crampon1923','surtout si vous-mêmes vous nous assistez aussi de vos prières, afin que ce bienfait, nous étant accordé en considération de beaucoup de personnes, soit aussi pour un grand nombre l''occasion de rendre grâces à notre sujet.'),
('2co',1,12,'crampon1923','Car ce qui fait notre gloire, c''est ce témoignage de notre conscience que nous nous sommes conduits dans le monde, et particulièrement envers vous, avec simplicité et sincérité devant Dieu, non avec une sagesse charnelle, mais avec la grâce de Dieu.'),
('2co',1,13,'crampon1923','Nous ne vous écrivons pas autre chose que ce que vous lisez et ce que vous connaissez bien; et ce que, je l''espère, vous reconnaîtrez jusqu''à la fin,'),
('2co',1,14,'crampon1923','— comme une partie d''entre vous nous connaissent, — que nous sommes votre gloire, de même que vous serez aussi la nôtre au jour du Seigneur Jésus.'),
('2co',1,15,'crampon1923','Dans cette persuasion, je m''étais proposé d''aller d''abord chez vous, afin que vous eussiez une double grâce:'),
('2co',1,16,'crampon1923','je voulais passer par chez vous pour aller en Macédoine, puis revenir de la Macédoine chez vous, et vous m''auriez fait accompagner en Judée.'),
('2co',1,17,'crampon1923','Est-ce donc qu''en formant ce dessein j''aurais agi avec légèreté? Ou bien est-ce que les projets que je fais, je les fais selon la chair, de sorte qu''il y ait en moi le oui et le non?'),
('2co',1,18,'crampon1923','Aussi vrai que Dieu est fidèle, la parole que nous vous avons adressée n''est pas oui et non.'),
('2co',1,19,'crampon1923','Car le Fils de Dieu, Jésus-Christ, que nous avons prêché au milieu de vous, Silvain, Timothée et moi, n''a pas été oui et non; il n''y eu que oui en lui.'),
('2co',1,20,'crampon1923','Car, pour autant qu''il y a de promesses de Dieu, elles sont oui en Jésus; c''est pourquoi aussi, grâce à lui, l''amen est prononcé, à la gloire de Dieu, par notre ministère.'),
('2co',1,21,'crampon1923','Et celui qui nous affermit avec vous dans le Christ, et qui nous a oints, c''est Dieu,'),
('2co',1,22,'crampon1923','lequel nous a aussi marqués d''un sceau et nous a donné à titre d''arrhes, le Saint-Esprit dans nos cœurs.'),
('2co',1,23,'crampon1923','Pour moi, je prends Dieu à témoin sur mon âme que c''est pour vous épargner que je ne suis point allé de nouveau à Corinthe;'),
('2co',1,24,'crampon1923','non que nous prétendions dominer sur votre foi, mais nous contribuons à votre joie; car dans la foi vous êtes fermes.'),
('2co',2,1,'crampon1923','Je me suis donc promis à moi-même de ne pas retourner chez vous dans la tristesse.'),
('2co',2,2,'crampon1923','Car si moi-même je vous attriste, de qui puis-je attendre de la joie? N''est-ce pas de celui même que j''aurais affligé?'),
('2co',2,3,'crampon1923','Je vous ai écrit comme je l''ai fait, pour ne pas éprouver, à mon arrivée, de la tristesse de la part de ceux qui devaient me donner de la joie, ayant en vous tous cette confiance, que vous faites tous votre joie de la mienne.'),
('2co',2,4,'crampon1923','Car c''est dans une grande affliction, dans l''angoisse de mon cœur, et avec beaucoup de larmes, que je vous ai écrit, non dans le dessein de vous attrister, mais pour vous faire connaître l''amour que j''ai pour vous.'),
('2co',2,5,'crampon1923','Si quelqu''un a été une cause de tristesse, ce n''est pas moi qu''il a attristé, mais c''est vous tous en quelque sorte, pour ne pas trop le charger.'),
('2co',2,6,'crampon1923','C''est assez pour cet homme du châtiment qui lui a été infligé par le plus grand nombre,'),
('2co',2,7,'crampon1923','en sorte que vous devez bien plutôt lui faire grâce et le consoler, de peur qu''il ne soit absorbé par une tristesse excessive.'),
('2co',2,8,'crampon1923','Je vous invite donc à prendre envers lui une décision charitable.'),
('2co',2,9,'crampon1923','Car, en vous écrivant, mon but était aussi de connaître, à l''épreuve, si vous m''obéiriez en toutes choses.'),
('2co',2,10,'crampon1923','A qui vous pardonnez, je pardonne également; car, pour moi si j''ai pardonné, si tant est que je pardonne quelque chose, c''est à cause de vous, et à la face du Christ,'),
('2co',2,11,'crampon1923','afin de ne pas laisser à Satan l''avantage sur nous; car nous n''ignorons pas ses desseins.'),
('2co',2,12,'crampon1923','Lorsque je fus arrivé à Troas pour l''Evangile du Christ, quoiqu''une porte m''y fût ouverte dans le Seigneur,'),
('2co',2,13,'crampon1923','je n''eus point l''esprit en repos, parce que je n''y trouvais pas Tite, mon frère; c''est pourquoi, ayant pris congé des frères, je partis pour la Macédoine.'),
('2co',2,14,'crampon1923','Mais grâces soient rendues à Dieu qui nous fait triompher en tout temps dans le Christ, et par nous répand en tout lieu le parfum de sa connaissance!'),
('2co',2,15,'crampon1923','En effet, nous sommes pour Dieu la bonne odeur du Christ parmi ceux qui sont sauvés et parmi ceux qui se perdent:'),
('2co',2,16,'crampon1923','aux uns, une odeur de mort, qui donne la mort; aux autres, une odeur de vie, qui donne la vie. — Et qui donc est capable d''un tel ministère?'),
('2co',2,17,'crampon1923','Car nous ne sommes pas comme la plupart, nous ne frelatons pas la parole de Dieu; mais c''est dans sa pureté, telle qu''elle vient de Dieu, que nous la prêchons devant Dieu en Jésus-Christ.'),
('2co',3,1,'crampon1923','Recommençons-nous à nous recommander nous-mêmes? Ou bien avons-nous besoin, comme certains, de lettres de recommandation auprès de vous ou de votre part?'),
('2co',3,2,'crampon1923','C''est vous-mêmes qui êtes notre lettre, écrite dans nos cœurs, connue et lue de tous les hommes.'),
('2co',3,3,'crampon1923','Oui, manifestement, vous êtes une lettre du Christ, écrite par notre ministère, non avec de l''encre, mais par l''Esprit du Dieu vivant; non sur des tables de pierre, mais sur des tables de chair, sur vos cœurs.'),
('2co',3,4,'crampon1923','Cette assurance, nous l''avons par le Christ en vue de Dieu.'),
('2co',3,5,'crampon1923','Ce n''est pas que nous soyons par nous-mêmes capables de concevoir quelque chose comme venant de nous-mêmes; mais notre aptitude vient de Dieu.'),
('2co',3,6,'crampon1923','C''est lui également qui nous a rendus capables d''être ministres d''une nouvelle alliance, non de la lettre, mais de l''esprit; car la lettre tue, mais l''esprit vivifie.'),
('2co',3,7,'crampon1923','Or, si le ministère de la mort, gravé en lettres sur des pierres, a été entouré de gloire au point que les fils d''Israël ne pouvaient fixer leurs regards sur la face de Moïse à cause de l''éclat de son visage, tout passager qu''il fût,'),
('2co',3,8,'crampon1923','combien plus le ministère de l''esprit ne sera-t-il pas entouré de gloire?'),
('2co',3,9,'crampon1923','C''est qu''en effet, si le ministère de la condamnation a été glorieux, le ministère qui confère la justice le surpasse de beaucoup.'),
('2co',3,10,'crampon1923','Et même, sous ce rapport, ce qui a été glorifié autrefois ne l''a pas été, en comparaison de cette gloire infiniment supérieure.'),
('2co',3,11,'crampon1923','Car, si ce qui était passager a été donné dans la gloire, à plus forte raison ce qui est permanent sera-t-il glorieux.'),
('2co',3,12,'crampon1923','Ayant donc une telle espérance, nous usons d''une grande liberté,'),
('2co',3,13,'crampon1923','et nous ne faisons pas comme Moïse, qui mettait un voile sur son visage pour que les fils d''Israël ne vissent point la fin de ce qui était passager.'),
('2co',3,14,'crampon1923','Mais leurs esprits se sont aveuglés. Car jusqu''à ce jour quand ils font la lecture de l''Ancien Testament, le même voile demeure sans être ôté, parce que c''est dans le Christ qu''il est levé.'),
('2co',3,15,'crampon1923','Aujourd''hui encore, quand on lit Moïse, un voile est étendu sur leurs cœurs;'),
('2co',3,16,'crampon1923','mais dès que leurs cœurs se seront tournés vers le Seigneur, le voile sera ôté.'),
('2co',3,17,'crampon1923','Or le Seigneur, c''est l''esprit, et là où est l''esprit du Seigneur, là est la liberté.'),
('2co',3,18,'crampon1923','Pour nous tous, le visage découvert, réfléchissant comme dans un miroir la gloire du Seigneur, nous sommes transformés en la même image, de plus en plus resplendissante, comme par le Seigneur, qui est esprit.'),
('2co',4,1,'crampon1923','C''est pourquoi, revêtus de ce ministère selon la miséricorde qui nous a été faite, nous ne perdons pas courage.'),
('2co',4,2,'crampon1923','Nous rejetons loin de nous les choses honteuses qui se font en secret, ne nous conduisant pas avec astuce et ne faussant pas la parole de Dieu; mais, en manifestant franchement la vérité, nous nous recommandons à la conscience de tous les hommes devant Dieu.'),
('2co',4,3,'crampon1923','Si notre Evangile est encore voilé, c''est pour ceux qui se perdent qu''il reste voilé, pour ces incrédules'),
('2co',4,4,'crampon1923','dont le dieu de ce siècle a aveuglé l''intelligence, afin qu''ils ne voient point briller la splendeur de l''Evangile, où reluit la gloire du Christ, qui est l''image de Dieu.'),
('2co',4,5,'crampon1923','Car ce n''est pas nous-mêmes que nous prêchons, c''est le Christ Jésus, comme Seigneur. Pour nous, nous nous disons vos serviteurs à cause de Jésus.'),
('2co',4,6,'crampon1923','Car Dieu, qui a dit: Que la lumière brille du sein des ténèbres, c''est lui qui a fait luire sa clarté dans nos cœurs, pour que nous fassions briller la connaissance de la gloire de Dieu, laquelle resplendit sur la face du Christ.'),
('2co',4,7,'crampon1923','Mais nous portons ce trésor dans des vases de terre, afin qu''il paraisse que cette souveraine puissance de l''Evangile vient de Dieu et non pas de nous.'),
('2co',4,8,'crampon1923','Nous sommes opprimés de toute manière, mais non écrasés; dans la détresse, mais non dans le désespoir;'),
('2co',4,9,'crampon1923','persécutés, mais non délaissés; abattus, mais non perdus;'),
('2co',4,10,'crampon1923','portant toujours avec nous dans notre corps la mort de Jésus, afin que la vie de Jésus soit aussi manifestée dans notre corps.'),
('2co',4,11,'crampon1923','Car nous qui vivons, nous sommes sans cesse livrés à la mort à cause de Jésus, afin que la vie de Jésus soit aussi manifestée dans notre chair mortelle.'),
('2co',4,12,'crampon1923','Ainsi la mort agit en nous, et la vie en vous.'),
('2co',4,13,'crampon1923','Animés du même Esprit de foi, selon ce qui est écrit: " J''ai cru, c''est pourquoi j''ai parlé, " nous aussi nous croyons, et c''est pourquoi nous parlons,'),
('2co',4,14,'crampon1923','sachant que celui qui a ressuscité le Seigneur Jésus, nous ressuscitera aussi avec Jésus, et nous présentera à lui avec vous.'),
('2co',4,15,'crampon1923','Car tout cela se fait à cause de vous, afin que la grâce, en se répandant avec abondance, fasse abonder l''action de grâces d''un plus grand nombre, à la gloire de Dieu.'),
('2co',4,16,'crampon1923','C''est pourquoi nous ne perdons pas courage; au contraire, alors même que notre homme extérieur dépérit, notre homme intérieur se renouvelle de jour en jour.'),
('2co',4,17,'crampon1923','Car notre légère affliction du moment présent produit pour nous, au delà de toute mesure, un poids éternel de gloire,'),
('2co',4,18,'crampon1923','nos regards ne s''attachant point aux choses visibles, mais aux invisibles; car les choses visibles ne sont que pour un temps, les invisibles sont éternelles.'),
('2co',5,1,'crampon1923','Nous savons, en effet, que, si cette tente, notre demeure terrestre, vient à être détruite, nous avons une maison qui est l''ouvrage de Dieu, une demeure éternelle qui n''est pas faite de main d''homme, dans le ciel.'),
('2co',5,2,'crampon1923','Aussi gémissons-nous, dans cette tente, dans l''ardent désir que nous avons d''être revêtus de notre demeure céleste,'),
('2co',5,3,'crampon1923','si du moins nous sommes trouvés vêtus, et non pas nus.'),
('2co',5,4,'crampon1923','Car tant que nous sommes dans cette tente, nous gémissons accablés, parce que nous voulons, non pas ôter notre vêtement, mais revêtir l''autre par-dessus, afin que ce qu''il y a de mortel soit englouti par la vie.'),
('2co',5,5,'crampon1923','Et celui qui nous a formés pour cela, c''est Dieu, qui nous a donné les arrhes de l''Esprit.'),
('2co',5,6,'crampon1923','Etant donc toujours pleins d''assurance, et sachant que, aussi longtemps que nous habitons dans ce corps, nous sommes loin du Seigneur,'),
('2co',5,7,'crampon1923','— car nous marchons par la foi, et non par la vue, —'),
('2co',5,8,'crampon1923','dans cette assurance, nous aimons mieux déloger de ce corps et habiter auprès du Seigneur.'),
('2co',5,9,'crampon1923','C''est pour cela aussi que nous nous efforçons d''être agréable à Dieu, soit que nous demeurions dans ce corps, soit que nous le quittions.'),
('2co',5,10,'crampon1923','Car nous tous, il nous faut comparaître devant le tribunal du Christ, afin que chacun reçoive ce qu''il a mérité étant dans son corps, selon ses œuvres, soit bien, soit mal.'),
('2co',5,11,'crampon1923','Etant donc pénétrés de la crainte du Seigneur, nous cherchons à convaincre les hommes; quant à Dieu, il nous connaît intimement, et j''espère que dans vos consciences vous nous connaissez aussi.'),
('2co',5,12,'crampon1923','Car nous ne venons pas nous recommander encore nous-mêmes auprès de vous; mais vous fournir l''occasion de vous glorifier à notre sujet, afin que vous puissiez répondre à ceux qui tirent gloire de l''apparence, et non de ce qui est dans le cœur.'),
('2co',5,13,'crampon1923','En effet, si nous sommes hors de sens, c''est pour Dieu; si nous sommes de sens rassis, c''est pour vous.'),
('2co',5,14,'crampon1923','Car l''amour du Christ nous presse, persuadés, comme nous le sommes, que si un seul est mort pour tous, tous donc sont morts;'),
('2co',5,15,'crampon1923','et qu''il est mort pour tous, afin que ceux qui vivent ne vivent plus pour eux-mêmes, mais pour celui qui est mort et ressuscité pour eux.'),
('2co',5,16,'crampon1923','Aussi, désormais, nous ne connaissons plus personne selon la chair; et si nous avons connu le Christ selon la chair, à présent nous ne le connaissons plus de cette manière.'),
('2co',5,17,'crampon1923','Aussi bien, quiconque est en Jésus-Christ est une nouvelle créature; les choses anciennes sont passées, voyez, tout est devenu nouveau.'),
('2co',5,18,'crampon1923','Tout cela vient de Dieu, qui nous a réconciliés avec lui par Jésus-Christ, et qui nous a confié le ministère de la réconciliation.'),
('2co',5,19,'crampon1923','Car Dieu réconciliait le monde avec lui-même dans le Christ, n''imputant pas aux hommes leurs offenses, et mettant sur nos lèvres la parole de la réconciliation.'),
('2co',5,20,'crampon1923','C''est donc pour le Christ que nous faisons les fonctions d''ambassadeurs, Dieu lui-même exhortant par nous: nous vous en conjurons pour le Christ, réconciliez-vous avec Dieu!'),
('2co',5,21,'crampon1923','Celui qui n''a point connu le péché, il l''a fait péché pour nous, afin que nous devenions en lui justice de Dieu.'),
('2co',6,1,'crampon1923','Or donc, étant ses coopérateurs, nous vous exhortons à ne pas recevoir la grâce de Dieu en vain.'),
('2co',6,2,'crampon1923','Car il dit: " Au temps favorable, je t''ai exaucé, au jour du salut je t''ai porté secours. " Voici maintenant le temps favorable, voici le jour du salut.'),
('2co',6,3,'crampon1923','Nous ne donnons aucun sujet de scandale en quoi que ce soit, afin que notre ministère ne soit pas un objet de blâme.'),
('2co',6,4,'crampon1923','Mais nous nous rendons recommandables de toutes choses, comme des ministres de Dieu, par une grande constance, dans les tribulations, dans les nécessités, dans les détresses,'),
('2co',6,5,'crampon1923','sous les coups, dans les prisons, au travers des émeutes, dans les travaux, les veilles, les jeûnes;'),
('2co',6,6,'crampon1923','par la pureté, par la science, par la longanimité, par la bonté, par l''Esprit-Saint, par une charité sincère,'),
('2co',6,7,'crampon1923','par la parole de vérité, par la puissance de Dieu, par les armes offensives et défensives de la justice;'),
('2co',6,8,'crampon1923','parmi l''honneur et l''ignominie, parmi la mauvaise et la bonne réputation; traités d''imposteurs, et pourtant véridiques; d''inconnus, et pourtant bien connus;'),
('2co',6,9,'crampon1923','regardés comme mourants, et voici que nous vivons; comme châtiés, et nous ne sommes pas mis à mort;'),
('2co',6,10,'crampon1923','comme attristés, nous qui sommes toujours joyeux; comme pauvres, nous qui en enrichissons un grand nombre; comme n''ayant rien, nous qui possédons tout.'),
('2co',6,11,'crampon1923','Notre bouche s''est ouverte pour vous, ô Corinthiens, notre cœur s''est élargi.'),
('2co',6,12,'crampon1923','Vous n''êtes point à l''étroit dans nos entrailles, mais les vôtres se sont rétrécies.'),
('2co',6,13,'crampon1923','Rendez-nous la pareille, — je vous parle comme à mes enfants, — vous aussi, élargissez vos cœurs.'),
('2co',6,14,'crampon1923','Ne vous attachez pas à un même joug, avec les infidèles. Car quelle société y a-t-il entre la justice et l''iniquité? ou qu''a de commun la lumière avec les ténèbres?'),
('2co',6,15,'crampon1923','Quel accord y a-t-il entre le Christ et Bélial? ou quelle part a le fidèle avec l''infidèle?'),
('2co',6,16,'crampon1923','Quel rapport y a-t-il entre le temple de Dieu et des idoles? Car nous sommes, nous, le temple du Dieu vivant, selon ce que Dieu lui-même a dit: " J''habiterai au milieu d''eux et j''y marcherai; je serai leur Dieu, et eux seront mon peuple. "'),
('2co',6,17,'crampon1923','" C''est pourquoi sortez du milieu d''eux et séparez-vous, dit le Seigneur; ne touchez pas à ce qui est impur et moi je vous accueillerai.'),
('2co',6,18,'crampon1923','Je serai pour vous un père, et vous serez pour moi des fils et des filles, dit le Seigneur tout-puissant. "'),
('2co',7,1,'crampon1923','Ayant donc de telles promesses, bien-aimés, purifions-nous de toute souillure de la chair et de l''esprit, et achevons l''œuvre de notre sainteté dans la crainte de Dieu.'),
('2co',7,2,'crampon1923','Recevez-nous. Nous n''avons fait de tort à personne, nous n''avons ruiné personne, nous n''avons exploité personne.'),
('2co',7,3,'crampon1923','Ce n''est pas pour vous condamner que je dis cela, car je viens de le dire: vous êtes dans nos cœurs à la mort et à la vie.'),
('2co',7,4,'crampon1923','Je vous parle en toute franchise, j''ai grand sujet de me glorifier de vous; je suis rempli de consolation, je surabonde de joie au milieu de toutes nos tribulations.'),
('2co',7,5,'crampon1923','Car, depuis notre arrivée en Macédoine, notre chair n''eut aucun repos; nous étions affligés de toute manière: au dehors des combats, au dedans des craintes.'),
('2co',7,6,'crampon1923','Mais celui qui console les humbles, Dieu, nous a consolés par l''arrivée de Tite;'),
('2co',7,7,'crampon1923','non seulement par son arrivée, mais encore par la consolation que Tite lui-même avait éprouvée à votre sujet: il nous a raconté votre ardent désir, vos larmes, votre amour jaloux pour moi, de sorte que ma joie en a été plus grande.'),
('2co',7,8,'crampon1923','Ainsi, quoique je vous aie attristés par ma lettre, je ne le regrette plus, bien que je l''aie d''abord regretté, — car je vois que cette lettre vous a attristés, ne fût-ce que pour un moment, —'),
('2co',7,9,'crampon1923','je me réjouis à cette heure, non pas de ce que vous avez été attristés, mais de ce que votre tristesse vous a portés à la pénitence; car vous avez été attristés selon Dieu, de manière à n''éprouver aucun préjudice de notre part.'),
('2co',7,10,'crampon1923','En effet, la tristesse selon Dieu produit un repentir salutaire, qu''on ne regrette jamais, au lieu que la tristesse du monde produit la mort.'),
('2co',7,11,'crampon1923','Et quel empressement n''a-t-elle pas produit en vous, cette tristesse selon Dieu! Que dis-je? quelle justification! quelle indignation! quelle crainte! quel désir ardent! quel zèle! quelle sévérité! Vous avez montré à tous égards que vous étiez innocents dans cette affaire.'),
('2co',7,12,'crampon1923','Aussi bien, si je vous ai écrit, ce n''est ni à cause de celui qui a fait l''injure, ni à cause de celui qui l''a reçue, mais pour que votre dévouement pour nous éclatât parmi vous devant Dieu.'),
('2co',7,13,'crampon1923','Voilà ce qui nous a consolés. Mais à cette consolation, s''est ajoutée une joie beaucoup plus vive, celle que nous a fait éprouver la joie de Tite, dont vous avez tranquillisé l''esprit.'),
('2co',7,14,'crampon1923','Et si devant lui je me suis un peu glorifié à votre sujet, je n''en ai point eu de confusion; mais de même que nous vous avons toujours parlé selon la vérité, de même l''éloge que j''ai fait de vous à Tite s''est trouvé être la vérité.'),
('2co',7,15,'crampon1923','Son cœur ressent pour vous un redoublement d''affection, au souvenir de votre obéissance à tous, de la crainte, du tremblement avec lequel vous l''avez accueilli.'),
('2co',7,16,'crampon1923','Je suis heureux de pouvoir en toutes choses compter sur vous.'),
('2co',8,1,'crampon1923','Nous vous faisons connaître, frères, la grâce que Dieu a faite aux fidèles des Eglises de Macédoine.'),
('2co',8,2,'crampon1923','Au milieu de beaucoup de tribulations qui les ont éprouvés, leur joie a été pleine, et leur profonde pauvreté a produit les abondantes largesses de leur simplicité.'),
('2co',8,3,'crampon1923','Je l''atteste, ils ont donné volontairement selon leurs moyens, et même au delà de leurs moyens,'),
('2co',8,4,'crampon1923','nous demandant avec de grandes instances la grâce de prendre part à ce ministère en faveur des saints.'),
('2co',8,5,'crampon1923','Et non seulement ils ont rempli notre espérance, mais ils se sont donnés eux-mêmes, d''abord au Seigneur, puis à nous, sous l''impulsion de Dieu.'),
('2co',8,6,'crampon1923','Nous avons donc prié Tite d''aller aussi chez vous achever cette œuvre de charité, comme il l''avait commencée.'),
('2co',8,7,'crampon1923','De même que vous excellez en toutes choses, en foi, en parole, en connaissance, en zèle à tous égards et en affection pour nous, faites en sorte d''exceller aussi dans cette œuvre de bienfaisance.'),
('2co',8,8,'crampon1923','Je ne dis pas cela pour donner un ordre, mais je profite du zèle des autres pour mettre aussi à l''épreuve la sincérité de votre propre charité.'),
('2co',8,9,'crampon1923','Car vous savez la grâce de notre Seigneur Jésus-Christ, qui pour vous s''est fait pauvre, de riche qu''il était, afin de vous faire riches par sa pauvreté.'),
('2co',8,10,'crampon1923','C''est un avis que je donne ici, car vous n''avez pas besoin d''autre chose, vous qui, les premiers, avez commencé dès l''an passé non seulement à exécuter, mais aussi à former le dessein.'),
('2co',8,11,'crampon1923','Maintenant donc achevez aussi l''œuvre elle-même, afin que l''exécution selon vos moyens réponde chez vous à l''empressement de la volonté.'),
('2co',8,12,'crampon1923','Quand la bonne volonté existe, elle est agréable, à raison de ce que l''on a, et non de ce que l''on n''a pas.'),
('2co',8,13,'crampon1923','Car il ne faut pas qu''il y ait soulagement pour les autres, et détresse pour vous, mais égalité:'),
('2co',8,14,'crampon1923','dans la circonstance présente, votre superflu supplée à ce qui leur manque, afin que pareillement leur superflu pourvoie à vos besoins, en sorte qu''il y ait égalité,'),
('2co',8,15,'crampon1923','selon qu''il est écrit: " Celui qui avait recueilli beaucoup n''avait rien de trop, et celui qui avait peu recueilli ne manquait de rien. "'),
('2co',8,16,'crampon1923','Grâces soient rendues à Dieu de ce qu''il a mis le même zèle pour vous dans le cœur de Tite;'),
('2co',8,17,'crampon1923','non seulement il a bien accueilli notre prière, mais il se montre actuellement plus empressé et c''est de son plein gré qu''il part pour aller chez vous.'),
('2co',8,18,'crampon1923','Nous envoyons avec lui le frère dont toutes les Eglises font l''éloge pour sa prédication de l''Evangile,'),
('2co',8,19,'crampon1923','et qui, de plus, a été désigné par le suffrage des Eglises pour être notre compagnon de voyage, dans cette œuvre de charité que nous accomplissons à la gloire du Seigneur même, et en preuve de notre bonne volonté.'),
('2co',8,20,'crampon1923','Nous prenons cette mesure, afin que personne ne puisse nous blâmer au sujet de cette abondante collecte à laquelle nous donnons nos soins;'),
('2co',8,21,'crampon1923','car nous nous préoccupons de ce qui est bien, non seulement devant Dieu, mais aussi devant les hommes.'),
('2co',8,22,'crampon1923','Avec eux nous envoyons [aussi] notre frère, dont vous avons souvent éprouvé le zèle en mainte occasion, et qui en montre encore plus cette fois à cause de sa grande confiance en vous.'),
('2co',8,23,'crampon1923','Ainsi, pour Tite, il est mon compagnon et mon collaborateur auprès de vous; et quant à nos frères, ils sont les envoyés des Eglises, la gloire du Christ.'),
('2co',8,24,'crampon1923','Donnez-leur donc, à la face des Eglises, des preuves de votre charité, et ne démentez pas le juste orgueil que nous leur avons témoigné à votre sujet.'),
('2co',9,1,'crampon1923','Pour ce qui est de l''assistance destinée aux saints, il est superflu de vous en écrire;'),
('2co',9,2,'crampon1923','car je connais votre bonne volonté, et je m''en fais gloire pour vous auprès des Macédoniens, leur disant que, dès l''année passée, l''Achaïe est prête. Ce zèle dont vous donnez l''exemple en a stimulé un grand nombre.'),
('2co',9,3,'crampon1923','Toutefois, je vous ai envoyé les frères, afin que l''éloge que j''ai fait de vous ne soit pas démenti sur ce point, et que vous soyez prêts, comme j''ai affirmé que le seriez.'),
('2co',9,4,'crampon1923','Prenez-y garde: si des Macédoniens venaient avec moi et ne vous trouvaient pas prêts, quelle confusion pour moi, — pour ne pas dire pour vous, — dans une telle assurance!'),
('2co',9,5,'crampon1923','J''ai donc jugé nécessaire de prier nos frères de nous devancer chez vous, et d''organiser à temps votre libéralité déjà promise, afin qu''elle soit prête, mais comme une libéralité, et non comme une lésinerie.'),
('2co',9,6,'crampon1923','Je vous le dis, celui qui sème peu moissonnera peu, et celui qui sème abondamment moissonnera abondamment.'),
('2co',9,7,'crampon1923','Que chacun donne, comme il l''a résolu en son cœur, non avec regret ni par contrainte; car " Dieu aime celui qui donne avec joie. "'),
('2co',9,8,'crampon1923','Il est puissant pour vous combler de toutes sortes de grâces, afin que, ayant toujours en toutes choses de quoi satisfaire à tous vos besoins, il vous en reste encore abondamment pour toute espèce de bonnes œuvres,'),
('2co',9,9,'crampon1923','selon qu''il est écrit: " Avec largesse, il a donné aux pauvres; sa justice subsiste à jamais. "'),
('2co',9,10,'crampon1923','Celui qui fournit la semence au semeur et du pain pour sa nourriture, vous fournira la semence à vous aussi, et la multipliera, et il fera croître les fruits de votre justice;'),
('2co',9,11,'crampon1923','et vous serez ainsi enrichis à tous égards, pour donner d''un cœur simple ce qui, recueilli par nous, fera offrir à Dieu des actions de grâces.'),
('2co',9,12,'crampon1923','Car la dispensation de cette libéralité ne pourvoit pas seulement en abondance aux besoins des saints, mais elle est encore une riche source de nombreuses actions de grâces envers Dieu.'),
('2co',9,13,'crampon1923','A cause de la vertu éprouvée que cette offrande montre en vous, ils glorifient Dieu de votre obéissance dans la profession de l''Evangile du Christ, et de la simplicité avec laquelle vous faites part de vos dons à eux et à tous.'),
('2co',9,14,'crampon1923','Ils prient aussi pour vous, vous aimant d''un tendre amour, à cause de la grâce éminente que Dieu a mise en vous.'),
('2co',9,15,'crampon1923','Grâces soient rendues à Dieu pour son don ineffable!'),
('2co',10,1,'crampon1923','Moi, Paul, je vous invite par la douceur et la bonté du Christ, — moi " qui ai l''air humble quand je suis au milieu de vous, mais qui suis hardi avec vous quand je suis absent! " —'),
('2co',10,2,'crampon1923','je vous en prie, que je n''aie pas, quand je serai présent, à user de cette hardiesse, avec l''assurance que je me propose de montrer contre certaines gens qui se figurent que nous marchons selon la chair.'),
('2co',10,3,'crampon1923','Si nous marchons dans la chair, nous ne combattons pas selon la chair.'),
('2co',10,4,'crampon1923','Car les armes avec lesquelles nous combattons ne sont pas charnelles; elles sont puissantes devant Dieu pour renverser des forteresses.'),
('2co',10,5,'crampon1923','Nous renversons les raisonnements et toute hauteur qui s''élève contre la science de Dieu, et nous assujettissons tout pensée à l''obéissance du Christ.'),
('2co',10,6,'crampon1923','Nous sommes prêts aussi à punir toute désobéissance, lorsque, de votre côté, votre obéissance sera complète.'),
('2co',10,7,'crampon1923','Vous regardez à l''air! Eh bien, si quelqu''un se persuade qu''il est au Christ, qu''il se dise de lui-même, à son tour, que, s''il appartient au Christ, nous aussi nous lui appartenons.'),
('2co',10,8,'crampon1923','Si même je me glorifiais encore un peu plus de l''autorité que le Seigneur m''a donnée pour votre édification, et non pour votre destruction, je n''en aurais pas de confusion,'),
('2co',10,9,'crampon1923','afin de ne pas paraître vouloir vous intimider par mes lettres.'),
('2co',10,10,'crampon1923','Car " ses lettres, dit-on, sont sévères et fortes; mais, quand il est présent, c''est un homme faible et sa parole est méprisable. " —'),
('2co',10,11,'crampon1923','Que celui qui parle de la sorte se dise bien que tels nous sommes de loin en paroles dans nos lettres, tels nous sommes en effet devant vous.'),
('2co',10,12,'crampon1923','Nous n''avons pas la hardiesse de nous égaler ou de nous comparer à certaines gens qui se recommandent eux-mêmes. Mais, en se mesurant à leur propre mesure et en se comparant eux-mêmes à eux-mêmes, ils manquent d''intelligence.'),
('2co',10,13,'crampon1923','Pour nous, nous ne nous glorifions pas hors de mesure, mais selon la mesure du champ d''action que Dieu nous a assigné, pour nous faire arriver jusqu''à vous:'),
('2co',10,14,'crampon1923','— car nous ne dépassons pas nos limites, comme si nous n''étions pas parvenus jusqu''à vous, et nous sommes réellement venus jusqu''à vous avec l''Evangile du Christ. —'),
('2co',10,15,'crampon1923','Ce n''est pas outre mesure, pour les travaux d''autrui que nous nous glorifions; et nous avons l''espérance que, lorsque votre foi aura fait des progrès, nous grandirons de plus en plus parmi vous, en suivant les limites qui nous sont assignées,'),
('2co',10,16,'crampon1923','de manière à prêcher l''Evangile dans les pays qui sont au delà du vôtre, sans entrer dans le partage d''autrui, pour nous glorifier des travaux faits par d''autres.'),
('2co',10,17,'crampon1923','Toutefois " que celui qui se glorifie se glorifie dans le Seigneur. "'),
('2co',10,18,'crampon1923','Car ce n''est pas celui qui se recommande lui-même qui est un homme éprouvé; c''est celui que le Seigneur recommande.'),
('2co',11,1,'crampon1923','Oh! si vous pouviez supporter de ma part un peu de folie! Mais oui, vous me supportez.'),
('2co',11,2,'crampon1923','J''ai conçu pour vous une jalousie de Dieu; car je vous ai fiancés à un époux unique, pour vous présenter au Christ comme une vierge pure.'),
('2co',11,3,'crampon1923','Mais je crains bien que, comme Eve fut séduite par l''astuce du serpent, ainsi vos pensées ne se corrompent et ne perdent leur simplicité à l''égard du Christ.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2co',11,4,'crampon1923','Car si quelqu''un vient vous prêcher un autre Jésus que celui que nous vous avons prêché, ou si vous recevez un autre esprit que celui que vous avez reçu, ou un autre évangile que celui que vous avez embrassé, vous le supportez fort bien.'),
('2co',11,5,'crampon1923','Certes, j''estime que je ne suis inférieur en rien à ces apôtres par excellence!'),
('2co',11,6,'crampon1923','Si je suis étranger à l''art de la parole, je ne le suis point à la science; à tous égards et en tout, nous l''avons fait voir parmi vous.'),
('2co',11,7,'crampon1923','Ou bien ai-je commis une faute, parce qu''en m''abaissant moi-même pour vous élever, je vous ai annoncé gratuitement l''Evangile de Dieu?'),
('2co',11,8,'crampon1923','J''ai dépouillé d''autres Eglises, en recevant d''elles un salaire, pour pouvoir vous servir.'),
('2co',11,9,'crampon1923','Me trouvant au milieu de vous et dans le besoin, je n''ai été à charge à personne: des frères venus de Macédoine ont pourvu à ce qui me manquait. Je me suis gardé de vous être à charge en quoi que ce soit, et je m''en garderai.'),
('2co',11,10,'crampon1923','Aussi vrai que la vérité du Christ est en moi, je proteste que cette gloire-là ne me sera pas enlevée dans les contrées de l''Achaïe.'),
('2co',11,11,'crampon1923','Pourquoi? Parce que je ne vous aime pas? Ah! Dieu le sait!'),
('2co',11,12,'crampon1923','Mais ce que je fais, je le ferai encore, pour ôter ce prétexte à ceux qui en cherchent un, afin d''être reconnus semblables à nous dans la conduite dont ils se vantent.'),
('2co',11,13,'crampon1923','Ces gens-là sont de faux apôtres, des ouvriers astucieux, qui se déguisent en apôtres du Christ.'),
('2co',11,14,'crampon1923','Et ne vous en étonnez pas; car Satan lui-même se déguise en ange de lumière.'),
('2co',11,15,'crampon1923','Il n''est donc pas étrange que ses ministres aussi se déguisent en ministres de justice. Leur fin sera selon leurs œuvres.'),
('2co',11,16,'crampon1923','Je le répète, que personne ne me regarde comme un insensé; si non, acceptez-moi comme tel, afin que moi aussi je me glorifie un peu.'),
('2co',11,17,'crampon1923','Ce que je vais dire, avec cette assurance d''avoir sujet de me glorifier, je ne le dis pas selon le Seigneur, mais comme si j''étais en état de folie.'),
('2co',11,18,'crampon1923','Puisque tant de gens se glorifient selon la chair, je me glorifierai aussi.'),
('2co',11,19,'crampon1923','Et vous qui êtes sensés, vous supportez volontiers les insensés.'),
('2co',11,20,'crampon1923','Vous supportez bien qu''on vous asservisse, qu''on vous dévore, qu''on vous pille, qu''on vous traite avec arrogance, qu''on vous frappe au visage.'),
('2co',11,21,'crampon1923','Je le dis à ma honte, nous avons été bien faibles! Cependant, de quoi que ce soit qu''on ose se vanter, — je parle en insensé, moi aussi je l''ose.'),
('2co',11,22,'crampon1923','Sont-ils Hébreux? Moi aussi, je le suis. Sont-ils Israélites? Moi aussi. Sont-ils de la postérité d''Abraham? Moi aussi.'),
('2co',11,23,'crampon1923','Sont-ils ministres du Christ? — Ah! je vais parler en homme hors de sens: — je le suis plus qu''eux: bien plus qu''eux par les travaux, bien plus par les coups, infiniment plus par les emprisonnements; souvent j''ai vu de près la mort;'),
('2co',11,24,'crampon1923','cinq fois j''ai reçu des Juifs quarante coups de fouet moins un;'),
('2co',11,25,'crampon1923','trois fois, j''ai été battu de verges; une fois j''ai été lapidé; trois fois j''ai fait naufrage; j''ai passé un jour et une nuit dans l''abîme.'),
('2co',11,26,'crampon1923','Et mes voyages sans nombre, les périls sur les fleuves, les périls de la part des brigands, les périls de la part de ceux de ma nation, les périls de la part des Gentils, les périls dans les villes, les périls dans les déserts, les périls sur la mer, les périls de la part des faux frères,'),
('2co',11,27,'crampon1923','les labeurs et les peines, les nombreuses veilles, la faim, la soif, les jeûnes multipliés, le froid, la nudité!'),
('2co',11,28,'crampon1923','Et sans parler de tant d''autres choses, rappellerai-je mes soucis de chaque jour, la sollicitude de toutes les Eglises?'),
('2co',11,29,'crampon1923','Qui est faible que je ne sois faible aussi? Qui vient à tomber sans qu''un feu me dévore?'),
('2co',11,30,'crampon1923','S''il faut se glorifier, c''est de ma faiblesse que je me glorifierai.'),
('2co',11,31,'crampon1923','Dieu, qui est le Père de notre Seigneur Jésus-Christ, et qui est béni éternellement, sait que je ne mens point.'),
('2co',11,32,'crampon1923','A Damas, l''ethnarque du roi Arétas faisait garder la ville pour se saisir de moi;'),
('2co',11,33,'crampon1923','mais on me descendit par une fenêtre, dans une corbeille, le long de la muraille, et j''échappai ainsi de ses mains.'),
('2co',12,1,'crampon1923','Faut-il se glorifier? Cela n''est pas utile; j''en viendrai néanmoins à des visions et à des révélations du Seigneur.'),
('2co',12,2,'crampon1923','Je connais un homme dans le Christ qui, il y a quatorze ans, fut ravi jusqu''au troisième ciel (si ce fut dans son corps, je ne sais; si ce fut hors de son corps, je ne sais: Dieu le sait).'),
('2co',12,3,'crampon1923','Et je sais que cet homme (si ce fut dans son corps ou sans son corps, je ne sais, Dieu le sait)'),
('2co',12,4,'crampon1923','fut enlevé dans le paradis, et qu''il a entendu des paroles ineffables qu''il n''est pas permis à un homme de révéler.'),
('2co',12,5,'crampon1923','C''est pour cet homme-là que je me glorifierai; mais pour ce qui est de ma personne, je ne me ferai gloire que de mes faiblesses.'),
('2co',12,6,'crampon1923','Certes, si je voulais me glorifier, je ne serais pas un insensé, car je dirais la vérité; mais je m''en abstiens afin que personne ne se fasse de moi une idée supérieure à ce qu''il voit en moi ou à ce qu''il entend de moi.'),
('2co',12,7,'crampon1923','Et de crainte que l''excellence de ces révélations ne vînt à m''enfler d''orgueil, il m''a été mis une écharde dans ma chair, un ange de Satan pour me souffleter, [afin que je m''enorgueillisse point].'),
('2co',12,8,'crampon1923','A son sujet, trois fois j''ai prié le Seigneur de l''écarter de moi,'),
('2co',12,9,'crampon1923','et il m''a dit: " Ma grâce te suffit, car c''est dans la faiblesse que ma puissance se montre tout entière. " Je préfère donc bien volontiers me glorifier de mes faiblesses, afin que la puissance du Christ habite en moi.'),
('2co',12,10,'crampon1923','C''est pourquoi je me plais dans les faiblesses, dans les opprobres, dans les nécessités, dans les persécutions, dans les détresses, pour le Christ; car lorsque je suis faible, c''est alors que je suis fort.'),
('2co',12,11,'crampon1923','Je viens de faire l''insensé: vous m''y avez contraint. C''était à vous de me recommander, car je n''ai été inférieur en rien à ceux qui sont les Apôtres, quoique je ne sois rien.'),
('2co',12,12,'crampon1923','Les preuves de mon apostolat ont paru au milieu de vous par une patience à toute épreuve, par des signes, des prodiges et des miracles.'),
('2co',12,13,'crampon1923','Qu''avez-vous à envier aux autres Eglises, si ce n''est que je ne vous ai pas été à charge? Pardonnez-moi ce tort.'),
('2co',12,14,'crampon1923','Voici que pour la troisième fois je suis prêt à aller chez vous, et je ne vous serai point à charge; car ce ne sont pas vos biens que je cherche, c''est vous-mêmes. Ce n''est pas, en effet, aux enfants à amasser pour leurs parents, mais aux parents pour leurs enfants.'),
('2co',12,15,'crampon1923','Pour moi, bien volontiers je dépenserai et je me dépenserai moi-même tout entier pour vos âmes, dussé-je, en vous aimant davantage, être moins aimé de vous.'),
('2co',12,16,'crampon1923','Soit! je ne vous ai point été à charge; mais, en homme astucieux, j''ai usé d''artifice pour vous surprendre. —'),
('2co',12,17,'crampon1923','Ai-je donc, par quelqu''un de ceux que je vous ai envoyés, tiré de vous du profit?'),
('2co',12,18,'crampon1923','J''ai engagé Tite à aller chez vous, et avec lui j''ai envoyé le frère que vous savez: est-ce que Tite à rien tiré de vous? N''avons-nous pas marché dans le même esprit, suivi les mêmes traces?'),
('2co',12,19,'crampon1923','Vous croyez toujours que nous nous justifions auprès de vous. C''est devant Dieu, dans le Christ, que nous parlons, et tout cela, bien-aimés, nous le disons pour votre édification.'),
('2co',12,20,'crampon1923','Ma crainte, c''est qu''à mon arrivée je ne vous trouve pas tels que je voudrais, et que par suite vous ne me trouviez tel que vous ne voudriez pas. Je crains de trouver parmi vous des querelles, des rivalités, des animosités, des contestations, des médisances, des faux rapports, de l''enflure, des troubles.'),
('2co',12,21,'crampon1923','Je crains que, lorsque je serai de retour chez vous, mon Dieu ne m''humilie de nouveau à votre sujet, et que je n''aie à pleurer sur plusieurs pécheurs qui n''auront pas fait pénitence de l''impureté, des fornications et des dissolutions auxquelles ils se sont livrés.'),
('2co',13,1,'crampon1923','C''est maintenant pour la troisième fois que je vais chez vous. " Toute affaire se décidera sur la déclaration de deux ou trois témoins. "'),
('2co',13,2,'crampon1923','Je l''ai déjà dit et je le répète à l''avance; aujourd''hui que je suis absent comme lorsque j''étais présent pour la seconde fois, je déclare à ceux qui ont déjà péché et à tous les autres que, si je retourne chez vous, je n''userai d''aucun ménagement,'),
('2co',13,3,'crampon1923','puisque vous cherchez une preuve que le Christ parle en moi, lui qui n''est pas faible à votre égard, mais reste puissant parmi vous.'),
('2co',13,4,'crampon1923','Car, s''il a été crucifié en raison de sa faiblesse, il vit par la puissance de Dieu; or nous aussi, nous sommes faibles en lui, mais nous vivrons avec lui par la puissance de Dieu, pour sévir parmi vous.'),
('2co',13,5,'crampon1923','Examinez-vous vous-mêmes, voyez si vous êtes dans la foi; éprouvez-vous vous-mêmes. Ne reconnaissez-vous pas que Jésus-Christ est en vous? A moins peut-être que vous ne soyez pas des chrétiens éprouvés.'),
('2co',13,6,'crampon1923','Mais j''espère que vous reconnaîtrez que nous, nous sommes éprouvés.'),
('2co',13,7,'crampon1923','Cependant nous prions Dieu que vous ne fassiez rien de mal, non pour paraître nous-mêmes éprouvés, mais afin que vous pratiquiez ce qui est bien, dussions-nous passer pour non éprouvés.'),
('2co',13,8,'crampon1923','Car nous n''avons pas de puissance contre la vérité; nous n''en avons que pour la vérité.'),
('2co',13,9,'crampon1923','C''est un bonheur pour nous lorsque nous sommes faibles, et que vous êtes forts, et même c''est là ce que nous demandons dans nos prières que vous soyez consommés en perfection.'),
('2co',13,10,'crampon1923','C''est pourquoi je vous écris ces choses pendant que je suis loin de vous, afin de n''avoir pas, arrivé chez vous, à user de sévérité, selon le pouvoir que le Seigneur m''a donné pour édifier et non pour détruire.'),
('2co',13,11,'crampon1923','Du reste mes frères, soyez dans la joie, rendez-vous parfaits, consolez-vous, ayez un même sentiment, vivez en paix, et le Dieu d''amour et de paix sera avec vous.'),
('2co',13,12,'crampon1923','Saluez-vous les uns les autres par un saint baiser. Tous les saints vous saluent.'),
('2co',13,13,'crampon1923','Que la grâce de notre Seigneur Jésus-Christ, l''amour de Dieu et la communication du Saint-Esprit soient avec vous tous!'),
('ga',1,1,'crampon1923','Paul, apôtre, non de la part des hommes, ni par l''intermédiaire d''un homme, mais par Jésus-Christ et Dieu le Père, qui l''a ressuscité d''entre les morts,'),
('ga',1,2,'crampon1923','ainsi que tous les frères qui sont avec moi, aux Eglises de Galatie;'),
('ga',1,3,'crampon1923','à tous grâce et paix de la part de Dieu le Père et de notre Seigneur Jésus-Christ,'),
('ga',1,4,'crampon1923','qui s''est donné lui-même pour nos péchés, afin de nous arracher à la corruption du siècle présent, selon la volonté de notre Dieu et Père,'),
('ga',1,5,'crampon1923','à qui soit la gloire aux siècles des siècles! Amen!'),
('ga',1,6,'crampon1923','Je m''étonne que si vite vous vous laissiez détourner de celui qui vous a appelés en la grâce de Jésus-Christ, pour passer à un autre Evangile:'),
('ga',1,7,'crampon1923','non certes qu''il y en ait un autre; seulement il y a des gens qui vous troublent et qui veulent changer l''Evangile du Christ.'),
('ga',1,8,'crampon1923','Mais quand nous-mêmes, quand un ange venu du ciel vous annoncerait un autre Evangile que celui que nous vous avons annoncé, qu''il soit anathème!'),
('ga',1,9,'crampon1923','Nous l''avons dit précédemment, et je le répète à cette heure, si quelqu''un vous annonce un autre Evangile que celui que vous avez reçu, qu''il soit anathème!'),
('ga',1,10,'crampon1923','En ce moment, est-ce la faveur des hommes, ou celle de Dieu que je recherche? Mon dessein est-il de complaire aux hommes? Si je plaisais encore aux hommes, je ne serais pas serviteur du Christ.'),
('ga',1,11,'crampon1923','Je vous le déclare, en effet, frères, l''Evangile que j''ai prêché n''est pas de l''homme;'),
('ga',1,12,'crampon1923','car ce n''est pas d''un homme que je l''ai reçu ni appris, mais par une révélation de Jésus-Christ.'),
('ga',1,13,'crampon1923','Vous avez, en effet, entendu parler de ma conduite, quand j''étais dans le judaïsme; comment je persécutais à outrance et ravageais l''Eglise de Dieu,'),
('ga',1,14,'crampon1923','et comment je surpassais dans le judaïsme beaucoup de ceux de mon âge et de ma nation, étant à l''excès partisan jaloux des traditions de mes pères.'),
('ga',1,15,'crampon1923','Mais, lorsqu''il plut à celui qui m''avait mis à part dès le sein de ma mère, et qui m''a appelé par sa grâce,'),
('ga',1,16,'crampon1923','de révéler en moi son Fils, afin que je l''annonce parmi les Gentils, sur-le-champ, sans consulter ni la chair ni le sang,'),
('ga',1,17,'crampon1923','sans monter à Jérusalem vers ceux qui étaient apôtres avant moi, je partis pour l''Arabie; puis je revins encore à Damas.'),
('ga',1,18,'crampon1923','Trois ans plus tard, je montai à Jérusalem pour faire la connaissance de Céphas, et je demeurai quinze jours auprès de lui.'),
('ga',1,19,'crampon1923','Mais je ne vis aucun des autres Apôtres, si ce n''est Jacques, le frère du Seigneur.'),
('ga',1,20,'crampon1923','En tout ce que je vous écris là, je l''atteste devant Dieu, je ne mens pas.'),
('ga',1,21,'crampon1923','J''allai ensuite dans les contrées de la Syrie et de la Cilicie.'),
('ga',1,22,'crampon1923','Or, j''étais inconnu de visage aux Eglises de Judée qui sont dans le Christ;'),
('ga',1,23,'crampon1923','seulement elles avaient entendu dire que celui qui les persécutait autrefois annonçait maintenant la foi qu''il s''efforçait alors de détruire.'),
('ga',1,24,'crampon1923','Et elles glorifiaient Dieu à mon sujet.'),
('ga',2,1,'crampon1923','Ensuite, quatorze ans plus tard, je montai à nouveau à Jérusalem avec Barnabé ayant aussi pris Tite avec moi.'),
('ga',2,2,'crampon1923','Ce fut d''après une révélation que j''y montai, et je leur exposai l''Evangile que je prêche parmi les Gentils; je l''exposai en particulier à ceux qui étaient les plus considérés, de peur de courir ou d''avoir couru en vain.'),
('ga',2,3,'crampon1923','Or on n''obligea même pas Tite qui m''accompagnait, et qui était Grec, à se faire circoncire.'),
('ga',2,4,'crampon1923','Et cela, à cause des faux frères intrus, qui s''étaient glissés parmi nous pour épier la liberté que nous avons dans le Christ Jésus, afin de nous réduire en servitude.'),
('ga',2,5,'crampon1923','Nous n''avons pas consenti, même pour un instant, à nous soumettre à eux, afin que la vérité de l''Evangile fût maintenue parmi vous.'),
('ga',2,6,'crampon1923','Quant à ceux qu''on tient en si haute estime, — ce qu''ils ont été autrefois ne m''importe pas: Dieu ne fait point acception des personnes, — ces hommes si considérés ne m''imposèrent rien de plus.'),
('ga',2,7,'crampon1923','Au contraire, voyant que l''Evangile m''avait été confié pour les incirconcis, comme à Pierre pour les circoncis,'),
('ga',2,8,'crampon1923','— car celui qui a fait de Pierre l''apôtre des circoncis a aussi fait de moi l''apôtre des Gentils, —'),
('ga',2,9,'crampon1923','et ayant reconnu la grâce qui m''avait été accordée, Jacques, Céphas et Jean, qui sont regardés comme des colonnes, nous donnèrent la main, à Barnabé et à moi, en signe de communion, pour aller, nous aux païens, eux aux circoncis.'),
('ga',2,10,'crampon1923','Seulement nous devions nous souvenir des pauvres, ce que j''ai eu bien soin de faire.'),
('ga',2,11,'crampon1923','Mais lorsque Céphas vint à Antioche, je lui résistai en face, parce qu''il était digne de blâme.'),
('ga',2,12,'crampon1923','En effet, avant l''arrivée de certaines gens de l''entourage de Jacques, il mangeait avec les païens; mais après leur arrivée, il s''esquiva, et se tint à l''écart, par crainte des partisans de la circoncision.'),
('ga',2,13,'crampon1923','Avec lui, les autres Juifs usèrent aussi de dissimulation, en sorte que Barnabé lui-même s''y laissa entraîner.'),
('ga',2,14,'crampon1923','Pour moi, voyant qu''ils ne marchaient pas droit selon la vérité de l''Evangile, je dis à Céphas en présence de tous: " Si toi qui es Juif, tu vis à la manière des Gentils et non à la manière des Juifs, comment peux-tu forcer les Gentils à judaïser? "'),
('ga',2,15,'crampon1923','Pour nous, nous sommes Juifs de naissance, et non pécheurs d''entre les Gentils.'),
('ga',2,16,'crampon1923','Cependant sachant que l''homme est justifié, non par les œuvres de la Loi, mais par la foi dans le Christ Jésus, nous aussi nous avons cru au Christ Jésus, afin d''être justifiés par la foi en lui et non par les œuvres de la Loi; car nul homme ne sera justifié par les œuvres de la Loi.'),
('ga',2,17,'crampon1923','Or si, tandis que nous cherchons à être justifiés par le Christ, nous étions nous-mêmes trouvés pécheurs..., le Christ serait-il donc un ministre du péché? Loin de là!'),
('ga',2,18,'crampon1923','Car si ce que j''ai détruit, je le rebâtis, je me constitue moi-même prévaricateur,'),
('ga',2,19,'crampon1923','puisque c''est par la Loi que je suis mort à la Loi, afin de vivre pour Dieu. J''ai été crucifié avec le Christ,'),
('ga',2,20,'crampon1923','et si je vis, ce n''est plus moi qui vis, c''est le Christ qui vit en moi. Ce que je vis maintenant dans la chair, je le vis dans la foi au Fils de Dieu, qui m''a aimé et qui s''est livré lui-même pour moi.'),
('ga',2,21,'crampon1923','Je ne rejette pas la grâce de Dieu; car si la justice s''obtient par la Loi, le Christ est donc mort pour rien.'),
('ga',3,1,'crampon1923','O Galates insensés! qui vous a fascinés, vous aux yeux de qui a été tracée l''image de Jésus-Christ crucifié.'),
('ga',3,2,'crampon1923','Voici seulement ce que je voudrais savoir de vous: Est-ce par les œuvres de la Loi que vous avez reçu l''Esprit, ou par la soumission de la foi?'),
('ga',3,3,'crampon1923','Avez-vous si peu de sens, qu''après avoir commencé par l''esprit, vous finissiez par la chair?'),
('ga',3,4,'crampon1923','Avez-vous fait une telle expérience en vain? si toutefois c''est en vain.'),
('ga',3,5,'crampon1923','Celui qui vous confère l''Esprit et qui opère parmi vous des miracles, le fait-il donc par les œuvres de la Loi, ou par la soumission de la foi?'),
('ga',3,6,'crampon1923','comme il est écrit: " Abraham crut à Dieu, et cela lui fut imputé à justice. "'),
('ga',3,7,'crampon1923','Reconnaissez donc que ceux-là sont fils d''Abraham, qui sont de la foi.'),
('ga',3,8,'crampon1923','Aussi l''Ecriture, prévoyant que Dieu justifierait les nations par la foi, annonça d''avance à Abraham cette bonne nouvelle: " Toutes les nations seront bénies en toi. "'),
('ga',3,9,'crampon1923','De sorte que ceux qui sont de la foi sont bénis avec le fidèle Abraham.'),
('ga',3,10,'crampon1923','En effet tous ceux qui s''appuient sur les œuvres de la Loi sont sous la malédiction; car il est écrit: " Maudit quiconque n''est pas constant à observer tout ce qui est écrit dans le livre de la Loi. "'),
('ga',3,11,'crampon1923','Or que par la Loi nul ne soit justifié devant Dieu, cela est manifeste, puisque le " juste vivra par la foi. "'),
('ga',3,12,'crampon1923','Or la Loi ne procède pas de la foi; mais elle dit: " Celui qui accomplira ces commandements vivra en eux. "'),
('ga',3,13,'crampon1923','Le Christ nous a rachetés de la malédiction de la Loi, en se faisant malédiction pour nous, — car il est écrit: " Maudit quiconque est pendu au bois, " —'),
('ga',3,14,'crampon1923','afin que la bénédiction promise à Abraham s''étendît aux nations dans le Christ Jésus, afin que nous pussions recevoir par la foi l''Esprit promis.'),
('ga',3,15,'crampon1923','Frères, — je parle selon les usages des hommes, — un contrat en bonne forme, bien que l''engagement soit pris par un homme, n''est annulé par personne, et personne n''y ajoute.'),
('ga',3,16,'crampon1923','Or les promesses ont été faites à Abraham et à sa descendance. On ne dit pas: " Et à ses descendants, " comme s''il s''agissait de plusieurs; mais il dit: " A ta descendance, " comme ne parlant que d''un seul, savoir le Christ.'),
('ga',3,17,'crampon1923','Voici ce que je veux dire: Dieu ayant conclu une alliance en bonne forme, la loi qui est venue quatre cent trente ans après ne la rend pas nulle, de manière à rendre vaine la promesse.'),
('ga',3,18,'crampon1923','Car si l''héritage s''obtenait par la Loi, il ne viendrait plus d''une promesse; or, c''est par une promesse que Dieu a fait à Abraham ce don de sa grâce.'),
('ga',3,19,'crampon1923','Pourquoi donc la Loi? Elle a été ajoutée à cause des transgressions, jusqu''à ce que vînt " la descendance " à qui la promesse avait été faite; elle a été promulguée par les anges, par l''entremise d''un médiateur.'),
('ga',3,20,'crampon1923','Or le médiateur n''est pas médiateur d''un seul; et Dieu est un.'),
('ga',3,21,'crampon1923','La Loi va-t-elle donc contre les promesses de Dieu? Loin de là! S''il eût été donné une loi capable de procurer la vie, la justice viendrait réellement de la loi.'),
('ga',3,22,'crampon1923','Mais l''Ecriture a tout enfermé sous le péché, afin que, par la foi en Jésus-Christ, ce qui avait été promis fût donné à ceux qui croient.'),
('ga',3,23,'crampon1923','Avant que vînt la foi, nous étions enfermés sous la garde de la Loi, en vue de la foi qui devait être révélée.'),
('ga',3,24,'crampon1923','Ainsi la Loi a été notre pédagogue pour nous conduire au Christ, afin que nous fussions justifiés par la foi.'),
('ga',3,25,'crampon1923','Mais la foi étant venue, nous ne sommes plus sous un pédagogue.'),
('ga',3,26,'crampon1923','Car vous êtes tous fils de Dieu par la foi dans le Christ Jésus.'),
('ga',3,27,'crampon1923','Vous tous, en effet, qui avez été baptisés dans le Christ, vous avez revêtu le Christ.'),
('ga',3,28,'crampon1923','Il n''y a plus ni Juif ni Grec; il n''y a plus ni esclave ni homme libre; il n''y a plus ni homme ni femme: car vous n''êtes tous qu''une personne dans le Christ Jésus.'),
('ga',3,29,'crampon1923','Et si vous êtes au Christ, vous êtes donc " descendance " d''Abraham, héritiers selon la promesse.'),
('ga',4,1,'crampon1923','Or je dis ceci: Aussi longtemps que l''héritier est enfant, il ne diffère en rien d''un esclave, quoiqu''il soit le maître de tout;'),
('ga',4,2,'crampon1923','mais il est soumis à des tuteurs et à des curateurs jusqu''au temps marqué par le père.'),
('ga',4,3,'crampon1923','De même, nous aussi, quand nous étions enfants, nous étions sous l''esclavage des rudiments du monde.'),
('ga',4,4,'crampon1923','Mais lorsque est venue la plénitude des temps, Dieu a envoyé son Fils, formé d''une femme, né sous la Loi,'),
('ga',4,5,'crampon1923','pour affranchir ceux qui sont sous la Loi, afin de nous conférer l''adoption.'),
('ga',4,6,'crampon1923','Et parce que vous êtes fils, Dieu a envoyé dans vos cœurs l''Esprit de son Fils, lequel crie: Abba! Père!'),
('ga',4,7,'crampon1923','Ainsi tu n''es plus esclave, tu es fils; et si tu es fils, tu es aussi héritier, grâce à Dieu.'),
('ga',4,8,'crampon1923','Autrefois, il est vrai, ne connaissant pas Dieu, vous serviez ceux qui par leur nature ne sont pas dieux;'),
('ga',4,9,'crampon1923','mais à présent que vous avez connu Dieu, ou plutôt que vous avez été connus de Dieu, comment retournez-vous à ces pauvres et faibles rudiments, auxquels de nouveau vous voulez vous asservir encore?'),
('ga',4,10,'crampon1923','Vous observez les jours, les mois, les temps et les années!'),
('ga',4,11,'crampon1923','J''ai peur pour vous d''avoir travaillé en vain parmi vous.'),
('ga',4,12,'crampon1923','Devenez comme moi, puisque moi-même je suis comme vous, frères, je vous en supplie. Vous ne m''avez blessé en rien.'),
('ga',4,13,'crampon1923','Quand je vous ai pour la première fois annoncé l''Evangile, vous savez quelle était l''infirmité de ma chair; et cependant ce qui dans ma chair était une épreuve pour vous,'),
('ga',4,14,'crampon1923','vous ne l''avez ni méprisé ni repoussé; mais vous m''avez reçu comme un ange de Dieu, comme le Christ Jésus.'),
('ga',4,15,'crampon1923','Que sont devenus ces heureux sentiments? Car je vous rends ce témoignage que, s''il eût été possible, vous vous seriez arraché les yeux pour me les donner.'),
('ga',4,16,'crampon1923','Je serais donc devenu votre ennemi, parce que je vous ai dit la vérité?'),
('ga',4,17,'crampon1923','L''affection dont ces gens font étalage pour vous, n''est pas bonne, ils veulent vous détacher de nous, afin que vous vous attachiez à eux.'),
('ga',4,18,'crampon1923','Il est beau d''être l''objet d''une vive affection, quand c''est dans le bien, toujours, et non pas seulement quand je suis présent parmi vous.'),
('ga',4,19,'crampon1923','Mes petits enfants, pour qui j''éprouve de nouveau les douleurs de l''enfantement, jusqu''à ce que le Christ soit formé en vous;'),
('ga',4,20,'crampon1923','combien je voudrais être auprès de vous à cette heure et changer de langage, car je suis dans une grande perplexité à votre sujet!'),
('ga',4,21,'crampon1923','Dites-moi, vous qui voulez être sous la Loi, n''entendez-vous pas la Loi?'),
('ga',4,22,'crampon1923','Car il est écrit qu''Abraham eut deux fils, l''un de la servante, l''autre de la femme libre.'),
('ga',4,23,'crampon1923','Mais le fils de la servante naquit selon la chair, et celui de la femme libre en vertu de la promesse.'),
('ga',4,24,'crampon1923','Ces choses ont un sens allégorique; car ces femmes sont deux alliances. L''une, du mont Sinaï, enfantant pour la servitude: c''est Agar,'),
('ga',4,25,'crampon1923','— car Sinaï est une montagne en Arabie — elle correspond à la Jérusalem actuelle, laquelle est esclave, elle et ses enfants.'),
('ga',4,26,'crampon1923','Mais la Jérusalem d''en haut est libre: c''est elle qui est notre mère;'),
('ga',4,27,'crampon1923','car il est écrit: " Réjouis-toi, stérile, toi qui n''enfantais point! Eclate en cris de joie et d''allégresse, toi qui ne connaissais pas les douleurs de l''enfantement! Car les enfants de la délaissée seront plus nombreux que les enfants de celle qui avait l''époux. "'),
('ga',4,28,'crampon1923','Pour vous, frères, vous êtes, à la manière d''Isaac, enfants de la promesse.'),
('ga',4,29,'crampon1923','Mais de même qu''alors celui qui était né selon la chair persécutait celui qui était né selon l''Esprit, ainsi en est-il encore maintenant.'),
('ga',4,30,'crampon1923','Mais que dit l''Ecriture? " Chasse l''esclave et son fils, car le fils de l''esclave ne saurait hériter avec le fils de la femme libre. "'),
('ga',4,31,'crampon1923','C''est pourquoi, frères, nous ne sommes pas enfants de la servante, mais de la femme libre.'),
('ga',5,1,'crampon1923','Dans la liberté par laquelle le Christ nous a affranchis, tenez ferme, et ne vous laissez pas mettre de nouveau sous le joug de la servitude.'),
('ga',5,2,'crampon1923','C''est moi, Paul, qui vous le dis: Si vous vous faites circoncire, le Christ ne vous servira de rien.'),
('ga',5,3,'crampon1923','Au contraire, je déclare encore une fois à tout homme qui se fait circoncire, qu''il est tenu d''accomplir la Loi tout entière.'),
('ga',5,4,'crampon1923','Vous n''avez plus rien de commun avec le Christ, vous tous qui cherchez la justification dans la Loi; vous êtes déchus de la grâce.'),
('ga',5,5,'crampon1923','Nous, c''est de la foi, par l''Esprit, que nous attendons l''espérance de la justice.'),
('ga',5,6,'crampon1923','Car dans le Christ Jésus ni circoncision ni incirconcision n''ont de valeur, mais la foi qui est agissante par la charité.'),
('ga',5,7,'crampon1923','Vous couriez si bien: qui vous a arrêtés, pour vous empêcher d''obéir à la vérité?'),
('ga',5,8,'crampon1923','Cette persuasion ne vient pas de celui qui vous appelle.'),
('ga',5,9,'crampon1923','Un peu de levain fait fermenter toute la pâte.'),
('ga',5,10,'crampon1923','J''ai cette confiance en vous dans le Seigneur, que vous ne penserez pas autrement; mais celui qui met le trouble parmi vous, en portera la peine, quel qu''il soit.'),
('ga',5,11,'crampon1923','Pour moi, mes frères, s''il est vrai que je prêche encore la circoncision, pourquoi suis-je encore persécuté? Le scandale de la croix a donc été levé!'),
('ga',5,12,'crampon1923','Ah! qu''ils se fassent plutôt mutiler complètement ceux qui vous troublent!'),
('ga',5,13,'crampon1923','Pour vous, mes frères, vous avez été appelés à la liberté; seulement ne faites pas de cette liberté un prétexte pour vivre selon la chair; mais, rendez-vous, par la charité, serviteurs les uns des autres.'),
('ga',5,14,'crampon1923','Car toute la Loi est contenue dans un seul mot: " Tu aimeras ton prochain comme toi-même. "'),
('ga',5,15,'crampon1923','Mais si vous vous mordez et vous dévorez les uns les autres, prenez garde que vous ne soyez détruits les uns par les autres.'),
('ga',5,16,'crampon1923','Je dis donc: " Marchez selon l''esprit; et vous n''accomplirez pas les convoitises de la chair.'),
('ga',5,17,'crampon1923','Car la chair a des désirs contraires à ceux de l''esprit, et l''esprit en a de contraires à ceux de la chair; ils sont opposés l''un à l''autre, de telle sorte que vous ne faites pas ce que vous voulez.'),
('ga',5,18,'crampon1923','Mais si vous êtes conduits par l''esprit, vous n''êtes plus sous la Loi.'),
('ga',5,19,'crampon1923','Or les œuvres de la chair sont manifestes: ce sont l''impudicité, l''impureté, le libertinage,'),
('ga',5,20,'crampon1923','l''idolâtrie, les maléfices, les inimitiés, les contentions, les jalousies, les emportements, les disputes, les dissensions, les sectes,'),
('ga',5,21,'crampon1923','l''envie, [les meurtres], l''ivrognerie, les excès de table, et autres choses semblables. Je vous préviens, comme je l''ai déjà fait, que ceux qui commettent de telles choses n''hériteront pas du royaume de Dieu.'),
('ga',5,22,'crampon1923','Le fruit de l''Esprit, au contraire, c''est la charité, la joie, la paix, la patience, la mansuétude, la bonté, la fidélité,'),
('ga',5,23,'crampon1923','la douceur, la tempérance. Contre de pareils fruits, il n''y a pas de loi.'),
('ga',5,24,'crampon1923','Ceux qui sont à Jésus-Christ ont crucifié la chair avec ses passions et ses convoitises.'),
('ga',5,25,'crampon1923','Si nous vivons par l''esprit, marchons aussi par l''esprit.'),
('ga',5,26,'crampon1923','Ne cherchons pas une vaine gloire en nous provoquant les uns les autres, en nous portant mutuellement envie.'),
('ga',6,1,'crampon1923','Frères, lors même qu''un homme se serait laissé surprendre à quelque faute, vous qui êtes spirituels, redressez-le avec un esprit de douceur, prenant garde à vous-mêmes, de peur que vous ne tombiez aussi en tentation.'),
('ga',6,2,'crampon1923','Portez les fardeaux les uns des autres, et vous accomplirez ainsi la parole du Christ;'),
('ga',6,3,'crampon1923','car si quelqu''un croit être quelque chose, alors qu''il n''est rien, il s''abuse lui-même.'),
('ga',6,4,'crampon1923','Que chacun examine ses propres œuvres, et alors il aura sujet de se glorifier pour lui seul, et non en se comparant à autrui;'),
('ga',6,5,'crampon1923','car chacun aura son propre fardeau à porter.'),
('ga',6,6,'crampon1923','Que celui à qui on enseigne la parole fasse part de tous ses biens à celui qui l''enseigne.'),
('ga',6,7,'crampon1923','Ne vous y trompez pas: on ne se rit pas de Dieu.'),
('ga',6,8,'crampon1923','Ce qu''on aura semé, on le moissonnera. Celui qui sème dans sa chair moissonnera, de la chair, la corruption; celui qui sème dans l''esprit moissonnera, de l''esprit, la vie éternelle.'),
('ga',6,9,'crampon1923','Ne nous lassons point de faire le bien; car nous moissonnerons en son temps, si nous ne nous relâchons pas.'),
('ga',6,10,'crampon1923','Ainsi donc, pendant que nous en avons le temps, faisons le bien envers tous, et surtout envers les frères dans la foi.'),
('ga',6,11,'crampon1923','Voyez quelles lettres j''ai tracées pour vous de ma propre main!'),
('ga',6,12,'crampon1923','Tous ceux qui veulent gagner les bonnes grâces des hommes, ce sont ceux-là qui vous contraignent à vous faire circoncire, à l''unique fin de n''être pas persécutés pour la croix du Christ.'),
('ga',6,13,'crampon1923','Car ces circoncis, n''observent pas eux-mêmes la Loi; mais ils veulent que vous receviez la circoncision, afin de se glorifier en votre chair. —'),
('ga',6,14,'crampon1923','Pour moi, Dieu me garde de me glorifier, si ce n''est dans la croix de Notre Seigneur Jésus-Christ, par qui le monde est crucifié pour moi, comme je le suis pour le monde!'),
('ga',6,15,'crampon1923','Car [en Jésus-Christ] la circoncision n''est rien, l''incirconcision n''est rien; ce qui est, tout, c''est d''être une nouvelle créature.'),
('ga',6,16,'crampon1923','Paix et miséricorde sur tous ceux qui suivront cette règle, et sur l''Israël de Dieu!'),
('ga',6,17,'crampon1923','Au reste, que personne désormais ne me suscite plus d''embarras; car je porte sur mon corps les stigmates de Jésus.'),
('ga',6,18,'crampon1923','Frères, que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit! Amen!'),
('ep',1,1,'crampon1923','Paul, apôtre de Jésus-Christ par la volonté de Dieu, aux saints qui sont [à Éphèse], et aux fidèles en Jésus-Christ:'),
('ep',1,2,'crampon1923','grâce et paix vous soient données de la part de Dieu, notre Père, et du Seigneur Jésus-Christ.'),
('ep',1,3,'crampon1923','Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, qui nous a bénis dans le Christ de toutes sortes de bénédictions spirituelles dans les cieux!'),
('ep',1,4,'crampon1923','C''est en lui qu''il nous a choisis dès avant la création du monde, pour que nous soyons saints et irrépréhensibles devant lui,'),
('ep',1,5,'crampon1923','nous ayant, dans son amour, prédestinés à être ses fils adoptifs par Jésus-Christ, selon sa libre volonté,'),
('ep',1,6,'crampon1923','en faisant ainsi éclater la gloire de sa grâce, par laquelle il nous a rendus agréables à ses yeux en son [Fils] bien-aimé.'),
('ep',1,7,'crampon1923','C''est en lui que nous avons la rédemption acquise par son sang, la rémission des péchés, selon la richesse de sa grâce,'),
('ep',1,8,'crampon1923','que Dieu a répandue abondamment sur nous en toute sagesse et intelligence,'),
('ep',1,9,'crampon1923','en nous faisant connaître le mystère de sa volonté, selon le libre dessein que s''était proposé sa bonté,'),
('ep',1,10,'crampon1923','pour le réaliser lorsque la plénitude des temps serait accomplie, à savoir, de réunir toutes choses en Jésus-Christ, celles qui sont dans les cieux et celles qui sont sur la terre.'),
('ep',1,11,'crampon1923','C''est aussi en lui que nous avons été élus, ayant été prédestinés suivant la résolution de celui qui opère toutes choses d''après le conseil de sa volonté,'),
('ep',1,12,'crampon1923','pour que nous servions à la louange de sa gloire, nous qui d''avance avons espéré dans le Christ.'),
('ep',1,13,'crampon1923','C''est en lui que vous-mêmes, après avoir entendu la parole de la vérité, L''Evangile de votre salut, c''est en lui, que vous avez cru et que vous avez été marqués du sceau du Saint-Esprit, qui avait été promis,'),
('ep',1,14,'crampon1923','et qui est une arrhe de notre héritage, en attendant la pleine rédemption de ceux que Dieu s''est acquis, à la louange de sa gloire.'),
('ep',1,15,'crampon1923','C''est pourquoi, ayant entendu parler de votre foi dans le Seigneur Jésus et de votre charité pour tous les saints,'),
('ep',1,16,'crampon1923','je ne cesse, moi aussi, de rendre grâces pour vous, et de faire mémoire de vous dans mes prières,'),
('ep',1,17,'crampon1923','afin que le Dieu de Notre-Seigneur Jésus-Christ, le Père de la gloire, vous donne un esprit de sagesse qui vous révèle sa connaissance,'),
('ep',1,18,'crampon1923','et qu''il éclaire les yeux de votre cœur, pour que vous sachiez quelle est l''espérance à laquelle il vous a appelés, quelles sont les richesses de la gloire de son héritage réservé aux saints,'),
('ep',1,19,'crampon1923','et quelle est, envers nous qui croyons, la suréminente grandeur de sa puissance, attestée par l''efficacité de sa force victorieuse.'),
('ep',1,20,'crampon1923','Cette force, il l''a déployée dans le Christ, lorsqu''il l''a ressuscité des morts et l''a fait asseoir à sa droite dans les cieux,'),
('ep',1,21,'crampon1923','au-dessus de toute principauté, de toute autorité, de toute puissance, de toute domination et de tout ce qui se peut nommer, non seulement dans le siècle présent, mais encore dans le siècle à venir.'),
('ep',1,22,'crampon1923','Il a tout mis sous ses pieds et il l''a donné pour chef suprême à l''Eglise,'),
('ep',1,23,'crampon1923','qui est son corps, la plénitude de celui qui remplit tout en tous.'),
('ep',2,1,'crampon1923','Et vous, vous étiez morts par vos offenses et vos péchés,'),
('ep',2,2,'crampon1923','dans lesquels vous marchiez autrefois selon le train de ce monde, selon le prince de la puissance de l''air, de l''esprit qui agit maintenant dans les fils de la désobéissance.'),
('ep',2,3,'crampon1923','Nous tous aussi, nous vivions autrefois comme eux selon les convoitises de notre chair, accomplissant les volontés de la chair et de nos pensées, et nous étions par nature enfants de colère, comme les autres.'),
('ep',2,4,'crampon1923','Mais Dieu, qui est riche en miséricorde, à cause du grand amour dont il nous a aimés,'),
('ep',2,5,'crampon1923','et alors que nous étions morts par nos offenses, nous a rendus vivants avec le Christ (c''est par grâce que vous êtes sauvés);'),
('ep',2,6,'crampon1923','il nous a ressuscités ensemble et nous a fait asseoir ensemble dans les cieux en Jésus-Christ,'),
('ep',2,7,'crampon1923','afin de montrer dans les siècles à venir l''infinie richesse de sa grâce par sa bonté envers nous en Jésus-Christ.'),
('ep',2,8,'crampon1923','Car c''est par la grâce que vous êtes sauvés, par le moyen de la foi; et cela ne vient pas de vous, c''est le don de Dieu;'),
('ep',2,9,'crampon1923','ce n''est point par les œuvres, afin que nul ne se glorifie.'),
('ep',2,10,'crampon1923','Car nous sommes son ouvrage, ayant été créés en Jésus-Christ pour faire de bonnes œuvres, que Dieu a préparées d''avance, afin que nous les pratiquions.'),
('ep',2,11,'crampon1923','C''est pourquoi souvenez-vous qu''autrefois, vous païens dans la chair, traités d''incirconcis par ceux qu''on appelle circoncis, et qui le sont en la chair par la main de l''homme,'),
('ep',2,12,'crampon1923','souvenez-vous que vous étiez en ce temps-là sans Christ, en dehors de la société d''Israël, étrangers aux alliances de la promesse, sans espérance et sans Dieu dans le monde.'),
('ep',2,13,'crampon1923','Mais maintenant, en Jésus-Christ, vous qui étiez jadis éloignés, vous êtes rapprochés par le sang du Christ.'),
('ep',2,14,'crampon1923','Car c''est lui qui est notre paix, lui qui des deux peuples n''en a fait qu''un: il a renversé le mur de séparation, l''inimitié,'),
('ep',2,15,'crampon1923','ayant abrogé par l''immolation de sa chair la loi des ordonnances avec ses rigoureuses prescriptions, afin de fondre en lui-même les deux dans un seul homme nouveau, en faisant la paix,'),
('ep',2,16,'crampon1923','et de les réconcilier, l''un et l''autre unis en un seul corps avec Dieu par la croix, en détruisant par elle l''inimitié.'),
('ep',2,17,'crampon1923','Et il est venu annoncer la paix à vous qui étiez loin, et la paix à ceux qui étaient proches;'),
('ep',2,18,'crampon1923','car par lui nous avons accès les uns et les autres auprès du Père, dans un seul et même Esprit.'),
('ep',2,19,'crampon1923','Ainsi donc vous n''êtes plus des étrangers, ni des hôtes de passage; mais vous êtes concitoyens des saints, et membres de la famille de Dieu,'),
('ep',2,20,'crampon1923','édifiés que vous êtes sur le fondement des apôtres et des prophètes, dont Jésus-Christ lui-même est la pierre angulaire.'),
('ep',2,21,'crampon1923','C''est en lui que tout l''édifice bien ordonné s''élève, pour former un temple saint dans le Seigneur;'),
('ep',2,22,'crampon1923','c''est en lui que, vous aussi, vous êtes édifiés, pour être par l''Esprit-Saint, une demeure où Dieu habite.'),
('ep',3,1,'crampon1923','A cause de cela, moi Paul, le prisonnier du Christ pour vous, païens...'),
('ep',3,2,'crampon1923','puisque vous avez appris la dispensation de la grâce de Dieu qui m''a été donnée pour vous,'),
('ep',3,3,'crampon1923','comment c''est par révélation que j''ai eu connaissance du mystère que je viens d''exposer en peu de mots.'),
('ep',3,4,'crampon1923','Vous pouvez, en les lisant, reconnaître l''intelligence que j''ai du mystère du Christ.'),
('ep',3,5,'crampon1923','Il n''a pas été manifesté aux hommes dans les âges antérieurs, comme il a été révélé de nos jours par l''Esprit aux saints apôtres et prophètes de Jésus-Christ.'),
('ep',3,6,'crampon1923','Ce mystère, c''est que les Gentils sont héritiers avec les Juifs, et membres du même corps et qu''ils participent à la promesse de Dieu en Jésus-Christ par l''Evangile,'),
('ep',3,7,'crampon1923','dont je suis devenu ministre selon le don de la grâce de Dieu qui m''a été accordée par son opération toute-puissante.'),
('ep',3,8,'crampon1923','C''est à moi, le moindre de tous les saints, qu''a été accordée cette grâce d''annoncer parmi les Gentils la richesse incompréhensible du Christ,'),
('ep',3,9,'crampon1923','et de mettre en lumière, aux yeux de tous, l''économie du mystère qui avait été caché depuis le commencement en Dieu, le Créateur de toutes choses,'),
('ep',3,10,'crampon1923','afin que les principautés et les puissances dans les cieux connaissent aujourd''hui, à la vue de l''Eglise, la sagesse infiniment variée de Dieu,'),
('ep',3,11,'crampon1923','selon le dessein éternel qu''il a réalisé par Jésus-Christ Notre-Seigneur,'),
('ep',3,12,'crampon1923','en qui nous avons, par la foi en lui, la hardiesse de nous approcher de Dieu avec confiance.'),
('ep',3,13,'crampon1923','C''est pourquoi je vous prie de ne pas vous laisser décourager à cause des afflictions que j''endure pour vous: elles sont votre gloire.'),
('ep',3,14,'crampon1923','A cause de cela, je fléchis le genou devant le Père,'),
('ep',3,15,'crampon1923','de qui tire son nom toute famille dans les cieux et sur le terre,'),
('ep',3,16,'crampon1923','afin qu''il vous donne, selon les trésors de sa gloire, d''être puissamment fortifiés par son Esprit en vue de l''homme intérieur,'),
('ep',3,17,'crampon1923','et que le Christ habite dans vos cœurs par la foi, de sorte que, étant enracinés et fondés dans la charité,'),
('ep',3,18,'crampon1923','vous deveniez capables de comprendre avec tous les saints quelle est la largeur et la longueur, la profondeur et la hauteur,'),
('ep',3,19,'crampon1923','même de connaître l''amour du Christ, qui surpasse toute connaissance, en sorte que vous soyez remplis de toute la plénitude de Dieu.'),
('ep',3,20,'crampon1923','A celui qui peut faire, par la puissance qui agit en nous, infiniment au delà de ce que nous demandons et concevons,'),
('ep',3,21,'crampon1923','à Lui soit la gloire dans l''Eglise et en Jésus-Christ, dans tous les âges, aux siècles des siècles! Amen!'),
('ep',4,1,'crampon1923','Je vous prie donc instamment, moi qui suis prisonnier dans le Seigneur, d''avoir une conduite digne de la vocation à laquelle vous avez été appelés,'),
('ep',4,2,'crampon1923','en toute humilité et douceur, avec patience, vous supportant mutuellement avec charité,'),
('ep',4,3,'crampon1923','vous efforçant de conserver l''unité de l''esprit par le lien de la paix.'),
('ep',4,4,'crampon1923','Il n''y a qu''un seul corps et un seul Esprit, comme aussi vous avez été appelés par votre vocation à une même espérance.'),
('ep',4,5,'crampon1923','Il n''y a qu''un Seigneur, une foi, un baptême,'),
('ep',4,6,'crampon1923','un Dieu, Père de tous, qui est au-dessus de tous, qui agit par tous, qui est en tous.'),
('ep',4,7,'crampon1923','Mais à chacun de nous la grâce a été donnée selon la mesure du don du Christ.'),
('ep',4,8,'crampon1923','C''est pourquoi il est dit: " Il est monté dans les hauteurs, il a emmené des captifs, et il a fait des largesses aux hommes. "'),
('ep',4,9,'crampon1923','Or que signifie: " Il est monté, " sinon qu''il était descendu [d''abord] dans les régions inférieures de la terre?'),
('ep',4,10,'crampon1923','Celui qui est descendu est celui-là même qui est monté au-dessus de tous les cieux, afin de tout remplir.'),
('ep',4,11,'crampon1923','C''est lui aussi qui a fait les uns apôtres, d''autres prophètes, d''autres évangélistes, d''autres pasteurs et docteurs,'),
('ep',4,12,'crampon1923','en vue du perfectionnement des saints, pour l''œuvre du ministère, pour l''édification du corps du Christ,'),
('ep',4,13,'crampon1923','jusqu''à ce que nous soyons tous parvenus à l''unité de la foi et de la connaissance du Fils de Dieu, à l''état d''homme fait, à la mesure de la stature parfaite du Christ,'),
('ep',4,14,'crampon1923','afin que nous ne soyons plus des enfants, flottants et emportés à tout vent de doctrine, par la tromperie des hommes, par leur astuce pour induire en erreur;'),
('ep',4,15,'crampon1923','mais que, confessant la vérité, nous continuions à croître à tous égards dans la charité en union avec celui qui est le chef, le Christ.'),
('ep',4,16,'crampon1923','C''est de lui que tout le corps, coordonné et uni par les liens des membres qui se prêtent un mutuel secours et dont chacun opère selon sa mesure d''activité, grandit et se perfectionne dans la charité.'),
('ep',4,17,'crampon1923','Voici donc ce que je dis et ce que je déclare dans le Seigneur, c''est que vous ne vous conduisiez plus comme les païens, qui suivent la vanité de leurs pensées.'),
('ep',4,18,'crampon1923','Ils ont l''intelligence obscurcie, et sont éloignés de la vie de Dieu, par l''ignorance et l''aveuglement de leur cœur.'),
('ep',4,19,'crampon1923','Ayant perdu tout sens, ils se sont livrés aux désordres, à toute espèce d''impureté, avec une ardeur insatiable.'),
('ep',4,20,'crampon1923','Mais vous, ce n''est pas ainsi que vous avez appris à connaître le Christ,'),
('ep',4,21,'crampon1923','si cependant vous l''avez bien compris, et que vous ayez été instruits, suivant la vérité qui est en Jésus,'),
('ep',4,22,'crampon1923','à vous dépouiller, en ce qui concerne votre vie passée, du vieil homme corrompu par les convoitises trompeuses,'),
('ep',4,23,'crampon1923','à vous renouveler dans votre esprit et dans vos pensées,'),
('ep',4,24,'crampon1923','et à revêtir l''homme nouveau, créé selon Dieu dans une justice et une sainteté véritables.'),
('ep',4,25,'crampon1923','C''est pourquoi, renonçant au mensonge, parlez selon la vérité, chacun dans ses rapports avec son prochain, car nous sommes membres les uns des autres.'),
('ep',4,26,'crampon1923','" Etes-vous en colère, ne péchez point; " que le soleil ne se couche point sur votre irritation.'),
('ep',4,27,'crampon1923','Ne donnez pas non plus accès au diable.'),
('ep',4,28,'crampon1923','Que celui qui dérobait ne dérobe plus; mais plutôt qu''il s''occupe en travaillant de ses mains à quelque honnête ouvrage, afin d''avoir de quoi donner à celui qui est dans le besoin.'),
('ep',4,29,'crampon1923','Qu''il ne sorte de votre bouche aucune parole mauvaise; mais quelque bon discours propre à édifier, selon le besoin, afin qu''il fasse du bien à ceux qui l''entendent.'),
('ep',4,30,'crampon1923','N''attristez pas le Saint-Esprit de Dieu, par lequel vous avez été marqués d''un sceau pour le jour de la rédemption.'),
('ep',4,31,'crampon1923','Que toute aigreur, toute animosité, toute colère, toute clameur, toute médisance soient bannies du milieu de vous, ainsi que toute méchanceté.'),
('ep',4,32,'crampon1923','Soyez bons les uns envers les autres, miséricordieux, vous pardonnant mutuellement, comme Dieu vous a pardonné dans le Christ.'),
('ep',5,1,'crampon1923','Soyez donc des imitateurs de Dieu, comme des enfants bien-aimés;'),
('ep',5,2,'crampon1923','et marchez dans la charité, à l''exemple du Christ, qui nous aimés et s''est livré lui-même à Dieu pour nous comme une oblation et un sacrifice d''agréable odeur.'),
('ep',5,3,'crampon1923','Qu''on n''entende même pas dire qu''il y ait parmi vous de fornication, d''impureté de quelque sorte, de convoitise, ainsi qu''il convient à des saints.'),
('ep',5,4,'crampon1923','Point de paroles déshonnêtes, ni de bouffonneries, ni de plaisanteries grossières, toutes choses qui sont malséantes; mais plutôt des actions de grâces.'),
('ep',5,5,'crampon1923','Car, sachez-le bien, aucun impudique, aucun impur, aucun homme cupide (lequel est un idolâtre), n''a d''héritage dans le royaume du Christ et de Dieu.'),
('ep',5,6,'crampon1923','Que personne ne vous abuse par de vains discours; car c''est à cause de ces vices que la colère de Dieu vient sur les fils de l''incrédulité.'),
('ep',5,7,'crampon1923','N''ayez donc aucune part avec eux.'),
('ep',5,8,'crampon1923','Autrefois vous étiez ténèbres, mais à présent vous êtes lumière dans le Seigneur: marchez comme des enfants de lumière.'),
('ep',5,9,'crampon1923','Car le fruit de la lumière consiste en tout ce qui est bon, juste et vrai.'),
('ep',5,10,'crampon1923','Examinez ce qui est agréable au Seigneur;'),
('ep',5,11,'crampon1923','et ne prenez aucune part aux œuvres stériles des ténèbres, mais plutôt condamnez-les.'),
('ep',5,12,'crampon1923','Car, ce qu''ils font en secret, on a honte même de le dire;'),
('ep',5,13,'crampon1923','mais toutes ces abominations, une fois condamnées, sont rendues manifestes par la lumière; car tout ce qui est mis au jour, est lumière.'),
('ep',5,14,'crampon1923','C''est pourquoi il est dit: " Eveille-toi, toi qui dors; lève-toi d''entre les morts, et le Christ t''illuminera. "'),
('ep',5,15,'crampon1923','Ayez donc soin, [mes frères], de vous conduire avec prudence, non en insensés,'),
('ep',5,16,'crampon1923','mais comme des hommes sages; rachetez le temps, car les jours sont mauvais.'),
('ep',5,17,'crampon1923','C''est pourquoi ne soyez pas inconsidérés, mais comprenez bien quelle est la volonté du Seigneur.'),
('ep',5,18,'crampon1923','Ne vous enivrez pas de vin: c''est la source de la débauche; mais remplissez-vous de l''Esprit-Saint.'),
('ep',5,19,'crampon1923','Entretenez-vous les uns les autres de psaumes, d''hymnes et de cantiques spirituels, chantant et psalmodiant du fond du cœur en l''honneur du Seigneur.'),
('ep',5,20,'crampon1923','Rendez continuellement grâces pour toutes choses à Dieu le Père, au nom de Notre-Seigneur Jésus-Christ.'),
('ep',5,21,'crampon1923','Soyez soumis les uns aux autres dans le crainte du Christ.'),
('ep',5,22,'crampon1923','Que les femmes soient soumises à leurs maris, comme au Seigneur;'),
('ep',5,23,'crampon1923','car le mari est le chef de la femme, comme le Christ est le chef de l''Eglise, son corps, dont il est le Sauveur.'),
('ep',5,24,'crampon1923','Or, de même que l''Eglise est soumise au Christ, les femmes doivent être soumises à leurs maris en toutes choses.'),
('ep',5,25,'crampon1923','Maris, aimez vos femmes, comme le Christ a aimé l''Eglise et s''est livré lui-même pour elle,'),
('ep',5,26,'crampon1923','afin de la sanctifier, après l''avoir purifiée dans l''eau baptismale, avec la parole,'),
('ep',5,27,'crampon1923','pour la faire paraître, devant lui, cette Eglise, glorieuse, sans tache, sans ride, ni rien de semblable, mais sainte et immaculée.'),
('ep',5,28,'crampon1923','C''est ainsi que les maris doivent aimer leurs femmes, comme leurs propres corps. Celui qui aime sa femme s''aime lui-même.'),
('ep',5,29,'crampon1923','Car jamais personne n''a haï sa propre chair; mais il la nourrit et l''entoure de soins, comme fait le Christ pour l''Eglise,'),
('ep',5,30,'crampon1923','parce que nous sommes membres de son corps, [formés " de sa chair et de ses os. "]'),
('ep',5,31,'crampon1923','" C''est pourquoi l''homme quittera son père et sa mère pour s''attacher à sa femme, et de deux ils deviendront une seule chair. "'),
('ep',5,32,'crampon1923','Ce mystère est grand; je veux dire, par rapport au Christ et à l''Eglise.'),
('ep',5,33,'crampon1923','Au reste, que chacun de vous, de la même manière, aime sa femme comme soi-même, et que la femme révère son mari.'),
('ep',6,1,'crampon1923','Enfants, obéissez à vos parents dans le Seigneur, car cela est juste.'),
('ep',6,2,'crampon1923','" Honore ton père et ta mère — c''est le premier commandement, accompagné d''une promesse. —'),
('ep',6,3,'crampon1923','afin que tu sois heureux et que tu vives longtemps sur la terre. "'),
('ep',6,4,'crampon1923','Et vous, pères, n''exaspérez pas vos enfants, mais élevez-les en les corrigeant et en les avertissant selon le Seigneur.'),
('ep',6,5,'crampon1923','Serviteurs, obéissez à vos maîtres selon la chair avec respect et crainte et dans la simplicité de votre cœur, comme au Christ,'),
('ep',6,6,'crampon1923','ne faisant pas seulement le service sous leurs yeux, comme pour plaire aux hommes, mais en serviteurs du Christ, qui font de bon cœur la volonté de Dieu.'),
('ep',6,7,'crampon1923','Servez-les avec affection, comme servant le Seigneur, et non des hommes,'),
('ep',6,8,'crampon1923','assurés que chacun, soit esclave, soit libre, sera récompensé par le Seigneur de ce qu''il aura fait de bien.'),
('ep',6,9,'crampon1923','Et vous, maîtres, agissez de même à leur égard et laissez là les menaces, sachant que leur Seigneur et le vôtre est dans les cieux et qu''il ne fait pas acception de personne.'),
('ep',6,10,'crampon1923','Au reste, frères, fortifiez-vous dans le Seigneur et dans sa vertu toute-puissante.'),
('ep',6,11,'crampon1923','Revêtez-vous de l''armure de Dieu, afin de pouvoir résister aux embûches du diable.'),
('ep',6,12,'crampon1923','Car nous n''avons pas à lutter contre la chair et le sang, mais contre les princes, contre les puissances, contre les dominateurs de ce monde de ténèbres, contre les esprits mauvais répandus dans l''air.'),
('ep',6,13,'crampon1923','C''est pourquoi prenez l''armure de Dieu, afin de pouvoir résister au jour mauvais, et après avoir tout surmonté, rester debout.'),
('ep',6,14,'crampon1923','Soyez donc fermes, les reins ceints de la vérité, revêtus de la cuirasse de justice,'),
('ep',6,15,'crampon1923','et les sandales aux pieds, prêts à annoncer l''Evangile de paix.'),
('ep',6,16,'crampon1923','Et surtout, prenez le bouclier de la foi, par lequel vous pourrez éteindre tous les traits enflammés du Malin.'),
('ep',6,17,'crampon1923','Prenez aussi le casque du salut, et le glaive de l''Esprit, qui est la parole de Dieu.'),
('ep',6,18,'crampon1923','Faites en tout temps par l''Esprit toutes sortes de prières et de supplications; et pour cela, veillez avec une persévérance continuelle et priez pour tous les saints,'),
('ep',6,19,'crampon1923','et pour moi, afin qu''il me soit donné d''ouvrir les lèvres et de prêcher avec liberté le mystère de l''Evangile,'),
('ep',6,20,'crampon1923','à l''égard duquel je fais fonction d''ambassadeur dans les chaînes, et afin que j''en parle avec assurance comme il convient.'),
('ep',6,21,'crampon1923','Quant à savoir ce qui me concerne et ce que je fais, Tychique, le bien-aimé frère et fidèle ministre dans le Seigneur, vous fera tout connaître.'),
('ep',6,22,'crampon1923','Je vous l''envoie tout exprès, pour que vous connaissiez notre situation et pour qu''il console vos cœurs.'),
('ep',6,23,'crampon1923','Paix aux frères, charité et foi, de la part de Dieu le Père et du Seigneur Jésus-Christ!'),
('ep',6,24,'crampon1923','Que la grâce soit avec tous ceux qui aiment Notre-Seigneur Jésus-Christ d''un amour incorruptible.'),
('ph',1,1,'crampon1923','Paul et Timothée, serviteurs du Christ Jésus, à tous les saints dans le Christ Jésus qui sont à Philippes, aux évêques et aux diacres:'),
('ph',1,2,'crampon1923','grâce et paix de la part de Dieu notre Père et du Seigneur Jésus-Christ!'),
('ph',1,3,'crampon1923','Je rends grâces à mon Dieu toutes les fois que je me souviens de vous, et dans toutes mes prières pour vous tous,'),
('ph',1,4,'crampon1923','c''est avec joie que je lui adresse ma prière,'),
('ph',1,5,'crampon1923','à cause de votre concours unanime pour le progrès de l''Evangile, depuis le premier jours jusqu''à présent;'),
('ph',1,6,'crampon1923','et j''ai confiance que celui qui a commencé en vous une œuvre excellente, en poursuivra l''achèvement jusqu''au jour du Christ.'),
('ph',1,7,'crampon1923','C''est une justice que je vous dois, de penser ainsi de vous tous, parce que je vous porte dans mon cœur, vous tous qui, soit dans mes liens, soit dans la défense et l''affermissement de l''Evangile, avez part à la même grâce que moi.'),
('ph',1,8,'crampon1923','Car Dieu m''en est témoin, c''est avec tendresse que je vous aime tous dans les entrailles de Jésus-Christ.'),
('ph',1,9,'crampon1923','Et ce que je lui demande, c''est que votre charité abonde de plus en plus en connaissance et en toute intelligence,'),
('ph',1,10,'crampon1923','pour discerner ce qui vaut le mieux, afin que vous soyez purs et irréprochables jusqu''au jour du Christ,'),
('ph',1,11,'crampon1923','remplis des fruits de justice, par Jésus-Christ, pour la gloire et la louange de Dieu.'),
('ph',1,12,'crampon1923','Frères, je désire que vous sachiez que ce qui m''est arrivé a plutôt tourné au progrès de l''Evangile.'),
('ph',1,13,'crampon1923','En effet, pour ceux du prétoire, et pour tous les autres, il est devenu notoire que c''est pour le Christ que je suis dans les chaînes:'),
('ph',1,14,'crampon1923','et la plupart des frères dans le Seigneur, encouragés par mes liens, ont redoublé de hardiesse pour annoncer sans crainte la parole de Dieu.'),
('ph',1,15,'crampon1923','Quelques-uns, il est vrai, prêchent aussi Jésus-Christ par envie et par esprit d''opposition; mais d''autres le font avec des dispositions bienveillantes.'),
('ph',1,16,'crampon1923','Ceux-ci agissent par charité, sachant que je suis établi pour la défense de l''Evangile;'),
('ph',1,17,'crampon1923','tandis que les autres, animés d''un esprit de dispute, annoncent le Christ par des motifs qui ne sont pas purs, avec la pensée de me causer un surcroît d''affliction dans mes liens.'),
('ph',1,18,'crampon1923','Mais quoi? De quelque manière qu''on le fasse, que ce soit avec des arrière-pensées, ou sincèrement, le Christ est annoncé: je m''en réjouis, et je m''en réjouirai encore.'),
('ph',1,19,'crampon1923','Car je sais que cela tournera à mon salut, grâce à vos prières et à l''assistance de l''Esprit de Jésus-Christ:'),
('ph',1,20,'crampon1923','selon l''attente où je suis et l''espérance que j''ai que je ne serai confondu en rien; mais que, maintenant comme toujours, avec la plus entière assurance, le Christ sera glorifié dans mon corps, soit par ma vie, soit par ma mort;'),
('ph',1,21,'crampon1923','car le Christ est ma vie, et la mort m''est un gain.'),
('ph',1,22,'crampon1923','Cependant si en vivant plus longtemps dans la chair je dois tirer du fruit, je ne sais que choisir.'),
('ph',1,23,'crampon1923','Je suis pressé des deux côtés: j''ai le désir de partir et d''être avec le Christ, ce qui est de beaucoup le meilleur;'),
('ph',1,24,'crampon1923','mais il est plus nécessaire que je demeure dans la chair à cause de vous.'),
('ph',1,25,'crampon1923','Et je le sais, j''en ai l''assurance, je demeurerai et je resterai avec vous tous, pour l''avancement et pour la joie de votre foi,'),
('ph',1,26,'crampon1923','afin que, par mon retour auprès de vous, vous ayez en moi un abondant sujet de vous glorifier en Jésus-Christ.'),
('ph',1,27,'crampon1923','Seulement, conduisez-vous d''une manière digne de l''Evangile du Christ, afin que, soit que je vienne et que je vous voie, soit que je demeure absent, j''entende dire de vous que vous tenez ferme dans un seul et même esprit, combattant d''un même cœur pour la foi de l''Evangile,'),
('ph',1,28,'crampon1923','sans vous laisser aucunement intimider par les adversaires: c''est là pour eux un signe de ruine, mais pour vous, de salut, et par la volonté de Dieu.'),
('ph',1,29,'crampon1923','Car c''est une grâce qu''il vous a faite, à vous, à l''égard du Christ, non seulement de croire en lui, mais encore de souffrir pour lui,'),
('ph',1,30,'crampon1923','en soutenant le même combat que vous m''avez vu soutenir, et que, vous le savez, je soutiens encore aujourd''hui.'),
('ph',2,1,'crampon1923','Si donc il est quelque encouragement dans le Christ, s''il est quelque consolation de charité, s''il est quelque communauté d''esprit, s''il est quelque tendresse et quelque compassion,'),
('ph',2,2,'crampon1923','rendez ma joie parfaite: ayez une même pensée, un même amour, une même âme, un même sentiment.'),
('ph',2,3,'crampon1923','Ne faites rien par esprit de rivalité ou par vaine gloire; mais que chacun, en toute humilité, regarde les autres comme au-dessus de soi;'),
('ph',2,4,'crampon1923','chacun ayant égard, non à ses propres intérêts, mais à ceux des autres.'),
('ph',2,5,'crampon1923','Ayez en vous les mêmes sentiments dont était animé le Christ Jésus:'),
('ph',2,6,'crampon1923','bien qu''il fût dans la condition de Dieu, il n''a pas retenu avidement son égalité avec Dieu;'),
('ph',2,7,'crampon1923','mais il s''est anéanti lui-même, en prenant la condition d''esclave, en se rendant semblable aux hommes, et reconnu pour homme par tout ce qui a paru de lui;'),
('ph',2,8,'crampon1923','il s''est abaissé lui-même, se faisant obéissant jusqu''à la mort, et à la mort de la croix.'),
('ph',2,9,'crampon1923','C''est pourquoi aussi Dieu l''a souverainement élevé, et lui a donné le nom qui est au-dessus de tout nom,'),
('ph',2,10,'crampon1923','afin qu''au nom de Jésus tout genou fléchisse dans les cieux, sur la terre et dans les enfers,'),
('ph',2,11,'crampon1923','et que toute langue confesse, à la gloire de Dieu le Père, que Jésus-Christ est Seigneur.'),
('ph',2,12,'crampon1923','Ainsi, mes bien-aimés, comme vous avez toujours été obéissants, travaillez à votre salut avec crainte et tremblement, non seulement comme en ma présence, mais bien plus encore maintenant que je suis absent;'),
('ph',2,13,'crampon1923','car c''est Dieu qui opère en vous le vouloir et le faire, selon son bon plaisir.'),
('ph',2,14,'crampon1923','Agissez en tout sans murmures ni hésitations,'),
('ph',2,15,'crampon1923','afin que vous soyez sans reproche, simples, enfants de Dieu irrépréhensibles au milieu de ce peuple pervers et corrompu, dans le sein duquel vous brillez comme des flambeaux dans le monde,'),
('ph',2,16,'crampon1923','étant en possession de la parole de vie; et ainsi je pourrai me glorifier, au jour du Christ, de n''avoir pas couru en vain, ni travaillé en vain.'),
('ph',2,17,'crampon1923','Et même dût mon sang servir de libation dans le sacrifice et dans le service de votre foi, je m''en réjouis et vous en félicite.'),
('ph',2,18,'crampon1923','Vous aussi réjouissez-vous-en et m''en félicitez.'),
('ph',2,19,'crampon1923','J''espère dans le Seigneur Jésus vous envoyer bientôt Timothée, afin de me sentir moi-même plein de courage en apprenant de vos nouvelles.'),
('ph',2,20,'crampon1923','Car je n''ai personne qui me soit tant uni de sentiments, pour prendre sincèrement à cœur ce qui vous concerne;'),
('ph',2,21,'crampon1923','tous, en effet, ont en vue leurs propres intérêts, et non ceux de Jésus-Christ.'),
('ph',2,22,'crampon1923','Vous savez qu''il est d''une vertu éprouvée, qu''il s''est dévoué avec moi, comme un enfant avec son père, au service de l''Evangile.'),
('ph',2,23,'crampon1923','J''espère donc vous l''envoyer dès que j''apercevrai l''issue de ma situation;'),
('ph',2,24,'crampon1923','et j''espère également du Seigneur que moi-même aussi je pourrai venir bientôt.'),
('ph',2,25,'crampon1923','En attendant j''ai cru nécessaire de vous envoyer Epaphrodite mon frère, le compagnon de mes travaux et de mes combats, qui était venu de votre part pour subvenir à mes besoins.'),
('ph',2,26,'crampon1923','Car il désirait vous revoir tous, et il était fort en peine de ce que vous aviez appris sa maladie.'),
('ph',2,27,'crampon1923','Il a été, en effet, malade à mourir; mais Dieu a eu pitié de lui et non pas seulement de lui, mais aussi de moi, afin que je n''eusse pas tristesse sur tristesse.'),
('ph',2,28,'crampon1923','J''ai donc mis plus d''empressement à vous l''envoyer, afin que la joie vous revînt en le voyant, et que moi-même je fusse moins triste.'),
('ph',2,29,'crampon1923','Recevez-le donc dans le Seigneur, avec une joie entière, et honorez de tels hommes.'),
('ph',2,30,'crampon1923','Car c''est pour l''œuvre du Christ qu''il a été près de la mort, ayant mis sa vie en jeu, afin de vous suppléer dans le service que vous ne pouviez me rendre.'),
('ph',3,1,'crampon1923','Du reste, mes frères, réjouissez-vous dans le Seigneur. — Vous écrire les mêmes choses ne me coûte pas et à vous cela est salutaire.'),
('ph',3,2,'crampon1923','Prenez garde à ces chiens, prenez garde à ces mauvais ouvriers, prenez garde à ces mutilés.'),
('ph',3,3,'crampon1923','Car c''est nous qui sommes les vrais circoncis, nous qui par l''esprit de Dieu lui rendons un culte, qui mettons notre gloire dans le Christ Jésus et ne nous confions point dans la chair.'),
('ph',3,4,'crampon1923','Et pourtant quant à moi, j''aurais sujet de mettre aussi ma confiance dans la chair. Si quelqu''autre croit pouvoir le faire, je le puis bien davantage, moi,'),
('ph',3,5,'crampon1923','un circoncis du huitième jour, de la race d''Israël, de la tribu de Benjamin; Hébreu, fils d''Hébreux; pharisien, pour ce qui est de la Loi;'),
('ph',3,6,'crampon1923','persécuteur de l''Eglise, pour ce qui est du zèle, et quant à la justice de la Loi, irréprochable.'),
('ph',3,7,'crampon1923','Mais ces titres qui étaient pour moi de précieux avantages, je les ai considérés comme un préjudice à cause du Christ.'),
('ph',3,8,'crampon1923','Oui certes, et même je tiens encore tout cela comme un préjudice, eu égard au prix éminent de la connaissance du Christ Jésus mon Seigneur. Pour son amour j''ai voulu tout perdre, regardant toutes choses comme de la balayure, afin de gagner le Christ,'),
('ph',3,9,'crampon1923','et d''être trouvé en lui, non avec ma propre justice, — c''est celle qui vient de la Loi, — mais avec celle qui naît de la foi dans le Christ, la justice qui vient de Dieu par la foi;'),
('ph',3,10,'crampon1923','afin de le connaître, lui et la vertu de sa résurrection, d''être admis à la communion de ses souffrances, en lui devenant conforme dans sa mort,'),
('ph',3,11,'crampon1923','pour parvenir, si je le puis, à la résurrection des morts.'),
('ph',3,12,'crampon1923','Ce n''est pas que j''aie déjà saisi le prix, ou que j''aie déjà atteint la perfection; mais je poursuis ma course pour tâcher de le saisir, puisque j''ai été saisi moi-même par le Christ.'),
('ph',3,13,'crampon1923','Pour moi, frères, je ne pense pas l''avoir saisi, mais je ne fais qu''une chose: oubliant ce qui est derrière moi, et me portant de tout moi-même vers ce qui est en avant,'),
('ph',3,14,'crampon1923','je cours droit au but, pour remporter le prix auquel Dieu m''a appelé d''en haut en Jésus-Christ.'),
('ph',3,15,'crampon1923','Que ce soient là nos sentiments, à nous tous qui sommes arrivés à l''âge d''homme; et si, sur quelque point, vous avez des pensées différentes, Dieu vous éclairera aussi là-dessus.'),
('ph',3,16,'crampon1923','Seulement, du point où nous sommes arrivés, marchons comme nous l''avons déjà fait jusqu''ici.'),
('ph',3,17,'crampon1923','Vous aussi, frères, soyez mes imitateurs, et ayez les yeux sur ceux qui marchent suivant le modèle que vous avez en nous.'),
('ph',3,18,'crampon1923','Car il en est plusieurs qui marchent en ennemis de la croix du Christ: je vous en ai souvent parlé, et j''en parle maintenant encore avec larmes.'),
('ph',3,19,'crampon1923','Leur fin, c''est la perdition, eux qui font leur Dieu de leur ventre, et mettent leur gloire dans ce qui fait leur honte, n''ayant de goût que pour les choses de la terre.'),
('ph',3,20,'crampon1923','Pour nous, notre cité est dans les cieux, d''où nous attendons aussi comme Sauveur le Seigneur Jésus-Christ,'),
('ph',3,21,'crampon1923','qui transformera notre corps si misérable, en le rendant semblable à son corps glorieux, par sa vertu puissante qui lui assujettit toutes choses.'),
('ph',4,1,'crampon1923','C''est pourquoi, mes chers et bien-aimés frères, ma joie et ma couronne, tenez ainsi ferme dans le Seigneur, mes bien-aimés.'),
('ph',4,2,'crampon1923','J''exhorte Evodie et j''invite Syntyché à être en bonne intelligence dans le Seigneur.'),
('ph',4,3,'crampon1923','Et toi aussi, mon fidèle compagnon, je te prie de leur venir en aide, elles qui ont combattu pour l''Evangile avec moi, avec Clément, et mes autres collaborateurs dont les noms sont dans le livre de vie.'),
('ph',4,4,'crampon1923','Réjouissez-vous dans le Seigneur en tout temps; je le répète, réjouissez-vous.'),
('ph',4,5,'crampon1923','Que votre modération soit connue de tous les hommes: le Seigneur est proche.'),
('ph',4,6,'crampon1923','Ne vous inquiétez de rien; mais en toute circonstance faites connaître vos besoins à Dieu par des prières et des supplications, avec des actions de grâce.'),
('ph',4,7,'crampon1923','Et la paix de Dieu, qui surpasse toute intelligence, gardera vos cœurs et vos pensées dans le Christ Jésus.'),
('ph',4,8,'crampon1923','Au reste, frères, que tout ce qui est vrai, tout ce qui est honorable, tout ce qui est juste, tout ce qui est pur, tout ce qui est aimable, tout ce qui est de bonne renommée, s''il est quelque vertu et s''il est quelque louange, que ce soit là l''objet de vos pensées;'),
('ph',4,9,'crampon1923','ce que vous avez appris et reçu, ce que vous m''avez entendu dire et vu faire à moi-même, pratiquez-le, et le Dieu de paix sera avec vous.'),
('ph',4,10,'crampon1923','Je me suis vivement réjoui dans le Seigneur, de ce que j''ai vu refleurir enfin vos sentiments d''autrefois à mon égard; vous les aviez bien, mais l''occasion vous avait manqué.'),
('ph',4,11,'crampon1923','Ce n''est pas à cause de mes besoins que je parle ainsi, car j''ai appris à me suffire avec ce que j''ai.'),
('ph',4,12,'crampon1923','Je sais vivre dans le dénûment, et je sais vivre dans l''abondance. En tout et par tout j''ai appris à être rassasié et à avoir faim, à être dans l''abondance et à être dans la détresse.'),
('ph',4,13,'crampon1923','Je puis tout en celui qui me fortifie.'),
('ph',4,14,'crampon1923','Cependant vous avez bien fait de prendre part à ma détresse.'),
('ph',4,15,'crampon1923','Vous savez aussi, vous, Philippiens, que dans les débuts de ma prédication de l''Evangile, lorsque je quittai la Macédoine, aucune Eglise ne m''ouvrit un compte de Doit et Avoir, excepté vous seuls.'),
('ph',4,16,'crampon1923','Car vous m''avez envoyé à Thessalonique, une première fois, puis une seconde, de quoi subvenir à mes besoins.'),
('ph',4,17,'crampon1923','Ce n''est pas que je recherche les dons; ce que je recherche, c''est le fruit qui va s''augmentant à votre compte.'),
('ph',4,18,'crampon1923','Maintenant j''ai abondamment de tout, et je suis dans l''abondance; je suis comblé, ayant reçu d''Epaphrodite ce qui vient de vous, comme un parfum de bonne odeur, une hostie que Dieu accepte et qui lui est agréable.'),
('ph',4,19,'crampon1923','Et mon Dieu pourvoira à tous vos besoins, selon sa richesse, avec gloire, dans le Christ Jésus.'),
('ph',4,20,'crampon1923','A notre Dieu et Père, soit la gloire aux siècles des siècles! Amen!'),
('ph',4,21,'crampon1923','Saluez en Jésus-Christ tous les saints. Les frères qui sont avec moi vous saluent.'),
('ph',4,22,'crampon1923','Tous les saints vous saluent, et principalement ceux de la maison de César.'),
('ph',4,23,'crampon1923','Que la grâce du Seigneur Jésus-Christ soit avec votre esprit!'),
('col',1,1,'crampon1923','Paul, apôtre de Jésus-Christ par la volonté de Dieu, et son frère Timothée,'),
('col',1,2,'crampon1923','aux saints qui sont à Colosses, nos fidèles frères dans le Christ:'),
('col',1,3,'crampon1923','que la grâce et la paix soient sur vous de la part de Dieu notre Père [et du Seigneur Jésus-Christ]! Nous ne cessons de rendre grâces à Dieu, le Père de notre Seigneur Jésus-Christ, dans nos prières pour vous,'),
('col',1,4,'crampon1923','depuis que nous avons entendu parler de votre foi en Jésus-Christ et de votre charité envers tous les saints,'),
('col',1,5,'crampon1923','en vue de l''espérance qui vous est réservée dans les cieux et dont vous avez eu connaissance par la prédication de la vérité évangélique.'),
('col',1,6,'crampon1923','Elle est parvenue à vous, ainsi qu''au monde entier; elle porte des fruits et gagne du terrain, comme cela a eu lieu parmi vous, depuis le jour où vous l''avez entendue, et où vous avez connu la grâce de Dieu dans la vérité,'),
('col',1,7,'crampon1923','d''après les instructions que vous avez reçues d''Epaphras notre bien-aimé compagnon au service de Dieu, et près de vous le fidèle ministre du Christ;'),
('col',1,8,'crampon1923','c''est lui qui nous a appris votre charité toute spirituelle.'),
('col',1,9,'crampon1923','C''est pourquoi, depuis le jour où nous en avons été informés, nous ne cessons de prier Dieu pour vous, et de demander que vous ayez la pleine connaissance de sa volonté en toute sagesse et intelligence spirituelle,'),
('col',1,10,'crampon1923','pour vous conduire d''une manière digne du Seigneur et lui plaire en toutes choses, produisant du fruit en toutes sortes de bonnes œuvres et faisant des progrès dans la connaissance de Dieu;'),
('col',1,11,'crampon1923','fortifiés à tous égards par sa puissance glorieuse, pour tout supporter avec patience et avec joie; —'),
('col',1,12,'crampon1923','rendant grâces à [Dieu] le Père, qui nous a rendus capables d''avoir part à l''héritage des saints dans la lumière,'),
('col',1,13,'crampon1923','en nous délivrant de la puissance des ténèbres, pour nous transporter dans le royaume de son Fils bien-aimé,'),
('col',1,14,'crampon1923','par le sang duquel nous avons la rédemption, la rémission des péchés.'),
('col',1,15,'crampon1923','Il est l''image du Dieu invisible, né avant toute créature;'),
('col',1,16,'crampon1923','car c''est en lui que toutes choses ont été créées, celles qui sont dans les cieux et celles qui sont sur la terre, les choses visibles et les choses invisibles, Trônes, Dominations, Principautés, Puissances; tout a été créé par lui et pour lui.'),
('col',1,17,'crampon1923','Il est, lui, avant toutes choses, et toutes choses subsistent en lui.'),
('col',1,18,'crampon1923','Il est la tête du corps de l''Eglise, lui qui est le principe, le premier-né d''entre les morts, afin qu''en toutes choses, il tienne, lui, la première place.'),
('col',1,19,'crampon1923','Car Dieu a voulu que toute la plénitude habitât en lui;'),
('col',1,20,'crampon1923','et il a voulu réconcilier par lui toutes choses avec lui-même, celles qui sont sur la terre, et celles qui sont dans les cieux, en faisant la paix par le sang de sa croix.'),
('col',1,21,'crampon1923','Vous aussi, qui étiez autrefois loin de lui et ennemis par vos pensées et par vos œuvres mauvaises,'),
('col',1,22,'crampon1923','il vous a maintenant réconciliés par la mort de son Fils en son corps charnel, pour vous faire paraître devant lui saints, sans tâche et sans reproche,'),
('col',1,23,'crampon1923','si du moins vous demeurez fondés et affermis dans la foi, et inébranlables dans l''espérance donnée par l''Evangile que vous avez entendu, qui a été prêché à toute créature sous le ciel, et dont moi, Paul, j''ai été fait ministre.'),
('col',1,24,'crampon1923','Maintenant je suis plein de joie dans mes souffrances pour vous, et ce qui manque aux souffrances du Christ en ma propre chair, je l''achève pour son corps, qui est l''Eglise.'),
('col',1,25,'crampon1923','J''en ai été fait ministre, en vue de la charge que Dieu m''a donnée auprès de vous, afin d''annoncer pleinement la parole de Dieu,'),
('col',1,26,'crampon1923','le mystère caché aux siècles et aux générations passées, mais manifesté maintenant à ses saints,'),
('col',1,27,'crampon1923','à qui Dieu a voulu faire connaître combien est grande pour les Gentils la gloire de ce mystère qui est le Christ, en qui vous avez l''espérance de la gloire.'),
('col',1,28,'crampon1923','C''est lui que nous annonçons, avertissant tous les hommes, les instruisant en toute sagesse, afin que nous rendions tout homme parfait dans le Christ Jésus.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('col',1,29,'crampon1923','C''est pour cela que je travaille, et que je lutte selon la force qu''il me donne, et qui agit en moi avec puissance.'),
('col',2,1,'crampon1923','Je veux, en effet, que vous sachiez quels combats je soutiens pour vous et pour ceux de Laodicée, et pour tous ceux qui ne m''ont pas vu de leurs yeux,'),
('col',2,2,'crampon1923','afin que leurs cœurs soient réconfortés, et qu''étant étroitement unis dans la charité, ils soient enrichis d''une pleine conviction de l''intelligence, et connaissent le mystère de Dieu, du Christ,'),
('col',2,3,'crampon1923','en qui sont cachés tous les trésors de la sagesse et de la science.'),
('col',2,4,'crampon1923','Je dis cela, afin que personne ne vous trompe par des discours subtils.'),
('col',2,5,'crampon1923','Car, si je suis absent de corps, je suis avec vous en esprit, heureux de voir le bon ordre qui règne parmi vous et la solidité de votre foi dans le Christ.'),
('col',2,6,'crampon1923','Ainsi donc, comme vous avez reçu le Christ Jésus, le Seigneur, marchez en lui,'),
('col',2,7,'crampon1923','enracinés et édifiés en lui, affermis par la foi, telle qu''on vous l''a enseignée et y faisant des progrès, avec actions de grâces.'),
('col',2,8,'crampon1923','Prenez garde que personne ne vous surprenne par la philosophie et par des enseignements trompeurs, selon une tradition toute humaine et les rudiments du monde, et non selon le Christ.'),
('col',2,9,'crampon1923','Car en lui habite corporellement toute la plénitude de la divinité.'),
('col',2,10,'crampon1923','En lui vous avez tout pleinement, lui qui est le chef de toute principauté et de toute puissance.'),
('col',2,11,'crampon1923','En lui vous avez été circoncis d''une circoncision non faite de main d''homme, de la circoncision du Christ, par le dépouillement de ce corps de chair.'),
('col',2,12,'crampon1923','Ensevelis avec lui dans le baptême, vous avez été dans le même baptême ressuscités avec lui par votre foi à l''action de Dieu, qui l''a ressuscité d''entre les morts.'),
('col',2,13,'crampon1923','Vous qui étiez morts par vos péchés et par l''incirconcision de votre chair, il vous a rendus à la vie avec lui, après nous avoir pardonné toutes nos offenses.'),
('col',2,14,'crampon1923','Il a détruit l''acte qui était écrit contre nous et nous était contraire avec ses ordonnances, et il l''a fait disparaître en le clouant à la croix;'),
('col',2,15,'crampon1923','il a dépouillé les principautés et les puissances, et les a livrées hardiment en spectacle, en triomphant d''elles par la croix.'),
('col',2,16,'crampon1923','Que personne donc ne vous condamne sur le manger et le boire, ou au sujet d''une fête, d''une nouvelle lune ou d''un sabbat:'),
('col',2,17,'crampon1923','ce n''est là que l''ombre des choses à venir, mais la réalité se trouve dans le Christ.'),
('col',2,18,'crampon1923','Qu''aucun homme ne vous fasse perdre la palme du combat, par affectation d''humilité et de culte des anges, tandis qu''il s''égare en des choses qu''il n''a pas vues, et qu''il s''enfle d''un vain orgueil par les pensées de la chair,'),
('col',2,19,'crampon1923','sans s''attacher au chef, duquel tout le corps, à l''aide des liens et des jointures, s''entretient et grandit par l''accroissement que Dieu lui donne.'),
('col',2,20,'crampon1923','Si vous êtes morts avec le Christ aux rudiments du monde, pourquoi, comme si vous viviez dans le monde, vous soumettez-vous à ces prescriptions:'),
('col',2,21,'crampon1923','" Ne prends pas! Ne goûte pas! Ne touche pas? "'),
('col',2,22,'crampon1923','— Toutes ces choses vont à la corruption par l''usage même qu''on en fait. — Ces défenses ne sont que des préceptes et des enseignements humains.'),
('col',2,23,'crampon1923','Elles ont quelque apparence de sagesse avec leur culte volontaire, leur humilité, et leur mépris pour le corps, mais elles sont sans valeur réelle, et ne servent qu''à la satisfaction de la chair.'),
('col',3,1,'crampon1923','Si donc vous êtes ressuscités avec le Christ, recherchez les choses d''en haut, où le Christ demeure assis à la droite de Dieu;'),
('col',3,2,'crampon1923','affectionnez-vous aux choses d''en haut, et non à celles de la terre:'),
('col',3,3,'crampon1923','car vous êtes morts, et votre vie est cachée avec le Christ en Dieu.'),
('col',3,4,'crampon1923','Quand le Christ, votre vie, apparaîtra, alors vous apparaîtrez, vous aussi, avec lui dans la gloire.'),
('col',3,5,'crampon1923','Faites donc mourir vos membres, les membres de l''homme terrestre, la fornication, l''impureté, la luxure, toute mauvaise convoitise et la cupidité qui est une idolâtrie:'),
('col',3,6,'crampon1923','toutes choses qui attirent la colère de Dieu sur les fils de l''incrédulité,'),
('col',3,7,'crampon1923','parmi lesquels vous aussi, vous marchiez autrefois, lorsque vous viviez dans ces désordres.'),
('col',3,8,'crampon1923','Mais maintenant, vous aussi, rejetez toutes ces choses, la colère, l''animosité, la méchanceté; que les injures et les paroles déshonnêtes soient bannies de votre bouche.'),
('col',3,9,'crampon1923','N''usez point de mensonge les uns envers les autres, puisque vous avez dépouillé le vieil homme avec ses œuvres,'),
('col',3,10,'crampon1923','et revêtu l''homme nouveau, qui se renouvelle sans cesse selon la science parfaite à l''image de celui qui l''a créé.'),
('col',3,11,'crampon1923','Dans ce renouvellement il n''y a plus ni Grec ou Juif, ni circoncis ou incirconcis, ni barbare ou Scythe, ni esclave ou homme libre; mais le Christ est tout en tous.'),
('col',3,12,'crampon1923','Ainsi donc, comme élus de Dieu, saints et bien-aimés, revêtez-vous d''entrailles de miséricorde, de bonté, d''humilité, de douceur, de patience,'),
('col',3,13,'crampon1923','vous supportant les uns les autres et vous pardonnant réciproquement, si l''un a sujet de se plaindre de l''autre. Comme le Seigneur vous a pardonné, pardonnez-vous aussi.'),
('col',3,14,'crampon1923','Mais surtout revêtez-vous de la charité, qui est le lien de la perfection.'),
('col',3,15,'crampon1923','Et que la paix du Christ, à laquelle vous avez été appelés de manière à former un seul corps, règne dans vos cœurs; soyez reconnaissants.'),
('col',3,16,'crampon1923','Que la parole du Christ demeure en vous avec abondance, de telle sorte que vous vous instruisiez et vous avertissiez les uns les autres en toute sagesse: sous l''inspiration de la grâce, que vos cœurs s''épanchent vers Dieu en chants, par des psaumes, par des hymnes, par des cantiques spirituels.'),
('col',3,17,'crampon1923','Et quoi que ce soit que vous fassiez, en parole ou en œuvre, faites tout au nom du Seigneur Jésus, en rendant par lui des actions de grâces à Dieu le Père.'),
('col',3,18,'crampon1923','Vous femmes, soyez soumises à vos maris, comme il convient dans le Seigneur.'),
('col',3,19,'crampon1923','Vous maris, aimez vos femmes et ne vous aigrissez pas contre elles.'),
('col',3,20,'crampon1923','Vous enfants, obéissez en toutes choses à vos parents, car cela est agréable dans le Seigneur.'),
('col',3,21,'crampon1923','Vous pères, n''irritez pas vos enfants, de peur qu''ils ne se découragent.'),
('col',3,22,'crampon1923','Vous serviteurs, obéissez en tout à vos maîtres selon la chair, non pas à l''œil et pour plaire aux hommes, mais avec simplicité de cœur, dans la crainte du Seigneur.'),
('col',3,23,'crampon1923','Quoi que vous fassiez, faites-le de bon cœur, comme pour le Seigneur, et non pour des hommes,'),
('col',3,24,'crampon1923','sachant que vous recevrez du Seigneur pour récompense l''héritage céleste. Servez le Seigneur Jésus-Christ.'),
('col',3,25,'crampon1923','Car celui qui commet l''injustice recevra selon son injustice, et il n''y a point d''acception de personnes.'),
('col',4,1,'crampon1923','Vous maîtres, rendez à vos serviteurs ce que la justice et l''équité demandent, sachant que vous aussi vous avez un maître dans le ciel.'),
('col',4,2,'crampon1923','Persévérez dans la prière, apportez-y de la vigilance, avec des actions de grâces.'),
('col',4,3,'crampon1923','Priez en même temps pour nous, afin que Dieu nous ouvre une porte pour la parole, et qu''ainsi je puisse annoncer le mystère du Christ, pour lequel je suis aussi dans les chaînes,'),
('col',4,4,'crampon1923','et le faire connaître comme je dois en parler.'),
('col',4,5,'crampon1923','Conduisez-vous avec prudence envers ceux qui sont hors de l''Eglise, sachant profiter des circonstances.'),
('col',4,6,'crampon1923','Que votre parole soit toujours aimable, assaisonnée de sel en sorte que vous sachiez comment il faut répondre à chacun.'),
('col',4,7,'crampon1923','Quant à ce qui me concerne, Tychique, le bien-aimé frère et le fidèle ministre, mon compagnon au service du Seigneur, vous fera tout connaître.'),
('col',4,8,'crampon1923','Je vous l''envoie tout exprès pour vous faire connaître notre situation, et pour qu''il console vos cœurs.'),
('col',4,9,'crampon1923','Il est accompagné d''Onésime, le fidèle et bien-aimé frère qui est des vôtres. Ils vous feront savoir tout ce qui se passe ici.'),
('col',4,10,'crampon1923','Aristarque, mon compagnon de captivité, vous salue, ainsi que Marc, le cousin de Barnabé, au sujet duquel vous avez reçu des ordres. S''il vient chez vous, accueillez-le.'),
('col',4,11,'crampon1923','Jésus aussi, appelé Justus, vous salue. Ce sont des circoncis et les seuls, parmi ceux de la circoncision, qui travaillent avec moi pour le royaume de Dieu; ils ont été pour moi une consolation.'),
('col',4,12,'crampon1923','Epaphras, qui est des vôtres, vous salue; serviteur du Christ, il ne cesse de combattre pour vous dans ses prières, afin que vous persévériez à accomplir exactement et avec pleine conviction tout ce que Dieu veut.'),
('col',4,13,'crampon1923','Car je lui rends le témoignage qu''il se donne bien de la peine pour vous, et pour ceux de Laodicée et d''Hiérapolis.'),
('col',4,14,'crampon1923','Luc, le médecin bien-aimé, vous salue, ainsi que Démas.'),
('col',4,15,'crampon1923','Saluez les frères qui sont à Laodicée, ainsi que Nymphas, et l''Eglise qui se réunit dans sa maison.'),
('col',4,16,'crampon1923','Lorsque cette lettre aura été lue chez vous, faites qu''on la lise aussi dans l''Eglise de Laodicée, et que vous lisiez à votre tour celle qui vous arrivera de Laodicée.'),
('col',4,17,'crampon1923','Dites à Archippe: " Considère le ministère que tu as reçu dans le Seigneur, afin de le bien remplir. "'),
('col',4,18,'crampon1923','LA SALUTATION EST DE MA PROPRE MAIN: MOI, PAUL. SOUVENEZ-VOUS DE MES LIENS. QUE LA GRÂCE SOIT AVEC VOUS! [AMEN!]'),
('1th',1,1,'crampon1923','Paul, Sylvain et Timothée à l''Eglise des Thessaloniciens, réunie en Dieu le Père et en Jésus-Christ le Seigneur:'),
('1th',1,2,'crampon1923','à vous, grâce et paix. Nous rendons à Dieu pour vous tous de continuelles actions de grâces, en faisant mémoire de vous dans nos prières,'),
('1th',1,3,'crampon1923','en rappelant sans cesse devant notre Dieu et Père, les œuvres de votre foi, les sacrifices de votre charité et la constance de votre espérance en Jésus-Christ,'),
('1th',1,4,'crampon1923','sachant, frères bien-aimés de Dieu, comment vous avez été élus;'),
('1th',1,5,'crampon1923','car notre prédication de l''Evangile ne vous a pas été faite en parole seulement, mais elle a été accompagnée de miracles, de l''effusion de l''Esprit-Saint et d''une pleine persuasion; vous savez aussi quels nous avons été parmi vous pour votre salut.'),
('1th',1,6,'crampon1923','Et vous êtes devenus nos imitateurs et ceux du Seigneur, en recevant la parole au milieu de beaucoup de tribulations avec la joie de l''Esprit-Saint,'),
('1th',1,7,'crampon1923','au point de devenir un modèle pour tous ceux qui croient dans la Macédoine et dans l''Achaïe.'),
('1th',1,8,'crampon1923','En effet, de chez vous, la parole du Seigneur a retenti non seulement dans la Macédoine et dans l''Achaïe, mais partout votre foi en Dieu s''est fait si bien connaître que nous n''avons pas besoin d''en rien dire.'),
('1th',1,9,'crampon1923','Car tous en parlant de nous racontent quel accès nous avons eu auprès de vous, et comment vous vous êtes convertis des idoles au Dieu vivant et vrai, pour le servir,'),
('1th',1,10,'crampon1923','et pour attendre des cieux son Fils, qu''il a ressuscité des morts, Jésus, qui nous sauve de la colère à venir.'),
('1th',2,1,'crampon1923','Vous savez vous-mêmes, frères, que notre venue parmi vous n''a pas été sans fruits.'),
('1th',2,2,'crampon1923','Mais après avoir souffert et subi des outrages à Philippes, comme vous le savez, nous vînmes pleins de confiance en notre Dieu, vous prêcher hardiment son Evangile, au milieu de bien des luttes.'),
('1th',2,3,'crampon1923','Car notre prédication n''a pas procédé de l''erreur, ni d''une intention vicieuse, ni de fraude aucune;'),
('1th',2,4,'crampon1923','mais, selon que Dieu nous a jugés dignes de nous confier l''Evangile, ainsi enseignons-nous, non comme pour plaire à des hommes, mais à Dieu, qui sonde nos cœurs.'),
('1th',2,5,'crampon1923','Jamais, en effet, nos discours n''ont été inspirés par la flatterie, comme vous le savez, ni par un motif de cupidité, Dieu en est témoin.'),
('1th',2,6,'crampon1923','La gloire humaine, nous ne l''avons recherchée ni de vous ni de personne;'),
('1th',2,7,'crampon1923','alors que nous aurions pu, comme apôtres du Christ, prétendre à quelque autorité, nous avons été au contraire plein de condescendance au milieu de vous. Comme une nourrice entoure de tendres soins ses enfants,'),
('1th',2,8,'crampon1923','ainsi, dans notre affection pour vous, nous aurions voulu vous donner, non seulement l''Evangile de Dieu, mais notre vie même, tant vous nous étiez devenus chers.'),
('1th',2,9,'crampon1923','Vous vous rappelez, frères, notre labeur et nos fatigues: c''est en travaillant nuit et jour, pour n''être à charge à personne d''entre vous, que nous vous avons prêché l''Evangile de Dieu.'),
('1th',2,10,'crampon1923','Vous êtes témoins, et Dieu aussi, combien sainte, juste et irrépréhensible a été notre conduite envers vous qui croyez;'),
('1th',2,11,'crampon1923','comment, ainsi que vous le savez, nous avons été pour chacun de vous ce qu''un père est pour ses enfants,'),
('1th',2,12,'crampon1923','vous priant, vous exhortant, vous conjurant de marcher d''une manière digne de Dieu, qui vous appelle à son royaume et à sa gloire.'),
('1th',2,13,'crampon1923','C''est pourquoi nous aussi, nous ne cessons de rendre grâces à Dieu, de ce qu''ayant reçu la divine parole que nous avons fait entendre, vous l''avez reçue, non comme parole des hommes, mais, ainsi qu''elle l''est véritablement, comme une parole de Dieu. C''est elle qui déploie sa puissance en vous qui croyez.'),
('1th',2,14,'crampon1923','Car vous, frères, vous êtes devenus les imitateurs des Eglises de Dieu qui se réunissent en Jésus-Christ dans la Judée, puisque vous avez souffert vous aussi de la part de vos compatriotes, ce qu''elles ont eu à souffrir de la part des Juifs, —'),
('1th',2,15,'crampon1923','de ces Juifs qui ont mis à mort le Seigneur Jésus et les prophètes, nous ont persécutés, ne plaisent point à Dieu et sont ennemis du genre humain,'),
('1th',2,16,'crampon1923','nous empêchant de prêcher aux nations pour leur salut: de sorte qu''ils comblent sans cesse la mesure de leurs péchés. Mais la colère de Dieu est tombée sur eux pour y demeurer jusqu''à la fin.'),
('1th',2,17,'crampon1923','Pour nous, frères, un instant tristement séparés de vous, de corps, non de cœur, nous avions grande hâte et un vif désir de vous revoir.'),
('1th',2,18,'crampon1923','Aussi voulions-nous vous aller trouver, en particulier, moi, Paul, une première et une seconde fois; mais Satan nous en a empêchés.'),
('1th',2,19,'crampon1923','Quelle est, en effet, notre espérance, notre joie, notre couronne de gloire? N''est-ce pas vous qui l''êtes, devant notre Seigneur Jésus, pour le jour de son avènement?'),
('1th',2,20,'crampon1923','Oui, c''est vous qui êtes notre gloire et notre joie.'),
('1th',3,1,'crampon1923','Aussi, n''y tenant plus, nous avons préféré rester seul à Athènes,'),
('1th',3,2,'crampon1923','et nous vous avons envoyé Timothée, notre frère et ministre de Dieu dans la prédication de l''Evangile du Christ, pour vous affermir et vous encourager dans votre foi,'),
('1th',3,3,'crampon1923','afin que personne ne fût ébranlé au milieu de ces tribulations qui, vous le savez vous-mêmes, sont notre partage.'),
('1th',3,4,'crampon1923','Déjà, lorsque nous étions auprès de vous, nous vous prédisions que nous serions en butte aux tribulations, ce qui est arrivé comme vous le savez.'),
('1th',3,5,'crampon1923','C''est pour cela que, moi aussi, n''y tenant plus, j''envoyai m''informer de votre foi, dans la crainte que le tentateur vous eût tentés et que notre travail ne devînt inutile.'),
('1th',3,6,'crampon1923','Mais maintenant que Timothée, venant d''arriver ici de chez vous, nous a dit votre foi et votre charité, et le bon souvenir que vous gardez toujours de nous et qui vous porte à désirer nous revoir, (comme nous aussi nous le désirons à votre égard),'),
('1th',3,7,'crampon1923','alors, frères, au milieu de toutes nos angoisses et de nos tribulations, nous avons été consolés en vous, à cause de votre foi.'),
('1th',3,8,'crampon1923','Car maintenant nous vivons, puisque vous demeurez fermes dans le Seigneur.'),
('1th',3,9,'crampon1923','Aussi, quelles actions de grâces pouvons-nous rendre à Dieu pour vous, dans la joie parfaite que nous éprouvons à cause de vous devant notre Dieu!'),
('1th',3,10,'crampon1923','Nuit et jour nous le prions avec une ardeur extrême de nous donner de vous voir, et de compléter ce qui manque encore à votre foi.'),
('1th',3,11,'crampon1923','Puisse Dieu lui-même, notre Père, et notre Seigneur Jésus-(Christ) aplanir notre route vers vous!'),
('1th',3,12,'crampon1923','Et vous, puisse le Seigneur faire croître et abonder votre charité les uns envers les autres et envers tous les hommes, telle qu''est la nôtre envers vous.'),
('1th',3,13,'crampon1923','Qu''il affermisse vos cœurs, qu''il les rende irréprochables en sainteté devant notre Dieu et Père, au jour où notre Seigneur Jésus viendra avec tous ses saints! Amen'),
('1th',4,1,'crampon1923','Au reste, frères, nous vous en prions et supplions par le Seigneur Jésus; vous avez appris de nous comment il faut se conduire pour plaire à Dieu, (et ainsi vous le faites); marchez donc de progrès en progrès.'),
('1th',4,2,'crampon1923','Vous connaissez en effet les préceptes que nous vous avons donnés de la part du Seigneur Jésus.'),
('1th',4,3,'crampon1923','Car ce que Dieu veut, c''est votre sanctification: c''est que vous évitiez l''impudicité,'),
('1th',4,4,'crampon1923','et que chacun de vous sache garder son corps dans la sainteté et l''honnêteté,'),
('1th',4,5,'crampon1923','sans l''abandonner aux emportements de la passion, comme font les païens qui ne connaissent pas Dieu;'),
('1th',4,6,'crampon1923','c''est que personne en cette matière n''use de violence ou de fraude à l''égard de son frère, parce que le Seigneur fait justice de tous ces désordres, comme nous vous l''avons déjà dit et attesté.'),
('1th',4,7,'crampon1923','Car Dieu ne nous a pas appelés à l''impureté, mais à la sainteté.'),
('1th',4,8,'crampon1923','Celui donc qui méprise ces préceptes, ce n''est pas un homme qu''il méprise, mais Dieu, qui a aussi donné son Esprit-Saint pour habiter en vous.'),
('1th',4,9,'crampon1923','Pour ce qui est de la charité fraternelle, il n''est pas besoin de vous en écrire; car vous-mêmes avez appris de Dieu à vous aimer les uns les autres;'),
('1th',4,10,'crampon1923','aussi bien le pratiquez-vous envers tous les frères par toute la Macédoine. Mais nous vous exhortons, frères, à le pratiquer toujours mieux.'),
('1th',4,11,'crampon1923','Appliquez-vous à vivre en repos, à vous occuper de vos propres affaires et à travailler de vos mains, comme nous vous l''avons recommandé,'),
('1th',4,12,'crampon1923','de telle sorte que vous teniez une conduite honnête aux yeux de ceux du dehors, sans avoir besoin de personne.'),
('1th',4,13,'crampon1923','Mais nous ne voulons pas, frères, que vous soyez dans l''ignorance au sujet de ceux qui se sont endormis, afin que vous ne vous affligiez pas, comme les autres hommes qui n''ont pas d''espérance.'),
('1th',4,14,'crampon1923','Car si nous croyons que Jésus est mort et qu''il est ressuscité, croyons aussi que Dieu amènera avec Jésus ceux qui se sont endormis en lui.'),
('1th',4,15,'crampon1923','Voici, en effet, ce que nous vous déclarons d''après la parole du Seigneur: Nous, les vivants, laissés pour l''avènement du Seigneur, nous ne devancerons pas ceux qui se sont endormis.'),
('1th',4,16,'crampon1923','Car, au signal donné, à la voix de l''archange, au son de la trompette divine, le Seigneur lui-même descendra du ciel, et ceux qui sont morts dans le Christ ressusciteront d''abord.'),
('1th',4,17,'crampon1923','Puis nous, qui vivons, qui sommes restés, nous serons emportés avec eux sur les nuées à la rencontre du Seigneur dans les airs, et ainsi nous serons pour toujours avec le Seigneur.'),
('1th',4,18,'crampon1923','Consolez-vous donc les uns les autres par ces paroles.'),
('1th',5,1,'crampon1923','Quant aux temps et aux moments il n''est pas besoin, frères, de vous en écrire.'),
('1th',5,2,'crampon1923','Car vous savez très bien vous-mêmes que le jour du Seigneur vient ainsi qu''un voleur pendant la nuit.'),
('1th',5,3,'crampon1923','Quand les hommes diront: " Paix et sûreté! " c''est alors qu''une ruine soudaine fondra sur eux comme la douleur sur la femme qui doit enfanter, et ils n''y échapperont point.'),
('1th',5,4,'crampon1923','Mais vous, frères, vous n''êtes pas dans les ténèbres, pour que ce jour vous surprenne comme un voleur.'),
('1th',5,5,'crampon1923','Oui, vous êtes tous enfants de lumière et enfants du jour; nous ne sommes pas de la nuit, ni des ténèbres.'),
('1th',5,6,'crampon1923','Ne dormons donc point comme le reste des hommes; mais veillons et soyons sobres.'),
('1th',5,7,'crampon1923','Car ceux qui dorment, dorment la nuit, et ceux qui s''enivrent, s''enivrent la nuit.'),
('1th',5,8,'crampon1923','Pour nous qui sommes du jour, soyons sobres, prenant pour cuirasse la foi et la charité, et pour casque l''espérance du salut.'),
('1th',5,9,'crampon1923','Dieu en effet ne nous a pas destinés à la colère, mais à l''acquisition du salut par notre Seigneur Jésus-Christ,'),
('1th',5,10,'crampon1923','qui est mort pour nous, afin que, soit que nous veillions, soit que nous dormions, nous vivions avec lui.'),
('1th',5,11,'crampon1923','C''est pourquoi consolez-vous mutuellement et édifiez-vous les uns les autres, comme déjà vous le faites.'),
('1th',5,12,'crampon1923','Nous vous prions aussi, frères, d''avoir de la considération pour ceux qui travaillent parmi vous, qui vous gouvernent dans le Seigneur et qui vous donnent des avis.'),
('1th',5,13,'crampon1923','Ayez pour eux une charité plus abondante, à cause de leur œuvre. Vivez en paix entre vous.'),
('1th',5,14,'crampon1923','Nous vous en prions, frères, reprenez ceux qui troublent l''ordre, consolez les pusillanimes, soutenez les faibles, usez de patience envers tous.'),
('1th',5,15,'crampon1923','Prenez garde à ce que nul ne rende à un autre le mal pour le mal; mais toujours cherchez ce qui est bien, les uns pour les autres et pour tous.'),
('1th',5,16,'crampon1923','Soyez toujours joyeux.'),
('1th',5,17,'crampon1923','Priez sans cesse.'),
('1th',5,18,'crampon1923','En toutes choses rendez grâces: car c''est la volonté de Dieu dans le Christ Jésus à l''égard de vous tous.'),
('1th',5,19,'crampon1923','N''éteignez pas l''Esprit.'),
('1th',5,20,'crampon1923','Ne méprisez pas les prophéties;'),
('1th',5,21,'crampon1923','mais éprouvez tout, et retenez ce qui est bon;'),
('1th',5,22,'crampon1923','abstenez-vous de toute apparence de mal.'),
('1th',5,23,'crampon1923','Que le Dieu de paix lui-même vous sanctifie tout entiers, et que tout ce qui est en vous, l''esprit, l''âme et le corps, se conserve sans reproche jusqu''au jour de l''avènement de notre Seigneur Jésus-Christ!'),
('1th',5,24,'crampon1923','Celui qui vous appelle est fidèle, et c''est lui qui fera encore cela.'),
('1th',5,25,'crampon1923','Frères, priez pour nous.'),
('1th',5,26,'crampon1923','Saluez tous les frères par un saint baiser.'),
('1th',5,27,'crampon1923','Je vous en conjure par le Seigneur, que cette lettre soit lue à tous les [saints] frères.'),
('1th',5,28,'crampon1923','Que la grâce de notre Seigneur Jésus-Christ soit avec vous!'),
('2th',1,1,'crampon1923','Paul, Sylvain et Timothée, à l''Eglise des Thessaloniciens réunie en Dieu notre Père et en Jésus-Christ le Seigneur:'),
('2th',1,2,'crampon1923','à vous grâce et paix de la part de Dieu notre Père et du Seigneur Jésus-Christ!'),
('2th',1,3,'crampon1923','Nous devons rendre à Dieu de continuelles actions de grâces pour vous, frères, ainsi qu''il est juste, parce que votre foi fait de grands progrès, et que votre charité les uns pour les autres s''accroît de plus en plus.'),
('2th',1,4,'crampon1923','Aussi nous-mêmes dans les Eglises de Dieu tirons-nous gloire de vous, à cause de votre constance et de votre fidélité au milieu de toutes les persécutions et de toutes les tribulations que vous avez à supporter.'),
('2th',1,5,'crampon1923','Elles sont une preuve du juste jugement de Dieu, que vous serez jugés dignes du royaume de Dieu, pour lequel vous souffrez.'),
('2th',1,6,'crampon1923','N''est-il pas juste en effet devant Dieu de rendre l''affliction à ceux qui vous affligent,'),
('2th',1,7,'crampon1923','et de vous donner, à vous qui êtes affligés, le repos avec nous, au jour où le Seigneur Jésus apparaîtra du ciel avec les messagers de sa puissance,'),
('2th',1,8,'crampon1923','au milieu d''une flamme de feu, pour faire justice de ceux qui ne connaissent pas Dieu et de ceux qui n''obéissent pas à l''Evangile de notre Seigneur Jésus.'),
('2th',1,9,'crampon1923','Ils subiront la peine d''une perdition éternelle, loin de la face du Seigneur et de l''éclat de sa puissance,'),
('2th',1,10,'crampon1923','au jour où il viendra pour être glorifié dans ses saints et reconnu admirable en tous ceux qui auront cru. — Pour vous, vous avez cru au témoignage que nous avons rendu devant vous.'),
('2th',1,11,'crampon1923','Dans cette attente, nous prions constamment pour vous, afin que Dieu vous rende dignes de sa vocation et qu''il réalise efficacement toute bonne volonté de faire le bien et l''exercice de votre foi,'),
('2th',1,12,'crampon1923','en sorte que le nom de notre Seigneur Jésus soit glorifié en vous, et vous en lui, par la grâce de notre Dieu et du Seigneur Jésus-Christ.'),
('2th',2,1,'crampon1923','En ce qui concerne l''avènement de notre Seigneur Jésus-Christ et notre réunion avec lui, nous vous prions, frères,'),
('2th',2,2,'crampon1923','de ne pas vous laisser ébranler facilement dans vos sentiments, ni alarmer, soit par quelque esprit, soit par quelque parole ou lettre supposées venir de nous, comme si le jour du Seigneur était imminent.'),
('2th',2,3,'crampon1923','Que personne ne vous égare d''aucune manière; car auparavant viendra l''apostasie, et se manifestera l''homme de péché, le fils de la perdition,'),
('2th',2,4,'crampon1923','l''adversaire qui s''élève contre tout ce qui est appelé Dieu ou honoré d''un culte, jusqu''à s''asseoir dans le sanctuaire de Dieu, et à se présenter comme s''il était Dieu.'),
('2th',2,5,'crampon1923','Ne vous souvenez-vous pas que je vous disais ces choses, lorsque j''étais encore chez vous?'),
('2th',2,6,'crampon1923','Et maintenant vous savez ce qui le retient, pour qu''il se manifeste en son temps.'),
('2th',2,7,'crampon1923','Car le mystère d''iniquité s''opère déjà, mais seulement jusqu''à ce que celui qui le retient encore paraisse au grand jour.'),
('2th',2,8,'crampon1923','Et alors se découvrira l''impie, que le Seigneur (Jésus) exterminera par le souffle de sa bouche, et anéantira par l''éclat de son avènement.'),
('2th',2,9,'crampon1923','Dans son apparition cet impie sera, par la puissance de Satan, accompagné de toutes sortes de miracles, de signes et de prodiges mensongers,'),
('2th',2,10,'crampon1923','avec toutes les séductions de l''iniquité, pour ceux qui se perdent, parce qu''ils n''ont pas ouvert leur cœur à l''amour de la vérité qui les eût sauvés.'),
('2th',2,11,'crampon1923','C''est pourquoi Dieu leur envoie des illusions puissantes qui les feront croire au mensonge,'),
('2th',2,12,'crampon1923','en sorte qu''ils tombent sous son jugement tous ceux qui ont refusé leur foi à la vérité, et ont au contraire pris plaisir à l''injustice.'),
('2th',2,13,'crampon1923','Pour nous, nous devons rendre à Dieu de continuelles actions de grâces pour vous, frères bien-aimés du Seigneur, de ce que Dieu vous a choisis dès le commencement pour vous sauver par la sanctification de l''Esprit et par la foi en la vérité.'),
('2th',2,14,'crampon1923','C''est à quoi il vous a appelés par notre prédication de l''Evangile, pour vous faire acquérir la gloire de notre Seigneur Jésus-Christ.'),
('2th',2,15,'crampon1923','Ainsi donc, frères, demeurez fermes et gardez les enseignements que vous avez reçus, soit de vive voix, soit par notre lettre.'),
('2th',2,16,'crampon1923','Que notre Seigneur Jésus-Christ lui-même, que Dieu notre Père, qui nous a aimés et nous a donné par sa grâce une consolation éternelle et une bonne espérance,'),
('2th',2,17,'crampon1923','console vos cœurs et vous affermisse en toute bonne œuvre et bonne parole!'),
('2th',3,1,'crampon1923','Au reste, frères, priez pour nous, afin que la parole du Seigneur poursuive sa course et soit en honneur, comme elle l''est chez vous,'),
('2th',3,2,'crampon1923','et afin que nous soyons délivrés des hommes fâcheux et pervers; car la foi n''est pas le partage de tous.'),
('2th',3,3,'crampon1923','Mais le Seigneur est fidèle, il vous affermira et vous préservera du mal.'),
('2th',3,4,'crampon1923','Nous avons en vous cette confiance dans le Seigneur, que vous faites et que vous ferez ce que nous vous prescrivons.'),
('2th',3,5,'crampon1923','Que le Seigneur dirige vos cœurs dans l''amour de Dieu et la patience du Christ!'),
('2th',3,6,'crampon1923','Nous vous enjoignons, frères, au nom de notre Seigneur Jésus-Christ, de vous séparer de tout frère qui vit d''une façon déréglée, et non selon les instructions reçues de nous.'),
('2th',3,7,'crampon1923','Vous savez vous-mêmes ce que vous devez faire pour nous imiter; car nous n''avons rien eu de déréglé parmi vous.'),
('2th',3,8,'crampon1923','Nous n''avons mangé gratuitement le pain de personne; mais nous avons été nuit et jour à l''œuvre, dans la fatigue et la peine, pour n''être à charge à aucun de vous.'),
('2th',3,9,'crampon1923','Ce n''est pas que nous n''en eussions le droit; mais nous voulions vous donner en nous-mêmes un exemple à imiter.'),
('2th',3,10,'crampon1923','Aussi bien, lorsque nous étions chez vous, nous vous déclarions que si quelqu''un ne veut pas travailler, il ne doit pas manger non plus.'),
('2th',3,11,'crampon1923','Cependant nous apprenons qu''il y a parmi vous des gens déréglés, qui ne travaillent pas, mais qui ne s''occupent que de choses vaines.'),
('2th',3,12,'crampon1923','Nous les invitons et nous les exhortons par le Seigneur Jésus-Christ, de travailler paisiblement pour manger un pain qui leur appartienne.'),
('2th',3,13,'crampon1923','Pour vous, frères, ne vous lassez pas de faire le bien.'),
('2th',3,14,'crampon1923','Et si quelqu''un n''obéit pas à l''ordre donnée par cette lettre, notez-le, et, pour le confondre, ne le fréquentez plus.'),
('2th',3,15,'crampon1923','Ne le considérez pourtant pas comme un ennemi, mais avertissez-le comme un frère.'),
('2th',3,16,'crampon1923','Que le Seigneur de la paix vous donne lui-même la paix en tout temps, de toute manière! Que le Seigneur soit avec tous!'),
('2th',3,17,'crampon1923','LA SALUTATION EST DE MA PROPRE MAIN, À MOI PAUL; C''EST LÀ MA SIGNATURE DANS TOUTES LES LETTRES: C''EST AINSI QUE J''ÉCRIS.'),
('2th',3,18,'crampon1923','QUE LA GRÂCE DE NOTRE SEIGNEUR JÉSUS-CHRIST SOIT AVEC VOUS TOUS!'),
('1tm',1,1,'crampon1923','Paul, apôtre de Jésus-Christ, selon l''ordre de Dieu notre Sauveur et du Christ Jésus notre espérance,'),
('1tm',1,2,'crampon1923','à Timothée, mon véritable fils en la foi: grâce, miséricorde et paix de la part de Dieu le Père et du Christ Jésus notre Seigneur!'),
('1tm',1,3,'crampon1923','Je te rappelle l''exhortation que je te fis en partant pour la Macédoine, de rester à Ephèse, afin d''enjoindre à certaines gens de ne pas enseigner d''autres doctrines,'),
('1tm',1,4,'crampon1923','et de ne pas s''attacher à des fables et à des généalogies sans fin, plus propres à exciter des disputes qu''à avancer l''œuvre de Dieu, qui repose sur la foi.'),
('1tm',1,5,'crampon1923','Le but de cette recommandation, c''est une charité venant d''un cœur pur, d''une bonne conscience et d''une foi sincère.'),
('1tm',1,6,'crampon1923','Quelques-uns, ayant perdu de vue ces choses, se sont égarés dans un vain bavardage;'),
('1tm',1,7,'crampon1923','ils ont la prétention d''être des docteurs de la Loi; et ils ne comprennent ni ce qu''ils disent, ni ce qu''ils affirment.'),
('1tm',1,8,'crampon1923','Nous savons que la Loi est bonne, pourvu qu''on en fasse un usage légitime,'),
('1tm',1,9,'crampon1923','et qu''on retienne bien qu''elle n''est pas faite pour le juste, mais pour les méchants et les rebelles, pour les impies et les pécheurs, pour les irréligieux et les profanes, pour ceux qui maltraitent leur père et leur mère, pour les meurtriers,'),
('1tm',1,10,'crampon1923','les impudiques, les infâmes, les voleurs d''hommes, les menteurs, les parjures, et pour quiconque commet tout autre crime contraire à la saine doctrine. —'),
('1tm',1,11,'crampon1923','Ainsi l''enseigne l''Evangile de la gloire du Dieu bienheureux, Evangile qui m''a été confié.'),
('1tm',1,12,'crampon1923','Je rends grâces à celui qui m''a fortifié, au Christ Jésus notre Seigneur, de ce qu''il m''a jugé digne de sa confiance, en m''établissant dans le ministère,'),
('1tm',1,13,'crampon1923','moi qui fus autrefois un blasphémateur, un persécuteur, un insulteur. Mais j''ai obtenu miséricorde, parce que j''agissais par ignorance, n''ayant pas encore la foi;'),
('1tm',1,14,'crampon1923','et la grâce de notre Seigneur a surabondé avec la foi et la charité qui est dans le Christ Jésus.'),
('1tm',1,15,'crampon1923','C''est une parole digne de foi et qui mérite toute créance, que le Christ Jésus est venu dans le monde pour sauver les pécheurs, dont je suis le premier.'),
('1tm',1,16,'crampon1923','Mais j''ai obtenu miséricorde, précisément afin que le Christ Jésus fît voir, en moi le premier, toute sa longanimité, pour que je servisse d''exemple à ceux qui, à l''avenir, croiront en lui pour la vie éternelle.'),
('1tm',1,17,'crampon1923','Au Roi des siècles, immortel, invisible, seul Dieu, honneur et gloire dans les siècles des siècles! Amen!'),
('1tm',1,18,'crampon1923','Voilà la recommandation que je t''adresse, Timothée, mon enfant, suivant les prophéties faites précédemment à ton sujet, afin que d''après elles, tu combattes le bon combat,'),
('1tm',1,19,'crampon1923','en gardant la foi et une bonne conscience. Quelques-uns pour y avoir renoncé, ont fait naufrage dans la foi.'),
('1tm',1,20,'crampon1923','De ce nombre sont Hyménée et Alexandre, que j''ai livrés à Satan, afin de leur apprendre à ne point blasphémer.'),
('1tm',2,1,'crampon1923','Avant tout, j''exhorte donc à faire des prières, des supplications, des intercessions, des actions de grâces pour tous les hommes,'),
('1tm',2,2,'crampon1923','pour les rois et pour ceux qui sont constitués en dignité, afin que nous passions une vie paisible et tranquille, en toute piété et honnêteté.'),
('1tm',2,3,'crampon1923','Cela est bon et agréable aux yeux de Dieu notre Sauveur,'),
('1tm',2,4,'crampon1923','qui veut que tous les hommes soient sauvés et parviennent à la connaissance de la vérité.'),
('1tm',2,5,'crampon1923','Car il y a un seul Dieu; et aussi un seul médiateur entre Dieu et les hommes, le Christ Jésus fait homme,'),
('1tm',2,6,'crampon1923','qui s''est donné lui-même en rançon pour tous: c''est là un fait attesté en son temps,'),
('1tm',2,7,'crampon1923','et c''est pour en témoigner, que j''ai été établi prédicateur et apôtre, — je dis la vérité, je ne mens pas, — docteur des nations dans la foi et la vérité.'),
('1tm',2,8,'crampon1923','Je veux donc que les hommes prient en tout lieu, levant au ciel des mains pures, sans colère ni agitation de pensées;'),
('1tm',2,9,'crampon1923','de même que les femmes soient en vêtements décents, se parant avec pudeur et simplicité, sans tresses, or, perles où habits somptueux;'),
('1tm',2,10,'crampon1923','mais de bonnes œuvres, comme il convient à des femmes qui font profession de servir Dieu.'),
('1tm',2,11,'crampon1923','Que la femme reçoive l''instruction en silence, avec une entière soumission.'),
('1tm',2,12,'crampon1923','Je ne permets pas à la femme d''enseigner, ni de prendre autorité sur l''homme; mais elle doit se tenir dans le silence.'),
('1tm',2,13,'crampon1923','Car Adam a été formé le premier, Eve ensuite;'),
('1tm',2,14,'crampon1923','et ce n''est pas Adam qui a été séduit: c''est la femme qui, séduite, est tombée dans la transgression.'),
('1tm',2,15,'crampon1923','Néanmoins, elle sera sauvée en devenant mère, pourvu qu''elle persévère dans la foi, dans la charité et dans la sainteté, unies à la modestie.'),
('1tm',3,1,'crampon1923','Cette parole est certaine: si quelqu''un aspire à un épiscopat, il désire une fonction excellente.'),
('1tm',3,2,'crampon1923','Il faut donc que l''évêque soit irréprochable, qu''il n''ait eu qu''une seule femme, qu''il soit de sens rassis, circonspect, bien réglé dans son extérieur, hospitalier, capable d''enseigner;'),
('1tm',3,3,'crampon1923','qu''il ne soit ni adonné au vin, ni violent, mais doux, pacifique, désintéressé;'),
('1tm',3,4,'crampon1923','qu''il gouverne bien sa propre maison, et qu''il maintienne ses enfants dans la soumission, avec une parfaite honnêteté.'),
('1tm',3,5,'crampon1923','Car si quelqu''un ne sait pas gouverner sa propre maison, comment aurait-il soin de l''Eglise de Dieu?'),
('1tm',3,6,'crampon1923','Que ce ne soit pas un nouveau converti, de peur que, venant à s''enfler d''orgueil, il ne tombe dans la même condamnation que le diable.'),
('1tm',3,7,'crampon1923','Il faut encore qu''il jouisse de la considération de ceux du dehors, afin de ne pas tomber dans l''opprobre et dans les pièges du diable.'),
('1tm',3,8,'crampon1923','Que les diacres pareillement soient des hommes graves, qu''ils ne soient pas doubles dans leurs paroles, ni adonnés au vin, ni avides d''un gain sordide,'),
('1tm',3,9,'crampon1923','mais qu''ils conservent le mystère de la foi dans une conscience pure.'),
('1tm',3,10,'crampon1923','Qu''ils soient éprouvés d''abord, et qu''ils exercent ensuite leur ministère, s''ils sont trouvés sans reproche.'),
('1tm',3,11,'crampon1923','Les femmes, de même, doivent être honorables, non médisantes, sobres, fidèles en toutes choses.'),
('1tm',3,12,'crampon1923','Que les diacres soient maris d''une seule femme; qu''ils gouvernent bien leurs enfants et leur propre maison.'),
('1tm',3,13,'crampon1923','Car ceux qui remplissent bien leur ministère s''acquièrent un rang honorable et une grande assurance dans la foi en Jésus-Christ.'),
('1tm',3,14,'crampon1923','Je t''écris ces choses, quoique j''espère aller bientôt vers toi,'),
('1tm',3,15,'crampon1923','afin que, si je tarde, tu saches comment il faut te conduire dans la maison de Dieu, qui est l''Eglise du Dieu vivant, la colonne et la base de la vérité.'),
('1tm',3,16,'crampon1923','Et sans contredit, c''est un grand mystère de la piété, celui qui a été manifesté en chair, justifié en Esprit, contemplé par les anges, prêché parmi les nations, cru dans le monde, exalté dans la gloire.'),
('1tm',4,1,'crampon1923','Mais l''Esprit dit clairement que dans les temps à venir, certains abandonneront la foi, pour s''attacher à des esprits séducteurs et à des doctrines diaboliques;'),
('1tm',4,2,'crampon1923','enseignées par d''hypocrites imposteurs qui ont la marque de la flétrissure dans leur propre conscience;'),
('1tm',4,3,'crampon1923','qui proscrivent le mariage, et l''usage d''aliments que Dieu a créés afin que les fidèles et ceux qui ont connu la vérité en usent avec actions de grâces.'),
('1tm',4,4,'crampon1923','Car tout ce que Dieu a créé est bon, et l''on ne doit rien rejeter de ce qui se prend avec action de grâces,'),
('1tm',4,5,'crampon1923','parce que tout est sanctifié par la parole de Dieu et par la prière.'),
('1tm',4,6,'crampon1923','En proposant aux frères ces enseignements, tu seras un bon ministre de Jésus-Christ, nourri des leçons de la foi et de la bonne doctrine que tu as fidèlement suivie.'),
('1tm',4,7,'crampon1923','Quant à ces fables profanes, ces contes de vieille femme, rejette-les, et exerce-toi à la piété.'),
('1tm',4,8,'crampon1923','Car l''exercice corporel est utile pour un peu; mais la piété est utile à tout; elle a des promesses pour la vie présente et pour la vie à venir.'),
('1tm',4,9,'crampon1923','C''est là une parole certaine et digne d''être reçue.'),
('1tm',4,10,'crampon1923','Car nous ne prenons tant de peine et nous n''endurons les outrages, que parce que nous avons mis notre espérance dans le Dieu vivant, qui est le Sauveur de tous les hommes, principalement des fidèles.'),
('1tm',4,11,'crampon1923','Voilà ce que tu dois prescrire et enseigner.'),
('1tm',4,12,'crampon1923','Que personne ne te méprise à cause de ta jeunesse; mais sois l''exemple des fidèles, en parole, en conduite, en charité, en foi, en chasteté.'),
('1tm',4,13,'crampon1923','En attendant que je vienne, applique-toi à la lecture, à l''exhortation, à l''enseignement.'),
('1tm',4,14,'crampon1923','Ne néglige pas la grâce qui est en toi, et qui t''a été conférée par action prophétique, lorsque l''assemblée des anciens t''a imposé les mains.'),
('1tm',4,15,'crampon1923','Médite ces choses et sois-y tout entier, afin que tes progrès soient évidents pour tous.'),
('1tm',4,16,'crampon1923','Veille sur toi-même et sur ton enseignement; mets-y une constante application; car, en agissant ainsi, tu te sauveras toi-même, et tu sauveras ceux qui t''écoutent.'),
('1tm',5,1,'crampon1923','Ne reprends pas avec rudesse un vieillard, mais avertis-le comme un père, les jeunes gens, comme des frères,'),
('1tm',5,2,'crampon1923','les femmes âgées comme des mères, celles qui sont jeunes comme des sœurs, avec entière pureté.'),
('1tm',5,3,'crampon1923','Honore les veuves qui sont véritablement veuves.'),
('1tm',5,4,'crampon1923','Si une veuve a des enfants ou des petits-enfants, qu''ils apprennent avant tout à exercer la piété envers leur propre famille, et à rendre à leurs parents ce qu''ils ont reçu d''eux.'),
('1tm',5,5,'crampon1923','Quant à celle qui est véritablement veuve, qui est seule dans le monde, celle-là a mis son espérance en Dieu, et elle persévère nuit et jour dans les supplications et les prières.'),
('1tm',5,6,'crampon1923','Pour celle qui vit dans les plaisirs, elle est morte, quoiqu''elle paraisse vivante.'),
('1tm',5,7,'crampon1923','Fais-leur ces recommandations, afin qu''elles soient sans reproche.'),
('1tm',5,8,'crampon1923','Or, si quelqu''un n''a pas soin des siens, surtout de ceux de sa famille, il a renié la foi, et il est pire qu''un infidèle.'),
('1tm',5,9,'crampon1923','Qu''une veuve, pour être inscrite sur le rôle, n''ait pas moins de soixante ans; qu''elle ait été femme d''un seul mari;'),
('1tm',5,10,'crampon1923','qu''elle ait réputation pour ses bonnes œuvres: d''avoir élevé ses enfants, exercé l''hospitalité, lavé les pieds des saints, secouru les malheureux, entrepris toute sorte de bonnes œuvres.'),
('1tm',5,11,'crampon1923','Quant aux jeunes veuves, écarte-les; car, lorsque l''attrait des voluptés les a dégoûtées du Christ, elles veulent se remarier,'),
('1tm',5,12,'crampon1923','et se rendent coupables, en manquant à leur premier engagement.'),
('1tm',5,13,'crampon1923','De plus, dans l''oisiveté, elles s''accoutument à aller de maison en maison; et non seulement elles sont oisives, mais encore jaseuses, intrigantes, parlant de choses qui ne conviennent point.'),
('1tm',5,14,'crampon1923','Je désire donc que les jeunes veuves se marient, qu''elles aient des enfants, qu''elles gouvernent leur maison, qu''elles ne donnent à l''adversaire aucune occasion de médire;'),
('1tm',5,15,'crampon1923','car il en est déjà qui se sont égarées pour suivre Satan.'),
('1tm',5,16,'crampon1923','Si quelque fidèle, homme ou femme, a des veuves dans sa famille, qu''il pourvoie à leurs besoins, et que l''Eglise n''en soit point surchargée, pour pouvoir assister celles qui sont véritablement veuves.'),
('1tm',5,17,'crampon1923','Les anciens qui gouvernent bien sont dignes d''être doublement rémunérés, principalement ceux qui travaillent à la prédication et à l''enseignement.'),
('1tm',5,18,'crampon1923','Car l''Ecriture dit: " Tu ne muselleras pas le bœuf qui foule le blé. " Et: " L''ouvrier mérite son salaire. "'),
('1tm',5,19,'crampon1923','N''accueille point d''accusation contre un ancien, si ce n''est sur la déposition de deux ou trois témoins.'),
('1tm',5,20,'crampon1923','Ceux qui manquent à leurs devoirs, reprends-les devant tous, afin d''inspirer aux autres de la crainte.'),
('1tm',5,21,'crampon1923','Je te conjure devant Dieu, devant le Christ Jésus, et devant les anges élus, d''observer ces choses sans prévention, et de ne rien faire par faveur.'),
('1tm',5,22,'crampon1923','N''impose trop vite les mains à personne, et n''aie pas de part aux péchés d''autrui; toi-même garde-toi pur.'),
('1tm',5,23,'crampon1923','Ne continue point à ne boire que de l''eau; mais prends un peu de vin, à cause de ton estomac et de tes fréquentes indispositions.'),
('1tm',5,24,'crampon1923','Il y a des personnes dont les péchés sont manifestes, même avant qu''on les juge; mais d''autres ne se découvrent qu''après.'),
('1tm',5,25,'crampon1923','De même les bonnes œuvres sont manifestes, et celles qui ne le sont pas d''abord ne sauraient rester cachées.'),
('1tm',6,1,'crampon1923','Que tous ceux qui sont sous le joug comme esclaves, estiment leurs maîtres dignes de tout honneur, afin que le nom de Dieu et sa doctrine ne soient pas blasphémés.'),
('1tm',6,2,'crampon1923','Et que ceux qui ont pour maîtres des fidèles ne les méprisent pas, parce qu''ils sont leurs frères; mais qu''ils les servent d''autant mieux, puisque ceux qui reçoivent leurs services sont des frères et des amis. 2b C''est ce qu''il faut enseigner et recommander.'),
('1tm',6,3,'crampon1923','Si quelqu''un donne un autre enseignement et n''adhère pas aux salutaires paroles de notre Seigneur Jésus-Christ et à la doctrine qui est conforme à la piété,'),
('1tm',6,4,'crampon1923','c''est un orgueilleux, un ignorant, un esprit malade qui s''occupe de questions et de disputes de mots, d''où naissent l''envie, les querelles, les propos injurieux, les mauvais soupçons,'),
('1tm',6,5,'crampon1923','les discussion sans fin d''hommes qui ont l''esprit perverti, qui privés de la vérité, ne voient dans la piété qu''un moyen de lucre.'),
('1tm',6,6,'crampon1923','C''est, en effet, une grande richesse que la piété contente du nécessaire;'),
('1tm',6,7,'crampon1923','car nous n''avons rien apporté dans le monde, et sans aucun doute nous n''en pouvons rien emporter.'),
('1tm',6,8,'crampon1923','Si donc nous avons de quoi nous nourrir et nous couvrir, nous serons satisfaits.'),
('1tm',6,9,'crampon1923','Ceux qui veulent être riches tombent dans la tentation, dans le piège, et dans une foule de convoitises insensées et funestes, qui plongent les hommes dans la ruine et la perdition.'),
('1tm',6,10,'crampon1923','Car c''est la racine de tous les maux que l''amour de l''argent, et certains, pour s''y être livrés, se sont égarés loin de la foi, et se sont transpercés eux-mêmes de beaucoup de tourments.'),
('1tm',6,11,'crampon1923','Pour toi, homme de Dieu, fuis ces désirs; recherche au contraire la justice, la piété, la foi, la charité, la patience, la douceur.'),
('1tm',6,12,'crampon1923','Combats le bon combat de la foi, conquiers la vie éternelle à laquelle tu as été appelé, et pour laquelle tu as fait cette belle confession de foi devant un grand nombre de témoins.'),
('1tm',6,13,'crampon1923','Je te recommande, devant Dieu qui donne la vie à toutes choses, et devant le Christ Jésus qui a rendu un si beau témoignage sous Ponce-Pilate,'),
('1tm',6,14,'crampon1923','de garder le commandement sans tache et sans reproche, jusqu''à la manifestation de notre Seigneur Jésus-Christ,'),
('1tm',6,15,'crampon1923','que fera paraître en son temps le bienheureux et seul Souverain, le Roi des rois et le Seigneur des seigneurs,'),
('1tm',6,16,'crampon1923','qui seul possède l''immortalité, qui habite une lumière inaccessible, que nul homme n''a vu ni ne peut voir, à qui appartiennent l''honneur et la puissance éternelle! Amen!'),
('1tm',6,17,'crampon1923','Recommande à ceux qui sont riches dans le siècle présent de n''être pas hautains, de ne pas mettre leur espérance dans des richesses incertaines, mais en Dieu, qui nous donne avec abondance tout ce qui est nécessaire à la vie,'),
('1tm',6,18,'crampon1923','de faire du bien, de devenir riches en bonnes œuvres, d''être prompts à donner de ce qu''ils ont, généreusement,'),
('1tm',6,19,'crampon1923','s''amassant ainsi pour l''avenir un solide trésor qui leur permette d''acquérir la vie véritable.'),
('1tm',6,20,'crampon1923','O Timothée, garde le dépôt, en évitant les discours vains et profanes, et tout ce qu''oppose une science qui n''en mérite pas le nom;'),
('1tm',6,21,'crampon1923','quelques-uns, pour en avoir fait profession, ont erré dans la foi. Que la grâce soit avec vous! [Amen!]'),
('2tm',1,1,'crampon1923','Paul, apôtre de Jésus-Christ par la volonté de Dieu, pour annoncer la promesse de la vie qui est dans le Christ Jésus,'),
('2tm',1,2,'crampon1923','à Timothée, mon enfant bien-aimé: grâce, miséricorde, et paix de la part de Dieu le Père et de Jésus-Christ notre Seigneur!'),
('2tm',1,3,'crampon1923','Je rends grâces à Dieu, que je sers ainsi que mes pères, avec une conscience pure, comme aussi je fais continuellement mention de toi dans mes prières, nuit et jour.'),
('2tm',1,4,'crampon1923','Je me rappelle tes larmes, et je désire te voir, afin d''être rempli de joie.'),
('2tm',1,5,'crampon1923','Je me souviens aussi de la foi qui est en toi si sincère; et qui a été constante d''abord dans ton aïeule Loïs et dans ta mère Eunice; et, j''en suis sûr, elle est de même en toi.'),
('2tm',1,6,'crampon1923','C''est pourquoi je t''avertis de ranimer la grâce de Dieu, que tu as reçue par l''imposition de mes mains.'),
('2tm',1,7,'crampon1923','Car ce n''est pas un esprit de timidité que Dieu nous a donné, mais un esprit de force, d''amour et de modération.'),
('2tm',1,8,'crampon1923','Ne rougis donc pas du témoignage à rendre à notre Seigneur, ni de moi, son prisonnier; mais souffre avec moi pour l''Evangile, appuyé sur la force de Dieu,'),
('2tm',1,9,'crampon1923','qui nous a sauvés et nous a appelés par une vocation sainte, non à cause de nos œuvres, mais selon son propre décret et selon la grâce qui nous a été donnée en Jésus-Christ avant le commencement des siècles,'),
('2tm',1,10,'crampon1923','et qui a été manifestée à présent par l''apparition de notre Sauveur Jésus-Christ, qui a détruit la mort et a mis en lumière la vie et l''immortalité par l''Evangile.'),
('2tm',1,11,'crampon1923','C''est pour cela que j''ai été établi prédicateur, apôtre et docteur des Gentils;'),
('2tm',1,12,'crampon1923','c''est aussi pour cette raison que j''endure les souffrances présentes. Mais je n''en ai point honte, car je sais en qui j''ai mis ma confiance, et j''ai la conviction qu''il a le pouvoir de garder mon dépôt jusqu''à ce jour-là.'),
('2tm',1,13,'crampon1923','Conserve le souvenir fidèle des saines instructions que tu as reçues de moi sur la foi et la charité qui est en Jésus-Christ.'),
('2tm',1,14,'crampon1923','Garde le bon dépôt, par le Saint-Esprit qui habite en nous.'),
('2tm',1,15,'crampon1923','Tu sais que tous ceux qui sont en Asie m''ont abandonné, entre autres Phygelle et Hermogène.'),
('2tm',1,16,'crampon1923','Que le Seigneur répande sa miséricorde sur la maison d''Onésiphore; car souvent il m''a réconforté, et il n''a pas rougi de mes fers.'),
('2tm',1,17,'crampon1923','Au contraire, dès son arrivée à Rome, il m''a cherché avec un grand empressement, et m''a trouvé.'),
('2tm',1,18,'crampon1923','Que le Seigneur lui donne d''obtenir miséricorde auprès du Seigneur en ce jour-là! Tu sais mieux que personne tous les services qu''il m''a rendus à Ephèse.'),
('2tm',2,1,'crampon1923','Pour toi donc, mon enfant, affermis-toi dans la grâce qui est dans le Christ Jésus.'),
('2tm',2,2,'crampon1923','Et les enseignements que tu as reçus de moi en présence de nombreux témoins, confie-les à des hommes sûrs, qui soient capables d''en instruire d''autres.'),
('2tm',2,3,'crampon1923','Prends ta part de la peine comme un brave soldat du Christ Jésus.'),
('2tm',2,4,'crampon1923','Dans le métier des armes, nul ne s''embarrasse des affaires de la vie, s''il veut plaire à celui qui l''a enrôlé;'),
('2tm',2,5,'crampon1923','et l''athlète n''obtient la couronne, que s''il a lutté selon les règles.'),
('2tm',2,6,'crampon1923','Il faut que le laboureur travaille d''abord avant de recueillir les fruits.'),
('2tm',2,7,'crampon1923','Réfléchis à ce que je te dis, car le Seigneur te donnera l''intelligence en toutes choses.'),
('2tm',2,8,'crampon1923','Souviens-toi que Jésus-Christ, issu de la race de David, est ressuscité d''entre les morts, d''après l''Evangile que je prêche,'),
('2tm',2,9,'crampon1923','et pour lequel je souffre jusqu''à être enchaîné comme un malfaiteur; mais la parole de Dieu n''est point enchaînée.'),
('2tm',2,10,'crampon1923','C''est pourquoi je supporte tout à cause des élus, afin qu''eux aussi obtiennent le salut qui est dans le Christ Jésus, avec la gloire éternelle.'),
('2tm',2,11,'crampon1923','C''est là une parole certaine: si nous mourons avec lui, nous vivrons aussi avec lui;'),
('2tm',2,12,'crampon1923','si nous persévérons dans l''épreuve, nous régnerons avec lui; si nous le renions, lui aussi nous reniera;'),
('2tm',2,13,'crampon1923','si nous sommes infidèles, lui reste fidèle, car il ne peut se démentir.'),
('2tm',2,14,'crampon1923','Voilà ce que tu dois rappeler, en conjurant devant le Seigneur d''éviter ces disputes de mots qui ne servent à rien, si ce n''est à la ruine de ceux qui les entendent.'),
('2tm',2,15,'crampon1923','Efforce-toi de te montrer dans le service de Dieu comme un homme éprouvé, un ouvrier qui n''a point à rougir, dispensant avec droiture la parole de la vérité.'),
('2tm',2,16,'crampon1923','Fuis les discours profanes et vains; car leurs auteurs iront toujours plus avant dans l''impiété,'),
('2tm',2,17,'crampon1923','et leur parole fera des ravages comme la gangrène. De ce nombre sont Hyménée, et Philète,'),
('2tm',2,18,'crampon1923','qui se sont éloignés de la vérité, en disant que la résurrection a déjà eu lieu, et qui renversent la foi de plusieurs.'),
('2tm',2,19,'crampon1923','Mais le solide fondement de Dieu demeure ferme, avec ce sceau: " Le Seigneur connaît ceux qui sont à lui "; et: " Qu''il s''éloigne de l''iniquité, celui qui prononce le nom du Seigneur. "'),
('2tm',2,20,'crampon1923','Dans une grande maison, il n''y a pas seulement des vases d''or et d''argent, mais il y en a aussi de bois et de terre; les uns pour des usages honorables, les autres pour des usages vils.'),
('2tm',2,21,'crampon1923','Si donc quelqu''un s''est gardé pur de ces choses-là, il sera un vase d''honneur, sanctifié, utile à son maître, propre à toute bonne œuvre.'),
('2tm',2,22,'crampon1923','Fuis les passions de la jeunesse et recherche la justice, la foi, la charité et la paix, avec ceux qui invoquent le Seigneur d''un cœur pur.'),
('2tm',2,23,'crampon1923','Rejette les questions folles et inutiles; tu sais qu''elles engendrent des disputes.'),
('2tm',2,24,'crampon1923','Or il ne faut pas qu''un serviteur du Seigneur conteste; il doit, au contraire, avoir de la condescendance pour tous, savoir instruire et supporter,'),
('2tm',2,25,'crampon1923','redressant avec douceur les opposants, dans l''espoir que Dieu leur donnera de se convertir à la connaissance de la vérité,'),
('2tm',2,26,'crampon1923','et que, revenus au bon sens, ils se dégageront des pièges du diable, qui les tient captifs et les asservit à ses volontés.'),
('2tm',3,1,'crampon1923','Sache que, dans les derniers jours, il viendra des temps difficiles.'),
('2tm',3,2,'crampon1923','Car les hommes seront égoïstes, cupides, fanfarons, superbes, blasphémateurs, rebelles à leurs parents, ingrats, impies,'),
('2tm',3,3,'crampon1923','sans affection, sans loyauté, calomniateurs, intempérants, cruels, ennemis des gens de bien,'),
('2tm',3,4,'crampon1923','traîtres, insolents, enflés d''orgueil, amis des voluptés plus que de Dieu,'),
('2tm',3,5,'crampon1923','ayant les dehors de la piété sans en avoir la réalité: éloigne-toi de cette sorte de gens.'),
('2tm',3,6,'crampon1923','Tels sont ceux qui s''insinuent dans les familles pour captiver des femmelettes chargées de péchés, travaillées de passions de toute espèce,'),
('2tm',3,7,'crampon1923','qui toujours apprennent sans pouvoir jamais parvenir à la connaissance de la vérité.'),
('2tm',3,8,'crampon1923','Pareils à Jannès et à Jambrès qui s''opposèrent à Moïse, de même ces hommes, viciés d''esprit et pervertis dans la foi, s''opposent à la vérité.'),
('2tm',3,9,'crampon1923','Mais ils ne feront plus de progrès; car leur folie éclatera aux yeux de tous, comme celle de ces deux hommes-là.'),
('2tm',3,10,'crampon1923','Pour toi, tu m''as suivi dans ma doctrine, dans ma conduite, dans mes projets, dans ma foi, dans ma longanimité, dans ma charité, dans ma constance,'),
('2tm',3,11,'crampon1923','dans mes persécutions, dans mes souffrances, telles qu''il m''en est survenu à Antioche, à Iconium, à Lystres. Elles sont sans nombre, les persécutions que j''ai endurées, et chaque fois le Seigneur m''en a délivré.'),
('2tm',3,12,'crampon1923','Aussi bien, tous ceux qui veulent vivre avec piété dans le Christ Jésus auront à souffrir persécution.'),
('2tm',3,13,'crampon1923','Quant aux méchants et aux imposteurs, ils iront toujours plus avant dans le mal, égarant les autres et égarés eux-mêmes.'),
('2tm',3,14,'crampon1923','Pour toi, demeure ferme dans ce que tu as appris, et dont tu as la certitude, sachant de qui tu le tiens,'),
('2tm',3,15,'crampon1923','et que, dès ton enfance, tu as connu les saintes lettres, qui peuvent te donner la sagesse qui conduit au salut par la foi en Jésus-Christ.'),
('2tm',3,16,'crampon1923','Toute Ecriture est divinement inspirée, et utile pour enseigner, pour convaincre, pour corriger, pour former à la justice,'),
('2tm',3,17,'crampon1923','afin que l''homme de Dieu soit parfait, apte à toute bonne œuvre.'),
('2tm',4,1,'crampon1923','Je t''adjure devant Dieu et devant le Christ Jésus, qui doit juger les vivants et les morts, et par son apparition et son règne,'),
('2tm',4,2,'crampon1923','prêche la parole, insiste à temps et à contretemps, reprends, menace, exhorte, avec une entière patience et toujours en instruisant.'),
('2tm',4,3,'crampon1923','Car un temps viendra où les hommes ne supporteront plus la saine doctrine; mais ils se donneront une foule de docteurs, suivant leurs convoitises et avides de ce qui peut chatouiller leurs oreilles;'),
('2tm',4,4,'crampon1923','ils les fermeront à la vérité pour les ouvrir à des fables.'),
('2tm',4,5,'crampon1923','Mais toi, sois circonspect en toutes choses, endure la souffrance, fais l''œuvre d''un prédicateur de l''Evangile, sois tout entier à ton ministère.'),
('2tm',4,6,'crampon1923','Car, pour moi, je sers déjà de libation, et le moment de mon départ est proche.'),
('2tm',4,7,'crampon1923','J''ai combattu le bon combat, j''ai achevé ma course, j''ai gardé la foi;'),
('2tm',4,8,'crampon1923','il ne me reste plus qu''à recevoir la couronne de justice, que me donnera en ce jour-là le Seigneur, le juste Juge, et non seulement à moi, mais à tous ceux qui auront aimé son avènement.'),
('2tm',4,9,'crampon1923','Tâche de me rejoindre au plus tôt; car Démas, m''a quitté par amour pour le siècle présent, et il est parti pour Thessalonique;'),
('2tm',4,10,'crampon1923','Crescent est allé en Galatie, Tite en Dalmatie.'),
('2tm',4,11,'crampon1923','Luc seul est avec moi. Prends Marc et amène-le avec toi, car il m''est d''un grand secours pour le ministère.'),
('2tm',4,12,'crampon1923','J''ai envoyé Tychique à Ephèse.'),
('2tm',4,13,'crampon1923','En venant, apporte le manteau que j''ai laissé à Troas chez Carpus, ainsi que les livres, surtout les parchemins.'),
('2tm',4,14,'crampon1923','Alexandre, le fondeur, m''a fait bien du mal: le Seigneur lui rendra selon ses œuvres.'),
('2tm',4,15,'crampon1923','Toi aussi, tiens-toi en garde contre lui, car il a fait une forte opposition à notre prédication.'),
('2tm',4,16,'crampon1923','Personne ne m''a assisté dans ma première défense; tous m''ont abandonné: que cela ne leur soit point imputé!'),
('2tm',4,17,'crampon1923','Cependant, le Seigneur m''a assisté et m''a fortifié afin que la parole fût pleinement annoncée par moi et entendue de toutes les nations; et j''ai été délivré de la gueule du lion.'),
('2tm',4,18,'crampon1923','Le Seigneur me délivrera de toute œuvre mauvaise, et il me sauvera en me faisant entrer dans son royaume céleste. A lui soit la gloire aux siècles des siècles! Amen!'),
('2tm',4,19,'crampon1923','Salue Prisca et Aquila, et la famille d''Onésiphore.'),
('2tm',4,20,'crampon1923','Eraste est resté à Corinthe, et j''ai laissé Trophime malade à Milet.'),
('2tm',4,21,'crampon1923','Hâte-toi de venir avant l''hiver. Eubule te salue, ainsi que Pudens, Linus, Claudia et tous les frères.'),
('2tm',4,22,'crampon1923','Que le Seigneur Jésus-Christ soit avec ton esprit! Que la grâce soit avec vous! Amen!'),
('tt',1,1,'crampon1923','Paul, serviteur de Dieu et apôtre de Jésus-Christ pour prêcher la foi aux élus de Dieu et faire connaître la vérité qui conduit à la piété,'),
('tt',1,2,'crampon1923','et donne l''espérance de la vie éternelle, promise dès les plus anciens temps par le Dieu qui ne ment point,'),
('tt',1,3,'crampon1923','et qui a manifesté sa parole en son temps par la prédication qui m''a été confiée d''après l''ordre de Dieu, notre Sauveur, —'),
('tt',1,4,'crampon1923','à Tite, mon véritable enfant en la foi qui nous est commune, grâce et paix de la part de Dieu le Père et du Christ Jésus notre Sauveur.'),
('tt',1,5,'crampon1923','Je t''ai laissé en Crète afin que tu achèves de tout organiser, et que, selon les instructions que je t''ai données, tu établisses des Anciens dans chaque ville.'),
('tt',1,6,'crampon1923','Que le sujet soit d''une réputation intacte, mari d''une seule femme, dont les enfants soient fidèles, et ne passent point pour être débauchés ou insoumis.'),
('tt',1,7,'crampon1923','Car il faut que l''évêque soit irréprochable, en qualité d''administrateur de la maison de Dieu; qu''il ne soit ni arrogant, ni colère, ni adonné au vin, ni enclin à frapper, ni porté à un gain sordide;'),
('tt',1,8,'crampon1923','mais qu''il soit hospitalier, zélé pour le bien, circonspect, juste, saint, maître de ses passions,'),
('tt',1,9,'crampon1923','fermement attaché à la doctrine, qui lui a été enseignée, afin d''être en état d''exhorter selon la saine doctrine et de réfuter ceux qui la contredisent.'),
('tt',1,10,'crampon1923','Car il y a, surtout parmi les circoncis, bien des gens insubordonnés, vains discoureurs et séducteurs des âmes.'),
('tt',1,11,'crampon1923','Il faut fermer la bouche à ces gens-là qui bouleversent des familles entières, et qui enseignent, pour un vil intérêt, ce qu''on ne doit pas enseigner.'),
('tt',1,12,'crampon1923','Un de leurs compatriotes, un prophète à eux, a dit: " Crétois toujours menteurs, méchantes bêtes, ventres paresseux. "'),
('tt',1,13,'crampon1923','Ce témoignage est vrai. C''est pourquoi reprends-les sévèrement, afin qu''ils aient une foi saine,'),
('tt',1,14,'crampon1923','et qu''ils ne prêtent pas l''oreille à des fables judaïques et aux prescriptions de gens qui se détournent de la vérité.'),
('tt',1,15,'crampon1923','Tout est pur pour ceux qui sont purs; mais pour ceux qui sont souillés et incrédules rien n''est pur; au contraire, leur esprit est souillé, ainsi que leur conscience.'),
('tt',1,16,'crampon1923','Ils font profession de connaître Dieu, et ils le renient par leurs actes, abominables qu''ils sont, rebelles et incapables de toute bonne œuvre.'),
('tt',2,1,'crampon1923','Pour toi, tiens un langage conforme à la saine doctrine.'),
('tt',2,2,'crampon1923','Dis aux vieillards d''être sobres, graves, circonspects, sains dans la foi, dans la charité, dans la patience;'),
('tt',2,3,'crampon1923','pareillement aux femmes âgées de faire paraître une sainte modestie dans leur tenue; de n''être ni médisantes, ni sujettes aux excès du vin; mais sages conseillères,'),
('tt',2,4,'crampon1923','capables d''apprendre aux jeunes femmes à aimer leurs maris et leurs enfants;'),
('tt',2,5,'crampon1923','à être retenues, chastes, occupées aux soins domestiques, bonnes, soumises chacune à son mari, afin que la parole de Dieu ne soit exposée à aucun blâme.'),
('tt',2,6,'crampon1923','Exhorte de même les jeunes gens à être sages,'),
('tt',2,7,'crampon1923','te montrant toi-même à tous égards un modèle de bonnes œuvres, mettant dans ton enseignement de la pureté, de la gravité,'),
('tt',2,8,'crampon1923','une parole saine et irréprochable, afin de confondre nos adversaires qui n''auront aucun mal à dire de nous.'),
('tt',2,9,'crampon1923','Aux esclaves, recommande d''être soumis à leurs maîtres, de leur complaire en toutes choses, de ne pas les contredire,'),
('tt',2,10,'crampon1923','de ne rien détourner, mais de montrer toujours une fidélité parfaite, afin de faire honneur en toutes choses à la doctrine de Dieu, notre Sauveur.'),
('tt',2,11,'crampon1923','Car elle s''est manifestée la grâce de Dieu, source de salut pour tous les hommes;'),
('tt',2,12,'crampon1923','elle nous enseigne à renoncer à l''impiété et aux convoitises mondaines, et à vivre dans le siècle présent avec tempérance, justice et piété,'),
('tt',2,13,'crampon1923','en attendant la bienheureuse espérance et l''apparition glorieuse de notre grand Dieu et Sauveur Jésus-Christ,'),
('tt',2,14,'crampon1923','qui s''est donné lui-même pour nous, afin de nous racheter de toute iniquité et de se faire, en nous purifiant, un peuple qui lui appartienne, et qui soit zélé pour les bonnes œuvres.'),
('tt',2,15,'crampon1923','Voilà ce que tu dois prêcher, recommander et revendiquer avec une pleine autorité. Que personne ne te méprise.'),
('tt',3,1,'crampon1923','Rappelle aux fidèles le devoir d''être soumis aux magistrats et aux autorités, de leur obéir, d''être prêts à toute bonne œuvre,'),
('tt',3,2,'crampon1923','de ne dire du mal de personne, d''éviter les contestations, mais d''être condescendants, et de témoigner la plus grande douceur à l''égard de tous les hommes.'),
('tt',3,3,'crampon1923','Car nous aussi, nous étions autrefois insensés, indociles, égarés, esclaves de toutes sortes de convoitises et de jouissances, vivant dans la malignité et l''envie, dignes de haine, et nous haïssant les uns les autres.'),
('tt',3,4,'crampon1923','Mais lorsque Dieu notre Sauveur a fait paraître sa bonté et son amour pour les hommes,'),
('tt',3,5,'crampon1923','il nous a sauvés, non à cause des œuvres de justice que nous faisions, mais selon sa miséricorde, par le bain de la régénération et en nous renouvelant par le Saint-Esprit,'),
('tt',3,6,'crampon1923','qu''il a répandu sur nous largement par Jésus-Christ notre Sauveur,'),
('tt',3,7,'crampon1923','afin que, justifiés par sa grâce, nous devenions héritiers de la vie éternelle selon notre espérance.'),
('tt',3,8,'crampon1923','C''est là une parole certaine, et je désire que tu affirmes ces choses, afin que ceux qui croient en Dieu s''appliquent à être les premiers dans la pratique des bonnes œuvres. C''est ce qui est bon et utile aux hommes.'),
('tt',3,9,'crampon1923','Quant aux questions folles, aux généalogies, aux querelles, aux disputes relatives à la Loi, évite-les, car elles sont inutiles et vaines.'),
('tt',3,10,'crampon1923','Pour celui qui fomente des divisions, après un premier et un second avertissement, éloigne-le de toi,'),
('tt',3,11,'crampon1923','sachant qu''un tel homme est entièrement perverti, et qu''il est un pécheur condamné de son propre jugement.'),
('tt',3,12,'crampon1923','Lorsque je t''aurai envoyé Artémas ou Tychique, hâte-toi de venir me rejoindre à Nicopolis, car j''ai résolu d''y passer l''hiver.'),
('tt',3,13,'crampon1923','Pourvois avec soin au voyage de Zénas, le docteur de la loi, et d''Apollos, en sorte que rien ne leur manque.'),
('tt',3,14,'crampon1923','De plus que les nôtres aussi apprennent à se porter aux bonnes œuvres, de manière à subvenir aux besoins urgents, afin qu''ils ne soient pas sans fruits.'),
('tt',3,15,'crampon1923','Tous ceux qui sont avec moi te saluent; salue ceux qui nous aiment dans la foi. Que la grâce soit avec vous tous. Amen!'),
('phm',1,1,'crampon1923','Paul, prisonnier du Christ Jésus et Timothée, notre frère, à Philémon notre très cher ami et collaborateur,'),
('phm',1,2,'crampon1923','à Appia, notre sœur, à Archippe, notre compagnon d''armes, et à l''Eglise qui est dans ta maison:'),
('phm',1,3,'crampon1923','à vous grâce et paix de la part de Dieu notre Père et du Seigneur Jésus-Christ!'),
('phm',1,4,'crampon1923','Me souvenant sans cesse de toi dans mes prières je rends grâces à mon Dieu;'),
('phm',1,5,'crampon1923','car j''apprends quelles sont ta charité et ta foi à l''égard du Seigneur Jésus et envers tous les saints.'),
('phm',1,6,'crampon1923','Puisse la générosité inspirée par ta foi devenir efficace et se faire connaître par tout le bien accompli parmi nous en vue du Christ.'),
('phm',1,7,'crampon1923','En effet, ta charité m''a comblé de joie et de consolation, parce que les cœurs des saints ont été ranimés par toi, frère.'),
('phm',1,8,'crampon1923','Voilà pourquoi, bien que j''ai dans le Christ toute liberté de te prescrire ce qu''il convient de faire,'),
('phm',1,9,'crampon1923','j''aime mieux, au nom de cette charité, t''en supplier. Tel que je suis, moi, Paul, vieux, et de plus actuellement prisonnier pour Jésus-Christ,'),
('phm',1,10,'crampon1923','je te supplie donc pour mon fils, que j''ai engendré dans les fers, pour Onésime,'),
('phm',1,11,'crampon1923','qui autrefois ne t''a guère été utile, mais qui maintenant l''est vraiment, et à toi et à moi.'),
('phm',1,12,'crampon1923','Je te le renvoie, lui, mon propre cœur.'),
('phm',1,13,'crampon1923','Je l''aurais volontiers retenu près de moi, afin qu''il me servit à ta place dans les chaînes que je porte pour l''Evangile.'),
('phm',1,14,'crampon1923','Mais je n''ai voulu rien faire sans ton assentiment, pour que ton bienfait ne paraisse pas forcé, mais qu''il vienne de ton plein gré.'),
('phm',1,15,'crampon1923','Peut-être aussi Onésime n''a-t-il été séparé de toi pour un temps, qu''afin que tu le recouvres à jamais,'),
('phm',1,16,'crampon1923','non plus comme un esclave, mais bien mieux qu''un esclave, comme un frère bien-aimé, tout particulièrement aimé de moi, et combien plus de toi, aussi bien selon la chair que selon le Seigneur?'),
('phm',1,17,'crampon1923','Si donc tu me tiens pour étroitement uni à toi, accueille-le comme moi-même.'),
('phm',1,18,'crampon1923','Et s''il t''a fait tort, s''il te doit quelque chose, passe-le à mon compte.'),
('phm',1,19,'crampon1923','C''est moi Paul, qui écris ceci de ma propre main; moi je te le rendrai, pour ne pas te dire que tu es mon débiteur, et même de ta propre personne.'),
('phm',1,20,'crampon1923','Oui, frère, que j''obtienne de toi cette satisfaction dans le Seigneur; réjouis mes entrailles dans le Christ.'),
('phm',1,21,'crampon1923','Je t''écris ceci plein de confiance en ta docilité, sachant que tu feras même au delà de ce que je demande.'),
('phm',1,22,'crampon1923','En même temps, prépare aussi pour moi l''hospitalité; car j''espère vous être rendu, grâce à vos prières.'),
('phm',1,23,'crampon1923','Epaphras, mon compagnon de captivité en Jésus-Christ, te salue,'),
('phm',1,24,'crampon1923','ainsi que Marc, Aristarque, Démas et Luc, mes collaborateurs.'),
('phm',1,25,'crampon1923','Que la grâce de notre Seigneur Jésus-Christ, soit avec votre esprit! Amen!'),
('he',1,1,'crampon1923','Après avoir, à plusieurs reprises et en diverses manières, parlé autrefois à nos pères par les Prophètes,'),
('he',1,2,'crampon1923','Dieu, dans ces derniers temps, nous a parlé par le Fils, qu''il a établi héritier de toutes choses, et par lequel il a aussi créé le monde.'),
('he',1,3,'crampon1923','Ce Fils, qui est le rayonnement de sa gloire, l''empreinte de sa substance, et qui soutient toutes choses par sa puissante parole, après nous avoir purifiés de nos péchés, s''est assis à la droite de la majesté divine au plus haut des cieux,'),
('he',1,4,'crampon1923','d''autant plus grand que les anges, que le nom qu''il possède est plus excellent que le leur.'),
('he',1,5,'crampon1923','Auquel des anges en effet Dieu a-t-il jamais dit: " Tu es mon Fils, aujourd''hui je t''ai engendré? " Et encore: " Je serai pour lui un père, et il sera pour moi un Fils? "'),
('he',1,6,'crampon1923','Et lorsqu''il introduit de nouveau dans le monde le Premier-né, il dit: " Que tous les anges de Dieu l''adorent! "'),
('he',1,7,'crampon1923','De plus, tandis qu''il est dit des anges: " Celui qui fait de ses anges des vents, et de ses serviteurs une flamme de feu ",'),
('he',1,8,'crampon1923','il dit au Fils: " Ton trône, ô Dieu, est éternel; le sceptre de ta royauté est un sceptre de droiture.'),
('he',1,9,'crampon1923','Tu as aimé la justice et haï l''iniquité; c''est pourquoi, ô Dieu, ton Dieu t''a oint d''une huile d''allégresse au-dessus de tous tes compagnons. "'),
('he',1,10,'crampon1923','Et encore: " C''est toi, Seigneur, qui as au commencement fondé la terre, et les cieux sont l''ouvrage de tes mains;'),
('he',1,11,'crampon1923','ils périront, mais tu demeures; ils vieilliront tous comme un vêtement;'),
('he',1,12,'crampon1923','comme un manteau tu les rouleras, et ils seront changés; mais toi, tu restes le même, et tes années ne s''épuiseront point. "'),
('he',1,13,'crampon1923','Et auquel des anges a-t-il jamais dit: " Assieds-toi à ma droite, jusqu''à ce que je fasse de tes ennemis l''escabeau de tes pieds? "'),
('he',1,14,'crampon1923','Ne sont-ils pas tous des esprits au service de Dieu, envoyés comme serviteurs pour le bien de ceux qui doivent recevoir l''héritage du salut?'),
('he',2,1,'crampon1923','C''est pourquoi nous devons nous attacher avec plus de soin aux choses que nous avons entendues de peur que nous ne venions à être entraînés.'),
('he',2,2,'crampon1923','Car, si déjà la parole promulguée par des anges a eu son effet, et si toute transgression et toute désobéissance a reçu en retour un juste châtiment,'),
('he',2,3,'crampon1923','comment pourrons-nous échapper, si nous venions à négliger un message si salutaire, qui, annoncé d''abord par le Seigneur, nous a été sûrement transmis par ceux qui l''ont entendu de lui,'),
('he',2,4,'crampon1923','Dieu confirmant leur témoignage par des signes, des prodiges et toutes sortes de miracles, ainsi que par les dons du Saint-Esprit, répartis selon sa volonté?'),
('he',2,5,'crampon1923','En effet, ce n''est pas à des anges que Dieu a soumis le monde à venir dont nous parlons.'),
('he',2,6,'crampon1923','Aussi quelqu''un a-t-il écrit quelque part ce témoignage: " Qu''est-ce que l''homme, pour que vous vous souveniez de lui; ou le fils de l''homme pour que vous en preniez soin?'),
('he',2,7,'crampon1923','Vous l''avez abaissé pour un peu de temps au-dessous des anges; vous l''avez couronné de gloire et d''honneur, [vous l''avez établi sur les ouvrages de vos mains],'),
('he',2,8,'crampon1923','vous avez mis toutes choses sous ses pieds. " En effet, en lui soumettant toutes choses, Dieu n''a rien laissé en dehors de son empire. Or à présent nous ne voyons pas encore que toutes choses lui soient soumises.'),
('he',2,9,'crampon1923','Mais celui qui " a été abaissé pour un peu de temps au-dessous des anges, " Jésus, nous le voyons couronné de gloire et d''honneur à cause de la mort qu''il a soufferte, afin que, par la grâce de Dieu, il goûtât la mort pour tous.'),
('he',2,10,'crampon1923','En effet, il était bien digne de celui pour qui et par qui sont toutes choses, qu''ayant à conduire à la gloire un grand nombre de fils, il élevât par les souffrances au plus haut degré de perfection le chef qui les a guidés vers le salut.'),
('he',2,11,'crampon1923','Car celui qui sanctifie et ceux qui sont sanctifiés, tous sont d''un seul. C''est pourquoi Jésus-Christ ne rougit point de les appeler frères, lorsqu''il dit:'),
('he',2,12,'crampon1923','" J''annoncerai ton nom à mes frères, je te louerai au milieu de l''assemblée. "'),
('he',2,13,'crampon1923','Et encore: " Je mettrai ma confiance en lui. " Et encore: " Me voici, moi et les enfants que Dieu m''a donnés. "'),
('he',2,14,'crampon1923','Puis donc que les " enfants " ont eu en partage le sang et la chair, lui aussi y a participé également, afin de briser par sa mort la puissance de celui qui a l''empire de la mort, c''est-à-dire du diable,'),
('he',2,15,'crampon1923','et de délivrer ceux que la crainte de la mort retenait toute leur vie assujettis à la servitude.'),
('he',2,16,'crampon1923','Car certes ce n''est pas à des anges qu''il vient en aide, mais c''est à la postérité d''Abraham.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('he',2,17,'crampon1923','De là vient qu''il a dû être fait semblable en tout à ses frères, afin d''être un Pontife miséricordieux et qui s''acquittât fidèlement de ce qu''il faut auprès de Dieu, pour expier les péchés du peuple;'),
('he',2,18,'crampon1923','car, c''est parce qu''il a souffert, et a été lui-même éprouvé, qu''il peut secourir ceux qui sont éprouvés.'),
('he',3,1,'crampon1923','C''est pourquoi, frères saints, vous qui entrez en partage de la vocation céleste, considérez l''apôtre et le grand prêtre de la foi que nous professons, Jésus,'),
('he',3,2,'crampon1923','qui est fidèle à celui qui l''a établi, comme Moïse a été " fidèle dans toute sa maison. "'),
('he',3,3,'crampon1923','Car il surpasse Moïse en dignité, d''autant que celui qui a construit une maison a plus d''honneur que la maison même.'),
('he',3,4,'crampon1923','— Car toute maison est construite par quelqu''un, et celui qui a construit toutes choses c''est Dieu. —'),
('he',3,5,'crampon1923','Tandis que Moïse a été " fidèle dans toute la maison de Dieu ", en qualité de serviteur, pour rendre témoignage de ce qu''il avait à dire,'),
('he',3,6,'crampon1923','le Christ a été fidèle comme fils, à la tête de sa propre maison, et sa maison c''est nous, pourvu que nous retenions fermement jusqu''à la fin la profession ouverte de notre foi, et l''espérance qui fait notre gloire.'),
('he',3,7,'crampon1923','C''est pourquoi, — comme le dit le Saint-Esprit: " Aujourd''hui, si vous entendez sa voix,'),
('he',3,8,'crampon1923','n''endurcissez pas vos cœurs, comme il arriva au lieu nommé la Contradiction, au jour de la tentation au désert,'),
('he',3,9,'crampon1923','où vos pères me provoquèrent pour m''éprouver; cependant, ils avaient vu mes œuvres pendant quarante ans!'),
('he',3,10,'crampon1923','Aussi je fus irrité contre cette génération, et je dis: Sans cesse leur cœur s''égare; ils n''ont pas connu mes voies.'),
('he',3,11,'crampon1923','Je jurai donc dans ma colère: Ils n''entreront pas dans mon repos: " —'),
('he',3,12,'crampon1923','prenez garde, mes frères, qu''il ne se trouve en quelqu''un de vous un cœur mauvais et infidèle, qui lui fasse abandonner le Dieu vivant.'),
('he',3,13,'crampon1923','Au contraire exhortez-vous les uns les autres, chaque jour, tant que dure ce temps appelé: " Aujourd''hui! " afin que personne d''entre vous " ne s''endurcisse " séduit par le péché.'),
('he',3,14,'crampon1923','Car nous sommes entrés en participation du Christ, pourvu que nous retenions fermement jusqu''à la fin le commencement de notre être en lui,'),
('he',3,15,'crampon1923','pendant qu''il nous est dit encore: " Aujourd''hui, si vous entendez sa voix, n''endurcissez pas vos cœurs, comme au lieu appelé la Contradiction. "'),
('he',3,16,'crampon1923','Qui sont, en effet, ceux qui, après " avoir entendu la voix de Dieu ", se révoltèrent? Mais ne sont-ce pas tous ceux qui étaient sortis de l''Egypte sous la conduite de Moïse?'),
('he',3,17,'crampon1923','Et contre qui Dieu fut-il " irrité pendant quarante ans! " N''est-ce pas contre ceux qui avaient péché, et dont les cadavres jonchèrent le désert?'),
('he',3,18,'crampon1923','" Et à qui jura-t-il qu''ils n''entreraient pas dans son repos ", sinon à ceux qui avaient désobéi?'),
('he',3,19,'crampon1923','En effet nous voyons qu''ils ne purent y entrer à cause de leur désobéissance.'),
('he',4,1,'crampon1923','Craignons donc, tandis que la promesse " d''entrer dans son repos " est encore en vigueur, qu''aucun de vous en vienne à être frustré.'),
('he',4,2,'crampon1923','Car le joyeux message nous a été adressé aussi bien qu''à eux; mais la parole qui leur fut annoncée ne leur servit à rien, n''étant pas alliée à la foi chez ceux qui l''entendirent.'),
('he',4,3,'crampon1923','Au contraire nous entrerons dans le repos, nous les croyants, selon ce qu''il a dit: " J''ai juré dans ma colère: Ils n''entreront pas dans mon repos! " Il parle ainsi, quoique ses œuvres eussent été achevées, depuis le commencement du monde.'),
('he',4,4,'crampon1923','Car il est dit quelque part au sujet du septième jour: " Et Dieu se reposa de toutes ses œuvres le septième jour ";'),
('he',4,5,'crampon1923','et ici de nouveau: " Ils n''entreront pas dans mon repos! "'),
('he',4,6,'crampon1923','Puis donc que quelques-uns doivent y entrer, et que ceux qui reçurent d''abord la promesse n''y sont pas entrés à cause de leur désobéissance,'),
('he',4,7,'crampon1923','Dieu fixe de nouveau un jour qu''il appelle " aujourd''hui ", en disant dans David si longtemps après, comme on l''a vu plus haut: " Aujourd''hui, si vous entendez sa voix, n''endurcissez pas vos cœurs. "'),
('he',4,8,'crampon1923','Car si Josué les eût introduits dans " le repos ", David ne parlerait pas après cela d''un autre jour.'),
('he',4,9,'crampon1923','Il reste donc un jour de repos réservé au peuple de Dieu.'),
('he',4,10,'crampon1923','En effet celui qui entre " dans le repos de Dieu " se repose aussi de ses œuvres, comme Dieu s''est reposé des siennes.'),
('he',4,11,'crampon1923','Empressons-nous donc d''entrer dans ce repos, afin qu''aucun ne tombe en donnant le même exemple de désobéissance.'),
('he',4,12,'crampon1923','Car elle est vivante la parole de Dieu; elle est efficace, plus acérée qu''aucune épée à deux tranchants; si pénétrante qu''elle va jusqu''à séparer l''âme et l''esprit, les jointures et les moelles; elle démêle les sentiments et les pensées du cœur.'),
('he',4,13,'crampon1923','Aussi nulle créature n''est cachée devant Dieu, mais tout est à nu et à découvert aux yeux de celui à qui nous devons rendre compte.'),
('he',4,14,'crampon1923','Ainsi, puisque nous avons en Jésus, le Fils de Dieu, un grand prêtre excellent qui a pénétré les cieux, demeurons fermes dans la profession de notre foi.'),
('he',4,15,'crampon1923','Car nous n''avons pas un grand prêtre impuissant à compatir à nos infirmités; pour nous ressembler, il les a toutes éprouvées hormis le péché.'),
('he',4,16,'crampon1923','Approchons-nous donc avec assurance du trône de la grâce, afin d''obtenir miséricorde et de trouver grâce, pour être secourus en temps opportun.'),
('he',5,1,'crampon1923','En effet, tout grand prêtre, pris d''entre les hommes, est établi pour les hommes en ce qui regarde le culte de Dieu, afin d''offrir des oblations et des sacrifices pour les péchés.'),
('he',5,2,'crampon1923','Il est capable d''user d''indulgence envers ceux qui péchent par ignorance et par erreur, puisqu''il est lui-même entouré de faiblesse.'),
('he',5,3,'crampon1923','Et c''est à cause de cette faiblesse qu''il doit offrir pour lui-même, comme pour le peuple, des sacrifices pour les péchés.'),
('he',5,4,'crampon1923','Et nul ne s''arroge cette dignité; il faut y être appelé de Dieu, comme Aaron.'),
('he',5,5,'crampon1923','Ainsi le Christ ne s''est pas élevé de lui-même à la gloire du souverain pontificat, mais il l''a reçue de celui qui lui a dit: " Tu es mon Fils, je t''ai engendré aujourd''hui ";'),
('he',5,6,'crampon1923','comme il dit encore dans un autre endroit: " Tu es prêtre pour toujours selon l''ordre de Melchisédech. "'),
('he',5,7,'crampon1923','C''est lui qui, dans les jours de sa chair, ayant avec de grands cris et avec larmes offert des prières et des supplications à celui qui pouvait le sauver de la mort, et ayant été exaucé pour sa piété,'),
('he',5,8,'crampon1923','a appris, tout Fils qu''il est, par ses propres souffrances, ce que c''est qu''obéir;'),
('he',5,9,'crampon1923','et maintenant que le voilà au terme, il sauve à jamais tous ceux qui lui obéissent,'),
('he',5,10,'crampon1923','Dieu l''ayant déclaré " grand prêtre selon l''ordre de Melchisédech. "'),
('he',5,11,'crampon1923','Sur ce sujet, nous aurions beaucoup de choses à dire, et des choses difficiles à vous expliquer, parce que vous êtes devenus lents à comprendre.'),
('he',5,12,'crampon1923','Vous, en effet, qui depuis longtemps devriez être des maîtres, vous avez encore besoin qu''on vous enseigne les premiers éléments des oracles de Dieu, et vous en êtes venus à avoir besoin de lait, plutôt que d''une nourriture solide.'),
('he',5,13,'crampon1923','Quiconque en est encore au lait, n''est pas capable de la parole de perfection; car c''est un enfant.'),
('he',5,14,'crampon1923','Mais la nourriture solide est pour les hommes faits, pour ceux dont le sens est exercé par habitude à discerner le bien et le mal.'),
('he',6,1,'crampon1923','C''est pourquoi, laissant de côté l''enseignement élémentaire sur le Christ, élevons-nous à l''enseignement parfait, sans poser de nouveau les principes fondamentaux du renoncement aux œuvres mortes, de la foi en Dieu,'),
('he',6,2,'crampon1923','de la doctrine des ablutions, de l''imposition des mains, de la résurrection des morts et du jugement éternel.'),
('he',6,3,'crampon1923','C''est ce que nous allons faire, si Dieu le permet.'),
('he',6,4,'crampon1923','Car il est impossible, pour ceux qui ont été une fois éclairés, qui ont goûté le don céleste, qui ont eu part au Saint-Esprit,'),
('he',6,5,'crampon1923','qui ont goûté la douceur de la parole de Dieu et les merveilles du monde à venir,'),
('he',6,6,'crampon1923','et qui pourtant sont tombés, de les renouveler une seconde fois en les amenant à la pénitence, eux qui pour leur part crucifient de nouveau le Fils de Dieu et le livrent à l''ignominie.'),
('he',6,7,'crampon1923','Lorsqu''une terre, abreuvée par la pluie qui tombe souvent sur elle, produit une herbe utile à ceux pour qui on la cultive, elle a part à la bénédiction de Dieu;'),
('he',6,8,'crampon1923','mais si elle ne produit que des épines et des chardons, elle est jugée de mauvaise qualité, près d''être maudite, et l''on finit par y mettre le feu.'),
('he',6,9,'crampon1923','Cependant, bien-aimés, quoique nous parlions ainsi, nous avons de vous une opinion meilleure et plus favorable à votre salut.'),
('he',6,10,'crampon1923','Car Dieu n''est pas injuste pour oublier vos œuvres et la charité que vous avez montrée pour son nom, vous qui avez rendu service aux saints et leur en rendez encore.'),
('he',6,11,'crampon1923','Nous désirons que chacun de vous déploie le même zèle jusqu''à la fin, afin que vos espérances soient accomplies,'),
('he',6,12,'crampon1923','en sorte que vous ne vous relâchiez point, mais que vous imitiez ceux qui, par la foi et la persévérance, entrent dans l''héritage promis.'),
('he',6,13,'crampon1923','Dans la promesse qu''il fit à Abraham, Dieu ne pouvant jurer par un plus grand que lui, il jura par lui-même,'),
('he',6,14,'crampon1923','et dit: " Oui, je te bénirai et je te multiplierai. "'),
('he',6,15,'crampon1923','Et ce fut ainsi que ce patriarche, ayant patiemment attendu entra en possession de la promesse.'),
('he',6,16,'crampon1923','En effet, les hommes jurent par celui qui est plus grand qu''eux, et le serment, servant de garantie, termine tous leurs différends.'),
('he',6,17,'crampon1923','C''est pourquoi Dieu, voulant montrer avec plus d''évidence aux héritiers de la promesse, l''immuable stabilité de son dessein, fit intervenir le serment,'),
('he',6,18,'crampon1923','afin que, par deux choses immuables, dans lesquelles il est impossible que Dieu nous trompe, nous soyons, nous qui avons cherché en lui un refuge, puissamment encouragés à tenir ferme l''espérance qui nous est proposée.'),
('he',6,19,'crampon1923','Nous la gardons comme une ancre de l''âme, sûre et ferme, cette espérance qui pénètre jusqu''au delà du voile,'),
('he',6,20,'crampon1923','dans le sanctuaire où Jésus est entré pour nous comme précurseur, en qualité de " grand prêtre pour toujours selon l''ordre de Melchisédech. "'),
('he',7,1,'crampon1923','Ce Melchisédech, roi de Salem, prêtre du Dieu très-haut. — qui vint au devant d''Abraham à son retour de la défaite des rois, le bénit,'),
('he',7,2,'crampon1923','et à qui Abraham donna la dîme de tout le butin, — qui est d''abord, selon la signification de son nom, roi de justice, ensuite roi de Salem, c''est-à-dire, roi de paix,'),
('he',7,3,'crampon1923','— qui est sans père, sans mère, sans généalogie, qui n''a ni commencement de jours, ni fin de vie, — et qui est ainsi devenu semblable au Fils de Dieu: ce Melchisédech demeure prêtre pour toujours.'),
('he',7,4,'crampon1923','Considérez combien est grand celui à qui Abraham, le patriarche, donna une dîme sur ce qu''il y avait de meilleur.'),
('he',7,5,'crampon1923','Ceux des fils de Lévi qui obtiennent le sacerdoce ont, d''après la Loi, l''ordre de lever la dîme sur le peuple, c''est-à-dire sur leurs frères, qui cependant sont sortis eux aussi du sang d''Abraham;'),
('he',7,6,'crampon1923','et lui, qui n''était pas issu de leur race, a levé la dîme sur Abraham, et il a béni celui qui avait les promesses.'),
('he',7,7,'crampon1923','Or, sans contredit, c''est l''inférieur qui est béni par le supérieur.'),
('he',7,8,'crampon1923','En outre, ici, ceux qui perçoivent les dîmes sont des hommes qui meurent; mais là, c''est un homme dont il est attesté qu''il est vivant.'),
('he',7,9,'crampon1923','Et Lévi même, qui perçoit la dîme, l''a payée, pour ainsi dire, en la personne d''Abraham;'),
('he',7,10,'crampon1923','car il était encore dans son aïeul, lorsque Melchisédech alla à sa rencontre.'),
('he',7,11,'crampon1923','Si donc la perfection avait pu être réalisée par le sacerdoce lévitique, — car c''est sous lui que le peuple reçut la loi, — quelle nécessité y avait-il qu''il surgît un autre prêtre " selon l''ordre de Melchisédech ", et non selon l''ordre d''Aaron?'),
('he',7,12,'crampon1923','Car, le sacerdoce étant changé, il est nécessaire que la Loi le soit aussi.'),
('he',7,13,'crampon1923','En effet, celui de qui ces paroles sont dites appartient à une autre tribu, dont aucun membre n''a servi à l''autel:'),
('he',7,14,'crampon1923','il est notoire en effet que notre Seigneur est sorti de Juda, tribu à laquelle Moïse n''a jamais attribué le sacerdoce.'),
('he',7,15,'crampon1923','Cela devient plus évident encore, s''il surgit un autre prêtre à la ressemblance de Melchisédech,'),
('he',7,16,'crampon1923','institué, non d''après les prescriptions d''une loi charnelle, mais selon la puissance d''une vie qui ne finit point,'),
('he',7,17,'crampon1923','selon ce témoignage: " Tu es prêtre pour toujours selon l''ordre de Melchisédech. "'),
('he',7,18,'crampon1923','Ainsi, a été abrogée la première ordonnance, à cause de son impuissance et de son inutilité,'),
('he',7,19,'crampon1923','— car la Loi n''a rien amené à la perfection, — mais elle a été l''introduction à une meilleure espérance, par laquelle nous avons accès auprès de Dieu.'),
('he',7,20,'crampon1923','Et comme cela ne s''est point fait sans serment, — car, tandis que les autres ont été établis prêtres sans serment,'),
('he',7,21,'crampon1923','celui-ci l''a été avec serment par celui qui lui a dit: " Le Seigneur l''a juré, et il ne s''en repentira pas: Tu es prêtre pour toujours selon l''ordre de Melchisédech ", —'),
('he',7,22,'crampon1923','Jésus est par cela même le garant d''une alliance supérieure.'),
('he',7,23,'crampon1923','De plus, ils forment, eux, une longue série de prêtres, parce que la mort les empêchait de l''être toujours;'),
('he',7,24,'crampon1923','mais lui, parce qu''il demeure éternellement, il possède un sacerdoce qui ne se transmet point.'),
('he',7,25,'crampon1923','De là vient aussi qu''il peut sauver parfaitement ceux qui s''approchent de Dieu par lui, puisqu''il est toujours vivant pour intercéder en leur faveur.'),
('he',7,26,'crampon1923','Tel est, en effet, le grand prêtre qu''il nous fallait, saint, innocent, sans tache, séparé des pécheurs, et élevé au-dessus des cieux;'),
('he',7,27,'crampon1923','qui n''a pas besoin, comme les grands prêtres, d''offrir chaque jour des sacrifices d''abord pour ses propres péchés, ensuite pour ceux du peuple, — car ceci, il l''a fait une fois pour toutes en s''offrant lui-même.'),
('he',7,28,'crampon1923','La Loi, en effet, institue grands prêtres des hommes sujets à la faiblesse; mais la parole du serment, intervenue après la Loi, institue le Fils qui est arrivé à la perfection pour l''éternité.'),
('he',8,1,'crampon1923','Cela étant dit, l''essentiel est que nous avons ainsi un grand prêtre qui s''est assis à la droite du trône de la majesté divine dans les cieux,'),
('he',8,2,'crampon1923','comme ministre du sanctuaire et du vrai tabernacle, qui a été dressé par le Seigneur, et non par un homme.'),
('he',8,3,'crampon1923','Car tout grand prêtre est établi pour offrir des oblations et des sacrifices; d''où il est nécessaire que lui aussi ait quelque chose à offrir.'),
('he',8,4,'crampon1923','S''il était sur la terre, il ne serait pas même prêtre, puisqu''il s''y trouve des prêtres chargés d''offrir les oblations selon la Loi, —'),
('he',8,5,'crampon1923','lesquels célèbrent un culte qui n''est qu''une image et une ombre des choses célestes, comme Moïse en fut divinement averti lorsqu''il dut construire le tabernacle: " Regarde, dit le Seigneur, tu feras tout d''après le modèle qui t''a été montré sur la montagne. "'),
('he',8,6,'crampon1923','Mais notre grand prêtre a reçu un ministère d''autant plus élevé, qu''il est médiateur d''une alliance supérieure et fondée sur de meilleures promesses.'),
('he',8,7,'crampon1923','En effet, si la première alliance avait été sans défaut, il n''y aurait pas eu lieu de lui en substituer une seconde.'),
('he',8,8,'crampon1923','Car c''est bien un blâme que Dieu exprime, quand il leur dit: " Voici, dit le Seigneur, que les jours viennent où je contracterai une alliance nouvelle avec la maison d''Israël et avec la maison de Juda;'),
('he',8,9,'crampon1923','non pas une alliance comme celle que je fis avec leurs pères, au jour où je les pris par la main pour les faire sortir de la terre d''Egypte. Puisqu''ils n''ont pas persévéré dans mon alliance, moi aussi je les ai délaissés, dit le Seigneur.'),
('he',8,10,'crampon1923','Mais voici l''alliance que je ferai avec la maison d''Israël après ces jours-là, dit le Seigneur: Je mettrai mes lois dans leur esprit et je les écrirai dans leur cœur; et je serai leur Dieu, et ils seront mon peuple.'),
('he',8,11,'crampon1923','Aucun d''eux n''enseignera plus son concitoyen, aucun n''enseignera plus son frère, disant: Connais le Seigneur! car tous me connaîtront, depuis le plus petit d''entre eux jusqu''au plus grand.'),
('he',8,12,'crampon1923','Je pardonnerai leurs iniquités, et je ne me souviendrai plus de leurs péchés. "'),
('he',8,13,'crampon1923','— En disant: " Une alliance nouvelle ", Dieu a déclaré la première vieillie; or, ce qui est devenu ancien, ce qui est vieilli, est près de disparaître.'),
('he',9,1,'crampon1923','La première alliance avait aussi ses règlements relatifs au culte, et un sanctuaire terrestre.'),
('he',9,2,'crampon1923','En effet, on a construit un tabernacle, avec une partie antérieure, appelée le lieu saint, où étaient le chandelier, la table et les pains de proposition.'),
('he',9,3,'crampon1923','Derrière le second voile, se trouvait la partie du tabernacle appelée le Saint des Saints,'),
('he',9,4,'crampon1923','ayant un autel d''or pour les parfums et l''arche de l''alliance toute recouverte d''or. Dans l''arche se trouvait une urne d''or renfermant la manne, la verge d''Aaron qui avait fleuri, et les tables de l''alliance.'),
('he',9,5,'crampon1923','Au dessus étaient des chérubins de la gloire, couvrant de leur ombre le propitiatoire. Mais ce n''est pas ici le lieu de parler sur ce sujet en détail.'),
('he',9,6,'crampon1923','Or, ces choses étant ainsi disposées, les prêtres entrent en tout temps dans la partie antérieure du tabernacle, lorsqu''ils font le service du culte;'),
('he',9,7,'crampon1923','le grand prêtre seul, une seule fois l''année, entre dans la seconde partie, mais avec du sang qu''il offre pour lui-même et pour les péchés du peuple.'),
('he',9,8,'crampon1923','L''Esprit-Saint montre par là que le chemin du Saint des Saints n''a pas encore été ouvert, tant que subsiste le premier tabernacle.'),
('he',9,9,'crampon1923','C''est une figure qui a rapport au temps présent; elle signifie que les oblations et les sacrifices offerts ne peuvent amener à la perfection, au point de vue de la conscience, celui qui rend ce culte.'),
('he',9,10,'crampon1923','Car avec les prescriptions relatives aux aliments, aux boissons et aux diverses ablutions, ce ne sont que des ordonnances charnelles, imposées seulement jusqu''à une époque de réformation.'),
('he',9,11,'crampon1923','Mais le Christ ayant paru comme grand prêtre des biens à venir, c''est en passant par un tabernacle plus excellent et plus parfait, qui n''est pas construit de main d''homme, c''est-à-dire, qui n''appartient pas à cette création-ci,'),
('he',9,12,'crampon1923','et ce n''est pas avec le sang des boucs et des taureaux, mais avec son propre sang, qu''il est entré une fois pour toutes dans le saint des Saints, après avoir acquis une rédemption éternelle.'),
('he',9,13,'crampon1923','Car si le sang des boucs et des taureaux, si la cendre d''une vache, dont on asperge ceux qui sont souillés, sanctifient de manière à procurer la pureté de la chair,'),
('he',9,14,'crampon1923','combien plus le sang du Christ qui, par l''Esprit éternel, s''est offert lui-même sans tache à Dieu, purifiera-t-il notre conscience des œuvres mortes, pour servir le Dieu vivant?'),
('he',9,15,'crampon1923','Et c''est pour cela qu''il est médiateur d''une nouvelle alliance, afin que, sa mort ayant eu lieu pour le pardon des transgressions commises sous la premiers alliance, ceux qui ont été appelés reçoivent l''héritage éternel qui leur a été promis.'),
('he',9,16,'crampon1923','Car, là où il y a un testament, il est nécessaire que la mort du testateur intervienne;'),
('he',9,17,'crampon1923','parce qu''un testament n''a son effet qu''en cas de mort, étant sans force lorsque le testateur est en vie.'),
('he',9,18,'crampon1923','Voilà pourquoi même la première alliance n''a pas été inaugurée sans effusion de sang.'),
('he',9,19,'crampon1923','Moïse, après avoir proclamé devant tout le peuple tous les commandements selon la teneur de la Loi, prit le sang des taureaux et des boucs, avec de l''eau, de la laine écarlate et de l''hysope, et il fit l''aspersion sur le Livre lui-même et sur tout le peuple,'),
('he',9,20,'crampon1923','en disant: " Voici le sang de l''alliance que Dieu a contractée avec vous. "'),
('he',9,21,'crampon1923','Il aspergea de même avec le sang le tabernacle et tous les ustensiles du culte.'),
('he',9,22,'crampon1923','Et d''après la Loi, presque tout se purifie avec du sang; et sans effusion de sang il n''y a pas de rémission.'),
('he',9,23,'crampon1923','Puisque les images des choses qui sont dans les cieux devaient être purifiées de cette manière, il était donc nécessaire que les choses célestes elles-mêmes fussent inaugurées par des sacrifices supérieurs à ceux-là.'),
('he',9,24,'crampon1923','Car ce n''est pas dans un sanctuaire fait de main d''homme, image du véritable, que le Christ est entré; mais il est entré dans le ciel même, afin de se tenir désormais pour nous présent devant la face de Dieu.'),
('he',9,25,'crampon1923','Et ce n''est pas pour s''offrir lui-même plusieurs fois, comme le grand prêtre entre chaque année dans le sanctuaire avec un sang qui n''est pas le sien:'),
('he',9,26,'crampon1923','autrement il aurait dû souffrir plusieurs fois depuis la fondation du monde; mais il s''est montré une seule fois, dans les derniers âges, pour abolir le péché par son sacrifice.'),
('he',9,27,'crampon1923','Et comme il est arrêté que les hommes meurent une seule fois, après quoi vient le jugement,'),
('he',9,28,'crampon1923','ainsi le Christ, après s''être offert une seule fois pour ôter les péchés de la multitude, apparaîtra une seconde fois, sans péché, pour donner le salut à ceux qui l''attendent.'),
('he',10,1,'crampon1923','La Loi, en effet, n''ayant qu''une ombre des biens à venir, et non l''image même des choses, ne peut jamais, par ces mêmes sacrifices que l''on offre sans interruption chaque année, sanctifier parfaitement ceux qui s''en approchent.'),
('he',10,2,'crampon1923','Autrement n''aurait-on pas cessé de les offrir; car ceux qui rendent ce culte, une foi purifiés, n''auraient plus eu aucune conscience de leurs péchés.'),
('he',10,3,'crampon1923','Tandis que, par ces sacrifices, on rappelle chaque année le souvenir des péchés;'),
('he',10,4,'crampon1923','parce qu''il est impossible que le sang des taureaux et des boucs enlève les péchés.'),
('he',10,5,'crampon1923','C''est pourquoi le Christ dit en entrant dans le monde: " Vous n''avez voulu ni sacrifice, ni oblation, mais vous m''avez formé un corps;'),
('he',10,6,'crampon1923','vous n''avez agréé ni holocaustes, ni sacrifices pour le péché.'),
('he',10,7,'crampon1923','Alors j''ai dit: Me voici (car il est question de moi dans le rouleau du livre), je viens ô Dieu, pour faire votre volonté. "'),
('he',10,8,'crampon1923','Après avoir commencé par dire: " Vous n''avez voulu et vous n''avez agréé ni oblations, ni holocaustes, ni sacrifices pour le péché ", — toutes choses qu''on offre selon la Loi,'),
('he',10,9,'crampon1923','il ajoute ensuite: " Voici que je viens pour faire votre volonté. " Il abolit ainsi le premier point, pour établir le second.'),
('he',10,10,'crampon1923','C''est en vertu de cette volonté que nous sommes sanctifiés, par l''oblation que Jésus-Christ a faite, une fois pour toutes, de son propre corps.'),
('he',10,11,'crampon1923','Et tandis que tout prêtre se présente chaque jour pour accomplir son ministère, et offre plusieurs fois les mêmes victimes, qui ne peuvent jamais enlever les péchés,'),
('he',10,12,'crampon1923','lui au contraire, après avoir offert un seul sacrifice pour les péchés, " s''est assis " pour toujours " à la droite de Dieu "'),
('he',10,13,'crampon1923','attendant désormais " que ses ennemis deviennent l''escabeau de ses pieds. "'),
('he',10,14,'crampon1923','Car, par une oblation unique, il a procuré la perfection pour toujours à ceux qui sont sanctifiés.'),
('he',10,15,'crampon1923','C''est ce que l''Esprit-Saint nous atteste aussi; car, après avoir dit:'),
('he',10,16,'crampon1923','" Voici l''alliance que je ferai avec eux après ces jours-là ", le Seigneur ajoute: " Je mettrai mes lois dans leurs cœurs, et je les écrirai dans leur esprit;'),
('he',10,17,'crampon1923','et je ne me souviendrai plus de leurs péchés, ni de leurs iniquités. "'),
('he',10,18,'crampon1923','Or, là où les péchés sont remis, il n''est plus question d''oblation pour le péché.'),
('he',10,19,'crampon1923','Ainsi donc, frères, puisque nous avons, par le sang de Jésus un libre accès dans le sanctuaire,'),
('he',10,20,'crampon1923','par la voie nouvelle et vivante, qu''il a inaugurée, pour nous à travers le voile, c''est-à-dire à travers sa chair,'),
('he',10,21,'crampon1923','et puisque nous avons un grand prêtre établi sur la maison de Dieu,'),
('he',10,22,'crampon1923','approchons-nous avec un cœur sincère, dans la plénitude de la foi, le cœur purifié des souillures d''une mauvaise conscience, et le corps lavé dans une eau pure.'),
('he',10,23,'crampon1923','Restons inébranlablement attachés à la profession de notre espérance; car celui qui a fait la promesse est fidèle.'),
('he',10,24,'crampon1923','Ayons l''œil ouvert les uns sur les autres pour nous exciter à la charité et aux bonnes œuvres.'),
('he',10,25,'crampon1923','Ne désertons pas notre assemblée, comme quelques-uns ont coutume de le faire; mais exhortons-nous les uns les autres, et cela d''autant plus que vous voyez s''approcher le jour.'),
('he',10,26,'crampon1923','Car si nous péchons volontairement après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés;'),
('he',10,27,'crampon1923','il n''y a plus qu''à attendre un jugement terrible et le feu jaloux qui dévorera les rebelles.'),
('he',10,28,'crampon1923','Celui qui a violé la loi de Moïse meurt sans miséricorde, sur la déposition de deux ou trois témoins;'),
('he',10,29,'crampon1923','de quel châtiment plus sévère pensez-vous que sera jugé digne celui qui aura foulé aux pieds le Fils de Dieu, qui aura tenu pour profane le sang de l''alliance par lequel il avait été sanctifié, et qui aura outragé l''Esprit de la grâce?'),
('he',10,30,'crampon1923','Car nous le connaissons, celui qui a dit: " A moi la vengeance! c''est moi qui paierai de retour! " Et encore: Le " Seigneur jugera son peuple. "'),
('he',10,31,'crampon1923','Il est effroyable de tomber entre les mains du Dieu vivant!'),
('he',10,32,'crampon1923','Rappelez-vous ces premiers jours, où, après avoir été éclairés, vous avez soutenu un grand combat de souffrances,'),
('he',10,33,'crampon1923','tantôt exposés comme en spectacle aux opprobres et aux tribulations, tantôt prenant part aux maux de ceux qui étaient ainsi traités.'),
('he',10,34,'crampon1923','En effet, vous avez compati aux prisonniers, et vous avez accepté avec joie le pillage de vos biens, sachant que vous avez une richesse meilleure et qui durera toujours.'),
('he',10,35,'crampon1923','N''abandonnez donc pas votre assurance; une grande récompense y est attachée.'),
('he',10,36,'crampon1923','Car la persévérance vous est nécessaire afin que, après avoir fait la volonté de Dieu, vous obteniez ce qui vous est promis.'),
('he',10,37,'crampon1923','Encore un peu, bien peu de temps et " celui qui doit venir viendra; il ne tardera pas.'),
('he',10,38,'crampon1923','Et mon juste vivra par la foi; mais, s''il se retire, mon âme ne mettra pas sa complaisance en lui. "'),
('he',10,39,'crampon1923','Pour nous, nous ne sommes pas de ceux qui se retirent pour leur perte, mais de ceux qui gardent la foi pour sauver leur âme.'),
('he',11,1,'crampon1923','Or la foi est la substance des choses qu''on espère, une conviction de celles qu''on ne voit point.'),
('he',11,2,'crampon1923','C''est pour l''avoir possédée que les anciens ont obtenu un bon témoignage.'),
('he',11,3,'crampon1923','C''est par la foi que nous reconnaissons que le monde a été formé par la parole de Dieu, en sorte que les choses que l''on voit n''ont pas été faites de choses visibles.'),
('he',11,4,'crampon1923','C''est par la foi qu''Abel offrit à Dieu un sacrifice plus excellent que celui de Caïn; c''est par elle qu''il fut déclaré juste, Dieu approuvant ses offrandes, et c''est par elle que, mort, il parle toujours.'),
('he',11,5,'crampon1923','C''est par la foi qu''Enoch fut enlevé sans qu''il eût subi la mort: " on ne le trouva plus, parce que Dieu l''avait enlevé "; car avant cet enlèvement, il avait reçu ce témoignage " qu''il avait plu à Dieu. "'),
('he',11,6,'crampon1923','Or, sans la foi, il est impossible de plaire à Dieu; car il faut que celui qui s''approche de Dieu croie qu''il existe, et qu''il est le rémunérateur de ceux qui le cherchent.'),
('he',11,7,'crampon1923','C''est par la foi que Noé, divinement averti des événements qu''on ne voyait pas encore, construisit, avec une pieuse crainte, une arche pour sauver sa famille; c''est par elle qu''il condamna le monde, et devint héritier de la justice qui s''obtient par la foi.'),
('he',11,8,'crampon1923','C''est par la foi qu''Abraham, obéissant à l''appel de Dieu, partit pour un pays qu''il devait recevoir en héritage, et se mit en chemin sans savoir où il allait.'),
('he',11,9,'crampon1923','C''est par la foi qu''il séjourna dans la terre promise, comme dans une terre étrangère, habitant sous des tentes, ainsi qu''Isaac et Jacob, héritiers comme lui de la même promesse.'),
('he',11,10,'crampon1923','Car il attendait la cité aux solides fondements, dont Dieu est l''architecte et le constructeur.'),
('he',11,11,'crampon1923','C''est par la foi que Sara, elle aussi, qui n''était plus dans l''âge de concevoir, en reçut la vertu, parce qu''elle crut à la fidélité de Celui qui en avait fait la promesse.'),
('he',11,12,'crampon1923','C''est pourquoi, d''un seul homme, déjà comme mort, sortit une postérité aussi nombreuse que les étoiles du ciel, et que les grains de sable innombrables qui sont sur le bord de la mer.'),
('he',11,13,'crampon1923','C''est dans la foi que ces patriarches sont tous morts, sans avoir reçu l''effet des promesses; mais ils l''ont vu et salué de loin, confessant " qu''ils étaient étrangers et voyageurs sur la terre. "'),
('he',11,14,'crampon1923','Ceux qui parlent ainsi montrent bien qu''ils cherchent une patrie.'),
('he',11,15,'crampon1923','Et certes, s''ils avaient entendu par là celle d''où ils étaient sortis, ils auraient eu le moyen d''y retourner.'),
('he',11,16,'crampon1923','Mais c''est à une patrie meilleure, à la patrie du ciel, que tendent leurs aspirations. C''est pourquoi Dieu n''a pas honte de s''appeler " leur Dieu ", car il leur a préparé une cité.'),
('he',11,17,'crampon1923','C''est par la foi qu''Abraham mis à l''épreuve, offrit Isaac en sacrifice. Ainsi celui qui avait reçu les promesses,'),
('he',11,18,'crampon1923','et à qui il avait été dit: " C''est d''Isaac que naîtra ta postérité ", offrit ce fils unique,'),
('he',11,19,'crampon1923','estimant que Dieu est assez puissant pour ressusciter même les morts; aussi le recouvra-t-il comme en figure.'),
('he',11,20,'crampon1923','C''est par la foi qu''Isaac bénit Jacob et Esaü, en vue des choses à venir.'),
('he',11,21,'crampon1923','C''est par la foi que Jacob mourant bénit chacun des fils de Joseph et qu''il " se prosterna appuyé sur le sommet de son sceptre ".'),
('he',11,22,'crampon1923','C''est par la foi que Joseph, prés de sa fin, fit mention de la sortie des fils d''Israël, et qu''il donna des ordres au sujet de ses restes.'),
('he',11,23,'crampon1923','C''est par la foi que Moïse à sa naissance, fut caché pendant trois mois par ses parents, parce qu''ils virent que l''enfant était beau, et qu''ils ne craignirent pas l''édit du roi.'),
('he',11,24,'crampon1923','C''est par la foi que Moïse, devenu grand, renonça au titre de fils de la fille de Pharaon,'),
('he',11,25,'crampon1923','aimant mieux d''être maltraité avec le peuple de Dieu, que de jouir des délices passagères du péché:'),
('he',11,26,'crampon1923','il considéra l''opprobre du Christ comme une richesse plus grande que les trésors de l''Egypte; car il avait les yeux fixés sur la récompense.'),
('he',11,27,'crampon1923','C''est par la foi qu''il quitta l''Egypte, sans redouter la colère du roi; car il tint ferme, comme s''il voyait celui qui est invisible.'),
('he',11,28,'crampon1923','C''est par la foi qu''il célébra la Pâque et fit l''aspersion du sang, afin que l''exterminateur des premiers-nés ne touchât pas à ceux des Israélites.'),
('he',11,29,'crampon1923','C''est par la foi qu''ils passèrent la mer Rouge comme une terre ferme, tandis que les Egyptiens qui tentèrent le passage furent engloutis.'),
('he',11,30,'crampon1923','C''est par la foi que les murailles de Jéricho tombèrent, après qu''on en eût fait le tour pendant sept jours.'),
('he',11,31,'crampon1923','C''est par la foi que Rahab la courtisane ne périt pas avec les rebelles, pour avoir donné aux espions une sûre hospitalité.'),
('he',11,32,'crampon1923','Et que dirai-je encore? Le temps me manquerait si je voulais parler aussi de Gédéon, de Barac, de Samson, de Jephté, de David, de Samuel et des prophètes:'),
('he',11,33,'crampon1923','par la foi, ils ont conquis des royaumes, exercé la justice, obtenu l''effet des promesses, fermé la gueule des lions,'),
('he',11,34,'crampon1923','éteint la violence du feu, échappé au tranchant de l''épée, triomphé de la maladie, déployé leur vaillance à la guerre, mis en fuite des armées ennemis;'),
('he',11,35,'crampon1923','par eux des femmes ont recouvré leurs morts ressuscités. Les uns ont péri dans les tortures, refusant la délivrance afin d''obtenir une meilleure résurrection;'),
('he',11,36,'crampon1923','d''autres ont souffert les moqueries et les verges; de plus, les chaînes et les cachots;'),
('he',11,37,'crampon1923','ils ont été lapidés, sciés, éprouvés; ils sont morts par le tranchant de l''épée; ils ont erré çà et là, couverts de peaux de brebis et de chèvres, dénués de tout, persécutés, maltraités,'),
('he',11,38,'crampon1923','— eux dont le monde n''était pas digne; — ils ont été errants dans les déserts et les montagnes, dans les cavernes et dans les antres de la terre.'),
('he',11,39,'crampon1923','Cependant eux tous que leur foi a rendus recommandables, n''ont pas obtenu l''objet de la promesse'),
('he',11,40,'crampon1923','parce que Dieu nous a fait une condition meilleure pour qu''ils n''obtinssent pas sans nous la perfection du bonheur.'),
('he',12,1,'crampon1923','Donc, nous aussi, puisque nous sommes environnés d''une si grande nuée de témoins, rejetons tout ce qui nous appesantit et le péché qui nous enveloppe, et courons avec persévérance dans la carrière qui nous est ouverte,'),
('he',12,2,'crampon1923','les yeux fixés sur Jésus, l''auteur et le consommateur de la foi, lui qui, au lieu de la joie qu''il avait devant lui, méprisant l''ignominie, a souffert la croix, et " s''est assis à la droite du trône de Dieu ".'),
('he',12,3,'crampon1923','Considérez celui qui a supporté contre sa personne une si grande contradiction de la part des pécheurs, afin de ne pas vous laisser abattre par le découragement.'),
('he',12,4,'crampon1923','Vous n''avez pas encore résisté jusqu''au sang dans votre lutte contre le péché.'),
('he',12,5,'crampon1923','Et vous avez oublié l''exhortation de Dieu qui vous dit comme à des fils: " Mon fils, ne méprise pas le châtiment du Seigneur, et ne perds point courage lorsqu''il te reprend;'),
('he',12,6,'crampon1923','car le Seigneur châtie celui qu''il aime, et il frappe de la verge tout fils qu''il reconnaît pour sien. "'),
('he',12,7,'crampon1923','C''est pour votre instruction que vous êtes éprouvés: Dieu vous traite comme des fils; car quel est le fils que son père ne châtie pas?'),
('he',12,8,'crampon1923','Si vous êtes exempts du châtiment auquel tous ont part, vous êtes donc des enfants illégitimes, et non de vrais fils.'),
('he',12,9,'crampon1923','D''ailleurs, puisque nos pères selon la chair nous ont châtiés et que nous les avons respectés, combien plus nous devons nous soumettre au Père des esprits, pour avoir la vie?'),
('he',12,10,'crampon1923','Quant à ceux-là, c''était pour peu de temps qu''ils nous châtiaient au gré de leur volonté; mais Dieu le fait autant qu''il est utile pour nous rendre capables de participer à sa sainteté.'),
('he',12,11,'crampon1923','Toute correction, il est vrai, paraît sur l''heure un sujet de tristesse, et non de joie; mais elle produit plus tard, pour ceux qui ont été ainsi exercés, un fruit de paix et de justice.'),
('he',12,12,'crampon1923','" Relevez donc vos mains languissantes et vos genoux défaillants;'),
('he',12,13,'crampon1923','dirigez vos pas dans la voie droite ", afin que ce qui est boiteux ne dévie pas, mais plutôt se raffermisse.'),
('he',12,14,'crampon1923','Recherchez la paix avec tous, et la sainteté, sans laquelle personne ne verra le Seigneur.'),
('he',12,15,'crampon1923','Veillez à ce que personne ne manque à la grâce de Dieu; à ce qu''aucune racine d''amertume, venant à pousser des rejetons, ne cause du trouble, et que la masse n''en soit infectée.'),
('he',12,16,'crampon1923','Qu''il n''y ait parmi vous ni impudique, ni profanateur comme Esaü, qui pour un seul mets vendit son droit d''aînesse.'),
('he',12,17,'crampon1923','Vous savez que, plus tard, voulant obtenir la bénédiction, il fut repoussé, quoiqu''il la sollicitât avec larmes; car il ne put amener son père à changer de sentiments.'),
('he',12,18,'crampon1923','Vous ne vous êtes pas approchés d''une montagne que la main puisse toucher, ni d''un feu ardent, ni de la nuée, ni des ténèbres, ni de la tempête,'),
('he',12,19,'crampon1923','ni de l''éclat de la trompette, ni d''une voix si retentissante, que ceux qui l''entendirent supplièrent qu''on ne leur parlât pas davantage;'),
('he',12,20,'crampon1923','car ils ne pouvaient supporter cette défense: " Si même une bête touche la montagne, elle sera lapidée. "'),
('he',12,21,'crampon1923','Et ce spectacle était si terrible que Moïse dit: " Je suis terrifié et tout tremblant! " —'),
('he',12,22,'crampon1923','Mais vous vous êtes approchés de la montagne de Sion, de la cité du Dieu vivant qui est la Jérusalem céleste, des myriades qui forment le chœur des anges,'),
('he',12,23,'crampon1923','de l''assemblée des premiers nés inscrits dans les cieux, du juge qui est le Dieu de tous, des esprits des justes parvenus à la perfection,'),
('he',12,24,'crampon1923','de Jésus, le médiateur de la nouvelle alliance, et du sang de l''aspersion qui parle plus éloquemment que celui d''Abel.'),
('he',12,25,'crampon1923','Prenez garde de résister à celui qui parle; car si ceux-là n''ont pas échappé au châtiment, qui ont refusé d''écouter celui qui publiait ses oracles sur la terre, combien moins échapperons-nous, si nous le repoussons, quand il nous parle du haut des cieux:'),
('he',12,26,'crampon1923','lui, dont la voix ébranla alors la terre, mais qui maintenant a fait cette promesse: " Une fois encore j''ébranlerai non seulement la terre, mais aussi le ciel. "'),
('he',12,27,'crampon1923','Ces mots: " Une fois encore ", indiquent le changement des choses qui vont être ébranlées comme ayant eu leur accomplissement, afin que celles qui ne doivent pas être ébranlées subsistent à jamais.'),
('he',12,28,'crampon1923','Ainsi, puisque nous rentrons en possession d''un royaume qui ne sera point ébranlé, retenons fermement la grâce; par elle rendons à Dieu un culte qui lui soit agréable, avec piété et avec crainte.'),
('he',12,29,'crampon1923','Car notre Dieu est aussi un feu dévorant.'),
('he',13,1,'crampon1923','Persévérez dans l''amour fraternel.'),
('he',13,2,'crampon1923','N''oubliez pas l''hospitalité; quelques-uns en la pratiquant ont, à leur insu, logé des anges.'),
('he',13,3,'crampon1923','Souvenez-vous des prisonniers, comme si vous étiez aussi prisonniers; et de ceux qui sont maltraités, comme étant vous aussi dans un corps.'),
('he',13,4,'crampon1923','Que le mariage soit honoré de tous, et le lit conjugal exempt de souillure, car Dieu condamnera les impudiques et les adultères.'),
('he',13,5,'crampon1923','Que votre conduite soit exempte d''avarice, vous contentant de ce que vous avez; car Dieu lui-même a dit: " Je ne te délaisserai point et ne t''abandonnerai point ";'),
('he',13,6,'crampon1923','de sorte que nous pouvons dire en toute assurance: " Le Seigneur est mon secours, je ne craindrai rien; que pourraient me faire les hommes? "'),
('he',13,7,'crampon1923','Souvenez-vous de ceux qui vous conduisent, qui vous ont annoncé la parole de Dieu; et considérant quelle a été l''issue de leur vie, imitez, leur foi.'),
('he',13,8,'crampon1923','Jésus-Christ est le même hier et aujourd''hui; il le sera éternellement.'),
('he',13,9,'crampon1923','Ne vous laissez pas entraîner par des doctrines diverses et étrangères, car il vaut mieux affermir son cœur par la grâce, que par des aliments, qui n''ont servi de rien à ceux qui s''y attachent.'),
('he',13,10,'crampon1923','Nous avons un autel dont ceux-là n''ont pas le droit de manger qui restent au service du tabernacle.'),
('he',13,11,'crampon1923','Car pour les animaux dont le sang, expiation du péché, est porté dans le sanctuaire par le grand prêtre, leurs corps sont brûlés hors du camp.'),
('he',13,12,'crampon1923','C''est pour cela que Jésus aussi, devant sanctifier le peuple par son sang, a souffert hors de la porte.'),
('he',13,13,'crampon1923','Donc, pour aller à lui, sortons hors du camp, en portant son opprobre.'),
('he',13,14,'crampon1923','Car nous n''avons pas ici-bas de cité permanente, mais nous cherchons celle qui est à venir.'),
('he',13,15,'crampon1923','Que ce soit donc par lui que nous offrions sans cesse à Dieu " un sacrifice de louange ", c''est-à-dire " le fruit de lèvres " qui célèbrent son nom.'),
('he',13,16,'crampon1923','Et n''oubliez pas la bienfaisance et la libéralité; car Dieu se plaît à de tels sacrifices.'),
('he',13,17,'crampon1923','Obéissez à ceux qui vous conduisent, et ayez pour eux de la déférence, car ils veillent sur vos âmes comme devant en rendre compte, — afin qu''ils le fassent avec joie, et non en gémissant; ce qui ne vous serait pas avantageux.'),
('he',13,18,'crampon1923','Priez pour nous; car nous sommes assurés d''avoir une bonne conscience, voulant en toutes choses nous bien conduire.'),
('he',13,19,'crampon1923','C''est avec instance que je vous conjure de le faire, afin que je vous sois plus tôt rendu.'),
('he',13,20,'crampon1923','Que le Dieu de la paix, — qui a ramené d''entre les morts celui qui, par le sang d''une alliance éternelle, est devenu le grand Pasteur des brebis, notre Seigneur Jésus, —'),
('he',13,21,'crampon1923','vous rende capables de toute bonne œuvre pour l''accomplissement de sa volonté, en opérant en vous ce qui est agréable à ses yeux, par Jésus-Christ, auquel soit la gloire dans les siècles des siècles! Amen!'),
('he',13,22,'crampon1923','Je vous prie, frères, d''agréer cette parole d''exhortation, car je vous ai écrit brièvement.'),
('he',13,23,'crampon1923','Apprenez que notre frère Timothée est relâché; s''il vient assez tôt, j''irai vous voir avec lui.'),
('he',13,24,'crampon1923','Saluez tous ceux qui vous conduisent et tous les saints. Les frères d''Italie vous saluent. Que la grâce soit avec vous tous! Amen!'),
('he',13,25,'crampon1923',''),
('jc',1,1,'crampon1923','JACQUES, serviteur de Dieu et du Seigneur Jésus-Christ, aux douze tribus qui sont dans la dispersion, salut.'),
('jc',1,2,'crampon1923','Ne voyez qu''un sujet de joie, mes frères, dans les épreuves de toute sorte qui tombent sur vous;'),
('jc',1,3,'crampon1923','sachant que l''épreuve de votre foi produit la patience.'),
('jc',1,4,'crampon1923','Mais que la patience soit accompagnée d''œuvres parfaites, afin que vous soyez parfaits et accomplis, ne laissant à désirer en rien.'),
('jc',1,5,'crampon1923','Si la sagesse fait défaut à quelqu''un d''entre vous, qu''il la demande à Dieu, lequel donne à tous simplement, sans rien reprocher; et elle lui sera donnée.'),
('jc',1,6,'crampon1923','Mais qu''il demande avec foi, sans hésiter; car celui qui hésite est semblable au flot de la mer, agité et ballotté par le vent.'),
('jc',1,7,'crampon1923','Que cet homme-là ne pense donc pas qu''il recevra quelque chose du Seigneur:'),
('jc',1,8,'crampon1923','homme à deux âmes, inconstant dans toutes ses voies.'),
('jc',1,9,'crampon1923','Que le frère pauvre se glorifie de son élévation.'),
('jc',1,10,'crampon1923','Et que le riche mette sa gloire dans son abaissement; car il passera comme l''herbe fleurie:'),
('jc',1,11,'crampon1923','le soleil s''est levé brûlant, et il a desséché l''herbe, et sa fleur est tombée, et toute sa beauté a disparu; de même aussi le riche se flétrira avec ses entreprises.'),
('jc',1,12,'crampon1923','Heureux l''homme qui supportera l''épreuve! Devenu un homme éprouvé, il recevra la couronne de vie que Dieu a promise à ceux qui l''aiment.'),
('jc',1,13,'crampon1923','Que nul, lorsqu''il est tenté, ne dise: " C''est Dieu qui me tente "; car Dieu ne saurait être tenté de mal, et lui-même ne tente personne.'),
('jc',1,14,'crampon1923','Mais chacun est tenté par sa propre convoitise, qui l''amorce et l''entraîne.'),
('jc',1,15,'crampon1923','Ensuite la convoitise, lorsqu''elle a conçu, enfante le péché, et le péché, lorsqu''il est consommé, engendre la mort.'),
('jc',1,16,'crampon1923','Ne vous abusez pas, mes frères bien-aimés.'),
('jc',1,17,'crampon1923','Tout don excellent, toute grâce parfaite, descend d''en haut, du Père des lumières, en qui n''existe aucune vicissitude, ni ombre de changement.'),
('jc',1,18,'crampon1923','De sa propre volonté, il nous a engendrés par la parole de la vérité, afin que nous soyons comme les prémices de ses créatures.'),
('jc',1,19,'crampon1923','Mes frères bien-aimés, vous le savez, que l''homme soit prompt à écouter, lent à parler, lent à se mettre en colère.'),
('jc',1,20,'crampon1923','Car la colère de l''homme n''opère point la justice de Dieu.'),
('jc',1,21,'crampon1923','C''est pourquoi, rejetant toute souillure et toute excroissance de méchanceté, recevez avec douceur la parole qui a été entée en vous, et qui peut sauver vos âmes.'),
('jc',1,22,'crampon1923','Mais efforcez-vous de la mettre en pratique, et ne vous contentez pas de l''écouter, en vous abusant vous-mêmes par de faux raisonnements.'),
('jc',1,23,'crampon1923','Car, si quelqu''un écoute la parole et ne l''observe pas, il est semblable à un homme qui regarde dans un miroir le visage qu''il tient de la nature:'),
('jc',1,24,'crampon1923','à peine s''est-il considéré, qu''il s''en est allé, oubliant aussitôt quel il était.'),
('jc',1,25,'crampon1923','Celui, au contraire, qui fixe son regard sur la loi parfaite, la loi de liberté, et qui l''y tient attaché, n''écoutant pas pour oublier aussitôt, mais pratiquant ce qu''il a entendu, celui-là trouvera son bonheur en l''accomplissant.'),
('jc',1,26,'crampon1923','Si quelqu''un s''imagine être religieux sans mettre un frein à sa langue, il s''abuse lui-même et sa religion est vaine.'),
('jc',1,27,'crampon1923','La religion pure et sans tache devant notre Dieu et Père, n''est pas autre qu''avoir soin des orphelins et des veuves dans leur détresse, et se préserver pur des souillures de ce monde.'),
('jc',2,1,'crampon1923','Mes frères, n''alliez aucune acception de personnes avec la foi en Jésus-Christ notre Seigneur de gloire.'),
('jc',2,2,'crampon1923','Si, par exemple, il entre dans votre assemblée un homme qui ait un anneau d''or et un vêtement magnifique, et qu''il y entre aussi un pauvre avec un habit sordide;'),
('jc',2,3,'crampon1923','et que tournant vos regards vers celui qui est magnifiquement vêtu, vous lui disiez: " Vous, asseyez-vous ici, à cette place d''honneur ", et que vous disiez au pauvre: " Toi, tiens-toi là debout, ou assieds-toi ici, au bas de mon marchepied: "'),
('jc',2,4,'crampon1923','n''est-ce pas faire entre vous des distinctions, et vous établir juges aux pensées perverses?'),
('jc',2,5,'crampon1923','Ecoutez, mes frères bien-aimés: Dieu n''a-t-il pas choisi ceux qui sont pauvres aux yeux du monde, pour être riches dans la foi et héritiers du royaume qu''il a promis à ceux qui l''aiment?'),
('jc',2,6,'crampon1923','Et vous, vous faites affront au pauvre! Ne sont-ce pas les riches qui vous oppriment et qui vous traînent devant les tribunaux?'),
('jc',2,7,'crampon1923','Ne sont-ce pas eux qui outragent le beau nom que vous portez?'),
('jc',2,8,'crampon1923','Que si vous accomplissez la loi royale, selon ce passage de l''Ecriture: " Tu aimeras ton prochain comme toi-même ", vous faites bien.'),
('jc',2,9,'crampon1923','Mais si vous faites acception des personnes, vous commettez un péché, et la loi elle-même vous condamne comme transgresseurs.'),
('jc',2,10,'crampon1923','Car quiconque aura observé toute la loi, s''il vient à faillir en un seul point, est coupable de tous.'),
('jc',2,11,'crampon1923','En effet, celui qui a dit: " Tu ne commettras point d''adultère ", a dit aussi: " Tu ne tueras point. " Si donc tu tues, quoique tu ne commettes point d''adultère, tu es transgresseur de la loi.'),
('jc',2,12,'crampon1923','Parlez et agissez comme devant être jugés par la loi de liberté.'),
('jc',2,13,'crampon1923','Car le jugement sera sans miséricorde pour celui qui n''aura pas fait miséricorde; la miséricorde triomphe du jugement.'),
('jc',2,14,'crampon1923','Que sert-il, mes frères, à un homme de dire qu''il a la foi, s''il n''a pas les œuvres? Est-ce que cette foi pourra le sauver?'),
('jc',2,15,'crampon1923','Si un frère ou une sœur sont dans la nudité et n''ont pas ce qui leur est nécessaire chaque jour de nourriture,'),
('jc',2,16,'crampon1923','et que l''un de vous leur dise: " Allez en paix, chauffez-vous et vous rassasiez ", sans leur donner ce qui est nécessaire à leur corps, à quoi cela sert-il?'),
('jc',2,17,'crampon1923','Il en est de même de la foi: si elle n''a pas les œuvres, elle est morte en elle-même.'),
('jc',2,18,'crampon1923','Mais on pourrait même dire: " Tu as la foi, et moi, j''ai les œuvres. " Montre-moi ta foi sans les œuvres et moi, je te montrerai ma foi par mes œuvres.'),
('jc',2,19,'crampon1923','Tu crois qu''il y a un seul Dieu, tu fais bien; les démons le croient aussi..., et ils tremblent!'),
('jc',2,20,'crampon1923','Mais veux-tu te convaincre, ô homme vain, que la foi sans les œuvres est sans vertu?'),
('jc',2,21,'crampon1923','Abraham, notre père, ne fut-il pas justifié par les œuvres, lorsqu''il offrit son fils Isaac sur l''autel?'),
('jc',2,22,'crampon1923','Tu vois que la foi coopérait à ses œuvres, et que par les œuvres sa foi fut rendue parfaite.'),
('jc',2,23,'crampon1923','Et la parole de l''Ecriture s''accomplit: " Abraham crut à Dieu, et cela lui fut imputé à justice ", et il fut appelé ami de Dieu.'),
('jc',2,24,'crampon1923','Vous voyez que l''homme est justifié par les œuvres, et non par la foi seulement.'),
('jc',2,25,'crampon1923','De même Rahab, la courtisane, ne fut-elle pas justifiée par les œuvres, quand elle reçut les envoyés de Josué et les fit partir par un autre chemin?'),
('jc',2,26,'crampon1923','De même que le corps sans âme est mort, ainsi la foi sans les œuvres est morte.'),
('jc',3,1,'crampon1923','Mes frères, qu''il n''y en ait pas tant parmi vous qui s''érigent en docteurs, sachant que nous serons jugés plus sévèrement.'),
('jc',3,2,'crampon1923','Car nous péchons tous en beaucoup de choses. Si quelqu''un ne pèche pas en parole, c''est un homme parfait, capable de tenir aussi tout le corps en bride.'),
('jc',3,3,'crampon1923','Si nous mettons aux chevaux un mors dans la bouche pour nous en faire obéir, nous gouvernons aussi leur corps tout entier.'),
('jc',3,4,'crampon1923','Voyez encore les vaisseaux: tout grands qu''ils sont et quoique poussés par des vents impétueux, ils sont conduits par un très petit gouvernail au gré du pilote qui les dirige.'),
('jc',3,5,'crampon1923','Ainsi la langue est un tout petit membre; mais de quelles grandes choses elle peut se vanter! Voyez, une étincelle peut embraser une grande forêt!'),
('jc',3,6,'crampon1923','La langue aussi est un feu, un monde d''iniquité. N''étant qu''un de nos membres, la langue est capable d''infecter tout le corps; elle enflamme le cours de notre vie, enflammée qu''elle est elle-même du feu de l''enfer.'),
('jc',3,7,'crampon1923','Toutes les espèces de quadrupèdes, d''oiseaux, de reptiles et d''animaux marins peuvent se dompter, et ont été domptés par l''homme.'),
('jc',3,8,'crampon1923','Mais la langue, aucun homme ne peut la dompter: c''est un fléau qu''on ne peut arrêter; elle est remplie d''un venin mortel.'),
('jc',3,9,'crampon1923','Par elle nous bénissons le Seigneur et notre Père, et par elle nous maudissons les hommes qui ont été faits à l''image de Dieu.'),
('jc',3,10,'crampon1923','De la même bouche sortent la malédiction et la bénédiction! Il ne faut pas, mes frères, qu''il en soit ainsi.'),
('jc',3,11,'crampon1923','Est-ce que de la même ouverture, la source fait jaillir le doux et l''amer?'),
('jc',3,12,'crampon1923','Est-ce qu''un figuier, mes frères, peut produire des olives, ou la vigne des figues? Ainsi une source salée ne peut donner de l''eau douce.'),
('jc',3,13,'crampon1923','Qui parmi vous est sage et intelligent? Qu''il fasse voir à l''œuvre dans la suite d''une bonne vie sa modération et sa sagesse.'),
('jc',3,14,'crampon1923','Mais si vous avez dans vos cœurs un zèle amer et un esprit de dispute, ne vous glorifiez point et ne mentez point contre la vérité.'),
('jc',3,15,'crampon1923','Une pareille sagesse ne descend pas d''en haut; elle est terrestre, charnelle, diabolique.'),
('jc',3,16,'crampon1923','Car là où il y a jalousie et esprit de contention, là est le trouble et toute action mauvaise.'),
('jc',3,17,'crampon1923','Mais la sagesse d''en haut est premièrement pure, ensuite pacifique, condescendante, traitable, pleine de miséricorde et de bons fruits, sans partialité, sans hypocrisie.'),
('jc',3,18,'crampon1923','Le fruit de justice se sème dans la paix par ceux qui pratiquent la paix.'),
('jc',4,1,'crampon1923','D''où viennent les guerres et les luttes parmi vous? N''est-ce pas de vos passions qui combattent dans vos membres?'),
('jc',4,2,'crampon1923','Vous convoitez, et vous n''avez pas; vous êtes meurtriers, vous êtes jaloux, et vous n''arrivez pas à obtenir; vous êtes dans un état de lutte et de guerre; et vous n''obtenez pas, parce que vous ne demandez pas;'),
('jc',4,3,'crampon1923','vous demandez, et vous ne recevez pas, parce que vous demandez mal, avec l''intention de satisfaire vos passions.'),
('jc',4,4,'crampon1923','Adultères, ne savez-vous pas que l''amitié du monde c''est l''inimitié contre Dieu? Quiconque veut être ami du monde se rend ennemi de Dieu.'),
('jc',4,5,'crampon1923','Ou bien pensez-vous que l''Ecriture dise en vain: " C''est jusqu''à la jalousie que vous aime l''Esprit qu''il a mis en vous? "'),
('jc',4,6,'crampon1923','Mais il donne une grâce d''autant plus grande, selon ce que dit l''Ecriture: " Dieu résiste aux orgueilleux, et il accorde sa grâce aux humbles. "'),
('jc',4,7,'crampon1923','Soumettez-vous donc à Dieu; résistez au diable, et il s''enfuira de vous.'),
('jc',4,8,'crampon1923','Approchez-vous de Dieu, et il s''approchera de vous. Nettoyez vos mains, pécheurs; purifiez vos cœurs, hommes à l''âme double.'),
('jc',4,9,'crampon1923','Sentez votre misère; prenez le deuil, et pleurez: que votre rire se change en pleurs, et votre joie en tristesse.'),
('jc',4,10,'crampon1923','Humiliez-vous devant le Seigneur, et il vous élèvera.'),
('jc',4,11,'crampon1923','Frères, ne dites point de mal les uns des autres. Celui qui parle mal de son frère ou qui juge son frère, parle mal de la loi et juge la loi. Or, si tu juges la loi, tu n''es plus un observateur de la loi, mais tu t''en fais juge.'),
('jc',4,12,'crampon1923','Il n''y a qu''un seul législateur et qu''un seul juge, celui qui a la puissance de sauver et de perdre.'),
('jc',4,13,'crampon1923','Mais qui es-tu, toi qui juges le prochain? Eh bien donc vous qui dites: " Aujourd''hui ou demain nous irons dans telle ville, nous y séjournerons une année, nous trafiquerons, et nous ferons des profits ",'),
('jc',4,14,'crampon1923','— vous qui ne savez pas ce qui arrivera demain; —'),
('jc',4,15,'crampon1923','car qu''est-ce que votre vie? Vous êtes une vapeur qui paraît un instant et s''évanouit ensuite: — au lieu de dire: " Si le Seigneur le veut ", ou: " Si nous sommes en vie, nous ferons ceci ou cela. "'),
('jc',4,16,'crampon1923','Mais maintenant vous vous vantez dans votre présomption. Toute jactance de cette sorte est mauvaise.'),
('jc',4,17,'crampon1923','Celui donc qui sait faire ce qui est bien et qui ne le fait pas, commet un péché.'),
('jc',5,1,'crampon1923','A vous maintenant, riches! Pleurez, éclatez en sanglots à la vue des misères qui vont fondre sur vous.'),
('jc',5,2,'crampon1923','Vos richesses sont pourries, et vos vêtements sont mangés des vers.'),
('jc',5,3,'crampon1923','Votre or et votre argent se sont rouillés, et leur rouille rendra témoignage contre vous, et comme un feu dévorera vos chairs. Vous avez thésaurisé dans les derniers jours!'),
('jc',5,4,'crampon1923','Voici qu''il crie contre vous, le salaire dont vous avez frustré les ouvriers qui ont fauché vos champs, et les cris des moissonneurs sont parvenus aux oreilles du Seigneur Sabaoth.'),
('jc',5,5,'crampon1923','Vous avez vécu sur la terre dans les délices et les festins; vous avez été comme la victime qui se repaît le jour où on doit l''égorger.'),
('jc',5,6,'crampon1923','Vous avez condamné, vous avez tué le juste: il ne vous résiste point.'),
('jc',5,7,'crampon1923','Prenez donc patience, mes frères, jusqu''à l''avènement du Seigneur. Voyez: le laboureur, dans l''espérance du précieux fruit de la terre, attend patiemment jusqu''à ce qu''il reçoive la pluie de l''automne et celle du printemps.'),
('jc',5,8,'crampon1923','Vous aussi, soyez patients, et affermissez vos cœurs, car l''avènement du Seigneur est proche.'),
('jc',5,9,'crampon1923','Frères, ne vous répandez point en plaintes les uns contre les autres, de peur que vous ne soyez jugés: voici que le juge est à la porte.'),
('jc',5,10,'crampon1923','Comme modèle de générosité dans l''épreuve et de patience, prenez, frères, les prophètes qui ont parlé au nom du Seigneur.'),
('jc',5,11,'crampon1923','Voyez, nous proclamons bienheureux ceux qui ont souffert. Vous avez entendu parler de la patience de Job, et vous avez vu quelle fin le Seigneur lui a ménagée; car le Seigneur est plein de compassion et de miséricorde.'),
('jc',5,12,'crampon1923','Surtout, mes frères, ne jurez ni par le ciel, ni par la terre, ni par quelque autre serment; mais que votre oui soit oui, et que votre non soit non, afin que vous ne tombiez pas sous le coup du jugement.'),
('jc',5,13,'crampon1923','Quelqu''un parmi vous est-il dans l''affliction? qu''il prie. Est-il dans la joie? qu''il chante des cantiques.'),
('jc',5,14,'crampon1923','Quelqu''un parmi vous est-il malade? qu''il appelle les prêtres de l''Eglise et que ceux-ci prient sur lui, en l''oignant d''huile au nom du Seigneur.'),
('jc',5,15,'crampon1923','Et la prière de la foi sauvera le malade, et le Seigneur le rétablira, et s''il a commis des péchés, ils lui seront pardonnés.'),
('jc',5,16,'crampon1923','Confessez donc vos fautes l''un à l''autre, et priez les uns pour les autres, afin que vous soyez guéris; car la prière fervente du juste a beaucoup de puissance.'),
('jc',5,17,'crampon1923','Elie était un homme soumis aux mêmes misères que nous: il pria instamment qu''il ne tombât point de pluie, et la pluie ne tomba pas sur la terre pendant trois ans et six mois;'),
('jc',5,18,'crampon1923','il pria de nouveau, et le ciel donna de la pluie, et la terre produisit ses fruits.'),
('jc',5,19,'crampon1923','Mes frères, si quelqu''un d''entre vous s''est laissé entraîner loin de la vérité, et qu''un autre l''y ramène,'),
('jc',5,20,'crampon1923','sachez que celui qui ramène un pécheur de la voie où il s''égare, sauvera une âme de la mort et couvrira une multitude de péchés.'),
('1p',1,1,'crampon1923','PIERRE apôtre de Jésus-Christ, aux élus, étrangers et dispersés dans le Pont, la Galatie, la Cappadoce, l''Asie et la Bithynie,'),
('1p',1,2,'crampon1923','choisis selon la prescience de Dieu le Père, par la sanctification de l''Esprit, pour obéir à la foi et pour avoir part à l''aspersion du sang de Jésus-Christ: à vous grâce et paix de plus en plus.'),
('1p',1,3,'crampon1923','Béni soit Dieu, le Père de Notre Seigneur Jésus-Christ, qui selon sa grande miséricorde nous a régénérés par la résurrection de Jésus-Christ d''entre les morts pour une vivante espérance;'),
('1p',1,4,'crampon1923','pour un héritage incorruptible, sans souillure et inflétrissable, qui vous est réservé dans les cieux,'),
('1p',1,5,'crampon1923','à vous que la puissance de Dieu garde par la foi pour le salut, qui est prêt à se manifester au dernier moment.'),
('1p',1,6,'crampon1923','Dans cette pensée, vous tressaillez de joie, bien qu''il vous faille encore pour un peu de temps être affligés par diverses épreuves,'),
('1p',1,7,'crampon1923','afin que l''épreuve de votre foi beaucoup plus précieuse que l''or périssable que l''on ne laisse pourtant pas d''éprouver par le feu, vous soit un sujet de louange, de gloire et d''honneur lorsque se manifestera Jésus-Christ.'),
('1p',1,8,'crampon1923','Vous l''aimez sans l''avoir jamais vu; vous croyez en lui, bien que maintenant encore vous ne le voyiez pas; et vous tressaillez d''une joie ineffable, et pleine de gloire,'),
('1p',1,9,'crampon1923','sûrs que vous êtes de remporter le prix de votre foi, le salut de vos âmes.'),
('1p',1,10,'crampon1923','Ce salut a été l''objet des recherches et des méditations de ceux d''entre les prophètes dont les prédictions annoncent la grâce qui vous était destinée;'),
('1p',1,11,'crampon1923','ils cherchaient à découvrir quel temps et quelles circonstances indiquait l''Esprit du Christ qui était en eux, et qui attestait d''avance les souffrances réservées au Christ et la gloire dont elles devaient être suivies.'),
('1p',1,12,'crampon1923','Il leur a été révélé que ce n''était pas pour eux-mêmes, mais pour vous, qu''ils avaient charge de dispenser les choses que vous ont aujourd''hui annoncées ceux qui, par le Saint-Esprit envoyé du ciel, vous ont prêché l''Evangile: mystère profond, où les anges désirent plonger leurs regards.'),
('1p',1,13,'crampon1923','C''est pourquoi, ayant ceint les reins de votre esprit, soyez sobres, et tournez toute votre espérance vers cette grâce qui vous sera apportée le jour où Jésus-Christ paraîtra.'),
('1p',1,14,'crampon1923','Comme des enfants obéissants, ne vous conformez plus aux convoitises que vous suiviez autrefois, au temps de votre ignorance;'),
('1p',1,15,'crampon1923','mais à l''imitation du Saint qui vous a appelés, vous-mêmes aussi soyez saints dans toute votre conduite,'),
('1p',1,16,'crampon1923','car il est écrit: " Soyez saints, parce que je suis saint. "'),
('1p',1,17,'crampon1923','Et si vous donnez le nom de Père à celui qui, sans faire acception des personnes, juge chacun selon ses œuvres, vivez dans la crainte pendant le temps de votre séjour comme étrangers ici-bas:'),
('1p',1,18,'crampon1923','sachant que vous avez été affranchis de la vaine manière de vivre que vous teniez de vos pères, non par des choses périssables, de l''argent ou de l''or,'),
('1p',1,19,'crampon1923','mais par un sang précieux, celui de l''agneau sans défaut et sans tache, le sang du Christ,'),
('1p',1,20,'crampon1923','qui a été désigné dès avant la création du monde, et manifesté dans les derniers temps à cause de vous.'),
('1p',1,21,'crampon1923','C''est par lui que vous avez la foi en Dieu, qui l''a ressuscité des morts et qui lui a donné la gloire, en sorte que votre foi est en même temps votre espérance en Dieu.'),
('1p',1,22,'crampon1923','Puisque vous avez, en obéissant à la vérité, purifié vos âmes et que par là vous vous êtes engagés à un sincère amour fraternel, aimez-vous ardemment les uns les autres, du fond du cœur,'),
('1p',1,23,'crampon1923','régénérés que vous êtes d''un germe non corruptible mais incorruptible, par la parole de Dieu vivante et éternelle.'),
('1p',1,24,'crampon1923','Car " toute chair est comme l''herbe, et toute sa gloire comme la fleur de l''herbe: l''herbe sèche et sa fleur tombe;'),
('1p',1,25,'crampon1923','mais la parole du Seigneur demeure éternellement. " C''est cette parole dont la bonne nouvelle vous a été apportée.'),
('1p',2,1,'crampon1923','Ayant donc dépouillé toute malice et toute fausseté, la dissimulation, l''envie et toute sorte de médisance,'),
('1p',2,2,'crampon1923','comme des enfants nouvellement nés, désirez ardemment le pur lait spirituel, afin qu''il vous fasse grandir pour le salut,'),
('1p',2,3,'crampon1923','si " vous avez goûté que le Seigneur est bon. "'),
('1p',2,4,'crampon1923','Approchez-vous de lui, pierre vivante, rejetée des hommes, il est vrai, mais choisie et précieuse devant Dieu;'),
('1p',2,5,'crampon1923','et, vous-mêmes comme des pierres vivantes, entrez dans la structure de l''édifice, pour former un temple spirituel, un sacerdoce saint, afin d''offrir des sacrifices spirituels, agréables à Dieu, par Jésus-Christ.'),
('1p',2,6,'crampon1923','Car il est dit dans l''Ecriture: " Voici que je pose en Sion une pierre angulaire, choisie, précieuse, et celui qui met en elle sa confiance ne sera pas confondu. "'),
('1p',2,7,'crampon1923','A vous donc l''honneur, vous qui croyez; mais pour les incrédules, " la pierre qu''ont rejetée ceux qui bâtissaient, c''est elle qui est devenue une pierre d''angle,'),
('1p',2,8,'crampon1923','une pierre d''achoppement et un rocher de scandale ": eux qui vont se heurter contre la parole parce qu''ils n''ont pas obéi; aussi bien, c''est à cela qu''ils sont destinés.'),
('1p',2,9,'crampon1923','Mais vous, vous êtes une race choisie, un sacerdoce royal, une nation sainte, un peuple que Dieu s''est acquis afin que vous annonciez les perfections de Celui qui vous a appelés des ténèbres à son admirable lumière;'),
('1p',2,10,'crampon1923','" vous qui autrefois n''étiez pas son peuple, et qui êtes maintenant le peuple de Dieu; vous qui n''aviez pas obtenu miséricorde, et qui maintenant avez obtenu miséricorde. "'),
('1p',2,11,'crampon1923','Bien-aimés, je vous exhorte, comme des étrangers et des voyageurs, à vous garder des convoitises de la chair qui font la guerre à l''âme.'),
('1p',2,12,'crampon1923','Ayez une conduite honnête au milieu des Gentils, afin que, sur le point même où ils vous calomnient comme si vous étiez des malfaiteurs, ils arrivent, en y regardant bien, à glorifier Dieu pour vos bonnes œuvres au jour de sa visite.'),
('1p',2,13,'crampon1923','Soyez donc soumis à toute institution humaine à cause du Seigneur, soit au roi, comme souverain,'),
('1p',2,14,'crampon1923','soit aux gouverneurs, comme délégués par lui pour faire justice des malfaiteurs et approuver les gens de bien.'),
('1p',2,15,'crampon1923','Car c''est la volonté de Dieu que, par votre bonne conduite, vous fermiez la bouche aux insensés qui vous méconnaissent.'),
('1p',2,16,'crampon1923','Comportez-vous comme des hommes libres, non pas comme des hommes qui se font de la liberté un manteau pour couvrir leur malice, mais comme des serviteurs de Dieu.'),
('1p',2,17,'crampon1923','Rendez honneur à tous; aimez tous les frères; craignez Dieu; honorez le roi.'),
('1p',2,18,'crampon1923','Vous, serviteurs, soyez soumis à vos maîtres avec toutes sortes de respects, non seulement à ceux qui sont bons et doux, mais encore à ceux qui sont difficiles.'),
('1p',2,19,'crampon1923','Car c''est une chose agréable à Dieu que ce soit en vue de lui que l''on endure des peines infligées injustement.'),
('1p',2,20,'crampon1923','En effet, quel mérite y a-t-il si, après avoir fait une faute, vous supportez patiemment les coups? Mais si, après voir fait le bien, vous avez à souffrir et que vous le supportiez avec patience, voilà ce qui est agréable à Dieu.'),
('1p',2,21,'crampon1923','C''est à quoi, en effet, vous avez été appelés, puisque le Christ aussi a souffert pour vous, vous laissant un modèle, afin que vous suiviez ses traces:'),
('1p',2,22,'crampon1923','lui qui " n''a point commis de péché, et dans la bouche duquel il ne s''est point trouvé de fausseté ";'),
('1p',2,23,'crampon1923','lui qui, outragé, ne rendait point l''outrage; qui, maltraité, ne faisait point de menaces, mais s''en remettait à celui qui juge avec justice;'),
('1p',2,24,'crampon1923','qui a lui-même porté nos péchés en son corps sur le bois, afin que, morts au péché, nous vivions pour la justice; c''est " par ses meurtrissures que vous avez été guéris. "'),
('1p',2,25,'crampon1923','Car " vous étiez comme des brebis errantes ", mais maintenant vous êtes revenus à celui qui est le pasteur et l''évêque de vos âmes.'),
('1p',3,1,'crampon1923','Vous de même, femmes, soyez soumises à vos maris, afin que, s''il en est qui n''obéissent pas à la prédication, ils soient gagnés sans la prédication, par la conduite de leurs femmes,'),
('1p',3,2,'crampon1923','rien qu''en voyant votre vie chaste et pleine de respect.'),
('1p',3,3,'crampon1923','Que votre parure ne soit pas celle du dehors: les cheveux tressés avec art, les ornements d''or ou l''ajustement des habits;'),
('1p',3,4,'crampon1923','mais, parez l''homme caché du cœur, par la pureté incorruptible d''un esprit doux et paisible: telle est la vraie richesse devant Dieu.'),
('1p',3,5,'crampon1923','C''est ainsi qu''autrefois se paraient les saintes femmes qui espéraient en Dieu, étant soumises à leurs maris.'),
('1p',3,6,'crampon1923','Ainsi Sara obéissait à Abraham, le traitant de Seigneur; et vous êtes devenues ses filles, si vous faites le bien sans craindre aucune menace.'),
('1p',3,7,'crampon1923','Vous de votre côté, maris, conduisez-vous avec sagesse à l''égard de vos femmes, comme avec des êtres plus faibles, les traitant avec honneur, puisqu''elles sont avec vous héritières de la grâce qui donne la vie; afin que rien n''arrête vos prières.'),
('1p',3,8,'crampon1923','Enfin qu''il y ait entre vous union de sentiments, bonté compatissante, charité fraternelle, affection miséricordieuse, humilité.'),
('1p',3,9,'crampon1923','Ne rendez point le mal pour le mal, ni l''injure pour l''injure; bénissez, au contraire; car c''est à cela que vous avez été appelés, afin de devenir héritiers de la bénédiction.'),
('1p',3,10,'crampon1923','" Celui qui veut aimer la vie et voir des jours heureux, qu''il garde sa langue du mal, et ses lèvres des paroles trompeuses;'),
('1p',3,11,'crampon1923','qu''il se détourne du mal, et fasse le bien; qu''il cherche la paix et la poursuive.'),
('1p',3,12,'crampon1923','Car le Seigneur a les yeux sur les justes, et ses oreilles sont attentives à leurs prières; mais la face du Seigneur est contre ceux qui font le mal. "'),
('1p',3,13,'crampon1923','Et qui pourra vous faire du mal, si vous êtes appliqués à faire le bien?'),
('1p',3,14,'crampon1923','Que si pourtant vous souffrez pour la justice, heureux êtes-vous! " Ne craignez point leurs menaces et ne vous laissez point troubler;'),
('1p',3,15,'crampon1923','mais sanctifiez dans vos cœurs le Seigneur, le Christ, étant toujours prêts à répondre mais avec douceur et respect, à quiconque vous demande raison de l''espérance qui est en vous;'),
('1p',3,16,'crampon1923','ayant une bonne conscience, afin que, sur le point même où l''on vous calomnie, vous couvriez de confusion ceux qui diffament votre bonne conduite dans le Christ.'),
('1p',3,17,'crampon1923','En effet, il vaut mieux souffrir, si Dieu le veut ainsi, en faisant le bien, qu''en faisant le mal.'),
('1p',3,18,'crampon1923','Aussi le Christ a souffert une fois la mort pour nos péchés, lui juste pour des injustes, afin de nous ramener à Dieu, ayant été mis à mort selon la chair, mais rendu à la vie selon l''esprit.'),
('1p',3,19,'crampon1923','C''est aussi dans cet esprit qu''il est allé prêcher aux esprits en prison,'),
('1p',3,20,'crampon1923','rebelles autrefois, lorsqu''aux jours de Noé la longanimité de Dieu temporisait, pendant que se construisait l''arche, dans laquelle un petit nombre, savoir huit personnes, furent sauvées à travers l''eau.'),
('1p',3,21,'crampon1923','C''est elle qui aujourd''hui vous sauve, vous aussi, par son antitype le baptême, non pas cette ablution qui ôte les souillures du corps, mais celle qui est la demande faite à Dieu d''une bonne conscience, par la résurrection de Jésus-Christ.'),
('1p',3,22,'crampon1923','Après être monté au ciel, il est maintenant à la droite de Dieu; à lui sont soumis les anges, les principautés et les puissances.'),
('1p',4,1,'crampon1923','Puis donc que le Christ a souffert [pour nous] en la chair, armez-vous, vous aussi, de la même pensée, savoir, que celui qui a souffert dans la chair a rompu avec le péché,'),
('1p',4,2,'crampon1923','pour vivre, pendant le temps qu''il lui reste à passer dans la chair, non plus selon les convoitises des hommes, mais selon la volonté de Dieu.'),
('1p',4,3,'crampon1923','C''est bien assez d''avoir fait autrefois la volonté des païens, en vivant dans le désordre, les convoitises, l''ivrognerie, les orgies, les excès de boisson et le culte criminel des idoles.'),
('1p',4,4,'crampon1923','Ils s''étonnent maintenant que vous ne couriez pas avec eux dans le même débordement de débauches; et ils se répandent en injures.'),
('1p',4,5,'crampon1923','Mais ils rendront compte à celui qui est prêt à juger les vivants et les morts.'),
('1p',4,6,'crampon1923','C''est pour cela que l''Évangile a été aussi annoncé aux morts, afin que, condamnés, il est vrai, selon les hommes dans la chair, ils vivent selon Dieu dans l''esprit.'),
('1p',4,7,'crampon1923','Or la fin de toutes choses est proche. Soyez donc prudents et sobres pour vaquer à la prière.'),
('1p',4,8,'crampon1923','Mais surtout ayez un ardent amour les uns pour les autres; car l''amour couvre une multitude de péchés.'),
('1p',4,9,'crampon1923','Exercez entre vous l''hospitalité sans murmurer.'),
('1p',4,10,'crampon1923','Que chacun mette au service des autres le don qu''il a reçu comme de bons dispensateurs de la grâce de Dieu, laquelle est variée. Si quelqu''un parle, que ce soit selon les oracles de Dieu;'),
('1p',4,11,'crampon1923','si quelqu''un exerce un ministère, qu''il le fasse comme par la vertu que Dieu donne, afin qu''en toutes choses Dieu soit glorifié par Jésus-Christ, à qui appartiennent la gloire et la puissance aux siècles des siècles. Amen!'),
('1p',4,12,'crampon1923','Bien-aimés, ne soyez point surpris de l''incendie qui s''est allumé au milieu de vous pour vous éprouver, comme s''il vous arrivait quelque chose d''extraordinaire.'),
('1p',4,13,'crampon1923','Mais, dans la mesure où vous avez part aux souffrances du Christ, réjouissez-vous, afin que, lorsque sa gloire sera manifestée, vous soyez aussi dans la joie et l''allégresse.'),
('1p',4,14,'crampon1923','Si vous êtes outragés pour le nom du Christ, heureux êtes-vous, parce que l''Esprit de gloire (et de puissance), l''Esprit de Dieu repose sur vous.'),
('1p',4,15,'crampon1923','Que nul d''entre vous ne souffre comme meurtrier, comme voleur ou malfaiteur, ou comme avide du bien d''autrui.'),
('1p',4,16,'crampon1923','Mais s''il souffre comme chrétien, qu''il n''en ait pas honte; plutôt, qu''il glorifie Dieu pour ce même nom.'),
('1p',4,17,'crampon1923','Car voici le temps où le jugement va commencer par la maison de Dieu. Et s''il commence par nous, quelle sera la fin de ceux qui n''obéissent pas à l''Evangile de Dieu?'),
('1p',4,18,'crampon1923','Et " si le juste est sauvé avec peine, que deviendra l''impie et le pécheur? "'),
('1p',4,19,'crampon1923','Que ceux qui souffrent selon la volonté de Dieu, lui confient leurs âmes comme au Créateur fidèle, en pratiquant le bien.'),
('1p',5,1,'crampon1923','J''exhorte les anciens qui sont parmi vous, moi ancien comme eux, témoin des souffrances du Christ, et qui prendrai part avec eux à la gloire qui doit être manifestée:'),
('1p',5,2,'crampon1923','paissez le troupeau de Dieu qui vous est confié, veillant sur lui, non par contrainte, mais de bon gré; non dans un intérêt sordide, mais par dévouement;'),
('1p',5,3,'crampon1923','non en dominateurs des Eglises, mais en devenant les modèles du troupeau.'),
('1p',5,4,'crampon1923','Et quand le Prince des pasteurs paraîtra, vous recevrez la couronne de gloire, qui ne se flétrit jamais.'),
('1p',5,5,'crampon1923','De même, vous qui êtes plus jeunes, soyez soumis aux anciens; tous, les uns à l''égard des autres, revêtez-vous d''humilité, car " Dieu résiste aux orgueilleux et donne sa grâce aux humbles. "'),
('1p',5,6,'crampon1923','Humiliez-vous donc sous la puissante main de Dieu, afin qu''il vous élève au temps marqué;'),
('1p',5,7,'crampon1923','déchargez-vous sur lui de toutes vos sollicitudes, car lui-même prend soin de vous.'),
('1p',5,8,'crampon1923','Soyez sobres, veillez; votre adversaire, le diable, comme un lion rugissant, rode autour de vous, cherchant qui dévorer.'),
('1p',5,9,'crampon1923','Résistez-lui, fermes dans la foi, sachant que vos frères dispersés dans le monde, endurent les mêmes souffrances que vous.'),
('1p',5,10,'crampon1923','Le Dieu de toute grâce, qui vous a appelés à sa gloire éternelle dans le Christ, après quelques souffrances, achèvera lui-même son œuvre, vous affermira, vous fortifiera, vous rendra inébranlables.'),
('1p',5,11,'crampon1923','A lui soient la gloire et la puissance aux siècles des siècles! Amen!'),
('1p',5,12,'crampon1923','C''est par Sylvain, un frère dont la fidélité m''est connue, que je vous écris ce peu de mots, pour vous exhorter et vous assurer que c''est bien dans la vraie grâce de Dieu que vous êtes établis.'),
('1p',5,13,'crampon1923','L''Eglise de Babylone, élue avec vous, et Marc, mon fils, vous saluent.'),
('1p',5,14,'crampon1923','Saluez-vous les uns les autres par un baiser d''amour. La paix soit avec vous tous qui êtes dans le Christ! Amen!'),
('2p',1,1,'crampon1923','Simon Pierre, serviteur et apôtre de Jésus-Christ, à ceux qui avec nous ont reçu le précieux don de la foi dans la justice de notre Dieu et du Sauveur Jésus-Christ:'),
('2p',1,2,'crampon1923','que la grâce et la paix croissent en vous de plus en plus par la connaissance de Dieu et de Jésus-Christ Notre-Seigneur!'),
('2p',1,3,'crampon1923','Puisque sa divine puissance nous a accordé tous les dons qui regardent la vie et la piété, en nous faisant connaître celui qui nous a appelés par sa propre gloire et par sa vertu,'),
('2p',1,4,'crampon1923','et qui par elles nous a mis en possession de si grandes et si précieuses promesses, afin de vous rendre ainsi participants de la nature divine, en vous soustrayant à la corruption de la convoitise qui règne dans le monde.'),
('2p',1,5,'crampon1923','A cause de cela même, apportez de votre côté tous vos soins pour unir à votre foi la vertu, à la vertu le discernement,'),
('2p',1,6,'crampon1923','au discernement la tempérance, à la tempérance la patience, à la patience la piété,'),
('2p',1,7,'crampon1923','à la piété l''amour fraternel, à l''amour fraternel la charité.'),
('2p',1,8,'crampon1923','Si ces vertus sont en vous et y abondent, elles ne vous laisseront ni oisifs ni stériles pour la connaissance de Notre-Seigneur Jésus-Christ.'),
('2p',1,9,'crampon1923','Car celui à qui elles font défaut est un homme qui a la vue courte, un aveugle; il a oublié la façon dont il a été purifié de ses anciens péchés.'),
('2p',1,10,'crampon1923','C''est pourquoi, mes frères, appliquez-vous d''autant plus à assurer par vos bonnes œuvres votre vocation et votre élection; car, en agissant ainsi, vous ne ferez jamais de faux pas.'),
('2p',1,11,'crampon1923','Et ainsi vous sera largement donnée l''entrée dans le royaume de notre Seigneur et Sauveur Jésus-Christ.'),
('2p',1,12,'crampon1923','Voilà pourquoi j''aurai à cœur de vous rappeler constamment ces choses, bien que vous les connaissiez et que vous soyez affermis dans la vérité présente.'),
('2p',1,13,'crampon1923','Je crois de mon devoir, aussi longtemps que je suis dans cette tente, de vous tenir en éveil par mes avertissements;'),
('2p',1,14,'crampon1923','car je sais que je la quitterai bientôt, ainsi que Notre-Seigneur Jésus-Christ me l''a fait connaître.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('2p',1,15,'crampon1923','Je veux aussi faire en sorte que vous puissiez toujours, après mon départ, vous remettre ces choses en mémoire.'),
('2p',1,16,'crampon1923','Ce n''est pas, en effet, sur la foi de fables ingénieusement imaginées que nous vous avons fait connaître la puissance et l''avènement de Notre-Seigneur Jésus-Christ, mais en témoins oculaires de sa majesté.'),
('2p',1,17,'crampon1923','En effet, il reçut honneur et gloire de Dieu le Père, lorsque de la gloire magnifique une voix se fit entendre qui disait: " Celui-ci est mon Fils bien-aimé en qui j''ai mis toutes mes complaisances. "'),
('2p',1,18,'crampon1923','Et nous, nous entendîmes cette voix venue du ciel, lorsque nous étions avec lui sur la montagne sainte.'),
('2p',1,19,'crampon1923','Et ainsi a été confirmée pour nous l''Ecriture prophétique, à laquelle vous faites bien de prêter attention, comme à une lampe qui brille dans un lieu obscur, jusqu''à ce que le jour vienne à poindre et que l''étoile du matin se lève dans vos cœurs.'),
('2p',1,20,'crampon1923','Mais sachez avant tout qu''aucune prophétie de l''Ecriture ne procède d''une interprétation propre,'),
('2p',1,21,'crampon1923','car ce n''est pas par une volonté d''homme qu''une prophétie a jamais été apportée, mais c''est poussés par l''Esprit-Saint que les saints hommes de Dieu ont parlé.'),
('2p',2,1,'crampon1923','Or, comme parmi le peuple il y eut aussi de faux prophètes, de même il y aura parmi vous de faux docteurs, qui introduiront sourdement des sectes pernicieuses, et qui, reniant le Seigneur qui les a rachetés, attireront sur eux une prompte ruine.'),
('2p',2,2,'crampon1923','Plusieurs les suivront dans leurs désordres, et ils exposeront la doctrine de la vérité à être calomniée.'),
('2p',2,3,'crampon1923','Par cupidité, ils trafiqueront de vous avec des paroles artificieuses; mais leur condamnation depuis longtemps ne se repose point, et leur ruine ne s''endort point.'),
('2p',2,4,'crampon1923','Si Dieu, en effet, n''a pas épargné les anges qui avaient péché, mais les a précipités dans l''enfer et les a livrés aux abîmes des ténèbres, où il les garde pour le jugement;'),
('2p',2,5,'crampon1923','s''il n''a pas épargné l''ancien monde, mais en préservant Noé, lui huitième, comme prédicateur de la justice, lorsqu''il fit venir le déluge sur un monde d''impies;'),
('2p',2,6,'crampon1923','s''il a condamné à une totale destruction et réduit en cendres les villes de Sodome et de Gomorrhe, pour servir d''exemple aux impies à venir,'),
('2p',2,7,'crampon1923','et s''il a délivré le juste Lot, affligé de la conduite de ces scélérats'),
('2p',2,8,'crampon1923','(car, à cause de ce qu''il voyait et de ce qu''il entendait, ce juste, continuant à habiter au milieu d''eux, avait chaque jour son âme vertueuse tourmentée de leurs œuvres iniques): —'),
('2p',2,9,'crampon1923','c''est que le Seigneur sait délivrer de l''épreuve les hommes pieux, et réserver les méchants pour être punis au jour du jugement,'),
('2p',2,10,'crampon1923','mais surtout ceux qui s''abandonnent aux impures convoitises de la chair, et méprisent la souveraineté. Audacieux et arrogants, ils ne craignent pas de blasphémer les gloires,'),
('2p',2,11,'crampon1923','quand des anges, supérieurs en force et en puissance, ne portent pas [devant le Seigneur], de jugement injurieux contre elles.'),
('2p',2,12,'crampon1923','Mais eux, semblables à des animaux stupides, destinés par leur nature à être pris et à périr, ils se répandent en injures contre ce qu''ils ignorent, et ils périront aussi par leur propre corruption:'),
('2p',2,13,'crampon1923','ce sera le salaire de leur iniquité. Leur félicité est de passer chaque jour dans les délices; ils ne sont que tache, et que honte, ils se font un plaisir de vous tromper, en faisant bonne chère avec vous.'),
('2p',2,14,'crampon1923','Ils ont les yeux pleins d''adultère, insatiables de péché; ils prennent à leurs amorces les âmes inconstantes; ils ont le cœur exercé à la cupidité: ce sont des enfants de malédiction.'),
('2p',2,15,'crampon1923','Ils ont quitté le droit chemin, et se sont égarés en suivant la voie de Balaam, fils de Bosor, qui aima le salaire de l''iniquité,'),
('2p',2,16,'crampon1923','mais qui fut repris de sa désobéissance: une bête de somme, muette, faisant entendre une voix humaine, réprima la folie du prophète.'),
('2p',2,17,'crampon1923','Ce sont des fontaines sans eau, des nuées agitées par un tourbillon: la profondeur des ténèbres leur est réservée.'),
('2p',2,18,'crampon1923','Avec leurs théories pompeuses et vides, ils attirent dans les convoitises de la chair, dans le libertinage, ceux qui s''étaient à peine retirés des hommes nourris dans l''erreur.'),
('2p',2,19,'crampon1923','Ils leur promettent la liberté, quand eux-mêmes sont esclaves de la corruption; car on est esclave de celui par qui on s''est laissé vaincre.'),
('2p',2,20,'crampon1923','Car si ceux qui, par la connaissance de notre Seigneur et Sauveur Jésus-Christ, s''étaient retirés de la corruption du monde, se laissent vaincre en s''y engageant de nouveau, leur dernier état devient pire que le premier.'),
('2p',2,21,'crampon1923','En effet mieux valait pour eux n''avoir pas connu la voie de la justice, que de retourner en arrière, après l''avoir connue, en abandonnant la loi sainte qui leur avait été enseignée.'),
('2p',2,22,'crampon1923','Il leur est arrivé ce que dit un proverbe avec beaucoup de vérité: " Le chien est retourné à son propre vomissement " et: " La truie lavée s''est vautrée dans le bourbier. "'),
('2p',3,1,'crampon1923','Mes bien-aimés, voici déjà la seconde lettre que je vous écris: dans l''une et dans l''autre, je m''adresse à vos souvenirs, pour exciter votre saine intelligence'),
('2p',3,2,'crampon1923','à se rappeler les choses annoncées d''avance par les saints prophètes, et le commandement du Seigneur et Sauveur, enseigné par vos apôtres.'),
('2p',3,3,'crampon1923','Sachez avant tout que, dans les derniers temps, il viendra des moqueurs pleins de raillerie, vivant au gré de leurs convoitises,'),
('2p',3,4,'crampon1923','et disant: " Où est la promesse de son avènement? Car depuis que nos pères sont morts, tout continue à subsister comme depuis le commencement de la création ".'),
('2p',3,5,'crampon1923','Ils veulent ignorer que, dès l''origine, des cieux existaient, ainsi qu''une terre que la parole de Dieu avait fait surgir du sein de l''eau, au moyen de l''eau,'),
('2p',3,6,'crampon1923','et que par là même monde d''alors périt submergé.'),
('2p',3,7,'crampon1923','Quant aux cieux et à la terre d''à présent, la même parole de Dieu les tient en réserve et les garde pour le feu, au jour du jugement et de la ruine des hommes impies.'),
('2p',3,8,'crampon1923','Mais il est une chose, bien-aimés, que vous ne devez pas ignorer, c''est que, pour le Seigneur, un jour est comme mille ans, " et mille ans sont comme un jour ".'),
('2p',3,9,'crampon1923','Non, le Seigneur ne retarde pas l''accomplissement de sa promesse, comme quelques-uns se l''imaginent; mais il use de patience envers vous, ne voulant pas qu''aucun périsse, mais que tous viennent à la pénitence.'),
('2p',3,10,'crampon1923','Cependant le jour du Seigneur viendra comme un voleur; en ce jour, les cieux passeront avec fracas, les éléments embrasés se dissoudront, et la terre sera consumée avec les ouvrages qu''elle renferme.'),
('2p',3,11,'crampon1923','Puis donc que toutes choses sont destinées à se dissoudre, quelles ne doivent pas être la sainteté de votre conduite et votre piété,'),
('2p',3,12,'crampon1923','attendant et hâtant l''avènement du jour de Dieu, auquel les cieux enflammés se dissoudront, et les éléments embrasés se fondront?'),
('2p',3,13,'crampon1923','Mais nous attendons, selon sa promesse, " de nouveaux cieux et une nouvelle terre ", où la justice habite.'),
('2p',3,14,'crampon1923','Dans cette attente, bien-aimés, faites tous vos efforts afin d''être trouvés par lui sans tache et irréprochables dans la paix.'),
('2p',3,15,'crampon1923','Croyez que la longue patience de Notre-Seigneur est pour votre salut, ainsi que Paul, notre bien-aimé frère, vous l''a aussi écrit, selon la sagesse qui lui a été donnée.'),
('2p',3,16,'crampon1923','C''est ce qu''il fait dans toutes les lettres où il aborde ces sujets; il s''y rencontre des passages difficiles à entendre, et que des personnes ignorantes et mal affermies détournent, comme elles font les autres Ecritures, pour leur perdition,'),
('2p',3,17,'crampon1923','Vous donc, bien-aimés, qui êtes prévenus, tenez-vous sur vos gardes, de peur qu''entraînés par l''égarement de ces impies, vous ne veniez à déchoir de votre propre fermeté.'),
('2p',3,18,'crampon1923','Mais croissez dans la grâce et dans la connaissance de notre Seigneur et Sauveur Jésus-Christ. A lui soit la gloire, maintenant et jusqu''au jour de l''éternité! Amen!'),
('1jn',1,1,'crampon1923','Ce qui était dès le commencement, ce que nous avons entendu, ce que nous avons vu de nos yeux, ce que nous avons contemplé et ce que nos mains ont touché, du Verbe de vie, —'),
('1jn',1,2,'crampon1923','car la Vie a été manifestée, et nous l''avons vue, et nous lui rendons témoignage, et nous vous annonçons la Vie éternelle, qui était dans le sein du Père et qui nous a été manifestée —'),
('1jn',1,3,'crampon1923','ce que nous avons vu et entendu, nous vous l''annonçons, afin que vous aussi vous soyez en communion avec nous, et que notre communion soit avec le Père et avec son Fils Jésus-Christ.'),
('1jn',1,4,'crampon1923','Et nous vous écrivons ces choses, afin que votre joie soit complète.'),
('1jn',1,5,'crampon1923','Le message qu''il nous a fait entendre, et que nous vous annonçons à notre tour, c''est que Dieu est lumière, et qu''il n''y a point en lui de ténèbres.'),
('1jn',1,6,'crampon1923','Si nous disons que nous sommes en communion avec lui, et que nous marchions dans les ténèbres, nous mentons, et nous ne pratiquons pas la vérité.'),
('1jn',1,7,'crampon1923','Mais si nous marchons dans la lumière, comme il est lui-même dans la lumière, nous sommes en communion les uns avec les autres, et le sang de Jésus[-Christ], son Fils, nous purifie de tout péché.'),
('1jn',1,8,'crampon1923','Si nous disons que nous sommes sans péché, nous nous séduisons nous-mêmes, et la vérité n''est point en nous.'),
('1jn',1,9,'crampon1923','Si nous confessons nos péchés, Dieu est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité.'),
('1jn',1,10,'crampon1923','Si nous disons que nous sommes sans péché, nous le faisons menteur, et sa parole n''est point en nous.'),
('1jn',2,1,'crampon1923','Mes petits enfants, je vous écris ces choses, afin que vous ne péchiez point. Et si quelqu''un a péché, nous avons un avocat auprès du Père, Jésus-Christ, le juste.'),
('1jn',2,2,'crampon1923','Il est lui-même une victime de propitiation pour nos péchés, non seulement pour les nôtres, mais pour ceux du monde entier.'),
('1jn',2,3,'crampon1923','Et voici par quoi nous savons que nous le connaissons: si nous gardons ses commandements.'),
('1jn',2,4,'crampon1923','Celui qui dit le connaître et ne garde pas ses commandements, est un menteur, et la vérité n''est point en lui.'),
('1jn',2,5,'crampon1923','Mais celui qui garde sa parole, c''est en lui véritablement que l''amour de Dieu est parfait; par là nous connaissons que nous sommes en lui.'),
('1jn',2,6,'crampon1923','Celui qui dit demeurer en lui doit lui aussi marcher comme il a marché lui-même.'),
('1jn',2,7,'crampon1923','Mes bien-aimés, ce n''est pas un commandement nouveau que je vous écris, c''est un commandement ancien, que vous avez reçu dès le commencement; ce commandement ancien, c''est la parole que vous avez entendue.'),
('1jn',2,8,'crampon1923','D''un autre côté, c''est un commandement nouveau que je vous écris, lequel s''est vérifié en Jésus-Christ et en vous, car les ténèbres se dissipent et déjà brille la véritable lumière.'),
('1jn',2,9,'crampon1923','Celui qui dit être dans la lumière et qui hait son frère est encore dans les ténèbres.'),
('1jn',2,10,'crampon1923','Celui qui aime son frère, demeure dans la lumière, et il n''y a en lui aucun sujet de chute.'),
('1jn',2,11,'crampon1923','Mais celui qui hait son frère est dans les ténèbres; il marche dans les ténèbres, sans savoir où il va, parce que les ténèbres ont aveuglé ses yeux.'),
('1jn',2,12,'crampon1923','Je vous écris, petits enfants, parce que vos péchés vous sont remis à cause de son nom.'),
('1jn',2,13,'crampon1923','Je vous écris, pères, parce que vous avez connu celui qui est dès le commencement. Je vous écris, jeunes gens, parce que vous avez vaincu le malin.'),
('1jn',2,14,'crampon1923','Je vous ai écrit, petits enfants, parce que vous avez connu le Père. Je vous ai écrit, pères, parce que vous avez connu celui qui est dès le commencement. Je vous ai écrit, jeunes gens, parce que vous êtes forts et que la parole de Dieu demeure en vous, et que vous avez vaincu le malin.'),
('1jn',2,15,'crampon1923','N''aimez point le monde, ni ce qui est dans le monde. Si quelqu''un aime le monde, l''amour du Père n''est point en lui.'),
('1jn',2,16,'crampon1923','Car tout ce qui est dans le monde, la concupiscence de la chair, la concupiscence des yeux, et l''orgueil de la vie, ne vient point du Père, mais du monde.'),
('1jn',2,17,'crampon1923','Le monde passe, et sa concupiscence aussi; mais celui qui fait la volonté de Dieu demeure éternellement.'),
('1jn',2,18,'crampon1923','Mes petits enfants, c''est la dernière heure. Comme vous avez appris que l''antéchrist doit venir, aussi y a-t-il maintenant plusieurs antéchrists: par là nous connaissons que c''est la dernière heure.'),
('1jn',2,19,'crampon1923','Ils sont sortis du milieu de nous, mais ils n''étaient pas des nôtres; car s''ils eussent été des nôtres, ils seraient demeurés avec nous; mais ils en sont sortis, afin qu''il soit manifeste que tous ne sont pas des nôtres.'),
('1jn',2,20,'crampon1923','Pour vous, c''est du Saint que vous avez reçu l''onction, et vous connaissez tout.'),
('1jn',2,21,'crampon1923','Je vous ai écrit, non que vous ne connaissiez pas la vérité, mais parce que vous la connaissez, et que vous savez qu''aucun mensonge ne vient de la vérité.'),
('1jn',2,22,'crampon1923','Qui est le menteur, sinon celui qui nie que Jésus est le Christ? Celui-là est l''antéchrist, qui nie le Père et le Fils.'),
('1jn',2,23,'crampon1923','Quiconque nie le Fils, n''a pas non plus le Père; celui qui confesse le Fils, a aussi le Père.'),
('1jn',2,24,'crampon1923','Pour vous, que ce que vous avez entendu dès le commencement demeure en vous. Si ce que vous avez entendu dès le commencement demeure en vous, vous demeurez aussi dans le Fils et dans le Père.'),
('1jn',2,25,'crampon1923','Et la promesse que lui-même nous a faite, c''est la vie éternelle.'),
('1jn',2,26,'crampon1923','Voilà ce que j''avais à vous écrire sur ceux qui vous séduisent.'),
('1jn',2,27,'crampon1923','Pour vous, l''onction que vous avez reçue de lui demeure en vous, et vous n''avez pas besoin que personne vous enseigne; mais comme son onction vous enseigne sur toute chose, cet enseignement est véritable et n''est point un mensonge; et selon qu''elle vous a enseignés, demeurez en lui.'),
('1jn',2,28,'crampon1923','Et maintenant, mes petits enfants, demeurez en lui, afin que, lorsqu''il paraîtra, nous ayons de l''assurance, et que nous ne soyons pas, à son avènement, rejetés loin de lui avec confusion.'),
('1jn',2,29,'crampon1923','Si vous savez qu''il est juste, reconnaissez que quiconque pratique la justice est né de lui.'),
('1jn',3,1,'crampon1923','Voyez quel amour le Père nous a témoigné, que nous soyons appelés enfants de Dieu, et que nous le soyons en effet! Si le monde ne nous connaît pas, c''est qu''il ne l''a pas connu.'),
('1jn',3,2,'crampon1923','Mes bien-aimés, nous sommes maintenant enfants de Dieu, et ce que nous serons un jour n''a pas encore été manifesté; mais nous savons qu''au temps de cette manifestation, nous lui serons semblables, parce que nous le verrons tel qu''il est.'),
('1jn',3,3,'crampon1923','Quiconque a cette espérance en lui, se rend pur, comme lui-même est pur.'),
('1jn',3,4,'crampon1923','Quiconque commet le péché transgresse la loi, et le péché est la transgression de la loi.'),
('1jn',3,5,'crampon1923','Or vous savez que Jésus a paru pour ôter les péchés, et que le péché n''est point en lui.'),
('1jn',3,6,'crampon1923','Quiconque demeure en lui ne pèche point; quiconque pèche, ne l''a pas vu et ne l''a pas connu.'),
('1jn',3,7,'crampon1923','Petits enfants, que personne ne vous séduise. Celui qui pratique la justice est juste, comme lui-même est juste.'),
('1jn',3,8,'crampon1923','Celui qui commet le péché est du diable, car le diable pèche dès le commencement. C''est pour détruire les œuvres du diable que le Fils de Dieu a paru.'),
('1jn',3,9,'crampon1923','Quiconque est né de Dieu ne commet point le péché, parce que la semence de Dieu demeure en lui; et il ne peut pécher, parce qu''il est né de Dieu.'),
('1jn',3,10,'crampon1923','C''est à cela que l''on reconnaît les enfants de Dieu et les enfants du diable. Quiconque ne pratique pas la justice n''est pas de Dieu, non plus que celui qui n''aime pas son frère.'),
('1jn',3,11,'crampon1923','Car le message que vous avez entendu dès le commencement, c''est que nous nous aimions les uns les autres;'),
('1jn',3,12,'crampon1923','non point comme Caïn, qui était du malin et qui tua son frère. Et pourquoi le tua-t-il? Parce que ses œuvres étaient mauvaises, tandis que celles de son frère étaient justes.'),
('1jn',3,13,'crampon1923','Ne vous étonnez pas, mes frères, si le monde vous hait.'),
('1jn',3,14,'crampon1923','Nous, nous savons que nous sommes passés de la mort à la vie, parce que nous aimons nos frères. Celui qui n''aime pas demeure dans la mort.'),
('1jn',3,15,'crampon1923','Quiconque hait son frère est un meurtrier, et vous savez qu''aucun meurtrier n''a la vie éternelle demeurant en lui.'),
('1jn',3,16,'crampon1923','A ceci nous avons connu l''amour, c''est que Lui a donné sa vie pour nous. Nous aussi, nous devons donner notre vie pour nos frères.'),
('1jn',3,17,'crampon1923','Si quelqu''un possède les biens de ce monde et que, voyant son frère dans la nécessité, il lui ferme ses entrailles, comment l''amour de Dieu demeure-t-il en lui?'),
('1jn',3,18,'crampon1923','Mes petits enfants, n''aimons pas de parole et de langue, mais en action et en vérité.'),
('1jn',3,19,'crampon1923','Par là nous connaissons que nous sommes de la vérité, et nous pouvons rassurer nos cœurs devant Dieu;'),
('1jn',3,20,'crampon1923','car si notre cœur nous condamne, Dieu est plus grand que notre cœur, et il connaît toutes choses.'),
('1jn',3,21,'crampon1923','Mes bien-aimés, si notre cœur ne nous condamne pas, nous pouvons nous adresser à Dieu avec assurance.'),
('1jn',3,22,'crampon1923','Quoi que ce soit que nous demandions, nous le recevons de lui, parce que nous gardons ses commandements, et que nous faisons ce qui est agréable à ses yeux.'),
('1jn',3,23,'crampon1923','Et son commandement est que nous croyions au nom de son Fils, Jésus-Christ, et que nous nous aimions les uns les autres, comme il nous en a donné le commandement.'),
('1jn',3,24,'crampon1923','Celui qui garde ses commandements, demeure en Dieu et Dieu en lui, et nous connaissons qu''il demeure en nous par l''Esprit qu''il nous a donné.'),
('1jn',4,1,'crampon1923','Mes bien-aimés, ne croyez pas à tout esprit; mais voyez par l''épreuve si les esprits sont de Dieu, car plusieurs faux prophètes sont venus dans le monde.'),
('1jn',4,2,'crampon1923','Vous reconnaîtrez à ceci l''esprit de Dieu: tout esprit qui confesse Jésus-Christ venu en chair est de Dieu;'),
('1jn',4,3,'crampon1923','et tout esprit qui ne confesse pas ce Jésus n''est pas de Dieu: c''est celui de l''antéchrist; dont on vous a annoncé la venue, et qui maintenant est déjà dans le monde.'),
('1jn',4,4,'crampon1923','Vous, mes petits enfants, vous êtes de Dieu, et vous les avez vaincus, parce que celui qui est en vous est plus grand que celui qui est dans le monde.'),
('1jn',4,5,'crampon1923','Eux, ils sont du monde; c''est pourquoi ils parlent le langage du monde, et le monde les écoute.'),
('1jn',4,6,'crampon1923','Mais nous, nous sommes de Dieu; celui qui connaît Dieu nous écoute; celui qui n''est pas de Dieu ne nous écoute point: c''est par là que nous connaissons l''esprit de la vérité et l''esprit de l''erreur.'),
('1jn',4,7,'crampon1923','Mes bien-aimés, aimons-nous les uns les autres, car l''amour vient de Dieu, et quiconque aime est né de Dieu et connaît Dieu.'),
('1jn',4,8,'crampon1923','Celui qui n''aime pas n''a pas connu Dieu, car Dieu est amour.'),
('1jn',4,9,'crampon1923','Il a manifesté son amour pour nous en envoyant son Fils unique dans le monde, afin que nous vivions par lui.'),
('1jn',4,10,'crampon1923','Et cet amour consiste en ce que ce n''est pas nous qui avons aimé Dieu, mais lui qui nous a aimés et qui a envoyé son Fils comme victime de propitiation pour nos péchés.'),
('1jn',4,11,'crampon1923','Mes bien-aimés, si Dieu nous a ainsi aimés, nous devons aussi nous aimer les uns les autres.'),
('1jn',4,12,'crampon1923','Personne n''a jamais vu Dieu; mais si nous nous aimons les uns les autres, Dieu demeure en nous, et son amour est parfait en nous.'),
('1jn',4,13,'crampon1923','Nous connaissons que nous demeurons en lui et qu''il demeure en nous, en ce qu''il nous donne de son Esprit.'),
('1jn',4,14,'crampon1923','Et nous, nous avons contemplé et nous attestons que le Père nous a envoyé le Fils comme Sauveur du monde.'),
('1jn',4,15,'crampon1923','Celui qui confessera que Jésus est le Fils de Dieu, Dieu demeure en lui et lui en Dieu.'),
('1jn',4,16,'crampon1923','Et nous, nous avons connu l''amour que Dieu a pour nous, et nous y avons cru. Dieu est amour; et celui qui demeure dans l''amour demeure en Dieu, et Dieu demeure en lui.'),
('1jn',4,17,'crampon1923','La perfection de l''amour en nous, c''est que nous ayons une confiance assurée au jour du jugement; car tel est Jésus-Christ, tels nous sommes aussi dans ce monde.'),
('1jn',4,18,'crampon1923','Il n''y a point de crainte dans l''amour; mais l''amour parfait bannit la crainte, car la crainte suppose un châtiment; celui qui craint n''est pas parfait dans l''amour.'),
('1jn',4,19,'crampon1923','Nous donc, aimons Dieu, puisque Dieu nous a aimés le premier.'),
('1jn',4,20,'crampon1923','Si quelqu''un dit: " J''aime Dieu ", et qu''il haïsse son frère, c''est un menteur; comment celui qui n''aime pas son frère qu''il voit, peut-il aimer Dieu qu''il ne voit pas?'),
('1jn',4,21,'crampon1923','Et nous avons reçu de lui ce commandement: " Que celui qui aime Dieu aime aussi son frère. "'),
('1jn',5,1,'crampon1923','Quiconque croit que Jésus est le Christ, est né de Dieu; et quiconque aime celui qui l''a engendré, aime aussi celui qui est né de lui.'),
('1jn',5,2,'crampon1923','A cette marque nous connaissons que nous aimons les enfants de Dieu, si nous aimons Dieu, et si nous observons ses commandements.'),
('1jn',5,3,'crampon1923','Car c''est aimer Dieu que de garder ses commandements. Et ses commandements ne sont pas pénibles,'),
('1jn',5,4,'crampon1923','parce que tout ce qui est né de Dieu remporte la victoire sur le monde; et la victoire qui a vaincu le monde, c''est notre foi.'),
('1jn',5,5,'crampon1923','Qui est celui qui est vainqueur du monde, sinon celui qui croit que Jésus est le Fils de Dieu?'),
('1jn',5,6,'crampon1923','C''est ce même Jésus-Christ qui est venu par l''eau et par le sang, non avec l''eau seulement, mais avec l''eau et avec le sang. Et c''est l''Esprit qui rend témoignage, parce que l''Esprit est la vérité.'),
('1jn',5,7,'crampon1923','Car il y en a trois qui rendent témoignage [dans le ciel: le Père, le Verbe et l''Esprit; et ces trois sont un.'),
('1jn',5,8,'crampon1923','Et il y en a trois qui rendent témoignage sur la terre]: l''Esprit, l''eau et le sang; et ces trois sont d''accord.'),
('1jn',5,9,'crampon1923','Si nous recevons le témoignage des hommes, le témoignage de Dieu est plus grand; et c''est bien là le témoignage de Dieu, qui a rendu témoignage à son Fils.'),
('1jn',5,10,'crampon1923','Celui qui croit au Fils de Dieu a ce témoignage (de Dieu) en lui-même; celui qui ne croit pas Dieu, le fait menteur, puisqu''il n''a pas cru au témoignage que Dieu a rendu à son Fils.'),
('1jn',5,11,'crampon1923','Et voici ce témoignage, c''est que, Dieu nous a donné la vie éternelle, et que cette vie est dans son Fils.'),
('1jn',5,12,'crampon1923','Celui qui a le Fils a la vie; celui qui n''a pas le Fils de Dieu n''a pas la vie.'),
('1jn',5,13,'crampon1923','Je vous ai écrit ces choses, afin que vous sachiez que vous avez la vie éternelle, vous qui croyez au nom du Fils de Dieu.'),
('1jn',5,14,'crampon1923','Et nous avons auprès de Dieu cette pleine confiance, que, si nous demandons quelque chose selon sa volonté, il nous écoute.'),
('1jn',5,15,'crampon1923','Et si nous savons qu''il nous écoute, quelque chose que nous lui demandions, nous savons que nous obtenons ce que nous avons demandé.'),
('1jn',5,16,'crampon1923','Si quelqu''un voit son frère commettre un péché qui ne va pas à la mort, qu''il prie, et Dieu donnera la vie à ce frère, [à tous ceux dont le péché ne va pas à la mort]. Il y a tel péché qui va à la mort; ce n''est point pour ce péché-là que je dis de prier.'),
('1jn',5,17,'crampon1923','Toute iniquité est un péché, et il y a tel péché qui ne va pas à la mort.'),
('1jn',5,18,'crampon1923','Nous savons que quiconque est né de Dieu ne pèche point; mais celui qui est né de Dieu se garde lui-même, et le malin ne le touche pas.'),
('1jn',5,19,'crampon1923','Nous savons que nous sommes de Dieu et que le monde entier est plongé dans le mal.'),
('1jn',5,20,'crampon1923','Mais nous savons que le Fils de Dieu est venu, et qu''il nous a donné l''intelligence pour connaître le vrai Dieu, et nous sommes en ce vrai Dieu, étant en son Fils Jésus-Christ. C''est lui qui est le Dieu véritable et la vie éternelle.'),
('1jn',5,21,'crampon1923','Mes petits-enfants, gardez-vous des idoles.'),
('2jn',1,1,'crampon1923','Moi, l''Ancien à l''élue Kyria et à ses enfants, que j''aime dans la vérité, — non pas moi seulement, mais aussi tous ceux qui ont connu la vérité, —'),
('2jn',1,2,'crampon1923','en considération de la vérité qui demeure en nous, et qui sera éternellement avec nous:'),
('2jn',1,3,'crampon1923','la grâce, la miséricorde et la paix soient avec vous de la part de Dieu le Père et de la part de Jésus-Christ, le Fils du Père, dans la vérité et la charité!'),
('2jn',1,4,'crampon1923','J''ai eu bien de la joie de rencontrer de tes enfants qui marchent dans la vérité, selon le commandement que nous avons reçu du Père.'),
('2jn',1,5,'crampon1923','Et maintenant je te le demande, Kyria, — non comme si je te prescrivais un commandement nouveau; car c''est celui que nous avons reçu dès le commencement, — aimons-nous les uns les autres.'),
('2jn',1,6,'crampon1923','L''amour consiste à marcher selon ses commandements; et, c''est là son commandement, comme vous l''avez appris dès le commencement, de marcher dans la charité.'),
('2jn',1,7,'crampon1923','Car plusieurs séducteurs ont paru dans le monde; ils ne confessent point Jésus comme Christ venu en chair: c''est là le séducteur et l''antéchrist.'),
('2jn',1,8,'crampon1923','Prenez garde à vous-mêmes, afin que vous ne perdiez pas le fruit de votre travail, mais que vous receviez une pleine récompense.'),
('2jn',1,9,'crampon1923','Quiconque va au delà et ne demeure pas dans la doctrine du Christ, ne possède point Dieu; celui qui demeure dans cette doctrine possède le Père et le Fils.'),
('2jn',1,10,'crampon1923','Si quelqu''un vient à vous et n''apporte point cette doctrine, ne le recevez pas dans votre maison, et ne lui dites pas: Salut!'),
('2jn',1,11,'crampon1923','Car celui qui lui dit: Salut! participe à ses œuvres mauvaises.'),
('2jn',1,12,'crampon1923','Quoique j''eusse beaucoup de choses à vous écrire, je n''ai pas voulu le faire avec le papier et l''encre; mais j''espère aller chez vous et vous entretenir de vive voix, afin que votre joie soit parfaite.'),
('2jn',1,13,'crampon1923','Les enfants de ta sœur l''élue te saluent.'),
('3jn',1,1,'crampon1923','Moi l''Ancien, à Gaïus, le bien-aimé que j''aime dans la vérité.'),
('3jn',1,2,'crampon1923','Bien-aimé, sur toutes choses je souhaite que l''état de tes affaires et de ta santé soit aussi prospère que celui de ton âme.'),
('3jn',1,3,'crampon1923','J''ai eu bien de la joie, lorsque des frères sont arrivés et ont rendu témoignage de ta vérité, je veux dire de la manière dont tu marches dans la vérité.'),
('3jn',1,4,'crampon1923','Je n''ai pas de plus grande joie que d''apprendre que mes enfants marchent dans la vérité.'),
('3jn',1,5,'crampon1923','Bien-aimé, tu agis fidèlement dans tout ce que tu fais pour les frères, et particulièrement pour des frères étrangers;'),
('3jn',1,6,'crampon1923','aussi ont-ils rendu témoignage de ta charité en présence de l''Eglise. Tu feras bien de pourvoir à leur voyage d''une manière digne de Dieu;'),
('3jn',1,7,'crampon1923','car c''est pour son nom qu''ils sont partis, sans rien recevoir des païens.'),
('3jn',1,8,'crampon1923','Nous devons soutenir de tels hommes, afin de travailler avec eux pour la vérité.'),
('3jn',1,9,'crampon1923','J''ai écrit à l''Eglise; mais Diotréphès, qui aime à primer parmi eux, ne nous reçoit pas.'),
('3jn',1,10,'crampon1923','C''est pourquoi, quand je viendrai, je lui mettrai devant les yeux les actes qu''il fait, et les méchants propos qu''il tient contre nous. Et non content de cela, il refuse lui-même d''accueillir les frères, et il empêche ceux qui voudraient les recevoir et les chasse de l''église.'),
('3jn',1,11,'crampon1923','Bien-aimé, n''imite pas le mal, mais imite le bien. Celui qui fait le bien est de Dieu; celui qui fait le mal n''a point vu Dieu.'),
('3jn',1,12,'crampon1923','Tout le monde, et la vérité elle-même, rendent un bon témoignage à Démétrius; nous le lui rendons aussi, et tu sais que notre témoignage est vrai.'),
('3jn',1,13,'crampon1923','J''aurais beaucoup de choses à t''écrire, mais je ne veux pas le faire avec l''encre et la plume:'),
('3jn',1,14,'crampon1923','j''espère te voir bientôt, et nous nous entretiendrons de vive voix. La paix soit avec toi! Nos amis te saluent. Salue nos amis, chacun en particulier.'),
('3jn',1,15,'crampon1923',''),
('jude',1,1,'crampon1923','Jude serviteur de Jésus-Christ et frère de Jacques, aux élus qui ont été aimés en Dieu le Père, et gardés pour Jésus-Christ:'),
('jude',1,2,'crampon1923','la miséricorde, la paix et l''amour vous soient donnés pleinement.'),
('jude',1,3,'crampon1923','Bien-aimés, comme je mettais tout mon zèle à vous écrire au sujet de notre salut commun, je me suis vu dans la nécessité de vous adresser cette lettre, pour vous exhorter à combattre pour la foi qui a été transmise aux saints une fois pour toutes.'),
('jude',1,4,'crampon1923','Car il s''est glissé parmi vous certains hommes, dont il a été écrit depuis longtemps qu''ils encouraient cette condamnation, hommes impies, qui changent la grâce de notre Dieu en licence, et qui renient notre seul Maître et Seigneur Jésus-Christ.'),
('jude',1,5,'crampon1923','Je veux vous rappeler ce que vous avez autrefois appris, que Jésus, après avoir sauvé son peuple de la terre d''Egypte, fit périr ensuite ceux qui furent incrédules;'),
('jude',1,6,'crampon1923','et qu''il retint pour le jugement du grand jour, liés de chaînes éternelles, au sein des ténèbres, les anges qui n''ont pas conservé leur principauté, mais qui ont abandonné leur propre demeure.'),
('jude',1,7,'crampon1923','De même Sodome et Gomorrhe, et les villes voisines qui se livrèrent à la même sorte d''impudicité et abusèrent d''une chair étrangère, gisent là en exemple, subissant la peine d''un feu éternel.'),
('jude',1,8,'crampon1923','Cependant, ces hommes eux aussi, dans leur délire, souillent pareillement leur chair, méprisent la souveraineté et injurient les gloires.'),
('jude',1,9,'crampon1923','L''archange Michel lui-même, lorsqu''il contestait avec le diable et lui disputait le corps de Moïse, n''osa pas porter contre lui une sentence d''exécration, mais il se contenta de dire: " Que le Seigneur te punisse! "'),
('jude',1,10,'crampon1923','Mais ceux-ci, ils blasphèment tout ce qu''ils ignorent, et quant à ce qu''ils connaissent naturellement, comme les bêtes sans raison, ils s''y corrompent.'),
('jude',1,11,'crampon1923','Malheur à eux! car ils sont entrés dans la voie de Caïn, ils se sont jetés pour un salaire dans l''égarement de Balaam, ils se sont perdus par la révolte de Coré?'),
('jude',1,12,'crampon1923','Ils sont des écueils dans vos agapes, où ils font impudemment bonne chère, ne songeant qu''à se repaître eux-mêmes; nuées sans eau, emportées au hasard par les vents; arbres d''automne sans fruits, deux fois morts, déracinés;'),
('jude',1,13,'crampon1923','vagues furieuses de la mer; jetant l''écume de leurs hontes; astres errants, auxquels d''épaisses ténèbres sont réservées pour l''éternité.'),
('jude',1,14,'crampon1923','C''est d''eux aussi qu''Enoch, le septième patriarche depuis Adam, a prophétisé en ces termes: " Voici que le Seigneur est venu avec la multitude innombrable de ses saints,'),
('jude',1,15,'crampon1923','pour exécuter son jugement sur tous, et convaincre tous les impies de toutes les œuvres d''impiété qu''ils ont commises et de toutes les paroles criminelles qu''eux, pécheurs impies, ont proférées contre lui. "'),
('jude',1,16,'crampon1923','Ce sont des gens qui murmurent et se plaignent sans cesse de leur sort, qui vivent au gré de leurs convoitises, ont la bouche remplie de paroles pompeuses, et qui par intérêt se font admirateurs d''autrui.'),
('jude',1,17,'crampon1923','Pour vous, bien-aimés, souvenez-vous de ce qui vous a été annoncé d''avance par les Apôtres de Notre-Seigneur Jésus-Christ.'),
('jude',1,18,'crampon1923','Ils vous disaient qu''au dernier temps il y aurait des hommes moqueurs, vivant au gré de leurs convoitises impies,'),
('jude',1,19,'crampon1923','gens qui provoquent des divisions, hommes sensuels qui n''ont pas l''esprit.'),
('jude',1,20,'crampon1923','Pour vous, bien-aimés, vous édifiant vous-même sur le fondement de votre très sainte foi, et priant dans le Saint-Esprit,'),
('jude',1,21,'crampon1923','conservez-vous dans l''amour de Dieu, attendant la miséricorde de Notre-Seigneur Jésus-Christ, pour la vie éternelle.'),
('jude',1,22,'crampon1923','Il en est qu''il faut confondre comme déjà séparés de vous;'),
('jude',1,23,'crampon1923','d''autres, sauvez-les en les arrachant au feu; pour les autres, ayez-en pitié, mais avec crainte, haïssant jusqu''à la tunique souillée par la chair.'),
('jude',1,24,'crampon1923','A celui qui a le pouvoir de vous préserver de toute chute et de vous faire paraître irrépréhensibles et pleins d''allégresse devant le trône de sa gloire,'),
('jude',1,25,'crampon1923','au seul Dieu notre Sauveur, par Jésus-Christ, Notre-Seigneur, soient gloire, majesté, force et empire dès avant tous les temps, et maintenant, et dans tous les siècles! Amen!'),
('ap',1,1,'crampon1923','RÉVÉLATION de Jésus-Christ, que Dieu lui a confiée pour découvrir à ses serviteurs les événements qui doivent arriver bientôt; et qu''il a fait connaître, en l''envoyant par son ange, à Jean, son serviteur,'),
('ap',1,2,'crampon1923','qui a attesté la parole de Dieu et le témoignage de Jésus-Christ en tout ce qu''il a vu.'),
('ap',1,3,'crampon1923','Heureux celui qui lit et ceux qui entendent les paroles de cette prophétie, et qui gardent les choses qui y sont écrites, car le temps est proche!'),
('ap',1,4,'crampon1923','Jean aux sept Eglises qui sont en Asie: grâce et paix vous soient données de la part de Celui qui est, qui était et qui vient,'),
('ap',1,5,'crampon1923','et de la part des sept esprits qui sont devant son trône, et de la part de Jésus-Christ; c''est le Témoin fidèle, le Premier-né d''entre les morts et le Prince des rois de la terre. A celui qui nous a aimés, qui nous a lavés de nos péchés par son sang,'),
('ap',1,6,'crampon1923','et qui nous a faits rois et prêtres de Dieu, son Père, à lui la gloire et la puissance des siècles des siècles! Amen!'),
('ap',1,7,'crampon1923','Le voici qui vient sur les nuées. Tout œil le verra, et ceux même qui l''ont percé; et toutes les tribus de la terre se frapperont la poitrine en le voyant. Oui. Amen!'),
('ap',1,8,'crampon1923','" Je suis l''alpha et l''oméga " [le commencement et la fin], dit le Seigneur Dieu, celui qui est, qui était et qui vient, le Tout-Puissant.'),
('ap',1,9,'crampon1923','Moi Jean, votre frère, qui participe avec vous, à l''affliction, à la royauté et à la patience en Jésus [-Christ], j''étais dans l''île appelée Patmos, à cause de la parole de Dieu et du témoignage de Jésus.'),
('ap',1,10,'crampon1923','Je fus ravi en esprit le jour du Seigneur, et j''entendis derrière moi une voix forte, comme une trompette,'),
('ap',1,11,'crampon1923','qui disait: " Ce que tu vois, écris-le dans un livre, et envoie-le aux sept Eglises qui sont en Asie: à Ephèse, à Smyrne, à Pergame, à Thyatire, à Sardes, à Philadelphie et à Laodicée. "'),
('ap',1,12,'crampon1923','Alors je me retournai pour voir quelle était la voix qui me parlait; et quand je me fus retourné, je vis sept chandeliers d''or,'),
('ap',1,13,'crampon1923','et, au milieu des chandeliers, quelqu''un qui ressemblait à un fils d''homme: il était vêtu d''une longue robe, portait à la hauteur des seins une ceinture d''or;'),
('ap',1,14,'crampon1923','sa tête et ses cheveux étaient blancs comme de la laine blanche, comme de la neige, et ses yeux étaient comme une flamme de feu;'),
('ap',1,15,'crampon1923','ses pieds étaient semblables à de l''airain qu''on aurait embrasé dans une fournaise, et sa voix était comme la voix des grandes eaux.'),
('ap',1,16,'crampon1923','Il tenait dans sa main droite sept étoiles; de sa bouche sortait un glaive aigu, à deux tranchants, et son visage était comme le soleil lorsqu''il brille dans sa force.'),
('ap',1,17,'crampon1923','Quand je le vis, je tombai à ses pieds comme mort; et il posa sur moi sa main droite, en disant: " Ne crains point; je suis le Premier et le Dernier,'),
('ap',1,18,'crampon1923','et le Vivant; j''ai été mort, et voici que je suis vivant aux siècles des siècles; je tiens les clefs de la mort et de l''enfer.'),
('ap',1,19,'crampon1923','Ecris donc les choses que tu as vues, et celles qui sont, et celles qui doivent arriver ensuite,'),
('ap',1,20,'crampon1923','le mystère des sept étoiles que tu as vues dans ma main droite, et les sept chandeliers d''or. Les sept étoiles sont les anges des sept Eglises, et les sept chandeliers sont sept Eglises. "'),
('ap',2,1,'crampon1923','Ecris à l''ange de l''Eglise d''Ephèse: Voici ce que dit Celui qui tient les sept étoiles dans sa main droite, Celui qui marche au milieu des sept chandeliers d''or:'),
('ap',2,2,'crampon1923','Je connais tes œuvres, ton labeur et ta patience; je sais que tu ne peux supporter les méchants; que tu as éprouvé ceux qui se disent apôtres et ne le sont pas, et que tu les as trouvés menteurs;'),
('ap',2,3,'crampon1923','que tu as de la patience, que tu as eu à supporter pour mon nom, et que tu ne t''es point lassé.'),
('ap',2,4,'crampon1923','Mais j''ai contre toi que tu t''es relâché de ton premier amour.'),
('ap',2,5,'crampon1923','Souviens-toi donc d''où tu es tombé, repens-toi et reviens à tes premières œuvres; sinon, je viendrai à toi, et j''ôterai ton chandelier de sa place, à moins que tu ne te repentes.'),
('ap',2,6,'crampon1923','Pourtant tu as en ta faveur que tu hais les œuvres des Nicolaïtes, œuvres que moi aussi je hais.'),
('ap',2,7,'crampon1923','Que celui qui a des oreilles entende ce que l''Esprit dit aux Eglises! A celui qui vaincra, je lui donnerai à manger de l''arbre de vie, qui est dans le paradis de [mon] Dieu.'),
('ap',2,8,'crampon1923','Ecris encore à l''ange de l''Eglise de Smyrne: Voici ce que dit le Premier et le Dernier, Celui qui était mort et qui a repris vie:'),
('ap',2,9,'crampon1923','Je connais ta tribulation et ta pauvreté, — mais tu es riche, — et les insultes de ceux qui se disent Juifs et ne le sont pas, mais bien une synagogue de Satan.'),
('ap',2,10,'crampon1923','Ne crains rien de ce que tu auras à souffrir. Voici que le diable va jeter quelques-uns de vous en prison, afin que vous soyez mis à l''épreuve, et vous aurez une tribulation de dix jours. Sois fidèle jusqu''à la mort et je te donnerai la couronne de la vie.'),
('ap',2,11,'crampon1923','Que celui qui a des oreilles entende ce que l''Esprit dit aux Eglises! Celui qui vaincra ne recevra aucun dommage de la seconde mort.'),
('ap',2,12,'crampon1923','Ecris encore à l''ange de l''Eglise de Pergame: Voici ce que dit Celui qui a le glaive aigu à deux tranchants:'),
('ap',2,13,'crampon1923','Je sais où tu habites: là où se trouve le trône de Satan; mais tu es fermement attaché à mon nom, et tu n''as point renié ma foi, même en ces jours où Antipas, mon témoin fidèle, a été mis à mort chez vous, où Satan habite.'),
('ap',2,14,'crampon1923','Mais j''ai contre toi quelques griefs; c''est que tu as là des gens attachés à la doctrine de Balaam, qui conseillait à Balac de mettre devant les fils d''Israël une pierre d''achoppement, pour les amener à manger des viandes immolées aux idoles et à se livrer à l''impudicité.'),
('ap',2,15,'crampon1923','De même toi aussi, tu as des gens attachés pareillement à la doctrine des Nicolaïtes.'),
('ap',2,16,'crampon1923','Repens-toi! sinon, je viendrai à toi promptement, et je leur ferai la guerre avec le glaive de ma bouche.'),
('ap',2,17,'crampon1923','Que celui qui a des oreilles entende ce que dit l''Esprit aux Eglises! A celui qui vaincra, je donnerai de la manne cachée; et je lui donnerai une pierre blanche, et sur cette pierre est écrit un nom nouveau, que personne ne connaît, si ce n''est celui qui le reçoit.'),
('ap',2,18,'crampon1923','Ecris encore à l''ange de l''Eglise de Thyatire: Voici ce que dit le Fils de Dieu, Celui qui a les yeux comme une flamme de feu, et dont les pieds sont semblables à l''airain:'),
('ap',2,19,'crampon1923','Je connais tes œuvres, ton amour, ta foi, ta bienfaisance, ta patience et tes dernières œuvres plus nombreuses que les premières.'),
('ap',2,20,'crampon1923','Mais j''ai contre toi quelques griefs: c''est que tu laisses la femme Jézabel, se disant prophétesse, enseigner et séduire mes serviteurs, pour qu''ils se livrent à l''impudicité et mangent des viandes immolées aux idoles.'),
('ap',2,21,'crampon1923','Je lui ai donné du temps pour faire pénitence, et elle ne veut pas se repentir de son impudicité.'),
('ap',2,22,'crampon1923','Voici que je vais la jeter sur un lit, et plonger dans une grande tristesse ses compagnons d''adultère, s''ils ne se repentent des œuvres qu''elle leur a enseignées.'),
('ap',2,23,'crampon1923','Je frapperai de mort ses enfants, et toutes les Eglises connaîtront que je suis celui qui sonde les reins et les cœurs; et je rendrai à chacun de vous selon vos œuvres.'),
('ap',2,24,'crampon1923','Mais à vous, aux autres fidèles de Thyatire, qui ne reçoivent pas cette doctrine, qui n''ont pas connu les profondeurs de Satan (comme ils les appellent), je vous dis: Je ne vous imposerai pas d''autre fardeau;'),
('ap',2,25,'crampon1923','seulement, tenez ferme ce que vous avez, jusqu''à ce que je vienne.'),
('ap',2,26,'crampon1923','Et à celui qui vaincra et qui gardera jusqu''à la fin mes œuvres, je lui donnerai pouvoir sur les nations;'),
('ap',2,27,'crampon1923','il les gouvernera avec un sceptre de fer, ainsi que l''on brise les vases d''argile,'),
('ap',2,28,'crampon1923','comme moi-même j''en ai reçu le pouvoir de mon Père, et je lui donnerai l''étoile du matin.'),
('ap',2,29,'crampon1923','Que celui qui a des oreilles entende ce que l''Esprit dit aux Eglises!'),
('ap',3,1,'crampon1923','Ecris encore à l''ange de l''Eglise de Sardes: Voici ce que dit Celui qui a les sept Esprits de Dieu et les sept étoiles: Je connais tes œuvres: tu as la réputation d''être vivant, mais tu es mort.'),
('ap',3,2,'crampon1923','Sois vigilant, et affermis le reste qui allait mourir; car je n''ai pas trouvé tes œuvres parfaites devant mon Dieu.'),
('ap',3,3,'crampon1923','Souviens-toi donc de l''enseignement que tu as reçu et entendu; garde-le et repens-toi. Si donc tu ne veilles pas, je viendrai à toi comme un voleur, sans que tu aies su à quelle heure je viendrai à toi.'),
('ap',3,4,'crampon1923','Pourtant tu as à Sardes quelques personnes qui n''ont pas souillé leurs vêtements; ceux-là marcheront avec moi en vêtements blancs, parce qu''ils en sont dignes.'),
('ap',3,5,'crampon1923','Celui qui vaincra sera ainsi revêtu de vêtements blancs; je n''effacerai point son nom du livre de la vie, et je confesserai son nom devant mon Père et devant ses anges.'),
('ap',3,6,'crampon1923','Que celui qui a des oreilles entende ce que l''Esprit dit aux Eglises!'),
('ap',3,7,'crampon1923','Ecris encore à l''ange de l''Eglise de Philadelphie: Voici ce que dit le saint, le Véritable, Celui qui a la clef de David, Celui qui ouvre et personne ne ferme, qui ferme et personne n''ouvre:'),
('ap',3,8,'crampon1923','Je connais tes œuvres. Voici que j''ai mis devant toi une porte ouverte, que personne ne peut fermer, parce que tu as peu de puissance, que tu as gardé ma parole et que tu n''as point renié mon nom.'),
('ap',3,9,'crampon1923','Voici que je te donne quelques-uns de la synagogue de Satan, qui se disent Juifs, et ne le sont point, mais ils mentent; voici, je les ferai venir se prosterner à tes pieds, et ils connaîtront que je t''ai aimé.'),
('ap',3,10,'crampon1923','Parce que tu as gardé ma parole sur la patience, moi aussi je te garderai de l''heure de l''épreuve qui va venir sur le monde entier, pour éprouver les habitants de la terre.'),
('ap',3,11,'crampon1923','Voici que je viens bientôt: tiens ferme ce que tu as, afin que personne ne ravisse ta couronne.'),
('ap',3,12,'crampon1923','Celui qui vaincra, j''en ferai une colonne dans le temple de mon Dieu, et il n''en sortira plus; et j''écrirai sur lui le nom de mon Dieu, et le nom de la ville de mon Dieu, de la nouvelle Jérusalem, qui descend du ciel d''auprès de mon Dieu, et mon nom nouveau.'),
('ap',3,13,'crampon1923','Que celui qui a des oreilles entende ce que l''Esprit dit aux Eglises!'),
('ap',3,14,'crampon1923','Ecris encore à l''ange de l''Eglise de Laodicée: Voici ce que dit l''Amen, le Témoin fidèle et véritable, le Principe de la création de Dieu:'),
('ap',3,15,'crampon1923','Je connais tes œuvres: tu n''es ni froid ni chaud. Plût à Dieu que tu fusses froid ou chaud!'),
('ap',3,16,'crampon1923','Aussi, parce que tu es tiède et que tu n''es ni froid ni chaud, je vais te vomir de ma bouche.'),
('ap',3,17,'crampon1923','Tu dis: Je suis riche, j''ai acquis de grands biens, je n''ai besoin de rien; et tu ne sais pas que tu es un malheureux, un misérable, pauvre, aveugle et nu,'),
('ap',3,18,'crampon1923','je te conseille de m''acheter de l''or éprouvé par le feu, afin que tu deviennes riche; des vêtements blancs pour te vêtir et ne pas laisser paraître la honte de ta nudité; et un collyre pour oindre tes yeux, afin que tu voies.'),
('ap',3,19,'crampon1923','Moi, je reprends et je châtie tous ceux que j''aime; aie donc du zèle et repens-toi.'),
('ap',3,20,'crampon1923','Voici que je me tiens à la porte et je frappe: si quelqu''un entend ma voix et ouvre la porte, j''entrerai chez toi, je souperai avec lui et lui avec moi.'),
('ap',3,21,'crampon1923','Celui qui vaincra, je le ferai asseoir avec moi sur mon trône comme moi aussi j''ai vaincu et me suis assis avec mon Père sur son trône.'),
('ap',3,22,'crampon1923','Que celui qui a des oreilles entende ce que l''Esprit dit aux Eglises!'),
('ap',4,1,'crampon1923','Après cela, je vis, et voici qu''une porte était ouverte dans le ciel, et la première voix que j''avais entendue, comme le son d''une trompette qui me parlait, dit: " Monte ici, et je te montrerai ce qui doit arriver dans la suite. "'),
('ap',4,2,'crampon1923','Aussitôt je fus ravi en esprit; et voici qu''un trône était dressé dans le ciel, et sur ce trône quelqu''un était assis.'),
('ap',4,3,'crampon1923','Celui qui était assis avait un aspect semblable à la pierre de jaspe et de sardoine; et le trône était entouré d''un arc-en-ciel, d''une apparence semblable à l''émeraude.'),
('ap',4,4,'crampon1923','Autour du trône étaient vingt-quatre trônes, et sur ces trônes vingt-quatre vieillards assis, revêtus de vêtements blancs, avec des couronnes d''or sur leurs têtes.'),
('ap',4,5,'crampon1923','Du trône sortent des éclairs, des voix et des tonnerres; et sept lampes ardentes brûlent devant le trône: ce sont les sept Esprits de Dieu.'),
('ap',4,6,'crampon1923','En face du trône, il y a comme une mer de verre semblable à du cristal; et devant le trône et autour du trône, quatre animaux remplis d''yeux devant et derrière.'),
('ap',4,7,'crampon1923','Le premier animal ressemble à un lion, le second à un jeune taureau, le troisième a comme la face d''un homme, et le quatrième ressemble à un aigle qui vole.'),
('ap',4,8,'crampon1923','Ces quatre animaux ont chacun six ailes; ils sont couverts d''yeux tout à l''entour et au dedans, et ils ne cessent jour et nuit de dire: " Saint, saint, saint est le Seigneur, le Dieu Tout-Puissant, qui était, qui est et qui vient! "'),
('ap',4,9,'crampon1923','Quand les animaux rendent gloire, honneur et actions de grâces à Celui qui est assis sur le trône, à Celui qui vit aux siècles des siècles,'),
('ap',4,10,'crampon1923','les vingt-quatre vieillards se prosternent devant Celui qui est assis sur le trône, et adorent Celui qui vit aux siècles des siècles, et ils jettent leurs couronnes devant le trône, en disant:'),
('ap',4,11,'crampon1923','" Vous êtes digne, notre Seigneur et notre Dieu, de recevoir la gloire et l''honneur, et la puissance, car c''est vous qui avez créé toutes choses, et c''est à cause de votre volonté qu''elles ont eu l''existence et qu''elles ont été créées. "'),
('ap',5,1,'crampon1923','Puis je vis dans la main droite de Celui qui était assis sur le trône un livre écrit en dedans et en dehors, et scellé de sept sceaux.'),
('ap',5,2,'crampon1923','Et je vis un ange puissant qui criait d''une voix forte: " Qui est digne d''ouvrir le livre et d''en rompre les sceaux? "'),
('ap',5,3,'crampon1923','Et personne ni dans le ciel, ni sur la terre, ne pouvait ouvrir le livre ni le regarder.'),
('ap',5,4,'crampon1923','Et moi je pleurais beaucoup de ce qu''il ne se trouvait personne qui fût digne d''ouvrir le livre, ni de le regarder.'),
('ap',5,5,'crampon1923','Alors un des vieillards me dit: " Ne pleure point; voici que le lion de la tribu de Juda, le rejeton de David, a vaincu, de manière à pouvoir ouvrir le livre et ses sept sceaux. "'),
('ap',5,6,'crampon1923','Et je vis, et voici qu''au milieu du trône et des quatre animaux, et au milieu des vieillards, un Agneau était debout: il semblait avoir été immolé; il avait sept cornes et sept yeux, qui sont les sept Esprits de Dieu envoyés par toute la terre.'),
('ap',5,7,'crampon1923','Il vint, et reçut le livre de la main droite de Celui qui était assis sur le trône.'),
('ap',5,8,'crampon1923','Quand il eut reçu le livre, les quatre animaux et les vingt-quatre vieillards se prosternèrent devant l''Agneau, tenant chacun une harpe et des coupes d''or pleines de parfums, qui sont les prières des saints.'),
('ap',5,9,'crampon1923','Et ils chantaient un cantique nouveau, en disant: " Vous êtes digne de recevoir le livre et d''en ouvrir les sceaux; car vous avez été immolé et vous avez racheté pour Dieu, par votre sang, des hommes de toute tribu, de toute langue, de tout peuple et de toute nation;'),
('ap',5,10,'crampon1923','et vous les avez faits rois et prêtres, et ils régneront sur la terre. "'),
('ap',5,11,'crampon1923','Puis je vis, et j''entendis autour du trône, autour des animaux et des vieillards, la voix d''une multitude d''anges, et leur nombre était des myriades et des milliers de milliers.'),
('ap',5,12,'crampon1923','Ils disaient d''une voix forte: " L''Agneau qui a été immolé est digne de recevoir la puissance, la richesse, la sagesse, la force, l''honneur, la gloire et la bénédiction. "'),
('ap',5,13,'crampon1923','Et toutes les créatures qui sont dans le ciel, sur la terre, sous la terre et dans la mer, et toutes les choses qui s''y trouvent, je les entendis qui disaient: " A Celui qui est assis sur le trône et à l''Agneau, louange, honneur, gloire et puissance dans les siècles des siècles! "'),
('ap',5,14,'crampon1923','Et les quatre animaux disaient: " Amen! " Et les vieillards se prosternèrent et adorèrent [Celui qui vit aux siècles des siècles].'),
('ap',6,1,'crampon1923','Et je vis l''Agneau qui ouvrit le premier des sept sceaux, et j''entendis l''un des quatre animaux qui disait comme d''une voix de tonnerre: " Viens! "'),
('ap',6,2,'crampon1923','Et je vis paraître un cheval blanc. Celui qui le montait avait un arc; on lui donna une couronne, et il partit en vainqueur et pour vaincre.'),
('ap',6,3,'crampon1923','Et quand il eut ouvert le deuxième sceau, j''entendis le second animal qui disait: " Viens! "'),
('ap',6,4,'crampon1923','Et il sortit un autre cheval qui était roux. Celui qui le montait reçut le pouvoir d''ôter la paix de la terre, afin que les hommes s''égorgeassent les uns les autres, et on lui donna une grande épée.'),
('ap',6,5,'crampon1923','Et quand il eut ouvert le troisième sceau, j''entendis le troisième animal qui disait: " Viens! " Et je vis paraître un cheval noir. Celui qui le montait tenait à la main une balance;'),
('ap',6,6,'crampon1923','et j''entendis au milieu des quatre animaux comme une voix qui disait: " Une mesure de blé pour un denier! Trois mesures d''orge pour un denier! " Et: " Ne gâte pas l''huile et le vin! "'),
('ap',6,7,'crampon1923','Et quand il eut ouvert le quatrième sceau, j''entendis la voix du quatrième animal qui disait: " Viens! "'),
('ap',6,8,'crampon1923','Et je vis paraître un cheval de couleur pâle. Celui qui le montait se nommait la Mort, et l''Enfer le suivait. On leur donna pouvoir sur la quatrième partie de la terre, pour faire tuer par l''épée, par la famine, par la mortalité et par les bêtes féroces de la terre.'),
('ap',6,9,'crampon1923','Et quand il eut ouvert le cinquième sceau, je vis sous l''autel les âmes de ceux qui avaient été immolés pour la parole de Dieu et pour le témoignage qu''ils avaient eu à rendre.'),
('ap',6,10,'crampon1923','Et ils crièrent d''une voix forte, en disant: " Jusques à quand, ô Maître Saint et Véritable, ne ferez-vous pas justice et ne redemanderez-vous pas notre sang à ceux qui habitent sur la terre? "'),
('ap',6,11,'crampon1923','Alors on leur donna à chacun une robe blanche, et on leur dit de se tenir en repos encore un peu de temps, jusqu''à ce que fût complet le nombre de leurs compagnons de service et de leurs frères qui devaient être mis à mort comme eux.'),
('ap',6,12,'crampon1923','Et je vis, quand il eut ouvert le sixième sceau, qu''il se fit un grand tremblement de terre, et le soleil devint noir comme un sac de crin, la lune entière parut comme du sang,'),
('ap',6,13,'crampon1923','et les étoiles du ciel tombèrent vers la terre, comme les figues vertes tombent d''un figuier secoué par un gros vent.'),
('ap',6,14,'crampon1923','Et le ciel se retira comme un livre qu''on roule, et toutes les montagnes et les îles furent remuées de leur place.'),
('ap',6,15,'crampon1923','Et les rois de la terre, et les grands, et les généraux, et les riches, et les puissants, et tout esclave ou homme libre se cachèrent dans les cavernes et les rochers des montagnes,'),
('ap',6,16,'crampon1923','et ils disaient aux montagnes et aux rochers: " Tombez sur nous et dérobez-nous à la face de Celui qui est assis sur le trône et à la colère de l''Agneau;'),
('ap',6,17,'crampon1923','car il est venu le grand jour de sa colère, et qui peut subsister? "'),
('ap',7,1,'crampon1923','Après cela, je vis quatre anges qui étaient debout aux quatre coins de la terre; ils retenaient les quatre vents de la terre, afin qu''aucun vent ne soufflât, ni sur la terre, ni sur la mer, ni sur aucun arbre.'),
('ap',7,2,'crampon1923','Et je vis un autre ange qui montait du côté où le soleil se lève, tenant le sceau du Dieu vivant, et il cria d''une voix forte aux quatre anges à qui il avait été donné de nuire à la terre et à la mer,'),
('ap',7,3,'crampon1923','en ces termes: " Ne faites point de mal à la terre, ni à la mer, ni aux arbres, jusqu''à ce que nous ayons marqué du sceau, sur le front, les serviteurs de notre Dieu. "'),
('ap',7,4,'crampon1923','Et j''entendis le nombre de ceux qui avaient été marqués du sceau, cent quarante-quatre mille de toutes les tribus des enfants d''Israël:'),
('ap',7,5,'crampon1923','de la tribu de Juda, douze mille marqués du sceau; de la tribu de Ruben, douze mille [marqués]; de la tribu de Gad, douze mille [marqués];'),
('ap',7,6,'crampon1923','de la tribu d''Aser, douze mille [marqués]; de la tribu de Nephthali, douze mille [marqués]; de la tribu de Manassé, douze mille [marqués];'),
('ap',7,7,'crampon1923','de la tribu de Siméon, douze mille [marqués]; de la tribu de Lévi, douze mille [marqués]; de la tribu d''Issachar, douze mille [marqués];'),
('ap',7,8,'crampon1923','de la tribu de Zabulon, douze mille [marqués]; de la tribu de Joseph, douze mille [marqués]; de la tribu de Benjamin, douze mille marqués du sceau.'),
('ap',7,9,'crampon1923','Après cela, je vis une foule immense que personne ne pouvait compter, de toute nation, de toute tribu, de tout peuple et de toute langue. Ils étaient debout devant le trône et devant l''Agneau, vêtus de robes blanches et tenant des palmes à la main.'),
('ap',7,10,'crampon1923','Et ils criaient d''une voix forte, disant: " Le salut vient de notre Dieu qui est assis sur le trône, et à l''Agneau! "'),
('ap',7,11,'crampon1923','Et tous les anges se tenaient autour du trône, autour des vieillards et des quatre animaux; et ils se prosternèrent sur leurs faces devant le trône,'),
('ap',7,12,'crampon1923','en disant: " Amen! La louange, la gloire, la sagesse, l''action de grâces, l''honneur, la puissance et la force soient à notre Dieu, pour les siècles des siècles! "'),
('ap',7,13,'crampon1923','Alors un des vieillards, prenant la parole me dit: " Ceux que tu vois revêtus de ces robes blanches, qui sont-ils, et d''où sont-ils venus? "'),
('ap',7,14,'crampon1923','Je lui dis: " Mon Seigneur, vous le savez. " Et il me dit: " Ce sont ceux qui viennent de la grande tribulation; ils ont lavé leurs robes et les ont blanchies dans le sang de l''Agneau.'),
('ap',7,15,'crampon1923','C''est pour cela qu''ils sont devant le trône de Dieu et le servent jour et nuit dans son sanctuaire. Et Celui qui est assis sur le trône les abritera sous sa tente;'),
('ap',7,16,'crampon1923','ils n''auront plus faim, ils n''auront plus soif; l''ardeur du soleil ne les accablera plus, ni aucune chaleur brûlante;'),
('ap',7,17,'crampon1923','car l''Agneau qui est au milieu du trône sera le pasteur et les conduira aux sources des eaux de la vie, et Dieu essuiera toute larme de leurs yeux. "'),
('ap',8,1,'crampon1923','Et quand l''Agneau eut ouvert le septième sceau, il se fit dans le ciel un silence d''environ une demi-heure.'),
('ap',8,2,'crampon1923','Puis je vis les sept anges qui se tiennent devant Dieu, et on leur donna sept trompettes.'),
('ap',8,3,'crampon1923','Puis il vint un autre ange, et il se tint près de l''autel, un encensoir d''or à la main; on lui donna beaucoup de parfums pour qu''il fit une offrande des prières de tous les saints, sur l''autel d''or qui est devant le trône;'),
('ap',8,4,'crampon1923','et la fumée des parfums, formés des prières des saints, monta de la main de l''ange devant Dieu.'),
('ap',8,5,'crampon1923','Puis l''ange prit l''encensoir, le remplit du feu de l''autel, et le jeta sur la terre; et il y eut des voix, des tonnerres, des éclairs, et la terre trembla.'),
('ap',8,6,'crampon1923','Et les sept anges qui avaient les sept trompettes se préparèrent à en sonner.'),
('ap',8,7,'crampon1923','Et le premier sonna de la trompette, et il y eut de la grêle et du feu mêlés de sang, qui tombèrent sur la terre; et le tiers de la terre fût brûlé, et le tiers des arbres fût brûlé, et toute l''herbe verte fut brûlée.'),
('ap',8,8,'crampon1923','Et le deuxième ange sonna de la trompette, et une sorte de grande montagne tout en feu fût jetée dans la mer; et le tiers de la mer devint du sang,'),
('ap',8,9,'crampon1923','et le tiers des créatures marines qui ont vie périt, et le tiers des navires fut détruit.'),
('ap',8,10,'crampon1923','Et le troisième ange sonna de la trompette; et il tomba du ciel une grande étoile, ardente comme une torche, et elle tomba sur le tiers des fleuves et sur les sources des eaux.'),
('ap',8,11,'crampon1923','Le nom de cette étoile est Absinthe; et le tiers des eaux fût changé en absinthe, et beaucoup d''hommes moururent de ces eaux, parce qu''elles étaient devenues amères.'),
('ap',8,12,'crampon1923','Et le quatrième ange sonna de la trompette; et le tiers du soleil fut frappé, ainsi que le tiers de la lune et le tiers des étoiles, afin que le tiers de ces astres fût obscurci, et que le jour perdit un tiers de sa clarté et la nuit de même.'),
('ap',8,13,'crampon1923','Puis je vis, et j''entendis un aigle qui volait par le milieu du ciel, disant d''une voix forte: " Malheur! Malheur! Malheur à ceux qui habitent sur la terre, à cause du son des trois autres trompettes dont les trois anges vont sonner! "'),
('ap',9,1,'crampon1923','Et le cinquième ange sonna de la trompette; et je vis une étoile qui était tombée du ciel sur la terre, et on lui donna la clef du puits de l''abîme.'),
('ap',9,2,'crampon1923','Elle ouvrit le puits de l''abîme, et il s''éleva du puits une fumée comme celle d''une grande fournaise; et le soleil et l''air furent obscurcie par la fumée du puits.'),
('ap',9,3,'crampon1923','De cette fumée s''échappèrent sur la terre des sauterelles; et il leur fût donné un pouvoir semblable à celui que possèdent les scorpions de la terre;'),
('ap',9,4,'crampon1923','et on leur ordonna de ne point nuire à l''herbe de la terre, ni à aucune verdure, ni à aucun arbre, mais seulement aux hommes qui n''ont pas le sceau de Dieu sur leur front.'),
('ap',9,5,'crampon1923','Il leur fût donné, non de les tuer, mais de les tourmenter pendant cinq mois; et le tourment qu''elles causent est semblable à celui d''un homme piqué par le scorpion.'),
('ap',9,6,'crampon1923','En ces jours-là, les hommes chercheront la mort, et ils ne la trouveront pas; ils souhaiteront la mort, et la mort fuira loin d''eux.'),
('ap',9,7,'crampon1923','Ces sauterelles ressemblaient à des chevaux préparés pour le combat; elles avaient sur la tête comme des couronnes d''or; leurs visages étaient comme des visages d''hommes,'),
('ap',9,8,'crampon1923','leurs cheveux comme des cheveux de femmes, et leurs dents comme des dents de lions.'),
('ap',9,9,'crampon1923','Elles avaient des cuirasses comme des cuirasses de fer, et le bruit de leurs ailes était comme un bruit de chars à plusieurs chevaux qui courent au combat.'),
('ap',9,10,'crampon1923','Elles ont des queues semblables à des scorpions, et des aiguillons, et c''est dans leurs queues qu''est le pouvoir de faire du mal aux hommes durant cinq mois.'),
('ap',9,11,'crampon1923','Elles ont à leur tête, comme roi, l''ange de l''abîme qui se nomme en hébreu Abaddon, en grec Apollyon.'),
('ap',9,12,'crampon1923','Le premier " malheur " est passé; voici qu''il en vient encore deux autres dans la suite.'),
('ap',9,13,'crampon1923','Et le sixième ange sonna de la trompette; et j''entendis une voix sortir des quatre cormes de l''autel d''or qui est devant Dieu;'),
('ap',9,14,'crampon1923','elle disait au sixième ange qui avait la trompette: " Délie les quatre anges qui sont liés sur le grand fleuve de l''Euphrate. "'),
('ap',9,15,'crampon1923','Alors furent déliés les quatre anges, qui se tenaient prêts pour l''heure, le jour, le mois et l''année, afin de tuer la troisième partie des hommes.'),
('ap',9,16,'crampon1923','Et le nombre des troupes de cavalerie avait deux myriades de myriades; j''en entendis le nombre.'),
('ap',9,17,'crampon1923','Et voici comment les chevaux me parurent dans la vision, ainsi que ceux qui les montaient: ils avaient des cuirasses couleur de feu, d''hyacinthe et de soufre; les têtes des chevaux étaient comme des têtes de lions, et leur bouche jetait du feu, de la fumée et du soufre.'),
('ap',9,18,'crampon1923','La troisième partie des hommes fût tuée par ces trois fléaux, par le feu, par la fumée et par le soufre qui sortaient de leur bouche.'),
('ap',9,19,'crampon1923','Car le pouvoir de ces chevaux est dans leur bouche et dans leurs queues: car leurs queues, semblables à des serpents, ont des têtes, et c''est avec elles qu''ils blessent.'),
('ap',9,20,'crampon1923','Les autres hommes, qui ne furent pas tués par ces fléaux, ne se repentirent pas non plus des œuvres de leurs mains, pour ne plus adorer les démons et les idoles d''or, d''argent, d''airain, de pierre et de bois, qui ne peuvent ni voir, ni entendre, ni marcher;'),
('ap',9,21,'crampon1923','et ils ne se repentirent ni de leurs meurtres, ni de leurs enchantements, ni de leur impudicité, ni de leurs vols.'),
('ap',10,1,'crampon1923','Puis je vis un autre ange puissant qui descendait du ciel, enveloppé d''un nuage, et l''arc-en-ciel au-dessus de la tête; son visage était comme le soleil, et ses pieds comme des colonnes de feu.'),
('ap',10,2,'crampon1923','Il tenait à la main un petit livre ouvert; et ayant posé le pied droit sur la mer et le pied gauche sur la terre,'),
('ap',10,3,'crampon1923','il cria d''une voix forte, comme rugit un lion; et quand il eut poussé ce cri, les sept tonnerres firent entendre leurs voix.'),
('ap',10,4,'crampon1923','Après que les sept tonnerres eurent parlé, je me disposais à écrire, mais j''entendis du ciel une voix qui disait: " Scelle ce qu''ont dit les sept tonnerres, ne l''écris point. "'),
('ap',10,5,'crampon1923','Alors l''ange que j''avais vu debout sur la mer et sur la terre, leva sa main droite vers le ciel,'),
('ap',10,6,'crampon1923','et jura par Celui qui vit aux siècles des siècles, qui a créé le ciel et les choses qui y sont, la terre et les choses qui y sont, la mer et les choses qui y sont, qu''il n''y aurait plus de temps,'),
('ap',10,7,'crampon1923','mais qu''aux jours où le septième ange ferait entendre sa voix en sonnant de la trompette, le mystère de Dieu serait consommé, comme il l''a annoncé à ses serviteurs, les prophètes.'),
('ap',10,8,'crampon1923','Et la voix que j''avais entendue du ciel, me parla de nouveau et dit: " Va, prends le petit livre ouvert dans la main de l''ange qui se tient debout sur la mer et sur la terre. "'),
('ap',10,9,'crampon1923','Et j''allai vers l''ange, et je lui dis de me donner le petit livre. Il me dit: " Prends, et dévore-le; il sera amer à tes entrailles, mais dans ta bouche il sera doux comme du miel. "'),
('ap',10,10,'crampon1923','Je pris alors le petit livre de la main de l''ange et je le dévorai; et il était dans ma bouche doux comme du miel; mais quand je l''eus dévoré, il me causa de l''amertume dans les entrailles.'),
('ap',10,11,'crampon1923','Puis on me dit: " Il faut encore que tu prophétises sur beaucoup de peuples, de nations, de langues et de rois. "'),
('ap',11,1,'crampon1923','Puis on me donna un roseau semblable à un bâton, en disant: " Lève-toi et mesure le temple de Dieu, l''autel et ceux qui y adorent.'),
('ap',11,2,'crampon1923','Mais le parvis extérieur du temple, laisse-le en dehors et ne le mesure pas, car il a été abandonné aux Nations, et elles fouleront aux pieds la ville sainte pendant quarante-deux mois.'),
('ap',11,3,'crampon1923','Et je donnerai à mes deux témoins de prophétiser, revêtus de sacs, pendant mille deux cent soixante jours.'),
('ap',11,4,'crampon1923','Ceux-ci sont les deux oliviers et les deux candélabres qui sont dressés en présence du Seigneur de la terre.'),
('ap',11,5,'crampon1923','Si quelqu''un veut leur nuire, un feu sort de leur bouche qui dévore leurs ennemis: c''est ainsi que doit périr quiconque voudra leur nuire.'),
('ap',11,6,'crampon1923','Ils ont la puissance de fermer le ciel pour empêcher la pluie de tomber durant les jours de leur prédication; et ils ont pouvoir sur les eaux pour les changer en sang, et pour frapper la terre de toutes sortes de plaies, autant de fois qu''ils le vaudront.'),
('ap',11,7,'crampon1923','Et quand ils auront achevé leur témoignage, la bête qui monte de l''abîme leur fera la guerre, les vaincra et les tuera;'),
('ap',11,8,'crampon1923','et leurs cadavres resteront gisants sur la place de la grande ville, qui est appelée en langage figuré Sodome et Egypte, là même où leur Seigneur a été crucifié.'),
('ap',11,9,'crampon1923','Des hommes des divers peuples, tribus, langues et nations verront leurs cadavres étendus trois jours et demi, sans permettre qu''on leur donne la sépulture.'),
('ap',11,10,'crampon1923','Et les habitants de la terre se réjouiront à leur sujet; ils se livreront à l''allégresse et s''enverront des présents les uns aux autres, parce que ces deux prophètes ont fait le tourment des habitants de la terre.'),
('ap',11,11,'crampon1923','Mais après trois jours et demi, un esprit de vie venant de Dieu pénétra dans ces cadavres; ils se dressèrent sur leurs pieds, et une grande crainte s''empara de ceux qui les regardaient.'),
('ap',11,12,'crampon1923','Et l''on entendit une grande voix venant du ciel, qui leur disait: " Montez ici. " Et ils montèrent au ciel dans une nuée, à la vue de leurs ennemis.'),
('ap',11,13,'crampon1923','A cette même heure, il se fit un grand tremblement de terre; la dixième partie de la ville s''écroula, et sept mille hommes périrent dans ce tremblement de terre; les autres, saisis d''effroi, rendirent gloire au Dieu du ciel.'),
('ap',11,14,'crampon1923','Le second " malheur " est passé; voici que le troisième " malheur " vient bientôt.'),
('ap',11,15,'crampon1923','Et le septième ange sonna de la trompette, et l''on entendit dans le ciel des voix fortes qui disaient: " L''empire du monde a passé à notre Seigneur et à son Christ, et il régnera aux siècles des siècles. "'),
('ap',11,16,'crampon1923','Alors les vingt-quatre vieillards qui sont assis devant Dieu sur leurs trônes, se prosternèrent sur leurs faces et adorèrent Dieu, en disant:'),
('ap',11,17,'crampon1923','" Nous vous rendons grâces, Seigneur Dieu tout-puissant, qui êtes et qui étiez, de ce que vous vous êtes revêtu de votre grande puissance et que vous régnez.'),
('ap',11,18,'crampon1923','Les nations se sont irritées, et votre colère est venue, ainsi que le moment de juger les morts, de donner la récompense à vos serviteurs, aux prophètes, et aux saints, et à ceux qui craignent votre nom, petits et grands, et de perdre ceux qui perdent la terre. "'),
('ap',11,19,'crampon1923','Et le sanctuaire de Dieu dans le ciel fut ouvert, et l''arche de son alliance apparut dans son sanctuaire. Et il y eut des éclairs, des bruits, des tonnerres, un tremblement de terre et une grosse grêle.'),
('ap',12,1,'crampon1923','Puis il parut dans le ciel un grand signe: une femme revêtue du soleil, la lune sous ses pieds, et une couronne de douze étoiles sur sa tête.'),
('ap',12,2,'crampon1923','Elle était enceinte, et elle criait, dans le travail et les douleurs de l''enfantement.'),
('ap',12,3,'crampon1923','Un autre signe parut encore dans le ciel: tout à coup on vit un grand dragon rouge, ayant sept têtes et dix cornes, et sur ses têtes, sept diadèmes;'),
('ap',12,4,'crampon1923','de sa queue, il entraînait le tiers des étoiles du ciel, et il les jeta sur la terre. Puis le dragon se dressa devant la femme qui allait enfanter afin de dévorer son enfant, dès qu''elle l''aurait mis au monde.'),
('ap',12,5,'crampon1923','Or, elle donna le jour à un enfant mâle, qui doit gouverner toutes les nations avec un sceptre de fer; et son enfant fût enlevé auprès de Dieu et auprès de son trône,'),
('ap',12,6,'crampon1923','et la femme s''enfuit au désert, où Dieu lui avait préparé une retraite, afin qu''elle y fût nourrie pendant mille deux cent soixante jours.'),
('ap',12,7,'crampon1923','Et il y eut un combat dans le ciel: Michel et ses anges combattaient contre le dragon; et le dragon et ses anges combattaient;'),
('ap',12,8,'crampon1923','mais ils ne purent vaincre, et leur place même ne se trouva plus dans le ciel.'),
('ap',12,9,'crampon1923','Et il fût précipité, le grand dragon, le serpent ancien, celui qui est appelé le diable et Satan, le séducteur de toute la terre, il fût précipité sur la terre, et ses anges furent précipités avec lui.'),
('ap',12,10,'crampon1923','Et j''entendis dans le ciel une voix forte qui disait: " Maintenant le salut, la puissance et l''empire sont à notre Dieu, et l''autorité à son Christ; car il a été précipité, l''accusateur de nos frères, celui qui les accuse jour et nuit devant notre Dieu.'),
('ap',12,11,'crampon1923','Eux aussi l''ont vaincu par le sang de l''Agneau et par la parole à laquelle ils ont rendu témoignage, et ils ont méprisé leur vie jusqu''à mourir.'),
('ap',12,12,'crampon1923','C''est pourquoi, réjouissez-vous, cieux, et vous qui y demeurez! Malheur à la terre et à la mer! car le diable est descendu vers vous, avec une grande fureur, sachant qu''il ne lui reste que peu de temps. "'),
('ap',12,13,'crampon1923','Quand le dragon se vit précipité sur la terre, il poursuivit la femme qui avait mis au monde l''enfant mâle.'),
('ap',12,14,'crampon1923','Et les deux ailes du grand aigle furent données à la femme pour s''envoler au désert, en sa retraite, où elle est nourrie un temps, des temps et la moitié d''un temps, hors de la présence du serpent.'),
('ap',12,15,'crampon1923','Alors le serpent lança de sa gueule, après la femme, de l''eau comme un fleuve, afin de la faire entraîner par le fleuve.'),
('ap',12,16,'crampon1923','Mais la terre vint au secours de la femme; elle ouvrit son sein et engloutit le fleuve que le dragon avait jeté de sa gueule.'),
('ap',12,17,'crampon1923','Et le dragon fût rempli de fureur contre la femme, et il alla faire la guerre au reste de ses enfants, à ceux qui observent les commandements de Dieu et qui gardent le commandement de Jésus.'),
('ap',12,18,'crampon1923','Et il s''arrêta sur le sable de la mer.'),
('ap',13,1,'crampon1923','Puis je vis monter de la mer une bête qui avait sept têtes et dix cornes, et sur ses cornes dix diadèmes, et sur ses têtes des noms de blasphème.'),
('ap',13,2,'crampon1923','La bête que je vis ressemblait à un léopard; ses pieds étaient comme ceux d''un ours, et sa gueule comme une gueule de lion. Le dragon lui donna sa puissance, son trône et une grande autorité.'),
('ap',13,3,'crampon1923','Une de ses têtes paraissait blessée à mort; mais sa plaie mortelle fût guérie, et toute la terre, saisie d''admiration, suivit la bête,'),
('ap',13,4,'crampon1923','et l''on adora le dragon, parce qu''il avait donné l''autorité à la bête, et l''on adora la bête, en disant: " Qui est semblable à la bête, et qui peut combattre contre elle? "'),
('ap',13,5,'crampon1923','Et il lui fut donné une bouche proférant des paroles arrogantes et blasphématoires, et il lui fût donné pouvoir d''agir pendant quarante-deux mois.'),
('ap',13,6,'crampon1923','Et elle ouvrit sa bouche pour proférer des blasphèmes contre Dieu, pour blasphémer son nom, son tabernacle et ceux qui habitent dans le ciel.'),
('ap',13,7,'crampon1923','Et il lui fut donné de faire la guerre aux saints et de les vaincre; et il lui fût donné autorité sur toute tribu, tout peuple, toute langue et toute nation.'),
('ap',13,8,'crampon1923','Et tous les habitants de la terre l''adoreront, ceux dont le nom n''a pas été écrit dans le livre de vie de l''Agneau immolé, dès la fondation du monde.'),
('ap',13,9,'crampon1923','Que celui qui a des oreilles entende!'),
('ap',13,10,'crampon1923','Si quelqu''un mène en captivité, il sera mené en captivité; si quelqu''un tue par l''épée, il faut qu''il soit tué par l''épée. C''est ici la patience et la foi des saints.'),
('ap',13,11,'crampon1923','Puis je vis monter de la terre une autre bête, qui avait deux cornes semblables à celles d''un agneau, et qui parlait comme un dragon.'),
('ap',13,12,'crampon1923','Elle exerçait toute la puissance de la première bête en sa présence, et elle amenait la terre et ses habitants à adorer la première bête, dont la plaie mortelle avait été guérie.'),
('ap',13,13,'crampon1923','Elle opérait aussi de grands prodiges, jusqu''à faire descendre le feu du ciel sur la terre, à la vue des hommes,'),
('ap',13,14,'crampon1923','et elle séduisait les habitants de la terre par les prodiges qu''il lui était donné d''opérer en présence de la bête, persuadant aux habitants de la terre de dresser une image à la bête qui porte la blessure de l''épée et qui a repris vie.'),
('ap',13,15,'crampon1923','Et il lui fut donné d''animer l''image de la bête, de façon à la faire parler et à faire tuer tous ceux qui n''adoreraient pas l''image de la bête.'),
('ap',13,16,'crampon1923','Elle fit qu''à tous, petits et grands, riches et pauvres, libres et esclaves, on mit une marque sur la main droite ou sur le front,'),
('ap',13,17,'crampon1923','et que nul ne pût acheter ou vendre, s''il n''avait pas la marque du nom de la bête ou le nombre de son nom.'),
('ap',13,18,'crampon1923','C''est ici la sagesse! Que celui qui a de l''intelligence compte le nombre de la bête; car c''est un nombre d''homme et ce nombre est six cent soixante-six.'),
('ap',14,1,'crampon1923','Je regardai encore et voici que l''Agneau se tenait sur la montagne de Sion, et avec lui cent quarante-quatre mille personnes, qui avaient son nom et le nom de son Père écrits sur le front.'),
('ap',14,2,'crampon1923','Et j''entendis un son qui venait du ciel, pareil au bruit de grandes eaux et à la voix d''un puissant tonnerre; et le son que j''entendis ressemblait à un concert de harpistes jouant de leurs instruments.'),
('ap',14,3,'crampon1923','Et ils chantaient comme un cantique nouveau devant le trône, et devant les quatre animaux et les vieillards; et nul ne pouvait apprendre ce cantique, si ce n''est les cent quarante-quatre mille qui ont été rachetés de la terre.'),
('ap',14,4,'crampon1923','Ce sont ceux qui ne se sont pas souillés avec des femmes, car ils sont vierges. Ce sont eux qui accompagnent l''Agneau partout où il va. Ils ont été rachetés d''entre les hommes, comme des prémices pour Dieu et pour l''Agneau;'),
('ap',14,5,'crampon1923','et il ne s''est point trouvé de mensonge dans leur bouche, car ils sont irréprochables.'),
('ap',14,6,'crampon1923','Puis je vis un autre ange qui volait par le milieu du ciel, tenant l''Evangile éternel, pour l''annoncer aux habitants de la terre, à toute nation, à toute tribu, à toute langue et à tout peuple.'),
('ap',14,7,'crampon1923','Il disait d''une voix forte: " Craignez Dieu et donnez-lui gloire, car l''heure de son jugement est venue; adorez Celui qui a fait le ciel et la terre, la mer et les sources des eaux. "'),
('ap',14,8,'crampon1923','Et un autre ange suivit, en disant: " Elle est tombée, elle est tombée, Babylone la grande, qui a abreuvé toutes les nations du vin de la fureur de son impudicité! "'),
('ap',14,9,'crampon1923','Et un troisième ange les suivit, en disant d''une voix forte: " Si quelqu''un adore la bête et son image, et en prend la marque sur son front ou sur sa main,'),
('ap',14,10,'crampon1923','il boira, lui aussi, du vin de la fureur de Dieu, du vin pur versé dans la coupe de sa colère, et il sera tourmenté dans le feu et dans le soufre, sous les yeux des saints anges et de l''Agneau.'),
('ap',14,11,'crampon1923','Et la fumée de leur supplice s''élèvera aux siècles des siècles, et il n''y aura de repos, ni jour ni nuit, pour ceux qui adorent la bête et son image, ni pour quiconque aura reçu la marque de son nom. "'),
('ap',14,12,'crampon1923','C''est ici que doit se montrer la patience des saints, qui gardent les commandements de Dieu et la foi en Jésus.'),
('ap',14,13,'crampon1923','Et j''entendis une voix venant du ciel, qui disait: " Ecris: Heureux dès maintenant les morts qui meurent dans le Seigneur! " — " Oui, dit l''Esprit, qu''ils se reposent de leurs travaux, car leurs œuvres les suivent. "'),
('ap',14,14,'crampon1923','Puis je regardai, et voici que parut une nuée blanche, et sur la nuée quelqu''un était assis qui ressemblait à un fils de l''homme ayant sur sa tête une couronne d''or, et dans sa main une faucille tranchante.'),
('ap',14,15,'crampon1923','Et un autre ange sortit du sanctuaire, criant d''une voix forte à celui qui était assis sur la nuée: " Lance ta faucille et moissonne; car le moment de moissonner est venu, parce que la moisson de la terre est mûre. "'),
('ap',14,16,'crampon1923','Alors Celui qui était assis sur la nuée jeta sa faucille sur la terre, et la terre fut moissonnée.'),
('ap',14,17,'crampon1923','Un autre ange sortit du sanctuaire qui est dans le ciel, portant, lui aussi, une faucille tranchante.'),
('ap',14,18,'crampon1923','Et un autre ange, celui qui a pouvoir sur le feu, sortit de l''autel, et s''adressa d''une voix forte à celui qui avait la faucille tranchante, disant: " Lance ta faucille tranchante, et coupe les grappes de la vigne de la terre, car les raisins en sont murs. "'),
('ap',14,19,'crampon1923','Et l''ange jeta sa faucille sur la terre, et vendangea la vigne de la terre, et il en jeta les grappes dans la grande cuve de la colère de Dieu.'),
('ap',14,20,'crampon1923','La cuve fut foulée hors de la ville, et il en sortit du sang jusqu''à la hauteur du mors des chevaux, sur un espace de mille six cents stades.'),
('ap',15,1,'crampon1923','Puis je vis dans le ciel un autre signe, grand et étonnant: sept anges qui tenaient en main sept plaies, les dernières, car c''est par elles que doit se consommer la colère de Dieu.'),
('ap',15,2,'crampon1923','Et je vis comme une mer de verre, mêlée de feu, et au bord de cette mer étaient debout les vainqueurs de la bête, de son image et du nombre de son nom, tenant les harpes sacrées.'),
('ap',15,3,'crampon1923','Ils chantaient le cantique de Moïse, le serviteur de Dieu, et le cantique de l''Agneau disant: " Grandes et admirables sont vos œuvres, Seigneur, Dieu tout-puissant! Justes et véritables sont vos voies, ô Roi des siècles!'),
('ap',15,4,'crampon1923','Qui ne craindrait, Seigneur, et ne glorifierait votre nom? Car vous seul êtes saint. Et toutes les nations viendront se prosterner devant vous, parce que vos jugements ont éclaté. "'),
('ap',15,5,'crampon1923','Après cela, je vis s''ouvrir dans le ciel le sanctuaire du tabernacle du témoignage.'),
('ap',15,6,'crampon1923','Et les sept anges qui ont en main les sept plaies sortirent du sanctuaire; ils étaient vêtus d''un lin pur et éclatant, et portaient des ceintures d''or autour de la poitrine.'),
('ap',15,7,'crampon1923','Alors l''un des quatre animaux donna aux sept anges sept coupes d''or, pleines de la colère du Dieu qui vit aux siècles des siècles.'),
('ap',15,8,'crampon1923','Et le sanctuaire fut rempli de fumée par la gloire de Dieu et par sa puissance, et personne ne pouvait entrer dans le sanctuaire, jusqu''à ce que fussent consommées les sept plaies des sept anges.'),
('ap',16,1,'crampon1923','Et j''entendis une grande voix qui sortait du sanctuaire, et qui disait aux sept anges: " Allez et versez sur la terre les sept coupes de la colère de Dieu. "'),
('ap',16,2,'crampon1923','Et le premier partit et répandit sa coupe sur la terre; et un ulcère malin et douloureux frappa les hommes qui avaient la marque de la bête et ceux qui adoraient son image.'),
('ap',16,3,'crampon1923','Puis le second répandit sa coupe dans la mer; et elle devint comme le sang d''un mort, et tout être vivant qui était dans la mer mourut.'),
('ap',16,4,'crampon1923','Puis le troisième répandit sa coupe dans les fleuves et les sources d''eau; et les eaux devinrent du sang.'),
('ap',16,5,'crampon1923','Et j''entendis l''ange des eaux qui disait: " Vous êtes juste, vous qui êtes et qui étiez, vous le Saint, d''avoir exercé ce jugement.'),
('ap',16,6,'crampon1923','Car ils ont versé le sang des justes et des prophètes, et vous leur avez donné du sang à boire: ils en sont dignes! "'),
('ap',16,7,'crampon1923','Et j''entendis l''autel qui disait: " Oui, Seigneur, Dieu tout-puissant, vos jugements sont vrais et justes. "'),
('ap',16,8,'crampon1923','Puis le quatrième répandit sa coupe sur le soleil, et il lui fut donné de brûler les hommes par le feu;'),
('ap',16,9,'crampon1923','et les hommes furent brûlés d''une chaleur extrême, et ils blasphémèrent le nom de Dieu qui est le maître de ces plaies, et ils ne se repentirent point pour lui rendre gloire.'),
('ap',16,10,'crampon1923','Puis le cinquième répandit sa coupe sur le trône de la bête, et son royaume fut plongé dans les ténèbres; les hommes se mordaient la langue de douleur,'),
('ap',16,11,'crampon1923','et ils blasphémèrent le Dieu du ciel à cause de leurs douleurs et de leurs ulcères, et ils ne se repentirent point de leurs œuvres.'),
('ap',16,12,'crampon1923','Puis le sixième répandit sa coupe sur le grand fleuve de l''Euphrate, et les eaux en furent desséchées, afin de livrer passage aux rois venant de l''Orient.'),
('ap',16,13,'crampon1923','Et je vis sortir de la bouche du dragon, et de la bouche de la bête, et de la bouche du faux prophète, trois esprits impurs, semblables à des grenouilles.'),
('ap',16,14,'crampon1923','Car ce sont des esprits de démons qui font des prodiges, et ils vont vers les rois de toute la terre, afin de les rassembler pour le combat du grand jour du Dieu tout-puissant.'),
('ap',16,15,'crampon1923','Voici que je viens comme un voleur. Heureux celui qui veille et qui garde ses vêtements, pour ne pas aller nu et ne pas laisser voir sa honte!'),
('ap',16,16,'crampon1923','Et ils les rassemblèrent dans le lieu appelé en hébreu Armaguédon.'),
('ap',16,17,'crampon1923','Puis le septième répandit sa coupe dans l''air; et il sortit du sanctuaire une grande voix venant du trône, qui disait: " C''en est fait! "'),
('ap',16,18,'crampon1923','Et il y eut des éclairs, des voix, des tonnerres, et un grand tremblement, tel que jamais, depuis que l''homme est sur la terre, il n''y eut tremblement de terre aussi grand.'),
('ap',16,19,'crampon1923','La grande cité fut divisée en trois parties, et les villes des nations s''écroulèrent, et Dieu se souvint de Babylone la grande, pour lui faire boire la coupe du vin de son ardente colère.'),
('ap',16,20,'crampon1923','Toutes les îles s''enfuirent, et l''on ne retrouva plus de montagnes.'),
('ap',16,21,'crampon1923','Et des grêlons énormes, pouvant peser un talent, tombèrent du ciel sur les hommes; et les hommes blasphémèrent Dieu à cause du fléau de la grêle, parce que ce fléau était très grand.'),
('ap',17,1,'crampon1923','Puis l''un des sept anges qui portaient les sept coupes vint me parler en ces termes: " Viens, je te montrerai le jugement de la grande prostituée qui est assise sur les grandes eaux,'),
('ap',17,2,'crampon1923','avec laquelle les rois de la terre se sont souillés, et qui a enivré les habitants de la terre du vin de son impudicité. "'),
('ap',17,3,'crampon1923','Et il me transporta en esprit dans un désert. Et je vis une femme assise sur une bête écarlate, pleine de noms de blasphème, et ayant sept têtes et dix cornes.'),
('ap',17,4,'crampon1923','Cette femme était vêtue de pourpre et d''écarlate; et richement parée d''or, de pierres précieuses et de perles; elle tenait à la main une coupe d''or, remplie d''abominations et des souillures de sa prostitution.'),
('ap',17,5,'crampon1923','Sur son front était un nom, nom mystérieux: " Babylone la grande, la mère des impudiques et des abominations de la terre. "'),
('ap',17,6,'crampon1923','Je vis cette femme ivre du sang des saints et du sang des martyrs de Jésus; et, en la voyant, je fus saisi d''un grand étonnement.'),
('ap',17,7,'crampon1923','Et l''ange me dit: " Pourquoi t''étonner? Moi je vais te dire le mystère de la femme et de la bête qui la porte, et qui a les sept têtes et les dix cornes.'),
('ap',17,8,'crampon1923','La bête que tu as vue était et n''est plus; elle doit remonter de l''abîme, puis s''en aller à la perdition. Et les habitants de la terre, dont le nom n''est pas écrit dès la fondation du monde dans le livre de la vie, seront étonnés en voyant la bête, parce qu''elle était, qu''elle n''est plus, et qu''elle reparaîtra.'),
('ap',17,9,'crampon1923','— C''est ici qu''il faut un esprit doué de sagesse. — Les sept têtes sont sept montagnes, sur lesquelles la femme est assise. Ce sont aussi sept rois:'),
('ap',17,10,'crampon1923','Les cinq premiers sont tombés, l''un subsiste, l''autre n''est pas encore venu, et quand il sera venu, il doit demeurer peu de temps.'),
('ap',17,11,'crampon1923','Et la bête qui était et qui n''est plus, en est elle-même un huitième et elle est des sept, et elle s''en va à la perdition.'),
('ap',17,12,'crampon1923','Et les dix cornes que tu as vues sont dix rois qui n''ont pas encore reçu la royauté, mais qui recevront un pouvoir de roi pour une heure avec la bête.'),
('ap',17,13,'crampon1923','Ceux-ci ont un seul et même dessein, et ils mettent au service de la bête leur puissance et leur autorité.'),
('ap',17,14,'crampon1923','Ils feront la guerre à l''Agneau, mais l''Agneau les vaincra, parce qu''il est Seigneur des seigneurs et Roi des rois, et ceux qui l''accompagnent sont les appelés, les élus et les fidèles. "'),
('ap',17,15,'crampon1923','Et il me dit: " Les eaux que tu as vues, au lieu où la prostituée est assise, ce sont des peuples, des foules, des nations et des langues.'),
('ap',17,16,'crampon1923','Et les dix cornes que tu as vues sur la bête haïront elles-mêmes la prostituée; elles la rendront désolée et nue; elles mangeront ses chairs et la consumeront par le feu.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ap',17,17,'crampon1923','Car Dieu leur a mis au cœur d''exécuter son dessein, et de donner leur royauté à la bête, jusqu''à ce que les paroles de Dieu soient accomplies.'),
('ap',17,18,'crampon1923','Et la femme que tu as vue, c''est la grande cité qui a la royauté sur les rois de la terre. "'),
('ap',18,1,'crampon1923','Après cela, je vis descendre du ciel un autre ange, qui avait une grande puissance; et la terre fut illuminée de sa gloire.'),
('ap',18,2,'crampon1923','Il cria d''une voix forte, disant: " Elle est tombée, elle est tombée, Babylone la grande! Elle est devenue une habitation de démons, un séjour de tout esprit impur, un repaire de tout oiseau immonde et odieux,'),
('ap',18,3,'crampon1923','parce que toutes les nations ont bu du vin de la fureur de son impudicité, que les rois de la terre se sont souillés avec elle, et que les marchands de la terre se sont enrichis par l''excès de son luxe. "'),
('ap',18,4,'crampon1923','Et j''entendis du ciel une autre voix qui disait: " Sortez du milieu d''elle, ô mon peuple, afin de ne point participer à ses péchés, et de n''avoir point part à ses calamités;'),
('ap',18,5,'crampon1923','car ses péchés se sont accumulés jusqu''au ciel, et Dieu s''est souvenu de ses iniquités.'),
('ap',18,6,'crampon1923','Payez-la comme elle-même a payé, et rendez-lui au double selon ses œuvres; dans la coupe où elle a versé à boire, versez-lui le double;'),
('ap',18,7,'crampon1923','autant elle s''est glorifiée et plongée dans le luxe, autant donnez-lui de tourment et de deuil. Parce qu''elle dit en son cœur: Je trône en reine; je ne suis point veuve et ne connaîtrai point le deuil!'),
('ap',18,8,'crampon1923','à cause de cela, en un même jour, les calamités fondront sur elle, la mort, le deuil et la famine, et elle sera consumée par le feu; car il est puissant le [Seigneur] Dieu qui l''a jugée. "'),
('ap',18,9,'crampon1923','Les rois de la terre qui se sont livrés avec elle à l''impudicité et au luxe, pleureront et se lamenteront sur son sort, quand ils verront la fumée de son embrasement.'),
('ap',18,10,'crampon1923','Se tenant à distance, par crainte de ses tourments, ils diront: " Malheur! Malheur! O grande ville, Babylone, ô puissante cité, en une heure est venu ton jugement! "'),
('ap',18,11,'crampon1923','Et les marchands de la terre pleurent et sont dans le deuil à son sujet, parce que personne n''achète plus leur cargaison:'),
('ap',18,12,'crampon1923','cargaison d''or, d''argent, de pierres précieuses, de perles, de lin fin, de pourpre, de soie et d''écarlate, et le bois de senteur de toute espèce, et toute sorte d''objets d''ivoire, et toute sorte d''objets de bois très précieux, d''airain, de fer et de marbre,'),
('ap',18,13,'crampon1923','et la cannelle, les parfums, la myrrhe, l''encens, le vin, l''huile, la fleur de farine, le blé, les bestiaux, les brebis, et des chevaux, et des chars, et des corps et des âmes d''hommes.'),
('ap',18,14,'crampon1923','— Les fruits dont tu faisais tes délices s''en sont allés loin de toi; toutes les choses délicates et magnifiques sont perdues pour toi, et tu ne les retrouveras plus. —'),
('ap',18,15,'crampon1923','Les marchands de ces produits, qui se sont enrichis avec elle, se tiendront à distance par crainte de ses tourments; ils pleureront et se désoleront,'),
('ap',18,16,'crampon1923','disant: " Malheur! Malheur! O grande ville, qui était vêtue de fin lin, de pourpre et d''écarlate, et qui était richement parée d''or, de pierres précieuses et de perles, en une heure ont été dévastées tant de richesses! "'),
('ap',18,17,'crampon1923','Et tous les pilotes, et tous ceux qui naviguent vers la ville, les matelots et tous ceux qui exploitent la mer, se tenaient à distance,'),
('ap',18,18,'crampon1923','et ils s''écriaient en voyant la fumée de son embrasement: " Que pouvait-on comparer à cette grande ville? "'),
('ap',18,19,'crampon1923','Et ils jetaient de la poussière sur leur tête, et ils criaient en pleurant et en se désolant: " Malheur! Malheur! La grande ville dont l''opulence a enrichi tous ceux qui avaient des vaisseaux sur la mer, en une heure elle a été réduite en désert! "'),
('ap',18,20,'crampon1923','Réjouis-toi sur elle, ô ciel, et vous aussi, les saints, les apôtres et les prophètes; car, en la jugeant, Dieu vous a fait justice.'),
('ap',18,21,'crampon1923','Alors un ange puissant prit une pierre semblable à une grande meule, et la lança dans la mer, en disant: " Ainsi sera soudain précipitée Babylone, la grande ville, et on ne la retrouvera plus.'),
('ap',18,22,'crampon1923','En toi on n''entendra plus les sons des joueurs de harpe, des musiciens, des joueurs de flûte et de trompette; en toi on ne trouvera plus d''artisan d''aucun métier, et le bruit de la meule ne s''y fera plus entendre;'),
('ap',18,23,'crampon1923','on n''y verra plus briller la lumière de la lampe; on n''y entendra plus la voix de l''époux et de l''épouse: parce que tes marchands étaient les grands de la terre, parce que toutes les nations ont été égarées par tes enchantements.'),
('ap',18,24,'crampon1923','Et c''est dans cette ville qu''on a trouvé le sang des prophètes et des saints, et de tous ceux qui ont été égorgés sur la terre. "'),
('ap',19,1,'crampon1923','Après cela, j''entendis dans le ciel comme une grande voix d''une foule immense qui disait: " Alléluia! Le salut, la gloire et la puissance appartiennent à notre Dieu,'),
('ap',19,2,'crampon1923','parce que ses jugements sont vrais et justes. Il a jugé la grande prostituée qui corrompait la terre par son impudicité, il a vengé le sang de ses serviteurs répandu par ses mains. "'),
('ap',19,3,'crampon1923','Et ils dirent une seconde fois: " Alléluia! Et la fumée de son embrasement monte aux siècles des siècles. "'),
('ap',19,4,'crampon1923','Et les vingt-quatre vieillards et les quatre animaux se prosternèrent et adorèrent Dieu assis sur le trône, en disant: " Amen! Alléluia! "'),
('ap',19,5,'crampon1923','Et il sortit du trône une voix qui disait: " Louez notre Dieu, vous tous ses serviteurs, et vous qui le craignez, petits et grands! "'),
('ap',19,6,'crampon1923','Et j''entendis comme la voix d''une foule immense, comme le bruit des grandes eaux, comme le fracas de puissants tonnerres, disant: " Alléluia! car il règne, le Seigneur notre Dieu, le Tout-Puissant!'),
('ap',19,7,'crampon1923','Réjouissons-nous, tressaillons d''allégresse et rendons-lui gloire; car les noces de l''Agneau sont venues, et son épouse s''est préparée,'),
('ap',19,8,'crampon1923','et il lui a été donné de se vêtir de lin fin, éclatant et pur. " — Ce fin lin, ce sont les vertus des saints.'),
('ap',19,9,'crampon1923','Et l''ange me dit: " Ecris: Heureux ceux qui sont invités au festin des noces de l''Agneau! " Et il ajouta: " Ces paroles sont les véritables paroles de Dieu. "'),
('ap',19,10,'crampon1923','Je tombai alors à ses pieds pour l''adorer; mais il me dit: " Garde-toi de le faire! Je suis ton compagnon de service, et celui de tes frères qui gardent le témoignage de Jésus. Adore Dieu. " — Car le témoignage de Jésus est l''esprit de la prophétie.'),
('ap',19,11,'crampon1923','Puis je vis le ciel ouvert, et il parut un cheval blanc; celui qui le montait s''appelle Fidèle et Véritable; il juge et combat avec justice.'),
('ap',19,12,'crampon1923','Ses yeux étaient comme une flamme ardente; il avait sur la tête plusieurs diadèmes, et portait un nom écrit que nul ne connaît que lui-même;'),
('ap',19,13,'crampon1923','il était revêtu d''un vêtement teint de sang: son nom est le Verbe de Dieu.'),
('ap',19,14,'crampon1923','Les armées du ciel le suivaient sur des chevaux blancs, vêtues de fin lin, blanc et pur.'),
('ap',19,15,'crampon1923','De sa bouche sortait un glaive affilé [à deux tranchants], pour en frapper les nations; c''est lui qui les gouvernera avec un sceptre de fer, et c''est lui qui foulera la cuve du vin de l''ardente colère du Dieu tout-puissant.'),
('ap',19,16,'crampon1923','Sur son vêtement et sur sa cuisse, il portait écrit ce nom: Roi des rois et Seigneur des seigneurs.'),
('ap',19,17,'crampon1923','Et je vis un ange debout dans le soleil; et il cria d''une voix forte à tous les oiseaux qui volaient par le milieu du ciel: " Venez, rassemblez-vous pour le grand festin de Dieu,'),
('ap',19,18,'crampon1923','pour manger la chair des rois, la chair des chefs militaires, la chair des soldats vaillants, la chair des chevaux et de ceux qui les montent, la chair de tous les hommes, libres et esclaves, petits et grands. "'),
('ap',19,19,'crampon1923','Et je vis la bête et les rois de la terre avec leurs armées, rassemblés pour faire la guerre à Celui qui était monté sur le cheval et à son armée.'),
('ap',19,20,'crampon1923','Et la bête fut prise, et avec elle le faux-prophète qui, par les prodiges faits devant elle, avait séduit ceux qui avaient la marque de la bête et ceux qui adoraient son image. Tous les deux furent jetés vivants dans l''étang de feu où brûle le soufre;'),
('ap',19,21,'crampon1923','le reste fut tué par le glaive qui sortait de la bouche de Celui qui était monté sur le cheval; et tous les oiseaux se rassasièrent de leurs chairs.'),
('ap',20,1,'crampon1923','Et je vis descendre du ciel un ange qui tenait dans sa main la clef de l''abîme et une grande chaîne;'),
('ap',20,2,'crampon1923','il saisit le dragon, le serpent ancien, qui est le diable et Satan, et il l''enchaîna pour mille ans.'),
('ap',20,3,'crampon1923','Et il le jeta dans l''abîme, qu''il ferma à clef et scella sur lui, afin qu''il ne séduisit plus les nations, jusqu''à ce que les mille ans fussent écoulés. Après cela, il doit être délié pour un peu de temps.'),
('ap',20,4,'crampon1923','Puis je vis, des trônes, où s''assirent des personnes à qui le pouvoir de juger fut donné, et je vis les âmes de ceux qui avaient été décapités à cause du témoignage de Jésus et à cause de la parole de Dieu, et ceux qui n''avaient point adoré la bête ni son image, et qui n''avaient pas reçu sa marque sur leur front et sur leur main. Ils eurent la vie, et régnèrent avec le Christ pendant [les] mille ans.'),
('ap',20,5,'crampon1923','Mais les autres morts n''eurent point la vie, jusqu''à ce que les mille ans fussent écoulés. — C''est la première résurrection! —'),
('ap',20,6,'crampon1923','Heureux et saint celui qui a part à la première résurrection! La seconde mort n''a point de pouvoir sur eux; ils seront prêtres de Dieu et du Christ, et ils régneront avec lui pendant mille ans.'),
('ap',20,7,'crampon1923','Quand les mille ans seront accomplis, Satan sera relâché de sa prison, et il en sortira pour séduire les nations qui sont aux quatre extrémités de la terre, Gog et Magog, afin de les rassembler pour le combat: leur nombre est comme le sable de la mer.'),
('ap',20,8,'crampon1923','Elles montèrent sur la surface de la terre, et elles cernèrent le camp des saints et la ville bien-aimée;'),
('ap',20,9,'crampon1923','mais Dieu fit tomber un feu du ciel qui les dévora. Et le diable, leur séducteur, fut jeté dans l''étang de feu et de soufre, où sont la bête'),
('ap',20,10,'crampon1923','et le faux prophète, et ils seront tourmentés jour et nuit aux siècles des siècles.'),
('ap',20,11,'crampon1923','Puis je vis un grand trône éclatant de lumière et Celui qui était assis dessus: devant sa face la terre et le ciel s''enfuirent et il ne fut plus trouvé de place pour eux.'),
('ap',20,12,'crampon1923','Et je vis les morts, grands et petits, debout devant le trône. Des livres furent ouverts; on ouvrit encore un autre livre, qui est le livre de la vie; et les morts furent jugés, d''après ce qui était écrit dans ces livres, selon leurs œuvres.'),
('ap',20,13,'crampon1923','La mer rendit ses morts; la Mort et l''Enfer rendirent les leurs; et ils furent jugés chacun selon ses œuvres.'),
('ap',20,14,'crampon1923','Puis la Mort et l''Enfer furent jetés dans l''étang de feu: — c''est la seconde mort, l''étang de feu.'),
('ap',20,15,'crampon1923','Quiconque ne fut pas trouvé inscrit dans le livre de la vie fut jeté dans l''étang de feu.'),
('ap',21,1,'crampon1923','Et je vis un nouveau ciel et une nouvelle terre; car le premier ciel et la première terre avaient disparu, et il n''y avait plus de mer.'),
('ap',21,2,'crampon1923','Et je vis descendre du ciel, d''auprès de Dieu, la ville sainte, une Jérusalem nouvelle, vêtue comme une nouvelle mariée parée pour son époux.'),
('ap',21,3,'crampon1923','Et j''entendis une voix forte qui disait: " Voici le tabernacle de Dieu avec les hommes: il habitera avec eux, et ils seront son peuple; et lui-même il sera le Dieu avec eux, il sera leur Dieu.'),
('ap',21,4,'crampon1923','Et Dieu essuiera toute larme de leurs yeux, et la mort ne sera plus, et il n''y aura plus ni deuil, ni cri, ni douleur, car les premières choses ont disparu. "'),
('ap',21,5,'crampon1923','Et Celui qui était assis sur le trône, dit: " Voici que je fais toutes choses nouvelles. " Et il ajouta: " Ecris, car ces paroles sont sûres et véritables. "'),
('ap',21,6,'crampon1923','Puis il me dit: " C''est fait! Je suis l''alpha et l''oméga, le commencement et la fin. A celui qui a soif, je donnerai gratuitement de la source de l''eau de la vie.'),
('ap',21,7,'crampon1923','Celui qui vaincra possédera ces choses; je serai son Dieu et il sera mon fils.'),
('ap',21,8,'crampon1923','Mais pour les lâches, les incrédules, les abominables, les meurtriers, les impudiques, les magiciens, les idolâtres et tous les menteurs, leur part est dans l''étang ardent de feu et de soufre: c''est la seconde mort. "'),
('ap',21,9,'crampon1923','Alors l''un des sept anges qui tenaient les sept coupes pleines des sept dernières plaies, vint me parler et me dit: " Viens, je te montrerai la nouvelle mariée, l''Epouse de l''Agneau. "'),
('ap',21,10,'crampon1923','Et il me transporta en esprit sur une grande et haute montagne, et il me montra la ville sainte, Jérusalem, qui descendait du ciel d''auprès de Dieu,'),
('ap',21,11,'crampon1923','brillante de la gloire de Dieu, et l''astre qui l''éclaire est semblable à une pierre très précieuse, à une pierre de jaspe transparente comme le cristal.'),
('ap',21,12,'crampon1923','Elle a une grande et haute muraille, avec douze portes; à ces portes sont douze anges, et des noms inscrits, ceux des douze tribus des fils d''Israël.'),
('ap',21,13,'crampon1923','Il y a trois portes à l''orient, trois portes au nord, trois portes au midi et trois portes à l''occident.'),
('ap',21,14,'crampon1923','La muraille de la ville a douze pierres fondamentales sur lesquelles sont douze noms, ceux des douze apôtres de l''Agneau.'),
('ap',21,15,'crampon1923','Et celui qui me parlait tenait une mesure, un roseau d''or, pour mesurer la ville, ses portes et sa muraille.'),
('ap',21,16,'crampon1923','La ville est quadrangulaire, et sa longueur est égale à sa largeur. Il mesura la ville avec son roseau, jusqu''à douze mille stades; la longueur, la largeur et la hauteur en sont égales.'),
('ap',21,17,'crampon1923','Il en mesura aussi la muraille, de cent quarante-quatre coudées, mesure d''homme, qui est aussi mesure d''ange.'),
('ap',21,18,'crampon1923','La muraille de la ville est construite en jaspe, et la ville est d''un or pur, semblable à un pur cristal.'),
('ap',21,19,'crampon1923','Les pierres fondamentales du mur de la ville sont ornées de toutes sortes de pierres précieuses; la première base est du jaspe; la deuxième, du saphir, la troisième, de la calcédoine; la quatrième, de l''émeraude;'),
('ap',21,20,'crampon1923','la cinquième, du sardonyx; la sixième, de la sardoine; la septième, de la chrysolithe; la huitième, du béryl; la neuvième, de la topaze; la dixième, de la chrysoprase; la onzième, de l''hyacinthe; la douzième, de l''améthyste.'),
('ap',21,21,'crampon1923','Les douze portes sont douze perles; chaque porte est d''une seule perle; la rue de la ville est d''un or pur, comme du verre transparent.'),
('ap',21,22,'crampon1923','Je n''y vis point de temple, car le Seigneur Dieu tout-puissant en est le temple, ainsi que l''Agneau.'),
('ap',21,23,'crampon1923','La ville n''a besoin ni du soleil ni de la lune pour l''éclairer, car la gloire de Dieu l''illumine, et l''Agneau est son flambeau.'),
('ap',21,24,'crampon1923','Les nations marcheront à sa lumière, et les rois de la terre y apporteront leur magnificence.'),
('ap',21,25,'crampon1923','Ses portes ne seront point fermées chaque jour, car il n''y aura point de nuit.'),
('ap',21,26,'crampon1923','On y apportera ce que les nations ont de plus magnifique et de plus précieux;'),
('ap',21,27,'crampon1923','et il n''y entrera rien de souillé, aucun artisan d''abomination et de mensonge, mais ceux-là seulement qui sont inscrits dans le livre de vie de l''Agneau.'),
('ap',22,1,'crampon1923','Puis il me montra un fleuve d''eau de la vie, clair comme du cristal, jaillissant du trône de Dieu et de l''Agneau,'),
('ap',22,2,'crampon1923','au milieu de la rue de la ville; et de part et d''autre du fleuve, des arbres de vie qui donnent douze fois leurs fruits, les rendant une fois par mois, et dont les feuilles servent à la guérison des nations.'),
('ap',22,3,'crampon1923','Il n''y aura plus aucun anathème; le trône de Dieu et de l''Agneau sera dans la ville; ses serviteurs le serviront, et'),
('ap',22,4,'crampon1923','ils verront sa face, et son nom sera sur leurs fronts.'),
('ap',22,5,'crampon1923','Il n''y aura plus de nuit, et ils n''auront besoin ni de la lumière de la lampe, ni de la lumière du soleil, parce que le Seigneur Dieu les illuminera; et ils régneront aux siècles des siècles.'),
('ap',22,6,'crampon1923','Et l''ange me dit: " Ces paroles sont certaines et véritables; et le Seigneur, le Dieu des esprits des prophètes, a envoyé son ange pour montrer à ses serviteurs les choses qui doivent arriver bientôt. —'),
('ap',22,7,'crampon1923','Voici que je viens bientôt. Heureux celui qui garde les paroles de la prophétie de ce livre! "'),
('ap',22,8,'crampon1923','C''est moi, Jean, qui ai entendu et vu ces choses. Et après les avoir entendues et vues, je tombai aux pieds de l''ange qui me les montrait pour l''adorer.'),
('ap',22,9,'crampon1923','Mais il me dit: " Garde-toi de le faire! Je suis serviteur au même titre que toi, que tes frères, les prophètes, et que ceux qui gardent les paroles de ce livre. Adore Dieu. "'),
('ap',22,10,'crampon1923','Et il me dit: " Ne scelle point les paroles de la prophétie de ce livre; car le moment est proche.'),
('ap',22,11,'crampon1923','Que celui qui est injuste fasse encore le mal; que l''impur se souille encore; que le juste pratique encore la justice, et que le saint se sanctifie encore.'),
('ap',22,12,'crampon1923','Et voici que je viens bientôt, et ma rétribution est avec moi, pour rendre à chacun selon son œuvre.'),
('ap',22,13,'crampon1923','Je suis l''alpha et l''oméga, le premier et le dernier, le commencement et la fin.'),
('ap',22,14,'crampon1923','Heureux ceux qui lavent leurs robes, afin d''avoir droit à l''arbre de la vie, et afin d''entrer dans la ville par les portes!'),
('ap',22,15,'crampon1923','Dehors les chiens, les magiciens, les impudiques, les meurtriers, les idolâtres, et quiconque aime le mensonge et s''y adonne!'),
('ap',22,16,'crampon1923','C''est moi, Jésus, qui ai envoyé mon ange vous attester ces choses, pour les Eglises. C''est moi qui suis le rejeton et le fils de David, l''étoile brillante du matin. "'),
('ap',22,17,'crampon1923','Et l''Esprit et l''Epouse disent: " Venez! " Que celui qui entend dise aussi: " Venez! " Que celui qui a soif, vienne! Que celui qui le désire, prenne de l''eau de la vie gratuitement!'),
('ap',22,18,'crampon1923','Je déclare aussi à quiconque entend les paroles de la prophétie de ce livre que, si quelqu''un y ajoute, Dieu le frappera des fléaux décrits dans ce livre;'),
('ap',22,19,'crampon1923','et que, si quelqu''un retranche des paroles de ce livre prophétique, Dieu lui retranchera sa part de l''arbre de la vie et de la cité sainte, qui sont décrits dans ce livre.'),
('ap',22,20,'crampon1923','Celui qui atteste ces choses, dit: " Oui, je viens bientôt. " Amen! Venez, Seigneur Jésus!'),
('ap',22,21,'crampon1923','Que la grâce du Seigneur Jésus [Christ] soit avec [vous] tous! [Amen!]')
